def agent_env_key(agent: str) -> str:
    return agent.upper().replace("-", "_")


def legacy_agent_env_key(agent: str) -> str | None:
    if agent == "a1":
        return "A"
    if agent == "b1":
        return "B"
    return None


def env_path_value(primary: str, fallback: str | None, default: Path) -> Path:
    value = os.environ.get(primary)
    if value is None and fallback:
        value = os.environ.get(fallback)
    return Path(value).expanduser() if value else default


def env_text_value(primary: str, fallback: str | None, default: str) -> str:
    value = os.environ.get(primary)
    if value is None and fallback:
        value = os.environ.get(fallback)
    return value if value is not None else default


def default_agentin_name(agent: str) -> str:
    if agent in DEFAULT_AGENTIN_NAMES:
        return DEFAULT_AGENTIN_NAMES[agent]
    match = re.search(r"([1-9][0-9]{0,2})$", agent)
    if match is None:
        return "Arbeitsbiene"
    index = int(match.group(1))
    base = DEFAULT_AGENTIN_BASE_NAMES[(index - 1) % len(DEFAULT_AGENTIN_BASE_NAMES)]
    return f"{base} {agent.upper()}"


def apply_agent_introduction_policy(
    prompt: str | None,
    *,
    agent_class: str | None,
    name: str | None,
) -> str | None:
    if agent_class is None:
        return prompt
    profile = load_agent_class_catalog(repo_root() / "codex-agent-classes.json").get(
        agent_class
    )
    if profile is None or not profile.introduces_to_user:
        return prompt
    stable_name = name.strip() if name else None
    name_instruction = (
        f'Verwende dabei den stabilen Namen "{stable_name}" und behalte ihn ueber deine gesamte Lebensdauer bei.'
        if stable_name
        else "Waehle dafuer einmal einen stabilen Namen und behalte ihn ueber deine gesamte Lebensdauer bei."
    )
    policy = "\n".join(
        [
            "[USER_INTRODUCTION_POLICY]",
            "Nur wenn dies dein erstes tatsaechliches direktes Gespraech mit einem User ist, stelle dich einmal vor.",
            name_instruction,
            "Rein interne Agentin-zu-Agentin-Kommunikation loest keine Vorstellung aus.",
            "Stelle dich nach diesem ersten direkten User-Gespraech nicht erneut vor und benenne dich nicht neu.",
        ]
    )
    return f"{policy}\n\n{prompt}" if prompt else policy


def build_agent_config(agent: str) -> dict[str, Any]:
    key = agent_env_key(agent)
    legacy_key = legacy_agent_env_key(agent)
    home_default = AGENT_POOL_ROOT / agent
    home = env_path_value(
        f"CODEX_AGENT_{key}_HOME",
        f"CODEX_AGENT_{legacy_key}_HOME" if legacy_key else None,
        home_default,
    )
    runner = env_path_value(
        f"CODEX_AGENT_{key}_RUNNER",
        f"CODEX_AGENT_{legacy_key}_RUNNER" if legacy_key else None,
        home / "codex",
    )
    session = env_text_value(
        f"CODEX_AGENT_{key}_SESSION",
        f"CODEX_AGENT_{legacy_key}_SESSION" if legacy_key else None,
        f"codex_agent_{agent}_mcp",
    )
    return {
        "label": f"Codex Agentin {agent.upper()}",
        "runner": runner,
        "home": home,
        "session": session,
    }


