def _resource_pressure_reason_codes(
    snapshot: Mapping[str, Any], policy: Mapping[str, Any]
) -> list[str]:
    fallback = [
        "cpu_metrics_unavailable",
        "memory_metrics_unavailable",
    ]
    if not isinstance(snapshot, Mapping) or not isinstance(policy, Mapping):
        return fallback
    declared = snapshot.get("reason_codes")
    g5_blocked = snapshot.get("_g5_facts") is True and snapshot.get("ok") is False
    if g5_blocked and declared is None:
        return ["resource_snapshot_invalid"]
    if declared is not None and (
        not isinstance(declared, list)
        or any(
            not isinstance(item, str) or item not in RESOURCE_REASON_CODES
            for item in declared
        )
    ):
        return ["resource_snapshot_invalid"] if g5_blocked else fallback
    if isinstance(declared, list):
        declared = [
            reason for reason in declared if reason != "session_metrics_unavailable"
        ]
    had_declared = bool(declared)
    had_declared_memory_reason = isinstance(declared, list) and any(
        reason in {"memory_metrics_unavailable", "memory_pressure_high"}
        for reason in declared
    )
    if declared is not None:
        declared = [
            reason
            for reason in declared
            if reason not in {"memory_metrics_unavailable", "memory_pressure_high"}
        ]
    if g5_blocked:
        if not had_declared:
            return []
        if not had_declared_memory_reason:
            return list(dict.fromkeys(declared))
    snapshot_ok = snapshot.get("ok")
    if not isinstance(snapshot_ok, bool) or (
        snapshot_ok is False and not declared and not had_declared
    ):
        return fallback
    reasons: list[str] = []
    load_per_cpu = snapshot.get("load_per_cpu")
    cpu_busy_percent = snapshot.get("cpu_busy_percent")
    io_wait_percent = snapshot.get("io_wait_percent")
    io_psi = snapshot.get("io_psi_percent")
    has_hive_io_pressure = snapshot.get(
        "_typed_hive_io_pressure"
    ) is True or isinstance(io_psi, CgroupIoPressureEvidenceV1)
    if not _finite_resource_number(load_per_cpu) or not _finite_resource_number(
        cpu_busy_percent
    ):
        reasons.append("cpu_metrics_unavailable")
    else:
        if (
            load_per_cpu > policy["max_load_per_cpu"]
            or cpu_busy_percent > policy["max_cpu_busy_percent"]
        ):
            reasons.append("cpu_pressure_high")
        if has_hive_io_pressure:
            if not isinstance(io_psi, CgroupIoPressureEvidenceV1):
                reasons.append("resource_monitor_unavailable")
            elif (
                io_psi.some_avg10 >= HIVE_IO_PRESSURE_SOME_AVG10_LIMIT
                or io_psi.full_avg10 >= HIVE_IO_PRESSURE_FULL_AVG10_LIMIT
                or io_psi.full_avg60 >= HIVE_IO_PRESSURE_FULL_AVG60_LIMIT
            ):
                reasons.append("io_pressure_high")
        else:
            if not _finite_resource_number(io_wait_percent):
                reasons.append("cpu_metrics_unavailable")
            elif io_wait_percent > policy["max_io_wait_percent"]:
                reasons.append("io_pressure_high")
    memory_mib = snapshot.get("available_memory_mib")
    if type(memory_mib) is not int or memory_mib < 0:
        reasons.append("memory_metrics_unavailable")
    elif memory_mib < policy["min_available_memory_mib"]:
        reasons.append("memory_pressure_high")
    for reason in declared or ():
        if reason not in reasons:
            reasons.append(reason)
    return list(dict.fromkeys(reasons))


def _typed_g5_cgroup_runtime() -> (
    tuple[CgroupProfileV1, SystemdUserCgroupAdapter] | None
):
    flow_runtime = _RESOURCE_GATE_RUNTIME_TYPED_G5.get()
    if flow_runtime is False:
        return None
    if flow_runtime is not None:
        try:
            profile, adapter = flow_runtime
        except ValueError:
            return None
        if (
            type(profile) is CgroupProfileV1
            and type(adapter) is SystemdUserCgroupAdapter
        ):
            return profile, adapter
        return None

    runtime = _RESOURCE_GATE_RUNTIME.get()
    adapter = None if runtime is None else runtime.cgroup_adapter
    if (
        runtime is None
        or runtime.h2_ready is not True
        or type(runtime.cgroup_profile) is not CgroupProfileV1
        or type(adapter) is not SystemdUserCgroupAdapter
    ):
        return None
    return runtime.cgroup_profile, adapter


def _g5_warmup_active() -> bool:
    if _SPAWN_WARMUP_UNTIL_NS <= 0:
        return False
    runtime = _RESOURCE_GATE_RUNTIME.get()
    if runtime is None:
        return True
    try:
        now_ns = runtime.monotonic_ns()
    except Exception:
        return True
    return type(now_ns) is not int or now_ns < _SPAWN_WARMUP_UNTIL_NS


@contextlib.contextmanager
def _resource_admission_scope(admission: dict[str, Any]) -> Iterator[None]:
    token = _RESOURCE_ADMISSION_CONTEXT.set(admission)
    try:
        yield
    finally:
        _RESOURCE_ADMISSION_CONTEXT.reset(token)


def _resource_admission_decision(
    *,
    agent: str | None = None,
    task: str | None = None,
    role: str = "arbeitsbiene",
    required_slots: int = 1,
    snapshot: Mapping[str, Any] | None = None,
    inventory: Any = None,
    enforce_pressure: bool = True,
) -> dict[str, Any]:
    """Apply pressure/cgroup/capability gates; required_slots is only a bounded operator batch size."""

    snapshot = system_resource_snapshot() if snapshot is None else snapshot
    policy = spawn_resource_policy()
    if not _valid_spawn_policy(policy):
        result = _admission_result(
            required_slots=required_slots,
            allowed=False,
            reason_codes=["policy_invalid"],
        )
    elif not isinstance(snapshot, Mapping):
        result = _admission_result(
            required_slots=required_slots,
            allowed=False,
            reason_codes=[
                "cpu_metrics_unavailable",
                "memory_metrics_unavailable",
            ],
        )
    else:
        reasons: list[str] = []
        descriptor = None
        if agent is not None:
            try:
                if inventory is None:
                    inventory, _registry_backed = effective_observation_inventory()
                descriptor = inventory.agents.get(agent)
            except (AttributeError, TypeError, ValueError):
                descriptor = None
                inventory = None
        if descriptor is not None and descriptor.provider is Provider.OLLAMA_LOCAL:
            task_ok = task is None or _ollama_simple_task_allowed(task, role)
            if descriptor.task_profile == "simple_only" and not task_ok:
                reasons.append("ollama_simple_task_only")
        if enforce_pressure and snapshot.get("_g5_facts") is True and not reasons:
            if _typed_g5_cgroup_runtime() is None:
                reasons.append("cgroup_preflight_failed")
        if (
            enforce_pressure
            and policy["pressure_limits_enabled"]
            and "cgroup_preflight_failed" not in reasons
        ):
            pressure_reasons = _resource_pressure_reason_codes(snapshot, policy)
            reasons.extend(
                reason
                for reason in pressure_reasons
                if reason != "session_metrics_unavailable"
            )
        if (
            enforce_pressure
            and snapshot.get("_g5_facts") is True
            and not reasons
            and _g5_warmup_active()
        ):
            reasons.append("spawn_warmup_active")

        result = _admission_result(
            required_slots=required_slots,
            allowed=not reasons,
            reason_codes=reasons,
        )

    if agent is not None:
        result["resource_snapshot"] = snapshot
    return result


def spawn_admission_decision(
    required_slots: int = 1,
    *,
    running_agents_override: int | None = None,
    enforce_pressure: bool = True,
    agent: str | None = None,
    task: str | None = None,
    role: str = "arbeitsbiene",
    inventory: Any = None,
) -> dict[str, Any]:
    """Return admission; required_slots caps one operator request, never running concurrency."""

    required_slots = normalize_int_field(
        required_slots,
        field="required_slots",
        minimum=1,
        maximum=MAX_SPAWN_REQUESTED_SLOTS,
    )
    scope = (
        _resource_gate_composer_scope()
        if enforce_pressure
        else contextlib.nullcontext()
    )
    with scope:
        snapshot = (
            system_resource_snapshot()
            if running_agents_override is None
            else system_resource_snapshot(
                running_agents_override=running_agents_override
            )
        )
        return _resource_admission_decision(
            required_slots=required_slots,
            snapshot=snapshot,
            enforce_pressure=enforce_pressure,
            agent=agent,
            task=task,
            role=role,
            inventory=inventory,
        )


def require_spawn_capacity(
    required_slots: int = 1,
    *,
    agent: str | None = None,
    task: str | None = None,
    role: str = "arbeitsbiene",
) -> dict[str, Any]:
    admission = spawn_admission_decision(
        required_slots,
        agent=agent,
        task=task,
        role=role,
    )
    if admission.get("allowed") is True:
        return admission
    reason_codes = [
        reason
        for reason in admission.get("reason_codes", [])
        if isinstance(reason, str) and reason in RESOURCE_REASON_CODES
    ]
    if not reason_codes:
        reason_codes = ["resource_snapshot_invalid"]
    raise AgentCapacityError(
        "capacity unavailable",
        {
            "error_code": "spawn_capacity_unavailable",
            "retryable": True,
            "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
            "reason_codes": reason_codes,
            "errors": admission.get("errors", spawn_error_details(reason_codes)),
        },
    )


def _ollama_simple_task_allowed(task: str, role: str) -> bool:
    if not isinstance(task, str) or len(task) > OLLAMA_SIMPLE_TASK_MAX_CHARS:
        return False
    blocked = (
        "commit",
        "push",
        "release",
        "deploy",
        "refactor",
        "architecture",
        "security scan",
        "benchmark",
        "subagent",
        "spawn",
        "install",
        "delete",
        "migration",
        "research",
    )
    normalized = task.casefold()
    return role in {"exploriererin", "arbeitsbiene"} and not any(
        item in normalized for item in blocked
    )


def ollama_resource_status(
    agent: str, *, task: str | None = None, role: str = "arbeitsbiene"
) -> dict[str, Any]:
    """Return pressure/capability admission for Ollama without a provider concurrency cap."""

    inventory = current_agent_inventory()
    descriptor = inventory.agents.get(agent)
    if descriptor is None or descriptor.provider is not Provider.OLLAMA_LOCAL:
        return {"allowed": True, "provider": "not_ollama", "raw_output": "not_returned"}
    decision = spawn_admission_decision(
        1,
        agent=agent,
        task=task,
        role=role,
        inventory=inventory,
    )
    reason_codes = decision.get("reason_codes", [])
    return {
        "allowed": decision.get("allowed") is True,
        "provider": "ollama_local",
        "agent": agent,
        "task_profile": descriptor.task_profile,
        "resource_snapshot": decision.get("resource_snapshot"),
        "reason_codes": reason_codes,
        "errors": decision.get("errors", []),
        "benchmark_policy": "resource_pressure_and_simple_task_capability",
        "raw_output": "not_returned",
    }


def _public_resource_gate_status(decision: Mapping[str, Any] | None) -> dict[str, Any]:
    reason_codes = (
        decision.get("reason_codes") if isinstance(decision, Mapping) else None
    )
    if not isinstance(reason_codes, list) or any(
        not isinstance(reason, str) or reason not in RESOURCE_REASON_CODES
        for reason in reason_codes
    ):
        return {
            "allowed": False,
            "reason_codes": ["resource_snapshot_invalid"],
            "raw_output": "not_returned",
        }
    return {
        "allowed": decision.get("allowed") is True,
        "reason_codes": list(dict.fromkeys(reason_codes)),
        "raw_output": "not_returned",
    }


def _raise_ollama_admission_denied(decision: Mapping[str, Any]) -> None:
    raise AgentCapacityError(
        "Ollama admission denied",
        {
            "error_code": "ollama_admission_denied",
            "retryable": True,
            "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
            "reason_codes": decision.get(
                "reason_codes", ["ollama_resource_unavailable"]
            ),
            "errors": decision.get("errors", []),
            "resource_snapshot": decision.get("resource_snapshot"),
        },
    )


def require_ollama_admission(
    agent: str, *, task: str | None = None, role: str = "arbeitsbiene"
) -> None:
    decision = ollama_resource_status(agent, task=task, role=role)
    if decision.get("allowed") is True:
        return
    _raise_ollama_admission_denied(decision)


def _spawn_priority_routes() -> tuple[str, ...]:
    configured = os.environ.get("CODEX_MASTER_SPAWN_PRIORITY")
    if configured is None:
        configured = "mcp_host"
    routes: list[str] = []
    seen: set[str] = set()
    for item in configured.split(","):
        route = item.strip()
        if route and route not in seen:
            routes.append(route)
            seen.add(route)
    return tuple(routes)


def agent_spawn_offers(required_slots: int = 1) -> dict[str, Any]:
    required_slots = normalize_int_field(
        required_slots,
        field="required_slots",
        minimum=1,
        maximum=MAX_SPAWN_REQUESTED_SLOTS,
    )
    admission = spawn_admission_decision(required_slots)
    routes = _spawn_priority_routes()
    allowed = admission.get("allowed") is True
    offers = [{"route": route} for route in routes if allowed and route == "mcp_host"]
    offered_routes = {offer["route"] for offer in offers}
    internal_reason_codes = admission.get("reason_codes")
    reason_codes: list[str] = []
    if not allowed and isinstance(internal_reason_codes, list):
        reason_codes = [
            reason
            for reason in internal_reason_codes
            if isinstance(reason, str) and reason in RESOURCE_REASON_CODES
        ]
    if not allowed and not reason_codes:
        reason_codes = ["resource_snapshot_invalid"]
    retryable = not allowed
    result = {
        "ok": allowed,
        "offers": offers,
        "offer_count": len(offers),
        "unavailable_route_count": sum(route not in offered_routes for route in routes),
        "ttl_seconds": SPAWN_OFFER_TTL_SECONDS,
        "reservation": "none",
        "retryable": retryable,
        "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS if retryable else None,
        "reason_codes": reason_codes,
        "raw_output": "not_returned",
    }
    if not allowed:
        result["errors"] = admission.get(
            "errors",
            spawn_error_details(reason_codes),
        )
    return result


def normalize_lease_seconds(value: Any) -> int:
    return normalize_int_field(
        value, field="ttl_seconds", minimum=1, maximum=MAX_AGENT_LEASE_SECONDS
    )


def normalize_wait_seconds(value: Any) -> int:
    return normalize_int_field(
        value, field="wait_seconds", minimum=0, maximum=MAX_WAIT_SECONDS
    )


def normalize_claim_wait_seconds(value: Any) -> int | None:
    if value is None:
        return None
    if isinstance(value, str) and value.strip().lower() in {
        "forever",
        "infinite",
        "unbounded",
        "unlimited",
    }:
        return None
    if isinstance(value, bool) or not isinstance(value, int):
        raise AgentError("wait_seconds must be an integer or forever")
    number = value
    if number < 0:
        raise AgentError("wait_seconds must be >= 0")
    return number


def normalize_stopped_lease_recovery_grace_seconds(value: Any) -> int:
    return normalize_int_field(
        value,
        field="stopped_grace_seconds",
        minimum=0,
        maximum=MAX_STOPPED_LEASE_RECOVERY_GRACE_SECONDS,
    )


def normalize_poll_interval_seconds(value: Any) -> int:
    return normalize_int_field(
        value,
        field="poll_interval_seconds",
        minimum=1,
        maximum=MAX_WAIT_POLL_SECONDS,
    )


def normalize_watchdog_idle_seconds(value: Any) -> int:
    return normalize_int_field(
        value,
        field="idle_seconds",
        minimum=1,
        maximum=MAX_WATCHDOG_IDLE_SECONDS,
    )


def normalize_watchdog_report_grace_seconds(value: Any) -> int:
    return normalize_int_field(
        value,
        field="report_grace_seconds",
        minimum=0,
        maximum=MAX_WATCHDOG_REPORT_GRACE_SECONDS,
    )


def parse_utc_timestamp(value: Any) -> float | None:
    if not isinstance(value, str) or not value.strip():
        return None
    text = value.strip()
    if text.endswith("Z"):
        text = f"{text[:-1]}+00:00"
    try:
        parsed = _dt.datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=_dt.timezone.utc)
    return parsed.timestamp()


def age_seconds_from_utc(value: Any, *, now: float | None = None) -> int | None:
    timestamp = parse_utc_timestamp(value)
    if timestamp is None:
        return None
    current = time.time() if now is None else now
    return max(0, int(current - timestamp))


def read_agent_lease_record(
    agent: str,
    snapshot: InventorySnapshot | None = None,
) -> dict[str, Any] | None:
    agent = canonical_agent_id(agent, snapshot=snapshot)
    candidate_paths = [agent_lease_path(agent, snapshot=snapshot)]
    candidate_paths.extend(
        LEASE_DIR / f"{legacy_agent}.json"
        for legacy_agent in sorted(agent_record_aliases(agent) - {agent})
    )
    for path in candidate_paths:
        if not path_present_no_follow(path):
            continue
        data = read_json_file(path)
        if data.get("meta_error"):
            raise AgentError("could_not_read_agent_lease")
        record_agent = data.get("agent")
        owner = data.get("owner")
        if (
            not isinstance(record_agent, str)
            or record_agent not in agent_record_aliases(agent)
            or not isinstance(owner, str)
            or not owner.strip()
        ):
            raise AgentError("could_not_read_agent_lease")
        data["agent"] = agent
        return data
    return None


def public_agent_lease(
    agent: str,
    record: dict[str, Any] | None = None,
    snapshot: InventorySnapshot | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent, snapshot=snapshot)
    now = time.time()
    valid_expiry = True
    if not record:
        return {
            "agent": agent,
            "state": "unclaimed",
            "holder": "none",
            "held_by_this_server": False,
            "lease_id": None,
            "expires_at_utc": None,
            "seconds_remaining": 0,
            "ttl_seconds": DEFAULT_AGENT_LEASE_SECONDS,
            "raw_output": "not_returned",
        }
    try:
        expires_at = float(record.get("expires_at_epoch", 0))
    except (OverflowError, TypeError, ValueError):
        expires_at = 0.0
        valid_expiry = False
    if not math.isfinite(expires_at):
        expires_at = 0.0
        valid_expiry = False
    ttl_seconds = record.get("ttl_seconds")
    lease_id = record.get("lease_id")
    if not isinstance(lease_id, str) or not LEASE_ID_RE.fullmatch(lease_id):
        lease_id = None
    active = expires_at > now
    held_by_this_server = active and record.get("owner") == SERVER_INSTANCE_ID
    holder = (
        "this_server" if held_by_this_server else "other_server" if active else "none"
    )
    return {
        "agent": agent,
        "state": "held" if active else "expired",
        "holder": holder,
        "held_by_this_server": held_by_this_server,
        "lease_id": lease_id,
        "expires_at_utc": lease_utc(expires_at) if valid_expiry else None,
        "seconds_remaining": max(0, int(expires_at - now)) if active else 0,
        "ttl_seconds": ttl_seconds
        if isinstance(ttl_seconds, int) and not isinstance(ttl_seconds, bool)
        else None,
        "raw_output": "not_returned",
    }


def agent_busy_error(agent: str, lease: dict[str, Any]) -> AgentBusyError:
    seconds_remaining = int(lease.get("seconds_remaining") or 0)
    retry_after = max(1, min(seconds_remaining or 1, 30))
    return AgentBusyError(
        f"agent {agent} is leased by another MCP client",
        {
            "error_code": "agent_lease_held_by_other_client",
            "agent": agent,
            "retryable": True,
            "retry_after_seconds": retry_after,
            "lease_seconds_remaining": seconds_remaining,
            "lease": lease,
            "raw_output": "not_returned",
        },
    )


def stopped_foreign_lease_recovery_status(
    agent: str,
    lease: dict[str, Any],
    *,
    stopped_grace_seconds: int,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    status = status_agent(agent)
    raw_idle = status.get("raw_log_idle_seconds")
    home_process_count = status.get("home_process_count")
    home_external_process_count = status.get("home_external_process_count")
    blockers: list[str] = []
    if lease.get("state") != "held":
        blockers.append("lease_not_held")
    if lease.get("held_by_this_server"):
        blockers.append("lease_held_by_this_server")
    if status.get("running"):
        blockers.append("agent_running")
    if not isinstance(raw_idle, int):
        blockers.append("missing_idle_evidence")
    elif raw_idle < stopped_grace_seconds:
        blockers.append("within_stopped_grace")
    if isinstance(home_process_count, int) and home_process_count > 0:
        blockers.append("agent_home_has_processes")
    elif home_process_count is None:
        blockers.append("missing_home_process_evidence")
    if isinstance(home_external_process_count, int) and home_external_process_count > 0:
        blockers.append("agent_home_has_external_processes")
    elif home_external_process_count is None:
        blockers.append("missing_home_external_process_evidence")
    recoverable = not blockers
    return {
        "recoverable": recoverable,
        "reason": "stopped_foreign_lease_orphan" if recoverable else "not_recoverable",
        "lease_state": lease.get("state"),
        "running": bool(status.get("running")),
        "raw_log_idle_seconds": raw_idle if isinstance(raw_idle, int) else None,
        "stopped_grace_seconds": stopped_grace_seconds,
        "home_process_count": home_process_count
        if isinstance(home_process_count, int)
        else None,
        "home_external_process_count": (
            home_external_process_count
            if isinstance(home_external_process_count, int)
            else None
        ),
        "blockers": blockers,
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }


def agent_lease_status(
    agent: str,
    *,
    initialize_state: bool = True,
    snapshot: InventorySnapshot | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent, snapshot=snapshot)
    if initialize_state:
        ensure_state()
    try:
        return public_agent_lease(
            agent,
            read_agent_lease_record(agent, snapshot=snapshot),
            snapshot=snapshot,
        )
    except AgentError:
        return {
            "agent": agent,
            "state": "unreadable",
            "holder": "unknown",
            "held_by_this_server": False,
            "expires_at_utc": None,
            "seconds_remaining": 0,
            "ttl_seconds": None,
            "raw_output": "not_returned",
        }


def agent_lifecycle_lock_busy_error(agent: str) -> AgentBusyError:
    agent = canonical_agent_id(agent)
    lease = agent_lease_status(agent, initialize_state=False)
    return AgentBusyError(
        f"agent {agent} lifecycle lock is busy",
        {
            "error_code": "agent_lifecycle_lock_busy",
            "agent": agent,
            "retryable": True,
            "retry_after_seconds": 1,
            "lease_seconds_remaining": int(lease.get("seconds_remaining") or 0),
            "lease": lease,
            "raw_output": "not_returned",
        },
    )


def write_agent_lease(agent: str, ttl_seconds: int) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    now = time.time()
    expires_at = now + ttl_seconds
    record = {
        "agent": agent,
        "owner": SERVER_INSTANCE_ID,
        "lease_id": uuid.uuid4().hex,
        "created_at_utc": _dt.datetime.fromtimestamp(now, _dt.timezone.utc).isoformat(),
        "updated_at_utc": _dt.datetime.fromtimestamp(now, _dt.timezone.utc).isoformat(),
        "expires_at_epoch": expires_at,
        "expires_at_utc": lease_utc(expires_at),
        "ttl_seconds": ttl_seconds,
    }
    replace_private_text(
        agent_lease_path(agent), json.dumps(record, indent=2, sort_keys=True) + "\n"
    )
    return record


def remove_agent_lease(agent: str) -> bool:
    agent = canonical_agent_id(agent)
    removed = False
    paths = [agent_lease_path(agent)]
    paths.extend(
        LEASE_DIR / f"{legacy_agent}.json"
        for legacy_agent in sorted(agent_record_aliases(agent) - {agent})
    )
    for path in paths:
        removed = remove_agent_lease_path(path) or removed
    return removed


def remove_agent_lease_path(path: Path) -> bool:
    path = path.expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    try:
        current = path.lstat()
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise AgentError("could_not_read_agent_lease") from exc
    if not stat_module.S_ISREG(current.st_mode) or stat_module.S_ISLNK(current.st_mode):
        raise AgentError("agent lease path is not a regular file")
    try:
        parent_stat = path.parent.lstat()
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise AgentError("could_not_read_agent_lease") from exc
    parent_fd = open_directory_no_follow_matching(
        path.parent,
        parent_stat,
        error_text="agent lease path changed unexpectedly",
        changed_text="agent lease path changed unexpectedly",
    )
    try:
        latest = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
        if not source_identity_matches(latest, current):
            raise AgentError("agent lease path changed unexpectedly")
        os.unlink(path.name, dir_fd=parent_fd)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise AgentError("could_not_read_agent_lease") from exc
    finally:
        os.close(parent_fd)
    return True


def claim_agent(
    agent: str,
    ttl_seconds: int = DEFAULT_AGENT_LEASE_SECONDS,
    force: bool = False,
    recover_stopped: bool = False,
    stopped_grace_seconds: int = DEFAULT_STOPPED_LEASE_RECOVERY_GRACE_SECONDS,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="agent_claim")
    require_fleet_recovery_ready("agent_claim")
    with agent_lifecycle_lock(agent):
        return _claim_agent_unlocked(
            agent,
            ttl_seconds=ttl_seconds,
            force=force,
            recover_stopped=recover_stopped,
            stopped_grace_seconds=stopped_grace_seconds,
        )


def _claim_agent_unlocked(
    agent: str,
    ttl_seconds: int = DEFAULT_AGENT_LEASE_SECONDS,
    force: bool = False,
    recover_stopped: bool = False,
    stopped_grace_seconds: int = DEFAULT_STOPPED_LEASE_RECOVERY_GRACE_SECONDS,
    *,
    enforce_recovery_gate: bool = True,
) -> dict[str, Any]:
    """Claim either new capacity or a narrowly scoped control lease.

    ``enforce_recovery_gate=False`` is reserved for control paths that already
    hold the lifecycle lock and can only stop, interrupt, release, or recover
    an existing agent.  It preserves the normal lease ownership checks while
    deliberately bypassing resource-capacity admission.
    """

    if not enforce_recovery_gate:
        return _claim_agent_after_capacity_probe_unlocked(
            agent,
            ttl_seconds=ttl_seconds,
            force=force,
            recover_stopped=recover_stopped,
            stopped_grace_seconds=stopped_grace_seconds,
            enforce_recovery_gate=enforce_recovery_gate,
        )
    with hive_capacity_probe_guard("agent_claim"):
        return _claim_agent_after_capacity_probe_unlocked(
            agent,
            ttl_seconds=ttl_seconds,
            force=force,
            recover_stopped=recover_stopped,
            stopped_grace_seconds=stopped_grace_seconds,
            enforce_recovery_gate=True,
        )


def _claim_agent_after_capacity_probe_unlocked(
    agent: str,
    ttl_seconds: int = DEFAULT_AGENT_LEASE_SECONDS,
    force: bool = False,
    recover_stopped: bool = False,
    stopped_grace_seconds: int = DEFAULT_STOPPED_LEASE_RECOVERY_GRACE_SECONDS,
    *,
    enforce_recovery_gate: bool = True,
) -> dict[str, Any]:
    if enforce_recovery_gate:
        require_fleet_recovery_ready("agent_claim")
    agent = canonical_agent_id(agent)
    ensure_state()
    ttl_seconds = normalize_lease_seconds(ttl_seconds)
    stopped_grace_seconds = normalize_stopped_lease_recovery_grace_seconds(
        stopped_grace_seconds
    )
    current = read_agent_lease_record(agent)
    current_public = public_agent_lease(agent, current)
    stopped_recovery = None
    if current_public["state"] == "held" and not current_public["held_by_this_server"]:
        if recover_stopped:
            stopped_recovery = stopped_foreign_lease_recovery_status(
                agent,
                current_public,
                stopped_grace_seconds=stopped_grace_seconds,
            )
        if not stopped_recovery or not stopped_recovery["recoverable"]:
            raise agent_busy_error(agent, current_public)
    if current_public["state"] == "held" and current_public["held_by_this_server"]:
        status = "renewed"
    elif (
        current_public["state"] == "held"
        and stopped_recovery
        and stopped_recovery["recoverable"]
    ):
        status = "claimed_stopped_orphan"
    elif current_public["state"] == "expired":
        status = "claimed_expired"
    else:
        status = "claimed"
    record = write_agent_lease(agent, ttl_seconds)
    result = {
        "agent": agent,
        "status": status,
        "lease": public_agent_lease(agent, record),
        "previous_lease": current_public,
        "raw_output": "not_returned",
    }
    if stopped_recovery is not None:
        result["stopped_lease_recovery"] = stopped_recovery
    return result


def release_agent(agent: str, force: bool = False) -> dict[str, Any]:
    with agent_lifecycle_lock(agent):
        return _release_agent_unlocked(agent, force=force)


def _release_agent_unlocked(agent: str, force: bool = False) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if HEADLESS_JOBS.status(agent).get("status") in {"running", "cancelling"}:
        raise AgentError("headless_job_running")
    ensure_state()
    current = read_agent_lease_record(agent)
    current_public = public_agent_lease(agent, current)
    if current_public["state"] != "held":
        if current_public["state"] == "expired":
            remove_agent_lease(agent)
        return {
            "agent": agent,
            "status": "not_held",
            "previous_lease": current_public,
            "lease": public_agent_lease(agent),
            "raw_output": "not_returned",
        }
    if not current_public["held_by_this_server"] and not force:
        raise agent_busy_error(agent, current_public)
    remove_agent_lease(agent)
    return {
        "agent": agent,
        "status": "released",
        "previous_lease": current_public,
        "lease": public_agent_lease(agent),
        "raw_output": "not_returned",
    }


def claim_for_agent_mutation(agent: str) -> tuple[dict[str, Any], bool]:
    agent = canonical_agent_id(agent)
    claim = claim_agent(agent)
    return claim["lease"], claim["status"] in {"claimed", "claimed_expired"}


def ensure_agent_lease_available(agent: str, *, force: bool = False) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    current = read_agent_lease_record(agent)
    current_public = public_agent_lease(agent, current)
    if (
        current_public["state"] == "held"
        and not current_public["held_by_this_server"]
        and not force
    ):
        raise agent_busy_error(agent, current_public)
    return current_public


def claim_agent_with_wait(
    agent: str,
    ttl_seconds: int = DEFAULT_AGENT_LEASE_SECONDS,
    force: bool = False,
    wait_seconds: int | str | None = None,
    poll_interval_seconds: int = DEFAULT_WAIT_POLL_SECONDS,
    recover_stopped: bool = True,
    stopped_grace_seconds: int = DEFAULT_STOPPED_LEASE_RECOVERY_GRACE_SECONDS,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="agent_claim")
    require_fleet_recovery_ready("agent_claim")
    agent = canonical_agent_id(agent)
    wait_seconds = normalize_claim_wait_seconds(wait_seconds)
    poll_interval_seconds = normalize_poll_interval_seconds(poll_interval_seconds)
    stopped_grace_seconds = normalize_stopped_lease_recovery_grace_seconds(
        stopped_grace_seconds
    )
    started = time.monotonic()
    wait_forever = wait_seconds is None
    if wait_forever:
        deadline = None
    else:
        try:
            deadline = started + wait_seconds
        except OverflowError:
            deadline = math.inf
    polls = 0

    def claim_once() -> dict[str, Any]:
        ensure_agent_not_blocked_by_codex_usage(agent)
        return claim_agent(
            agent,
            ttl_seconds=ttl_seconds,
            force=force,
            recover_stopped=recover_stopped,
            stopped_grace_seconds=stopped_grace_seconds,
        )

    while True:
        remaining = None if deadline is None else max(0.0, deadline - time.monotonic())
        try:
            lock_timeout = (
                remaining if remaining is None or math.isfinite(remaining) else None
            )
            result = call_agent_lifecycle(
                agent, claim_once, timeout_seconds=lock_timeout
            )
            result["waited_seconds"] = max(0, int(time.monotonic() - started))
            result["poll_count"] = polls
            result["wait_forever"] = wait_forever
            result["wait_limit_seconds"] = None if wait_forever else wait_seconds
            result["recover_stopped"] = recover_stopped
            result["stopped_grace_seconds"] = stopped_grace_seconds
            return result
        except (AgentBusyError, AgentLifecycleLockBusyError) as exc:
            if isinstance(exc, AgentLifecycleLockBusyError):
                exc = agent_lifecycle_lock_busy_error(agent)
            if deadline is not None and time.monotonic() >= deadline:
                raise exc
            sleep_seconds = float(poll_interval_seconds)
            if deadline is not None:
                remaining = max(0.0, deadline - time.monotonic())
                sleep_seconds = min(sleep_seconds, remaining)
            time.sleep(sleep_seconds)
            polls += 1


def is_real_directory_no_symlink(path: Path) -> bool:
    try:
        mode = path.lstat().st_mode
    except OSError:
        return False
    return stat_module.S_ISDIR(mode)


def is_regular_executable_no_symlink(path: Path) -> bool:
    try:
        current = path.lstat()
    except OSError:
        return False
    if not stat_module.S_ISREG(current.st_mode) or getattr(current, "st_nlink", 1) > 1:
        return False
    return os.access(path, os.X_OK)


def trusted_runner_executable(path: Path) -> Path:
    """Resolve a trusted launcher symlink to one pinned executable bundle."""

    if not isinstance(path, Path) or not path.is_absolute():
        raise AgentError("fleet_executable_invalid")
    try:
        source = path.lstat()
        resolved = path.resolve(strict=True)
        target = resolved.lstat()
    except OSError as exc:
        raise AgentError("fleet_executable_invalid") from exc
    if (
        not stat_module.S_ISREG(target.st_mode)
        or getattr(target, "st_nlink", 1) != 1
        or target.st_uid not in {0, os.geteuid() if hasattr(os, "geteuid") else -1}
        or target.st_mode & 0o022
        or not os.access(resolved, os.X_OK)
        or not directory_chain_is_real_no_symlink(path.parent)
        or not executable_directory_chain_is_trusted(path.parent)
        or not executable_directory_chain_is_trusted(resolved.parent)
        or stat_module.S_ISLNK(source.st_mode)
        and source.st_uid != target.st_uid
    ):
        raise AgentError("fleet_executable_invalid")
    return resolved


def trusted_gemini_executable(path: Path) -> Path:
    """Compatibility wrapper for Gemini launcher validation."""

    return trusted_runner_executable(path)


def close_runner_execution_fd(agent: str) -> None:
    fd = RUNNER_EXECUTION_FDS.pop(agent, None)
    if fd is not None:
        with contextlib.suppress(OSError):
            os.close(fd)


def _managed_codex_home(home: Path) -> Path:
    if not isinstance(home, Path) or not home.is_absolute():
        raise AgentError("managed_codex_home_invalid")
    try:
        metadata = home.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_home_invalid") from exc
    if (
        stat_module.S_ISLNK(metadata.st_mode)
        or not stat_module.S_ISDIR(metadata.st_mode)
        or metadata.st_mode & 0o022
    ):
        raise AgentError("managed_codex_home_invalid")
    return home


def _managed_codex_wrapper_snapshot(wrapper: Path) -> os.stat_result:
    if not isinstance(wrapper, Path) or not wrapper.is_absolute():
        raise AgentError("managed_codex_runner_metadata_invalid")
    try:
        expected = wrapper.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if (
        stat_module.S_ISLNK(expected.st_mode)
        or not stat_module.S_ISREG(expected.st_mode)
        or getattr(expected, "st_nlink", 1) != 1
        or expected.st_mode & 0o022
        or expected.st_mode & 0o111 == 0
        or expected.st_size > _MANAGED_CODEX_WRAPPER_MAX_BYTES
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    return expected


def _managed_codex_runner_candidate(wrapper: Path) -> bool:
    """Recognize a Fleet wrapper before applying its stricter home contract."""

    if wrapper.name != "codex":
        return False
    try:
        metadata = wrapper.lstat()
    except OSError:
        return False
    if stat_module.S_ISLNK(metadata.st_mode) or getattr(metadata, "st_nlink", 1) != 1:
        return True
    if not stat_module.S_ISREG(metadata.st_mode):
        return False
    try:
        with wrapper.open("rb") as source:
            prefix = source.read(128)
    except OSError:
        return True
    return prefix.startswith(
        b"#!/usr/bin/env bash\nset -euo pipefail\n\nexport CODEX_HOME="
    )


def _read_managed_codex_wrapper(wrapper: Path, expected: os.stat_result) -> str:
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        current_before = wrapper.lstat()
        if not source_identity_with_snapshot_matches(current_before, expected):
            raise AgentError("managed_codex_runner_changed")
        fd = os.open(wrapper, flags)
    except OSError as exc:
        raise AgentError("managed_codex_runner_changed") from exc
    try:
        opened = os.fstat(fd)
        data = os.read(fd, _MANAGED_CODEX_WRAPPER_MAX_BYTES + 1)
        current = wrapper.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_changed") from exc
    finally:
        with contextlib.suppress(OSError):
            os.close(fd)
    if (
        len(data) > _MANAGED_CODEX_WRAPPER_MAX_BYTES
        or not source_identity_with_snapshot_matches(opened, expected)
        or not source_identity_with_snapshot_matches(current, expected)
        or not stat_module.S_ISREG(opened.st_mode)
        or getattr(opened, "st_nlink", 1) != 1
        or opened.st_mode & 0o022
        or opened.st_mode & 0o111 == 0
    ):
        raise AgentError("managed_codex_runner_changed")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc


def _read_managed_codex_metadata(path: Path) -> dict[str, Any]:
    if (
        not path.is_absolute()
        or not directory_chain_is_real_no_symlink(path.parent)
        or not executable_directory_chain_is_trusted(path.parent)
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    try:
        expected = path.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if (
        not stat_module.S_ISREG(expected.st_mode)
        or getattr(expected, "st_nlink", 1) != 1
        or expected.st_uid != 0
        or expected.st_mode & 0o022
        or expected.st_size > _MANAGED_CODEX_METADATA_MAX_BYTES
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    try:
        opened = os.fstat(fd)
        data = os.read(fd, _MANAGED_CODEX_METADATA_MAX_BYTES + 1)
        current = path.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    finally:
        with contextlib.suppress(OSError):
            os.close(fd)
    if (
        len(data) > _MANAGED_CODEX_METADATA_MAX_BYTES
        or not source_identity_with_snapshot_matches(opened, expected)
        or not source_identity_with_snapshot_matches(current, expected)
        or not stat_module.S_ISREG(opened.st_mode)
        or getattr(opened, "st_nlink", 1) != 1
        or opened.st_uid != 0
        or opened.st_mode & 0o022
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    try:
        metadata = json.loads(data)
    except (TypeError, ValueError, UnicodeDecodeError) as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if not isinstance(metadata, dict):
        raise AgentError("managed_codex_runner_metadata_invalid")
    return metadata


def _managed_codex_platform_layout() -> tuple[str, str]:
    try:
        platform_name = os.uname().sysname
        machine = os.uname().machine
    except (AttributeError, OSError) as exc:
        raise AgentError("managed_codex_runner_platform_unsupported") from exc
    layouts = {
        ("Linux", "x86_64"): ("codex-linux-x64", "x86_64-unknown-linux-musl"),
        ("Linux", "aarch64"): ("codex-linux-arm64", "aarch64-unknown-linux-musl"),
    }
    layout = layouts.get((platform_name, machine))
    if layout is None:
        raise AgentError("managed_codex_runner_platform_unsupported")
    return layout


def _managed_codex_launcher(path: Path) -> Path:
    if not path.is_absolute():
        raise AgentError("managed_codex_runner_metadata_invalid")
    current = path
    for _ in range(_MANAGED_CODEX_MAX_SYMLINKS + 1):
        try:
            metadata = current.lstat()
        except OSError as exc:
            raise AgentError("managed_codex_runner_metadata_invalid") from exc
        if not stat_module.S_ISLNK(metadata.st_mode):
            break
        if metadata.st_uid != 0:
            raise AgentError("managed_codex_runner_metadata_invalid")
        try:
            target = os.readlink(current)
        except OSError as exc:
            raise AgentError("managed_codex_runner_metadata_invalid") from exc
        current = Path(
            os.path.abspath(
                target if os.path.isabs(target) else current.parent / target
            )
        )
    else:
        raise AgentError("managed_codex_runner_metadata_invalid")
    try:
        final = current.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if (
        current.name != "codex.js"
        or not stat_module.S_ISREG(final.st_mode)
        or getattr(final, "st_nlink", 1) != 1
        or final.st_uid != 0
        or final.st_mode & 0o022
        or final.st_mode & 0o111 == 0
        or not directory_chain_is_real_no_symlink(path.parent)
        or not directory_chain_is_real_no_symlink(current.parent)
        or not executable_directory_chain_is_trusted(path.parent)
        or not executable_directory_chain_is_trusted(current.parent)
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    return current


def _managed_codex_native_from_launcher(launcher_path: Path) -> Path:
    launcher = _managed_codex_launcher(launcher_path)
    if launcher.parent.name != "bin":
        raise AgentError("managed_codex_runner_metadata_invalid")
    package_root = launcher.parent.parent
    try:
        package_stat = package_root.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if (
        not stat_module.S_ISDIR(package_stat.st_mode)
        or package_stat.st_uid != 0
        or package_stat.st_mode & 0o022
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    package = _read_managed_codex_metadata(package_root / "package.json")
    if package.get("name") != "@openai/codex" or package.get("bin") != {
        "codex": "bin/codex.js"
    }:
        raise AgentError("managed_codex_runner_metadata_invalid")
    package_name, target_triple = _managed_codex_platform_layout()
    optional_dependencies = package.get("optionalDependencies")
    if (
        not isinstance(optional_dependencies, dict)
        or f"@openai/{package_name}" not in optional_dependencies
    ):
        raise AgentError("managed_codex_runner_platform_unsupported")
    candidate_roots = (
        package_root
        / "node_modules"
        / "@openai"
        / package_name
        / "vendor"
        / target_triple,
        package_root / "vendor" / target_triple,
    )
    candidates: list[Path] = []
    for root in candidate_roots:
        candidate = root / "bin" / "codex"
        try:
            candidate.lstat()
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise AgentError("managed_codex_runner_metadata_invalid") from exc
        candidates.append(candidate)
    if not candidates:
        raise AgentError("managed_codex_runner_native_missing")
    if len(candidates) != 1:
        raise AgentError("managed_codex_runner_native_ambiguous")
    native = candidates[0]
    try:
        native.relative_to(package_root)
    except ValueError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    vendor_metadata = _read_managed_codex_metadata(
        native.parents[1] / "codex-package.json"
    )
    if (
        vendor_metadata.get("layoutVersion") != 1
        or vendor_metadata.get("variant") != "codex"
        or vendor_metadata.get("target") != target_triple
        or vendor_metadata.get("entrypoint") != "bin/codex"
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    return native


def _managed_codex_native_snapshot(native: Path) -> os.stat_result:
    try:
        expected = native.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_invalid") from exc
    if (
        stat_module.S_ISLNK(expected.st_mode)
        or not stat_module.S_ISREG(expected.st_mode)
        or getattr(expected, "st_nlink", 1) != 1
        or expected.st_mode & 0o022
        or expected.st_mode & 0o111 == 0
    ):
        raise AgentError("managed_codex_runner_invalid")
    return expected


def _managed_codex_native_path(
    agent: str,
    home: Path,
    wrapper: Path,
    wrapper_snapshot: os.stat_result,
) -> tuple[Path, os.stat_result]:
    home = _managed_codex_home(home)
    wrapper_text = _read_managed_codex_wrapper(wrapper, wrapper_snapshot)
    candidates = _MANAGED_CODEX_BIN_LINE.findall(wrapper_text)
    if not candidates:
        raise AgentError("managed_codex_runner_metadata_missing")
    if len(candidates) != 1:
        raise AgentError("managed_codex_runner_metadata_ambiguous")
    try:
        words = shlex.split(candidates[0], posix=True)
    except ValueError as exc:
        raise AgentError("managed_codex_runner_metadata_invalid") from exc
    if len(words) != 1:
        raise AgentError("managed_codex_runner_metadata_invalid")
    configured = Path(words[0])
    if not configured.is_absolute() or wrapper_text != pool_wrapper_text(
        agent, home, str(configured)
    ):
        raise AgentError("managed_codex_runner_metadata_invalid")
    try:
        configured_stat = configured.lstat()
    except OSError as exc:
        raise AgentError("managed_codex_runner_invalid") from exc
    native = (
        _managed_codex_native_from_launcher(configured)
        if stat_module.S_ISLNK(configured_stat.st_mode) or configured.name == "codex.js"
        else configured
    )
    return native, _managed_codex_native_snapshot(native)


_RUNTIME_CLASS_MARKDOWN_RE = re.compile(r"AGENTS\.class-[a-z0-9][a-z0-9_-]{0,63}\.md\Z")
_FLEET_AGENT_MARKER_BASE_FIELDS = frozenset(
    {
        "schema_version",
        "kind",
        "agent_id",
        "prefix",
        "runner",
        "provider",
        "model",
        "common_policy",
        "managed_files",
        "files",
    }
)
_FLEET_COMMON_POLICY_FIELDS = frozenset({"schema_version", "generation", "digest"})
_FLEET_RUNTIME_SKILL_PROFILE_FIELD = "runtime_skill_profile"


@dataclass(frozen=True, slots=True)
class FleetHomeTarget:
    descriptor: AgentDescriptor
    effective_skill_profile: str
    runtime_skill_profile: str | None
    files: tuple[tuple[str, bytes, int], ...]
    marker_bytes: bytes
    policy_schema_version: int
    policy_generation: int
    common_digest: str
    provider_projection_digest: str
    executable_checks: tuple[tuple[Path, os.stat_result], ...]


@dataclass(frozen=True, slots=True)
class FleetHomePolicyObservation:
    state: Literal["absent", "current", "stale"]
    expected_schema_version: int
    expected_generation: int
    expected_common_digest: str
    expected_provider_projection_digest: str
    observed_schema_version: int | None
    observed_generation: int | None
    observed_common_digest: str | None
    observed_provider_artifact_digest: str | None


def _runtime_class_projection_name(name: str) -> bool:
    return (
        name == "AGENTS.md"
        or _RUNTIME_CLASS_MARKDOWN_RE.fullmatch(name) is not None
        or _portable_skill_projection_name(name)
    )


def _runtime_class_skill_profile(agent_class: str) -> str:
    profile = load_agent_class_catalog(repo_root() / "codex-agent-classes.json").get(
        agent_class
    )
    if profile is None:
        raise AgentError("agent_class_materialization_invalid")
    return "worker" if profile.role_kind == "worker" else profile.class_id


def _known_runtime_skill_profiles(error: str) -> frozenset[str]:
    try:
        profiles = load_agent_class_catalog(
            repo_root() / "codex-agent-classes.json"
        ).values()
        return frozenset(
            "worker" if profile.role_kind == "worker" else profile.class_id
            for profile in profiles
        )
    except Exception as exc:
        raise AgentError(error) from exc


def _fleet_marker_runtime_skill_profile(
    marker: Mapping[str, Any],
    descriptor: AgentDescriptor,
    error: str,
) -> str | None:
    if _FLEET_RUNTIME_SKILL_PROFILE_FIELD not in marker:
        return None
    value = marker[_FLEET_RUNTIME_SKILL_PROFILE_FIELD]
    if value is None:
        return None
    if (
        not isinstance(value, str)
        or value == "generic"
        or descriptor.runner is not RunnerKind.CODEX_CLI
    ):
        raise AgentError(error)
    allowed = _known_runtime_skill_profiles(error)
    if value not in allowed:
        raise AgentError(error)
    return value


def _fleet_marker_common_policy(projection: Any) -> dict[str, Any]:
    metadata = projection.metadata
    return {
        "schema_version": metadata.schema_version,
        "generation": metadata.generation,
        "digest": metadata.common_digest,
    }


def _fleet_validate_agent_marker_shape(
    marker: Any,
    *,
    marker_error: str,
    policy_error: str,
) -> Mapping[str, Any]:
    if not isinstance(marker, dict):
        raise AgentError(marker_error)
    if type(marker.get("schema_version")) is not int or marker["schema_version"] != 2:
        raise AgentError(policy_error)
    if "common_policy" not in marker:
        raise AgentError(policy_error)
    if set(marker) not in {
        _FLEET_AGENT_MARKER_BASE_FIELDS,
        _FLEET_AGENT_MARKER_BASE_FIELDS | {_FLEET_RUNTIME_SKILL_PROFILE_FIELD},
    }:
        raise AgentError(marker_error)
    managed_files = marker.get("managed_files")
    files = marker.get("files")
    if (
        marker.get("kind") != "codex_master_fleet_agent"
        or not isinstance(marker.get("agent_id"), str)
        or not isinstance(marker.get("prefix"), str)
        or not isinstance(marker.get("runner"), str)
        or not isinstance(marker.get("provider"), str)
        or not isinstance(marker.get("model"), str)
        or not isinstance(managed_files, list)
        or not isinstance(files, dict)
        or len(files) > MAX_PORTABLE_SKILLS + 8
        or any(not isinstance(name, str) for name in managed_files)
        or any(not isinstance(name, str) for name in files)
        or managed_files != sorted(files)
        or len(set(managed_files)) != len(managed_files)
    ):
        raise AgentError(marker_error)
    return marker


def _fleet_current_policy_projection(
    marker: Mapping[str, Any],
    descriptor: AgentDescriptor,
    error: str,
) -> Any:
    common_policy = _fleet_marker_common_policy_value(marker, error)
    try:
        projection = fleet_markdown_projection(descriptor)
    except Exception as exc:
        raise AgentError(error) from exc
    if common_policy != _fleet_marker_common_policy(projection):
        raise AgentError(error)
    return projection


def _fleet_marker_common_policy_value(
    marker: Mapping[str, Any],
    error: str,
) -> Mapping[str, Any]:
    common_policy = marker.get("common_policy")
    if (
        not isinstance(common_policy, dict)
        or set(common_policy) != _FLEET_COMMON_POLICY_FIELDS
        or type(common_policy.get("schema_version")) is not int
        or type(common_policy.get("generation")) is not int
        or common_policy["generation"] <= 0
        or not isinstance(common_policy.get("digest"), str)
        or re.fullmatch(r"[0-9a-f]{64}", common_policy["digest"]) is None
    ):
        raise AgentError(error)
    return common_policy


def _fleet_read_current_agent_marker(
    home: Path,
    error: str,
    *,
    missing_ok: bool = False,
) -> tuple[bytes, Mapping[str, Any], Any] | None:
    marker_bytes = fleet_read_optional_private_bytes(
        home / FLEET_AGENT_MARKER_FILE,
        MAX_FLEET_ARTIFACT_BYTES,
        error,
    )
    if marker_bytes is None:
        if missing_ok:
            return None
        raise AgentError(error)
    try:
        payload = json.loads(marker_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AgentError(error) from exc
    marker = _fleet_validate_agent_marker_shape(
        payload,
        marker_error=error,
        policy_error=error,
    )
    descriptor = _fleet_projection_descriptor_from_marker(marker, home, error)
    projection = _fleet_current_policy_projection(marker, descriptor, error)
    provider_bytes = fleet_read_optional_private_bytes(
        home / projection.metadata.provider_artifact_name,
        MAX_FLEET_ARTIFACT_BYTES,
        error,
    )
    if provider_bytes is None or not hmac.compare_digest(
        hashlib.sha256(provider_bytes).hexdigest(),
        projection.metadata.provider_artifact_digest,
    ):
        raise AgentError(error)
    return marker_bytes, marker, projection


def _fleet_effective_runtime_descriptor(
    marker: Mapping[str, Any],
    descriptor: AgentDescriptor,
    error: str,
) -> tuple[AgentDescriptor, str | None]:
    runtime_profile = _fleet_marker_runtime_skill_profile(marker, descriptor, error)
    return (
        dataclass_replace(descriptor, skill_profile=runtime_profile)
        if runtime_profile is not None
        else descriptor,
        runtime_profile,
    )


def _legacy_pool_wrapper_runner(home: Path, text: str) -> Path:
    """Return runner from one exact authorized pool wrapper template."""

    home_text = pool_shell_double_content(str(home))
    prefix = "\n".join(
        [
            "#!/usr/bin/env bash",
            "set -euo pipefail",
            "",
            f'export CODEX_HOME="{home_text}"',
            'if [[ -z "${CODEX_AGENT_BIN:-}" ]]; then',
            "  CODEX_AGENT_BIN=",
        ]
    )
    suffixes = (
        "\n".join(
            [
                "",
                "fi",
                "export CODEX_AGENT_BIN",
                "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
                "if taskset --cpu-list 4-10 /usr/bin/true >/dev/null 2>&1; then",
                '  exec taskset --cpu-list 4-10 /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
                "fi",
                'exec /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
                "",
            ]
        ),
        "\n".join(
            [
                "",
                "fi",
                "export CODEX_AGENT_BIN",
                "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
                'exec "${CODEX_AGENT_BIN}" "$@"',
                "",
            ]
        ),
        "\n".join(
            [
                "",
                "fi",
                "export CODEX_AGENT_BIN",
                "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
                'exec -- "${CODEX_AGENT_BIN}" "$@"',
                "",
            ]
        ),
        "\n".join(
            [
                "",
                "fi",
                "export CODEX_AGENT_BIN",
                "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
                'exec taskset --cpu-list 4-10 /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
                "",
            ]
        ),
    )
    for suffix in suffixes:
        if not text.startswith(prefix) or not text.endswith(suffix):
            continue
        encoded = text[len(prefix) : -len(suffix)]
        try:
            words = shlex.split(encoded, posix=True)
        except ValueError:
            continue
        if len(words) != 1:
            continue
        runner = Path(words[0])
        if runner.is_absolute() and text == prefix + shlex.quote(str(runner)) + suffix:
            return runner

    legacy_prefix = "\n".join(
        [
            "#!/usr/bin/env bash",
            "set -euo pipefail",
            "",
            f'export CODEX_HOME="{home_text}"',
            ': "${CODEX_AGENT_BIN:=',
        ]
    )
    legacy_suffix = "\n".join(
        [
            '}"',
            "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
            'exec "${CODEX_AGENT_BIN}" "$@"',
            "",
        ]
    )
    if text.startswith(legacy_prefix) and text.endswith(legacy_suffix):
        encoded = text[len(legacy_prefix) : -len(legacy_suffix)]
        if re.fullmatch(r"(?:[^\\\"\n]|\\[\\\"$`])*", encoded):
            unescaped = re.sub(r"\\([\\\"$`])", r"\1", encoded)
            runner = Path(unescaped)
            if (
                runner.is_absolute()
                and text
                == legacy_prefix
                + pool_shell_double_content(str(runner))
                + legacy_suffix
            ):
                return runner
    raise AgentError("agent_class_materialization_invalid")


def _home_refresh_text(value: Any, *, field: str, maximum: int) -> str:
    if (
        not isinstance(value, str)
        or not value
        or len(value) > maximum
        or "\x00" in value
        or any(ord(char) < 32 for char in value)
    ):
        raise AgentError("agent_class_materialization_invalid")
    return value


_HOME_REFRESH_PLUGIN_HOOK_ID_RE = re.compile(
    r"(?P<plugin>[a-z0-9][a-z0-9_-]{0,63})@"
    r"(?P<source>[a-z0-9][a-z0-9_-]{0,63}):"
    r"hooks/hooks\.json:"
    r"(?P<event>[a-z][a-z0-9_]{0,63}):"
    r"(?P<group>0|[1-9][0-9]{0,3}):"
    r"(?P<handler>0|[1-9][0-9]{0,3})"
)
_HOME_REFRESH_PLUGIN_EVENT_NAMES = MappingProxyType(
    {
        "session_start": "SessionStart",
        "stop": "Stop",
    }
)


def _home_refresh_open_trusted_directory_at(parent_fd: int, name: str) -> int:
    current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if (
        not stat_module.S_ISDIR(current.st_mode)
        or current.st_uid not in {0, os.geteuid()}
        or current.st_mode & 0o022
        or current.st_mode & 0o500 != 0o500
    ):
        raise AgentError("agent_class_materialization_invalid")
    return open_directory_no_follow_matching(
        name,
        current,
        error_text="agent_class_materialization_invalid",
        changed_text="agent_class_materialization_invalid",
        dir_fd=parent_fd,
    )


def _home_refresh_read_trusted_json_at(parent_fd: int, name: str) -> dict[str, Any]:
    current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if (
        not stat_module.S_ISREG(current.st_mode)
        or getattr(current, "st_nlink", 1) != 1
        or current.st_uid not in {0, os.geteuid()}
        or current.st_mode & 0o022
        or current.st_mode & 0o444 == 0
        or current.st_size > MAX_PLUGIN_MANIFEST_BYTES
    ):
        raise AgentError("agent_class_materialization_invalid")
    parent = Path(f"/proc/self/fd/{parent_fd}")
    text = read_private_regular_text(
        parent / name,
        MAX_PLUGIN_MANIFEST_BYTES,
        "agent_class_materialization_invalid",
        expected_parent_stat=parent.lstat(),
        expected_target_stat=current,
    )
    after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if not source_identity_with_snapshot_matches(after, current):
        raise AgentError("agent_class_materialization_invalid")
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        raise AgentError("agent_class_materialization_invalid") from None
    if not isinstance(payload, dict):
        raise AgentError("agent_class_materialization_invalid")
    return payload


def _home_refresh_plugin_hook_hash(
    event: str,
    group: dict[str, Any],
    handler: dict[str, Any],
) -> str:
    if event == "session_start":
        if set(group) != {"matcher", "hooks"} or set(handler) != {
            "type",
            "command",
            "commandWindows",
            "timeout",
            "statusMessage",
        }:
            raise AgentError("agent_class_materialization_invalid")
        matcher = _home_refresh_text(group["matcher"], field="matcher", maximum=1024)
        status_message = _home_refresh_text(
            handler["statusMessage"],
            field="statusMessage",
            maximum=1024,
        )
    elif event == "stop":
        if set(group) != {"hooks"} or set(handler) != {
            "type",
            "command",
            "commandWindows",
            "timeout",
        }:
            raise AgentError("agent_class_materialization_invalid")
        matcher = None
        status_message = None
    else:
        raise AgentError("agent_class_materialization_invalid")
    command = _home_refresh_text(handler["command"], field="command", maximum=4096)
    _home_refresh_text(handler["commandWindows"], field="commandWindows", maximum=4096)
    timeout = handler["timeout"]
    if (
        handler["type"] != "command"
        or type(timeout) is not int
        or not 0 <= timeout <= 86_400
    ):
        raise AgentError("agent_class_materialization_invalid")
    normalized_handler: dict[str, Any] = {
        "type": "command",
        "command": command,
        "timeout": max(timeout, 1),
        "async": False,
    }
    if status_message is not None:
        normalized_handler["statusMessage"] = status_message
    identity: dict[str, Any] = {
        "event_name": event,
        "hooks": [normalized_handler],
    }
    if matcher is not None:
        identity["matcher"] = matcher
    canonical = json.dumps(
        identity,
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(canonical).hexdigest()


def _home_refresh_authorize_plugin_hook(
    match: re.Match[str],
    trusted_hash: str,
) -> None:
    fds: list[int] = []
    try:
        cache_root = codex_plugin_cache_root().parents[1]
        if not directory_chain_is_real_no_symlink(
            cache_root
        ) or not executable_directory_chain_is_trusted(cache_root):
            raise AgentError("agent_class_materialization_invalid")
        cache_stat = cache_root.lstat()
        cache_fd = open_directory_chain_no_follow_matching(
            cache_root,
            cache_stat,
            error_text="agent_class_materialization_invalid",
            changed_text="agent_class_materialization_invalid",
        )
        fds.append(cache_fd)
        source_fd = _home_refresh_open_trusted_directory_at(cache_fd, match["source"])
        fds.append(source_fd)
        plugin_fd = _home_refresh_open_trusted_directory_at(source_fd, match["plugin"])
        fds.append(plugin_fd)

        entries = sorted(os.listdir(plugin_fd))
        marker_name = ".codex-remote-plugin-install.json"
        version_names = [name for name in entries if name != marker_name]
        if (
            len(version_names) != 1
            or PLUGIN_VERSION_RE.fullmatch(version_names[0]) is None
        ):
            raise AgentError("agent_class_materialization_invalid")
        marker = _home_refresh_read_trusted_json_at(plugin_fd, marker_name)
        if (
            set(marker) != {"schema_version", "remote_plugin_id"}
            or marker["schema_version"] != 1
            or not isinstance(marker["remote_plugin_id"], str)
            or re.fullmatch(r"plugins_[0-9a-f]{32}", marker["remote_plugin_id"]) is None
        ):
            raise AgentError("agent_class_materialization_invalid")

        version = version_names[0]
        version_fd = _home_refresh_open_trusted_directory_at(plugin_fd, version)
        fds.append(version_fd)
        plugin_manifest_fd = _home_refresh_open_trusted_directory_at(
            version_fd, ".codex-plugin"
        )
        fds.append(plugin_manifest_fd)
        plugin_manifest = _home_refresh_read_trusted_json_at(
            plugin_manifest_fd, "plugin.json"
        )
        if (
            plugin_manifest.get("name") != match["plugin"]
            or plugin_manifest.get("version") != version
        ):
            raise AgentError("agent_class_materialization_invalid")

        hooks_fd = _home_refresh_open_trusted_directory_at(version_fd, "hooks")
        fds.append(hooks_fd)
        if os.listdir(hooks_fd) != ["hooks.json"]:
            raise AgentError("agent_class_materialization_invalid")
        hook_manifest = _home_refresh_read_trusted_json_at(hooks_fd, "hooks.json")
        if set(hook_manifest) != {"hooks"} or not isinstance(
            hook_manifest["hooks"], dict
        ):
            raise AgentError("agent_class_materialization_invalid")
        manifest_event = _HOME_REFRESH_PLUGIN_EVENT_NAMES.get(match["event"])
        groups = (
            hook_manifest["hooks"].get(manifest_event)
            if manifest_event is not None
            else None
        )
        if not isinstance(groups, list):
            raise AgentError("agent_class_materialization_invalid")
        group_index = int(match["group"])
        handler_index = int(match["handler"])
        if group_index >= len(groups) or not isinstance(groups[group_index], dict):
            raise AgentError("agent_class_materialization_invalid")
        group = groups[group_index]
        handlers = group.get("hooks")
        if (
            not isinstance(handlers, list)
            or handler_index >= len(handlers)
            or not isinstance(handlers[handler_index], dict)
        ):
            raise AgentError("agent_class_materialization_invalid")
        derived_hash = _home_refresh_plugin_hook_hash(
            match["event"],
            group,
            handlers[handler_index],
        )
        if not hmac.compare_digest(derived_hash, trusted_hash):
            raise AgentError("agent_class_materialization_invalid")
    except (AgentError, IndexError, OSError, TypeError, ValueError):
        raise AgentError("agent_class_materialization_invalid") from None
    finally:
        for fd in reversed(fds):
            os.close(fd)


def _home_refresh_config(
    home: Path,
    data: bytes,
    *,
    model: Any,
    reasoning_effort: Any,
) -> bytes:
    """Keep narrow user trust state while restoring Fleet-owned Codex settings."""

    try:
        document = tomllib.loads(data.decode("utf-8"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError):
        raise AgentError("agent_class_materialization_invalid") from None
    if not isinstance(document, dict) or set(document) - {
        "model_catalog_json",
        "service_tier",
        "model",
        "model_reasoning_effort",
        "approval_policy",
        "sandbox_mode",
        "tui",
        "projects",
        "hooks",
    }:
        raise AgentError("agent_class_materialization_invalid")
    catalog = document.get("model_catalog_json")
    if catalog is not None:
        catalog = _home_refresh_text(
            catalog, field="model_catalog_json", maximum=MAX_PATH_TEXT
        )
        if not Path(catalog).is_absolute():
            raise AgentError("agent_class_materialization_invalid")
    tier = document.get("service_tier")
    if tier is not None and (
        not isinstance(tier, str)
        or re.fullmatch(r"[a-z][a-z0-9_-]{0,31}", tier) is None
    ):
        raise AgentError("agent_class_materialization_invalid")
    for field, maximum in (
        ("model", 128),
        ("approval_policy", 64),
        ("sandbox_mode", 64),
    ):
        if field in document:
            _home_refresh_text(document[field], field=field, maximum=maximum)
    if "model_reasoning_effort" in document and document[
        "model_reasoning_effort"
    ] not in {
        "low",
        "medium",
        "high",
        "xhigh",
        "max",
    }:
        raise AgentError("agent_class_materialization_invalid")
    tui = document.get("tui", {})
    if (
        not isinstance(tui, dict)
        or set(tui) - {"animations"}
        or ("animations" in tui and type(tui["animations"]) is not bool)
    ):
        raise AgentError("agent_class_materialization_invalid")
    projects = document.get("projects", {})
    if not isinstance(projects, dict):
        raise AgentError("agent_class_materialization_invalid")
    preserved_projects: set[str] = set()
    for path, state in projects.items():
        if (
            not isinstance(path, str)
            or not Path(path).is_absolute()
            or not isinstance(state, dict)
            or state != {"trust_level": "trusted"}
        ):
            raise AgentError("agent_class_materialization_invalid")
        preserved_projects.add(path)
    hooks = document.get("hooks")
    hook_state: dict[str, str | dict[str, str]] = {}
    if hooks is not None:
        if (
            not isinstance(hooks, dict)
            or set(hooks) != {"state"}
            or not isinstance(hooks["state"], dict)
        ):
            raise AgentError("agent_class_materialization_invalid")
        for hook_id, value in hooks["state"].items():
            plugin_match: re.Match[str] | None = None
            if hook_id == "trusted_hash":
                hash_value = value
            elif (
                isinstance(hook_id, str)
                and len(hook_id) <= 128
                and isinstance(value, dict)
                and set(value) == {"trusted_hash"}
            ):
                plugin_match = _HOME_REFRESH_PLUGIN_HOOK_ID_RE.fullmatch(hook_id)
                if (
                    re.fullmatch(r"[A-Za-z0-9_-]{1,128}", hook_id) is None
                    and plugin_match is None
                ):
                    raise AgentError("agent_class_materialization_invalid")
                hash_value = value["trusted_hash"]
            else:
                raise AgentError("agent_class_materialization_invalid")
            if (
                not isinstance(hash_value, str)
                or re.fullmatch(r"sha256:[0-9a-f]{64}", hash_value) is None
            ):
                raise AgentError("agent_class_materialization_invalid")
            if plugin_match is not None:
                _home_refresh_authorize_plugin_hook(plugin_match, hash_value)
            hook_state[hook_id] = (
                hash_value
                if hook_id == "trusted_hash"
                else {"trusted_hash": hash_value}
            )

    current_model = _home_refresh_text(model, field="model", maximum=128)
    if reasoning_effort not in {"low", "medium", "high", "xhigh", "max"}:
        raise AgentError("agent_class_materialization_invalid")
    preserved_projects.discard(str(home))
    lines = []
    if catalog is not None:
        lines.append(f"model_catalog_json = {json.dumps(catalog)}")
    if tier is not None:
        lines.append(f"service_tier = {json.dumps(tier)}")
    lines.extend(
        [
            f"model = {json.dumps(current_model)}",
            f"model_reasoning_effort = {json.dumps(reasoning_effort)}",
            'approval_policy = "never"',
            'sandbox_mode = "danger-full-access"',
            "",
            "[tui]",
            "animations = false",
        ]
    )
    for path in sorted((*preserved_projects, str(home))):
        lines.extend(["", f"[projects.{json.dumps(path)}]", 'trust_level = "trusted"'])
    if hooks is not None:
        lines.extend(["", "[hooks.state]"])
        if "trusted_hash" in hook_state:
            lines.append(f"trusted_hash = {json.dumps(hook_state['trusted_hash'])}")
        for hook_id in sorted(key for key in hook_state if key != "trusted_hash"):
            value = hook_state[hook_id]
            serialized_hook_id = (
                hook_id
                if re.fullmatch(r"[A-Za-z0-9_-]{1,128}", hook_id) is not None
                else json.dumps(hook_id)
            )
            lines.extend(
                [
                    "",
                    f"[hooks.state.{serialized_hook_id}]",
                    f"trusted_hash = {json.dumps(value['trusted_hash'])}",
                ]
            )
    return ("\n".join((*lines, ""))).encode("utf-8")


def _materialize_managed_codex_runtime_class(
    descriptor: AgentDescriptor,
    agent_class: str,
    *,
    expected_pool_parent_stat: os.stat_result,
    expected_pool_root_stat: os.stat_result,
    expected_home_stat: os.stat_result,
    confirm_home_refresh: bool = False,
    model_reasoning_effort: str | None = None,
) -> bool:
    """Project resolver-selected class context into one stopped, pinned Fleet home."""

    if (
        descriptor.runner is not RunnerKind.CODEX_CLI
        or descriptor.home != AGENT_POOL_ROOT / descriptor.agent_id
        or type(confirm_home_refresh) is not bool
    ):
        raise AgentError("agent_class_materialization_invalid")
    runtime_profile = _runtime_class_skill_profile(agent_class)
    projected = dataclass_replace(descriptor, skill_profile=runtime_profile)
    desired = fleet_markdown_artifacts(projected)
    if runtime_profile != "generic":
        desired.update(portable_gemini_skill_artifacts(runtime_profile))
    if (
        not desired
        or len(desired) > MAX_PORTABLE_SKILLS + 2
        or any(not _runtime_class_projection_name(name) for name in desired)
    ):
        raise AgentError("agent_class_materialization_invalid")

    journal: list[dict[str, Any]] = []

    def replace_at(
        home_fd: int,
        name: str,
        data: bytes,
        expected: os.stat_result | None,
        mode: int = 0o600,
    ) -> os.stat_result:
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        try:
            replace_private_bytes(
                Path(f"/proc/self/fd/{parent_fd}") / basename,
                data,
                mode=mode,
                expected_existing_stat=expected,
            )
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            if (
                not stat_module.S_ISREG(current.st_mode)
                or getattr(current, "st_nlink", 1) != 1
                or current.st_uid != os.geteuid()
                or stat_module.S_IMODE(current.st_mode) != mode
            ):
                raise AgentError("agent_class_materialization_changed")
            return current
        except AgentError:
            raise
        except OSError as exc:
            raise AgentError("agent_class_materialization_changed") from exc
        finally:
            os.close(parent_fd)

    def optional_file_at(
        home_fd: int,
        name: str,
        mode: int,
    ) -> tuple[bytes, os.stat_result] | None:
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        try:
            try:
                os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return None
        finally:
            os.close(parent_fd)
        return _fleet_read_private_file_at(
            home_fd,
            name,
            mode,
            "agent_class_materialization_changed",
        )

    def optional_directory_at(home_fd: int, name: str) -> os.stat_result | None:
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        try:
            try:
                current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return None
            _fleet_private_directory_stat(
                current, "agent_class_materialization_changed"
            )
            return current
        finally:
            os.close(parent_fd)

    def ensure_directory_at(home_fd: int, name: str) -> None:
        current = optional_directory_at(home_fd, name)
        if current is not None:
            return
        journal.append({"kind": "directory_create", "name": name})
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        child_fd = -1
        try:
            os.mkdir(basename, 0o700, dir_fd=parent_fd)
            os.fsync(parent_fd)
            child_fd = open_directory_no_follow_matching(
                basename,
                os.stat(basename, dir_fd=parent_fd, follow_symlinks=False),
                error_text="agent_class_materialization_changed",
                changed_text="agent_class_materialization_changed",
                dir_fd=parent_fd,
            )
            _fleet_private_directory_stat(
                os.fstat(child_fd),
                "agent_class_materialization_changed",
            )
        finally:
            if child_fd >= 0:
                os.close(child_fd)
            os.close(parent_fd)

    def remove_empty_directory_at(home_fd: int, name: str) -> None:
        current = optional_directory_at(home_fd, name)
        if current is None:
            return
        entry = {"kind": "directory_remove", "name": name, "before_stat": current}
        journal.append(entry)
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        try:
            try:
                os.rmdir(basename, dir_fd=parent_fd)
            except OSError as exc:
                if exc.errno in {errno.ENOTEMPTY, errno.EEXIST}:
                    journal.pop()
                    return
                raise
            os.fsync(parent_fd)
            try:
                os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return
            raise AgentError("agent_class_materialization_changed")
        finally:
            os.close(parent_fd)

    def journal_file(
        name: str,
        before_data: bytes | None,
        before_stat: os.stat_result | None,
        after_data: bytes | None,
        mode: int = 0o600,
    ) -> None:
        journal.append(
            {
                "kind": "file",
                "name": name,
                "before_data": before_data,
                "before_stat": before_stat,
                "after_data": after_data,
                "mode": mode,
            }
        )

    def unlink_at(home_fd: int, name: str, expected: os.stat_result) -> None:
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_changed",
        )
        try:
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            if (
                not source_identity_with_snapshot_matches(current, expected)
                or not stat_module.S_ISREG(current.st_mode)
                or getattr(current, "st_nlink", 1) != 1
            ):
                raise AgentError("agent_class_materialization_changed")
            os.unlink(basename, dir_fd=parent_fd)
            os.fsync(parent_fd)
        except AgentError:
            raise
        except OSError as exc:
            raise AgentError("agent_class_materialization_changed") from exc
        finally:
            os.close(parent_fd)

    def rollback_file(home_fd: int, entry: Mapping[str, Any]) -> None:
        name = str(entry["name"])
        mode = int(entry["mode"])
        before_data = entry["before_data"]
        before_stat = entry["before_stat"]
        after_data = entry["after_data"]
        current = optional_file_at(home_fd, name, mode)
        if before_data is not None and current is not None:
            current_data, current_stat = current
            if (
                current_data == before_data
                and before_stat is not None
                and source_identity_with_snapshot_matches(current_stat, before_stat)
            ):
                return
        if after_data is None:
            if current is not None or before_data is None:
                if current is None and before_data is None:
                    return
                raise AgentError("agent_class_materialization_rollback_failed")
            replace_at(home_fd, name, before_data, None, mode=mode)
            return
        if current is None or current[0] != after_data:
            if current is None and before_data is None:
                return
            raise AgentError("agent_class_materialization_rollback_failed")
        if before_data is None:
            unlink_at(home_fd, name, current[1])
        else:
            replace_at(home_fd, name, before_data, current[1], mode=mode)

    def rollback_directory(home_fd: int, entry: Mapping[str, Any]) -> None:
        name = str(entry["name"])
        current = optional_directory_at(home_fd, name)
        if entry["kind"] == "directory_remove":
            before_stat = entry["before_stat"]
            if current is not None:
                if source_identity_with_snapshot_matches(current, before_stat):
                    return
                raise AgentError("agent_class_materialization_rollback_failed")
            parent_fd, basename = _fleet_open_artifact_parent(
                home_fd,
                name,
                create=False,
                error="agent_class_materialization_rollback_failed",
            )
            try:
                os.mkdir(basename, 0o700, dir_fd=parent_fd)
                os.fsync(parent_fd)
            finally:
                os.close(parent_fd)
            return
        if current is None:
            return
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error="agent_class_materialization_rollback_failed",
        )
        child_fd = -1
        try:
            child_fd = open_directory_no_follow_matching(
                basename,
                current,
                error_text="agent_class_materialization_rollback_failed",
                changed_text="agent_class_materialization_rollback_failed",
                dir_fd=parent_fd,
            )
            if os.listdir(child_fd):
                raise AgentError("agent_class_materialization_rollback_failed")
            os.close(child_fd)
            child_fd = -1
            os.rmdir(basename, dir_fd=parent_fd)
            os.fsync(parent_fd)
        finally:
            if child_fd >= 0:
                os.close(child_fd)
            os.close(parent_fd)

    def rollback(home_fd: int) -> bool:
        restored = True
        for entry in reversed(journal):
            try:
                if entry["kind"] == "file":
                    rollback_file(home_fd, entry)
                else:
                    rollback_directory(home_fd, entry)
            except BaseException:
                restored = False
        return restored

    with (
        pool_root_lock(AGENT_POOL_ROOT),
        pool_root_operation(
            AGENT_POOL_ROOT,
            ensure=False,
            error_text="agent_class_materialization_changed",
            expected_parent_stat=expected_pool_parent_stat,
            expected_root_stat=expected_pool_root_stat,
            require_private=True,
        ) as root,
    ):
        root_fd = -1
        home_fd = -1
        try:
            root_fd = open_directory_no_follow_matching(
                root,
                expected_pool_root_stat,
                error_text="agent_class_materialization_changed",
                changed_text="agent_class_materialization_changed",
            )
            home_fd = open_directory_no_follow_matching(
                descriptor.agent_id,
                expected_home_stat,
                error_text="agent_class_materialization_changed",
                changed_text="agent_class_materialization_changed",
                dir_fd=root_fd,
            )
            _fleet_private_directory_stat(
                os.fstat(home_fd),
                "agent_class_materialization_changed",
            )
            marker_bytes, marker_stat = _fleet_read_private_file_at(
                home_fd,
                FLEET_AGENT_MARKER_FILE,
                0o600,
                "agent_class_materialization_invalid",
            )
            try:
                marker = json.loads(marker_bytes.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                raise AgentError("agent_class_materialization_invalid") from None
            marker = _fleet_validate_agent_marker_shape(
                marker,
                marker_error="agent_class_materialization_invalid",
                policy_error="agent_class_materialization_invalid",
            )
            marker_files = marker["files"]
            if (
                marker.get("agent_id") != descriptor.agent_id
                or marker.get("prefix") != descriptor.series_prefix
                or marker.get("runner") != descriptor.runner.value
                or marker.get("provider") != descriptor.provider.value
            ):
                raise AgentError("agent_class_materialization_invalid")

            legacy_marker = (
                _FLEET_RUNTIME_SKILL_PROFILE_FIELD not in marker
                and marker.get("model") != descriptor.model
            )
            projection: dict[str, tuple[bytes, os.stat_result]] = {}
            managed_projection: dict[str, tuple[bytes, os.stat_result]] = {}
            digest_drift: set[str] = set()
            for name, digest in marker_files.items():
                if (
                    not _fleet_managed_name(name)
                    or not isinstance(digest, str)
                    or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                ):
                    raise AgentError("agent_class_materialization_invalid")
                mode = 0o700 if name == "codex" else 0o600
                content, current_stat = _fleet_read_private_file_at(
                    home_fd,
                    name,
                    mode,
                    "agent_class_materialization_invalid",
                )
                if not hmac.compare_digest(hashlib.sha256(content).hexdigest(), digest):
                    digest_drift.add(name)
                managed_projection[name] = (content, current_stat)
                if _runtime_class_projection_name(name):
                    projection[name] = (content, current_stat)

            if not legacy_marker and digest_drift:
                raise AgentError("agent_class_materialization_invalid")
            if legacy_marker:
                if (
                    "codex" not in managed_projection
                    or "config.toml" not in managed_projection
                    or digest_drift - {"codex", "config.toml"}
                ):
                    raise AgentError("agent_class_materialization_invalid")
                current_descriptor = _fleet_projection_descriptor_from_marker(
                    marker,
                    descriptor.home,
                    "agent_class_materialization_invalid",
                )
            else:
                current_descriptor, _current_runtime_profile = (
                    _fleet_effective_runtime_descriptor(
                        marker,
                        descriptor,
                        "agent_class_materialization_invalid",
                    )
                )
                if marker.get("model") != descriptor.model:
                    raise AgentError("agent_class_materialization_invalid")
            policy_projection = _fleet_current_policy_projection(
                marker,
                current_descriptor,
                "agent_class_materialization_invalid",
            )
            provider_artifact = projection.get(
                policy_projection.metadata.provider_artifact_name
            )
            if provider_artifact is None or not hmac.compare_digest(
                hashlib.sha256(provider_artifact[0]).hexdigest(),
                policy_projection.metadata.provider_artifact_digest,
            ):
                raise AgentError("agent_class_materialization_invalid")
            current_markdown = set(policy_projection.artifacts)
            marker_markdown = {
                name
                for name in projection
                if name == "AGENTS.md"
                or _RUNTIME_CLASS_MARKDOWN_RE.fullmatch(name) is not None
            }
            if marker_markdown != current_markdown:
                raise AgentError("agent_class_materialization_invalid")

            refreshed_config: bytes | None = None
            if legacy_marker:
                if _fleet_tmux_state(descriptor.session) != "stopped":
                    raise AgentError("agent_class_materialization_invalid")
                process_summary = agent_home_process_summary(descriptor.agent_id)
                if process_summary.get("process_count") != 0:
                    raise AgentError("agent_class_materialization_invalid")

                codex_runtime_directories = _FLEET_CODEX_RUNTIME_DIRECTORIES
                with _fleet_pinned_shared_runtime_symlinks(
                    root,
                    descriptor,
                    "fleet_home_content_invalid",
                ) as codex_runtime_symlinks:
                    actual_files, actual_directories, actual_symlinks = (
                        _fleet_tree_entries(
                            home_fd,
                            "fleet_home_content_invalid",
                            allow_gemini_runtime=True,
                            opaque_runtime_directories=codex_runtime_directories,
                            allowed_runtime_symlinks=codex_runtime_symlinks,
                        )
                    )
                    runtime_regular_files = {
                        path
                        for path in actual_files
                        if path in _FLEET_CODEX_RUNTIME_FILES
                        or _FLEET_CODEX_RUNTIME_DATABASE_RE.fullmatch(path) is not None
                    }
                    for path in runtime_regular_files:
                        _fleet_codex_runtime_regular_file_stat(
                            home_fd,
                            path,
                            "fleet_home_content_invalid",
                        )
                    allowed_files = {
                        FLEET_AGENT_MARKER_FILE,
                        *marker_files,
                        "auth.json",
                        ".gemini/projects.json",
                        "settings.json",
                    }
                    expected_directories = _fleet_artifact_directories(
                        {name: None for name in marker_files}
                    )
                    runtime_files = runtime_regular_files | set(actual_symlinks)
                    runtime_directories = actual_directories & set(
                        codex_runtime_directories
                    )
                    if (
                        not (actual_files | set(actual_symlinks))
                        <= allowed_files | runtime_files
                        or actual_directories
                        != expected_directories | runtime_directories
                    ):
                        raise AgentError("fleet_home_content_invalid")
                    _fleet_revalidate_symlink_snapshots(
                        home_fd,
                        actual_symlinks,
                        "fleet_home_content_invalid",
                    )

                if digest_drift:
                    _legacy_pool_wrapper_runner(
                        descriptor.home,
                        managed_projection["codex"][0].decode("utf-8"),
                    )
                    refreshed_config = _home_refresh_config(
                        descriptor.home,
                        managed_projection["config.toml"][0],
                        model=descriptor.model,
                        reasoning_effort=model_reasoning_effort,
                    )
                    if not confirm_home_refresh:
                        raise AgentError("agent_home_refresh_confirmation_required")

            next_digests = {
                name: digest
                for name, digest in marker_files.items()
                if not _runtime_class_projection_name(name)
            }
            if legacy_marker and digest_drift:
                next_digests["codex"] = hashlib.sha256(
                    managed_projection["codex"][0]
                ).hexdigest()
                next_digests["config.toml"] = hashlib.sha256(
                    refreshed_config
                    if refreshed_config is not None
                    else managed_projection["config.toml"][0]
                ).hexdigest()
            next_digests.update(
                {
                    name: hashlib.sha256(content).hexdigest()
                    for name, content in desired.items()
                }
            )
            next_marker = dict(marker)
            next_marker["model"] = descriptor.model
            next_marker["managed_files"] = sorted(next_digests)
            next_marker["files"] = {
                name: next_digests[name] for name in sorted(next_digests)
            }
            next_runtime_profile = (
                None if runtime_profile == descriptor.skill_profile else runtime_profile
            )
            if legacy_marker:
                next_marker[_FLEET_RUNTIME_SKILL_PROFILE_FIELD] = runtime_profile
            elif (
                _FLEET_RUNTIME_SKILL_PROFILE_FIELD in marker
                or next_runtime_profile is not None
            ):
                next_marker[_FLEET_RUNTIME_SKILL_PROFILE_FIELD] = next_runtime_profile
            next_marker_bytes = (
                json.dumps(next_marker, indent=2, sort_keys=True) + "\n"
            ).encode("utf-8")
            stale = set(projection) - set(desired)
            current_directories = _fleet_artifact_directories(projection)
            desired_directories = _fleet_artifact_directories(desired)
            if (
                not stale
                and marker_bytes == next_marker_bytes
                and all(
                    projection.get(name, (None, None))[0] == content
                    for name, content in desired.items()
                )
            ):
                _fleet_managed_home_state(
                    AGENT_POOL_ROOT,
                    descriptor,
                    strict_contents=True,
                )
                return False

            try:
                if refreshed_config is not None:
                    old_config, old_config_stat = managed_projection["config.toml"]
                    if old_config != refreshed_config:
                        journal_file(
                            "config.toml",
                            old_config,
                            old_config_stat,
                            refreshed_config,
                        )
                        replace_at(
                            home_fd,
                            "config.toml",
                            refreshed_config,
                            old_config_stat,
                        )
                for name in sorted(
                    desired_directories, key=lambda item: (len(Path(item).parts), item)
                ):
                    ensure_directory_at(home_fd, name)
                for name, content in sorted(desired.items()):
                    old = projection.get(name)
                    if old is not None and old[0] == content:
                        continue
                    journal_file(
                        name,
                        old[0] if old is not None else None,
                        old[1] if old is not None else None,
                        content,
                        mode=0o700 if name == "codex" else 0o600,
                    )
                    replace_at(
                        home_fd,
                        name,
                        content,
                        old[1] if old is not None else None,
                        mode=0o700 if name == "codex" else 0o600,
                    )
                for name in sorted(stale):
                    old_content, old_stat = projection[name]
                    journal_file(name, old_content, old_stat, None)
                    unlink_at(home_fd, name, old_stat)
                for name in sorted(
                    current_directories - desired_directories,
                    key=lambda item: (-len(Path(item).parts), item),
                ):
                    remove_empty_directory_at(home_fd, name)
                journal_file(
                    FLEET_AGENT_MARKER_FILE,
                    marker_bytes,
                    marker_stat,
                    next_marker_bytes,
                )
                replace_at(
                    home_fd,
                    FLEET_AGENT_MARKER_FILE,
                    next_marker_bytes,
                    marker_stat,
                )
                for name, digest in next_marker["files"].items():
                    mode = 0o700 if name == "codex" else 0o600
                    content, _current_stat = _fleet_read_private_file_at(
                        home_fd,
                        name,
                        mode,
                        "agent_class_materialization_changed",
                    )
                    if not hmac.compare_digest(
                        hashlib.sha256(content).hexdigest(), digest
                    ):
                        raise AgentError("agent_class_materialization_changed")
                verified_marker, _verified_marker_stat = _fleet_read_private_file_at(
                    home_fd,
                    FLEET_AGENT_MARKER_FILE,
                    0o600,
                    "agent_class_materialization_changed",
                )
                if verified_marker != next_marker_bytes:
                    raise AgentError("agent_class_materialization_changed")
                _fleet_managed_home_state(
                    AGENT_POOL_ROOT,
                    descriptor,
                    strict_contents=False,
                )
            except BaseException as exc:
                if not rollback(home_fd):
                    raise AgentError(
                        "agent_class_materialization_rollback_failed"
                    ) from exc
                if isinstance(exc, AgentError):
                    raise
                if isinstance(exc, (KeyboardInterrupt, SystemExit)):
                    raise
                raise AgentError("agent_class_materialization_failed") from exc
            return True
        except AgentError:
            raise
        except OSError as exc:
            raise AgentError("agent_class_materialization_changed") from exc
        finally:
            if home_fd >= 0:
                os.close(home_fd)
            if root_fd >= 0:
                os.close(root_fd)


def open_runner_execution_path(
    agent: str,
    path: Path,
    expected_stat: os.stat_result,
    *,
    require_elf: bool = False,
    error_code: str = "runner changed unexpectedly",
) -> RunnerExecutionTargetV1:
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise AgentError(error_code) from exc
    try:
        opened_stat = os.fstat(fd)
        current_stat = path.lstat()
        if (
            not stat_module.S_ISREG(opened_stat.st_mode)
            or getattr(opened_stat, "st_nlink", 1) != 1
            or opened_stat.st_mode & 0o022
            or not stat_module.S_ISREG(current_stat.st_mode)
            or getattr(current_stat, "st_nlink", 1) != 1
            or current_stat.st_mode & 0o022
            or not source_identity_with_snapshot_matches(opened_stat, expected_stat)
            or not source_identity_with_snapshot_matches(current_stat, expected_stat)
            or not os.access(Path(f"/proc/{os.getpid()}/fd/{fd}"), os.X_OK)
        ):
            raise AgentError(error_code)
        if require_elf:
            magic = os.pread(fd, len(_MANAGED_CODEX_ELF_MAGIC), 0)
            if (
                opened_stat.st_mode & 0o022
                or opened_stat.st_mode & 0o111 == 0
                or magic != _MANAGED_CODEX_ELF_MAGIC
            ):
                raise AgentError("managed_codex_runner_invalid")
        close_runner_execution_fd(agent)
        RUNNER_EXECUTION_FDS[agent] = fd
        return RunnerExecutionTargetV1(
            owner_pid=os.getpid(),
            fd=fd,
            device=opened_stat.st_dev,
            inode=opened_stat.st_ino,
        )
    except OSError as exc:
        with contextlib.suppress(OSError):
            os.close(fd)
        raise AgentError(error_code) from exc
    except Exception:
        with contextlib.suppress(OSError):
            os.close(fd)
        raise


def is_regular_file_no_symlink(path: Path) -> bool:
    try:
        current = path.lstat()
    except OSError:
        return False
    return stat_module.S_ISREG(current.st_mode) and getattr(current, "st_nlink", 1) == 1


def auth_access_token_state(value: Any) -> str:
    if not isinstance(value, str) or not value:
        return "missing"
    parts = value.split(".")
    if len(parts) != 3:
        return "opaque"
    payload = parts[1].replace("-", "+").replace("_", "/")
    payload += "=" * (-len(payload) % 4)
    try:
        decoded = base64.b64decode(payload, validate=True)
        claims = json.loads(decoded.decode("utf-8"))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError, RecursionError):
        return "opaque"
    if not isinstance(claims, dict):
        return "opaque"
    expiry = claims.get("exp")
    if isinstance(expiry, bool) or not isinstance(expiry, (int, float)):
        return "opaque"
    if isinstance(expiry, float) and not math.isfinite(expiry):
        return "opaque"
    return "expired" if expiry <= time.time() else "unexpired"


def agent_auth_status(
    agent: str,
    snapshot: InventorySnapshot | None = None,
) -> dict[str, Any]:
    inventory = snapshot or current_agent_inventory()
    agent = canonical_agent_id(agent, snapshot=inventory)
    auth_file = agent_config(agent, inventory)["home"] / "auth.json"
    token_state = "unknown"
    auth_mode = "unknown"
    try:
        auth_stat = auth_file.lstat()
    except FileNotFoundError:
        state = "missing"
        authenticated = False
    except OSError:
        state = "unreadable"
        authenticated = False
    else:
        if stat_module.S_ISLNK(auth_stat.st_mode):
            state = "symlink_rejected"
            authenticated = False
        elif not stat_module.S_ISREG(auth_stat.st_mode):
            state = "not_regular"
            authenticated = False
        elif getattr(auth_stat, "st_nlink", 1) > 1:
            state = "hardlink_rejected"
            authenticated = False
        elif auth_stat.st_size > MAX_CODEX_CONFIG_BYTES:
            state = "too_large"
            authenticated = False
        else:
            flags = os.O_RDONLY
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            fd = -1
            parent_fd = -1
            try:
                parent_stat = auth_file.parent.lstat()
                parent_fd = open_directory_no_follow_matching(
                    auth_file.parent,
                    parent_stat,
                    error_text="auth file changed unexpectedly",
                    changed_text="auth file changed unexpectedly",
                )
                current_stat = os.stat(
                    auth_file.name, dir_fd=parent_fd, follow_symlinks=False
                )
                if not source_identity_matches(current_stat, auth_stat):
                    raise OSError("auth file changed unexpectedly")
                fd = os.open(auth_file.name, flags, dir_fd=parent_fd)
                opened_stat = os.fstat(fd)
                if (
                    not source_identity_matches(opened_stat, current_stat)
                    or not source_identity_matches(opened_stat, auth_stat)
                    or not stat_module.S_ISREG(opened_stat.st_mode)
                    or getattr(opened_stat, "st_nlink", 1) > 1
                    or opened_stat.st_size > MAX_CODEX_CONFIG_BYTES
                ):
                    raise OSError("auth file changed unexpectedly")
                raw = os.read(fd, MAX_CODEX_CONFIG_BYTES + 1)
                if len(raw) > MAX_CODEX_CONFIG_BYTES:
                    state = "too_large"
                    authenticated = False
                elif not raw:
                    state = "empty"
                    authenticated = False
                else:
                    try:
                        document = json.loads(raw.decode("utf-8"))
                    except (UnicodeDecodeError, json.JSONDecodeError, RecursionError):
                        document = None
                    if not isinstance(document, dict):
                        state = "invalid_json"
                        authenticated = False
                    else:
                        auth_mode_value = document.get("auth_mode")
                        if isinstance(auth_mode_value, str) and auth_mode_value.strip():
                            normalized_auth_mode = auth_mode_value.strip().lower()
                            auth_mode = (
                                normalized_auth_mode
                                if normalized_auth_mode in {"api", "chatgpt", "oauth"}
                                else "other"
                            )
                        tokens = document.get("tokens")
                        access_token = (
                            tokens.get("access_token")
                            if isinstance(tokens, dict)
                            else None
                        )
                        token_state = auth_access_token_state(access_token)
                        if token_state == "expired":
                            state = "access_token_expired"
                            authenticated = False
                        else:
                            state = "present_regular"
                            authenticated = True
            except (AgentError, OSError):
                state = "unreadable"
                authenticated = False
            finally:
                if fd >= 0:
                    os.close(fd)
                if parent_fd >= 0:
                    os.close(parent_fd)
    return {
        "authenticated": authenticated,
        "auth_state": state,
        "auth_mode": auth_mode,
        "token_state": token_state,
        "auth_file": PATH_NOT_RETURNED,
        "raw_output": "not_returned",
    }


def require_authenticated_agent_for_mutation(
    agent: str,
    *,
    operation: str,
    allow_unauthenticated: bool = False,
) -> dict[str, Any]:
    auth = agent_auth_status(agent)
    if allow_unauthenticated:
        return {
            **auth,
            "required": False,
            "override": True,
            "operation": operation,
        }
    if not auth["authenticated"]:
        raise AgentError(
            f"{operation} requires authenticated Agentin {canonical_agent_id(agent)}; "
            f"auth_state={auth['auth_state']}; pass allow_unauthenticated=true only for login/bootstrap"
        )
    return {
        **auth,
        "required": True,
        "override": False,
        "operation": operation,
    }


def normalize_routing_context_id(value: Any, *, field: str) -> str | None:
    if value is None:
        return None
    text = bounded_text(value, field=field, max_chars=128, required=True) or ""
    if not ROUTING_CONTEXT_ID_RE.fullmatch(text):
        raise AgentError(f"{field} contains unsupported characters")
    return text


def validate_codex_usage_routing_decision(
    payload: Any,
    *,
    agent: str,
    role: str,
) -> dict[str, Any]:
    if not isinstance(payload, dict) or payload.get("schema_version") != 1:
        raise AgentError("codex-usage routing schema is unsupported")
    decision = payload.get("decision")
    model = payload.get("model")
    if (
        not isinstance(decision, str)
        or decision not in CODEX_USAGE_DECISIONS
        or payload.get("role") != role
    ):
        raise AgentError("codex-usage routing decision is invalid")
    if not isinstance(
        payload.get("account"), str
    ) or not CODEX_USAGE_ACCOUNT_RE.fullmatch(payload["account"]):
        raise AgentError("codex-usage routing account is invalid")
    backend_account_id = bounded_text(
        payload.get("backend_account_id"),
        field="codex-usage routing backend account id",
        max_chars=MAX_CODEX_USAGE_BACKEND_ACCOUNT_ID,
        required=decision != "blocked",
    )
    expected_models = {
        "spark": {WRITE_AGENT_MODEL},
        "main": {DEFAULT_AGENT_MODEL, CODEX_USAGE_LEGACY_MAIN_MODEL},
        "credits": {DEFAULT_AGENT_MODEL, CODEX_USAGE_LEGACY_MAIN_MODEL},
        "blocked": {None},
        "unchanged": {None},
    }[decision]
    if model not in expected_models:
        raise AgentError("codex-usage routing model does not match decision")
    selected_model = (
        DEFAULT_AGENT_MODEL if model == CODEX_USAGE_LEGACY_MAIN_MODEL else model
    )
    if decision == "credits" and payload.get("paid_overage_allowed") is not True:
        raise AgentError("codex-usage credits decision lacks explicit paid policy")
    if not isinstance(payload.get("paid_overage_allowed"), bool):
        raise AgentError("codex-usage paid policy is invalid")
    result = {
        "schema_version": 1,
        "account": payload["account"],
        "backend_account_id": backend_account_id,
        "role": role,
        "decision": decision,
        "model": selected_model,
        "reason": bounded_text(
            payload.get("reason"), field="routing reason", max_chars=120
        ),
        "usage_state": bounded_text(
            payload.get("usage_state"), field="routing usage_state", max_chars=32
        ),
        "paid_overage_allowed": payload["paid_overage_allowed"],
        "policy_source": bounded_text(
            payload.get("policy_source"), field="routing policy_source", max_chars=160
        ),
        "raw_output": "not_returned",
    }
    if model == CODEX_USAGE_LEGACY_MAIN_MODEL:
        result["model_fallback"] = {
            "requested": model,
            "selected": selected_model,
            "reason": "legacy_main_model_replaced",
        }
    threshold = payload.get("threshold_percent")
    if threshold is not None:
        if (
            isinstance(threshold, bool)
            or not isinstance(threshold, (int, float))
            or not math.isfinite(float(threshold))
            or not 0 <= float(threshold) <= 100
        ):
            raise AgentError("codex-usage routing threshold is invalid")
        result["threshold_percent"] = float(threshold)

    remaining = payload.get("remaining")
    normalized_remaining: dict[str, float] = {}
    if remaining is not None:
        if not isinstance(remaining, dict) or len(remaining) > 16:
            raise AgentError("codex-usage routing remaining values are invalid")
        for window, value in remaining.items():
            if (
                not isinstance(window, str)
                or not window
                or len(window) > 32
                or isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(float(value))
                or not 0 <= float(value) <= 100
            ):
                raise AgentError("codex-usage routing remaining values are invalid")
            normalized_remaining[window] = float(value)
        if normalized_remaining:
            result["remaining_percent"] = min(normalized_remaining.values())

    resets = payload.get("resets")
    normalized_resets: dict[str, tuple[float, str]] = {}
    if resets is not None:
        if not isinstance(resets, dict) or len(resets) > 16:
            raise AgentError("codex-usage routing resets are invalid")
        for window, value in resets.items():
            parsed = parse_utc_timestamp(value)
            if (
                not isinstance(window, str)
                or not window
                or len(window) > 32
                or parsed is None
            ):
                raise AgentError("codex-usage routing resets are invalid")
            normalized_resets[window] = (parsed, value)
    if decision == "blocked" and normalized_resets:
        blocked_windows = set(normalized_resets)
        if normalized_remaining and threshold is not None:
            blocked_windows = {
                window
                for window, value in normalized_remaining.items()
                if value <= float(threshold)
            }
        blocked_resets = [
            normalized_resets[window]
            for window in blocked_windows
            if window in normalized_resets
        ]
        if blocked_resets:
            result["blocked_until_utc"] = max(blocked_resets)[1]
    return result


def resolve_runtime_agent_selection(
    *,
    role: str,
    routing: Mapping[str, Any] | None,
    task_profile: TaskProfile,
    requested_class: str | None = None,
    requested_lifecycle: str | None = None,
    requested_model: str | None = None,
    requested_reasoning: str | None = None,
    authority_class: str | None = None,
) -> ResolutionDecision:
    """Resolve the one model decision consumed by start and assign.

    ``authority_class=None`` is reserved for trusted in-process callers. MCP
    callers always bind a verified or fail-safe principal class before reaching
    this shared resolver path.
    """

    scope_kind = (
        "read"
        if role == "exploriererin"
        else "write"
        if role == "arbeitsbiene"
        else "unknown"
    )
    class_catalog = load_agent_class_catalog(repo_root() / "codex-agent-classes.json")
    classes, models = policies_from_catalogs(
        class_catalog,
        load_model_policy(repo_root() / "codex-model-policy.json"),
    )
    if authority_class is not None:
        allowed_class_ids = set(
            delegable_nonleadership_class_ids(
                authority_class,
                class_catalog,
            )
        )
        authority = class_catalog.get(authority_class)
        if (
            authority_class == "koenigin"
            and requested_class == "teamleiterin"
            and authority is not None
            and "teamleiterin" in authority.delegation_targets
        ):
            allowed_class_ids.add("teamleiterin")
        classes = tuple(item for item in classes if item.class_id in allowed_class_ids)
    available_models = available_model_ids_for_routing(models, routing)
    try:
        return resolve_agent_selection(
            ResolutionRequest(
                scope_kind=scope_kind,
                complexity=task_profile.complexity.value,
                requested_class=requested_class,
                requested_lifecycle=requested_lifecycle,
                requested_model=requested_model,
                requested_reasoning=requested_reasoning,
                required_capabilities=task_profile.required_capabilities,
                spark_eligible=task_profile.spark_eligible,
            ),
            classes=classes,
            models=models,
            available_models=available_models,
        )
    except ValueError as exc:
        if str(exc).startswith(
            ("required_model_unavailable:", "required_model_effort_unavailable:")
        ):
            raise AgentError(str(exc)) from exc
        raise


def classify_runtime_task(request: TaskClassificationRequest) -> TaskProfile:
    return TaskClassifier().classify(request)


def available_model_ids_for_routing(
    models: tuple[ModelPolicy, ...], routing: Mapping[str, Any] | None
) -> set[str]:
    available = {item.model_id for item in models}
    if routing is not None and routing.get("decision") != "spark":
        available -= {item.model_id for item in models if item.family == "spark"}
    return available


def public_task_profile(profile: TaskProfile) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "complexity": profile.complexity.value,
        "spark_eligible": profile.spark_eligible,
        "reason_codes": list(profile.reason_codes),
        "required_capabilities": list(profile.required_capabilities),
        "raw_output": "not_returned",
    }


def _complexity_override(value: Any) -> TaskComplexity | None:
    if not isinstance(value, str):
        raise AgentError("complexity must be simple, medium, complex, or unknown")
    normalized = value.strip().lower()
    if normalized not in {"simple", "medium", "complex", "unknown"}:
        raise AgentError("complexity must be simple, medium, complex, or unknown")
    return {
        "simple": TaskComplexity.SIMPLE,
        "medium": TaskComplexity.MEDIUM,
        "complex": TaskComplexity.COMPLEX,
        "unknown": None,
    }[normalized]


def public_resolution_decision(
    decision: ResolutionDecision | None,
) -> dict[str, Any] | None:
    if decision is None:
        return None
    return {
        "schema_version": 1,
        "class": decision.class_id,
        "lifecycle": decision.lifecycle,
        "model": decision.model,
        "reasoning": decision.reasoning,
        "requested": {
            "class": decision.requested_class,
            "lifecycle": decision.requested_lifecycle,
            "model": decision.requested_model,
            "reasoning": decision.requested_reasoning,
        },
        "fallback": decision.fallback,
        "reason_codes": list(decision.reason_codes),
        "raw_output": "not_returned",
    }


def _resolver_target_selection_inputs(
    agent: str,
    requested_class: str | None,
    authority_class: str | None,
) -> tuple[str | None, str | None]:
    """Keep role selection bound to verified authority, never target series."""

    del agent
    return requested_class, authority_class


def resolver_class_for_agent(
    agent: str,
    requested_class: str | None,
    *,
    authority_class: str | None = "arbeitsbiene",
) -> str | None:
    resolved_class, _resolver_authority = _resolver_target_selection_inputs(
        agent,
        requested_class,
        authority_class,
    )
    return resolved_class


def delegable_nonleadership_class_ids(
    authority_class: str,
    class_catalog: Mapping[str, Any],
) -> frozenset[str]:
    """Return the non-leading classes available to one bound principal."""

    authority = class_catalog.get(authority_class)
    if authority is None:
        raise AgentError("verified principal class is unknown")
    allowed: set[str] = set()
    pending = list(authority.delegation_targets)
    while pending:
        class_id = pending.pop()
        if class_id in allowed:
            continue
        profile = class_catalog.get(class_id)
        if profile is None:
            continue
        allowed.add(class_id)
        pending.extend(profile.delegation_targets)
    allowed -= LEADERSHIP_CLASS_IDS
    if not allowed and authority_class not in LEADERSHIP_CLASS_IDS:
        allowed.add(authority_class)
    if not allowed:
        raise AgentError("verified principal cannot delegate to a non-leading class")
    return frozenset(allowed)


def agent_selection_options(
    agent: str,
    *,
    principal_class: str | None = None,
    requester_class: str | None = None,
    known_generation: str | None = None,
) -> dict[str, Any]:
    """Return one advisory, account-aware first-round resolver offer.

    ``requester_class`` remains only as an explicit trusted in-process adapter.
    The public MCP schema cannot supply it. Calls without a bound principal
    fail safe to the smallest non-leading authority.
    """

    agent = canonical_agent_id(agent)
    class_catalog = load_agent_class_catalog(repo_root() / "codex-agent-classes.json")
    if principal_class is not None and requester_class is not None:
        raise AgentError("selection authority is ambiguous")
    authority_class = principal_class or requester_class or "arbeitsbiene"
    classes, models = policies_from_catalogs(
        class_catalog,
        load_model_policy(repo_root() / "codex-model-policy.json"),
    )
    allowed_class_ids = set(
        delegable_nonleadership_class_ids(
            authority_class,
            class_catalog,
        )
    )
    authority = class_catalog.get(authority_class)
    if (
        authority_class == "koenigin"
        and authority is not None
        and "teamleiterin" in authority.delegation_targets
    ):
        allowed_class_ids.add("teamleiterin")
    classes = tuple(item for item in classes if item.class_id in allowed_class_ids)
    ensure_agent_not_blocked_by_codex_usage(agent)
    available_models = available_model_ids_for_routing(models, None)
    try:
        offer = build_selection_offer(
            classes=classes,
            models=models,
            available_models=available_models,
        )
    except ValueError as exc:
        if str(exc).startswith(
            ("required_model_unavailable:", "required_model_effort_unavailable:")
        ):
            raise AgentError(str(exc)) from exc
        raise
    if (
        authority_class == "koenigin"
        and "teamleiterin" in allowed_class_ids
        and not offer.options
    ):
        if "gpt-5.6-terra" not in available_models:
            raise AgentError("required_model_unavailable:gpt-5.6-terra")
        raise AgentError("required_model_effort_unavailable:gpt-5.6-terra:xhigh")
    return {
        "schema_version": 1,
        "generation": offer.generation,
        "options_changed": known_generation != offer.generation,
        "classes": list(offer.classes),
        "lifecycles": list(offer.lifecycles),
        "models": list(offer.models),
        "reasoning_levels": list(offer.reasoning_levels),
        "options": [
            {
                "class": item.class_id,
                "lifecycle": item.lifecycle,
                "model": item.model,
                "reasoning": item.reasoning,
            }
            for item in offer.options
        ],
        "raw_output": "not_returned",
    }


def managed_raw_dirs() -> tuple[Path, ...]:
    legacy_raw = LEGACY_STATE_ROOT / "raw"
    dirs = [RAW_DIR]
    if legacy_raw != RAW_DIR:
        dirs.append(legacy_raw)
    return tuple(dirs)


def allowed_raw_log_identity(raw_log: Any) -> tuple[Path, os.stat_result | None] | None:
    if not isinstance(raw_log, str) or not raw_log.strip():
        return None
    raw_path = Path(raw_log).expanduser()
    if not raw_path.is_absolute():
        raw_path = Path.cwd() / raw_path
    raw_path = raw_path.absolute()
    if not directory_chain_is_real_no_symlink(raw_path.parent):
        return None
    current_stat: os.stat_result | None = None
    try:
        current_stat = raw_path.lstat()
    except FileNotFoundError:
        pass
    except OSError:
        return None
    else:
        if (
            stat_module.S_ISLNK(current_stat.st_mode)
            or getattr(current_stat, "st_nlink", 1) > 1
        ):
            return None
    try:
        candidate = raw_path.resolve(strict=False)
    except OSError:
        return None
    if candidate.suffix != ".log":
        return None
    for root in managed_raw_dirs():
        if not is_real_directory_no_symlink(root):
            continue
        try:
            candidate.relative_to(root.resolve(strict=False))
            return candidate, current_stat
        except (OSError, ValueError):
            continue
    return None


def allowed_raw_log_path(raw_log: Any) -> Path | None:
    identity = allowed_raw_log_identity(raw_log)
    return identity[0] if identity is not None else None


def allowed_agent_raw_log_identity(
    agent: str, raw_log: Any
) -> tuple[Path, os.stat_result | None] | None:
    agent = canonical_agent_id(agent)
    identity = allowed_raw_log_identity(raw_log)
    if identity is None:
        return None
    name = identity[0].name
    if not name.endswith(".log"):
        return None
    _prefix, separator, suffix = name[:-4].rpartition("-")
    known_suffixes = set(all_agent_ids()) | set(LEGACY_AGENT_ALIASES)
    if (
        separator
        and suffix in known_suffixes
        and suffix not in agent_record_aliases(agent)
    ):
        return None
    return identity


def raw_log_identity_is_legacy(
    identity: tuple[Path, os.stat_result | None] | None,
) -> bool:
    if identity is None:
        return False
    legacy_raw = LEGACY_STATE_ROOT / "raw"
    if legacy_raw == RAW_DIR or not is_real_directory_no_symlink(legacy_raw):
        return False
    try:
        identity[0].relative_to(legacy_raw.resolve(strict=False))
    except (OSError, ValueError):
        return False
    return True


def latest_managed_raw_log(agent: str, *, include_legacy: bool = True) -> Path | None:
    agent = canonical_agent_id(agent)
    suffixes = tuple(f"-{alias}.log" for alias in agent_record_aliases(agent))
    candidates: list[tuple[int, Path]] = []
    roots = managed_raw_dirs() if include_legacy else (RAW_DIR,)
    for root in roots:
        if not is_real_directory_no_symlink(root):
            continue
        try:
            entries = tuple(root.iterdir())
        except OSError:
            continue
        for path in entries:
            if not path.name.endswith(suffixes) or not path.name.endswith(".log"):
                continue
            run_timestamp, separator, run_agent = path.name[:-4].rpartition("-")
            if separator != "-" or run_agent not in agent_record_aliases(agent):
                continue
            try:
                _dt.datetime.strptime(run_timestamp, "%Y%m%dT%H%M%S%fZ")
            except ValueError:
                continue
            identity = allowed_raw_log_identity(str(path))
            if (
                identity is None
                or identity[1] is None
                or not stat_module.S_ISREG(identity[1].st_mode)
            ):
                continue
            candidates.append((identity[1].st_mtime_ns, identity[0]))
    if not candidates:
        return None
    newest_mtime = max(item[0] for item in candidates)
    newest = [path for mtime, path in candidates if mtime == newest_mtime]
    return newest[0] if len(newest) == 1 else None


def raw_log_candidate_agents(running_agents: set[str]) -> list[str]:
    snapshot = current_agent_inventory()
    candidates = {agent for agent in running_agents if agent in snapshot.agents}

    for metadata_dir in (META_DIR, LEGACY_META_DIR):
        if not is_real_directory_no_symlink(metadata_dir):
            continue
        try:
            entries = tuple(metadata_dir.iterdir())
        except OSError:
            continue
        for path in entries:
            if not path.name.endswith(".json"):
                continue
            name = path.name[:-5]
            candidate = (
                name if name in snapshot.agents else LEGACY_AGENT_ALIASES.get(name)
            )
            if candidate in snapshot.agents:
                candidates.add(candidate)

    for raw_dir in managed_raw_dirs():
        if not is_real_directory_no_symlink(raw_dir):
            continue
        try:
            entries = tuple(raw_dir.iterdir())
        except OSError:
            continue
        for path in entries:
            if not path.name.endswith(".log"):
                continue
            _prefix, separator, name = path.name[:-4].rpartition("-")
            if not separator:
                continue
            candidate = (
                name if name in snapshot.agents else LEGACY_AGENT_ALIASES.get(name)
            )
            if candidate in snapshot.agents:
                candidates.add(candidate)

    return sorted(candidates, key=snapshot.positions.__getitem__)


def protected_raw_log_paths() -> set[Path]:
    protected: set[Path] = set()
    has_artifacts = False
    for metadata_dir in (META_DIR,):
        if is_real_directory_no_symlink(metadata_dir):
            try:
                if any(path.name.endswith(".json") for path in metadata_dir.iterdir()):
                    has_artifacts = True
                    break
            except OSError:
                pass
    if not has_artifacts and is_real_directory_no_symlink(RAW_DIR):
        try:
            has_artifacts = any(
                path.name.endswith(".log") for path in RAW_DIR.iterdir()
            )
        except OSError:
            pass
    if not has_artifacts:
        return protected
    try:
        running_agents = set(managed_applet_inventory()["running_agents"])
    except AgentError:
        running_agents = set()
    for agent in raw_log_candidate_agents(running_agents):
        raw_log = read_meta(agent).get("raw_log")
        identity = allowed_agent_raw_log_identity(agent, raw_log)
        if (
            identity is not None
            and identity[1] is not None
            and stat_module.S_ISREG(identity[1].st_mode)
        ):
            protected.add(identity[0])
            continue
        recovered = latest_managed_raw_log(
            agent,
            include_legacy=raw_log_identity_is_legacy(identity),
        )
        if recovered is not None and agent in running_agents:
            protected.add(recovered)
    return protected


def bound_raw_log_file(path: Path, max_bytes: int = MAX_RAW_LOG_BYTES) -> bool:
    max_bytes = max(1, int(max_bytes))
    try:
        current_stat = path.lstat()
    except OSError:
        return False
    if (
        not stat_module.S_ISREG(current_stat.st_mode)
        or getattr(current_stat, "st_nlink", 1) > 1
    ):
        return False
    marker = RAW_LOG_TRUNCATION_MARKER[: max(0, max_bytes - 1)]
    with open_private_regular_update(path) as fh:
        opened_stat = os.fstat(fh.fileno())
        if (
            not source_identity_matches(opened_stat, current_stat)
            or getattr(opened_stat, "st_nlink", 1) > 1
        ):
            return False
        fh.seek(0, os.SEEK_END)
        size = fh.tell()
        if size <= max_bytes:
            return False
        tail_limit = max(0, max_bytes - len(marker))
        fh.seek(max(0, size - tail_limit), os.SEEK_SET)
        tail = fh.read(tail_limit)
    replace_private_bytes(path, marker + tail)
    return True


def harden_raw_log_at_dir_fd(
    directory_fd: int, name: str, expected_stat: os.stat_result
) -> None:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(name, flags, dir_fd=directory_fd)
        current = os.fstat(fd)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) > 1
            or not source_identity_matches(current, expected_stat)
        ):
            return
        try:
            os.fchmod(fd, 0o600)
        except PermissionError:
            pass
    except OSError:
        return
    finally:
        if fd >= 0:
            os.close(fd)


def unlink_raw_entry_at_dir_fd(
    directory_fd: int, name: str, expected_stat: os.stat_result
) -> bool:
    try:
        latest = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except OSError:
        return False
    if not source_identity_matches(latest, expected_stat):
        return False
    try:
        os.unlink(name, dir_fd=directory_fd)
    except FileNotFoundError:
        return False
    except OSError:
        return False
    return True


def replace_private_bytes_at_dir_fd(directory_fd: int, name: str, data: bytes) -> None:
    tmp_name = f".{name}.{now_id()}.{uuid.uuid4().hex}.tmp"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    tmp_created = False
    try:
        fd = os.open(tmp_name, flags, 0o600, dir_fd=directory_fd)
        tmp_created = True
        with os.fdopen(fd, "wb") as fh:
            fd = -1
            fh.write(data)
        os.replace(tmp_name, name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd)
        tmp_created = False
    except OSError as exc:
        raise AgentError("could not bound raw log") from exc
    finally:
        if fd >= 0:
            os.close(fd)
        if tmp_created:
            with contextlib.suppress(OSError):
                os.unlink(tmp_name, dir_fd=directory_fd)


def bound_raw_log_at_dir_fd(
    directory_fd: int, name: str, max_bytes: int = MAX_RAW_LOG_BYTES
) -> bool:
    max_bytes = max(1, int(max_bytes))
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(name, flags, dir_fd=directory_fd)
        current = os.fstat(fd)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) > 1
        ):
            return False
        if current.st_size <= max_bytes:
            return False
        marker = RAW_LOG_TRUNCATION_MARKER[: max(0, max_bytes - 1)]
        tail_limit = max(0, max_bytes - len(marker))
        with os.fdopen(fd, "rb") as fh:
            fd = -1
            fh.seek(max(0, current.st_size - tail_limit), os.SEEK_SET)
            tail = fh.read(tail_limit)
    except OSError as exc:
        raise AgentError("could not bound raw log") from exc
    finally:
        if fd >= 0:
            os.close(fd)
    try:
        latest = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except OSError:
        return False
    if (
        not stat_module.S_ISREG(latest.st_mode)
        or getattr(latest, "st_nlink", 1) > 1
        or not source_identity_matches(latest, current)
    ):
        return False
    replace_private_bytes_at_dir_fd(directory_fd, name, marker + tail)
    return True


def append_bounded_raw_log(
    path: Path,
    chunk: bytes,
    max_bytes: int = MAX_RAW_LOG_BYTES,
    *,
    expected_stat: os.stat_result | None = None,
) -> None:
    max_bytes = max(1, int(max_bytes))
    if not chunk:
        return
    with open_private_regular_update(path) as fh:
        opened_stat = os.fstat(fh.fileno())
        if expected_stat is not None and not source_identity_matches(
            opened_stat, expected_stat
        ):
            raise AgentError("raw log path changed unexpectedly")
        if getattr(opened_stat, "st_nlink", 1) > 1:
            raise RuntimeError("raw log path must not be a hardlink")
        fh.seek(0, os.SEEK_END)
        size = fh.tell()
        if size + len(chunk) <= max_bytes:
            fh.write(chunk)
            return
        marker = RAW_LOG_TRUNCATION_MARKER[: max(0, max_bytes - 1)]
        tail_limit = max(0, max_bytes - len(marker) - len(chunk))
        preserved = b""
        if tail_limit:
            fh.seek(max(0, size - tail_limit), os.SEEK_SET)
            preserved = fh.read(tail_limit)
        payload_limit = max(0, max_bytes - len(marker) - len(preserved))
        payload = chunk[-payload_limit:] if payload_limit else b""
        new_content = marker + preserved + payload
        if len(new_content) > max_bytes:
            tail_limit = max(0, max_bytes - len(marker))
            new_content = marker + new_content[-tail_limit:]
        fh.seek(0)
        fh.truncate()
        fh.write(new_content)


def validate_raw_log_writer_max_bytes(max_bytes: Any) -> int:
    if isinstance(max_bytes, bool) or not isinstance(max_bytes, int):
        raise AgentError("raw log max_bytes must be an integer")
    if max_bytes < 1:
        raise AgentError("raw log max_bytes must be >= 1")
    if max_bytes > MAX_RAW_LOG_BYTES:
        raise AgentError(f"raw log max_bytes must be <= {MAX_RAW_LOG_BYTES}")
    return max_bytes


def write_bounded_raw_log(path: Path, max_bytes: int = MAX_RAW_LOG_BYTES) -> int:
    max_bytes = validate_raw_log_writer_max_bytes(max_bytes)
    ensure_state()
    allowed_identity = allowed_raw_log_identity(str(path))
    if (
        allowed_identity is None
        or allowed_identity[1] is None
        or not stat_module.S_ISREG(allowed_identity[1].st_mode)
    ):
        raise AgentError("raw log path is outside managed raw log state")
    allowed, expected_stat = allowed_identity
    stream = sys.stdin.buffer
    while True:
        chunk = (
            stream.read1(RAW_LOG_CHUNK_BYTES)
            if hasattr(stream, "read1")
            else stream.read(RAW_LOG_CHUNK_BYTES)
        )
        if not chunk:
            return 0
        append_bounded_raw_log(allowed, chunk, max_bytes, expected_stat=expected_stat)


def prune_raw_logs(
    max_files: int = MAX_RAW_LOG_FILES, max_bytes: int = MAX_RAW_LOG_BYTES
) -> dict[str, Any]:
    max_files = max(1, int(max_files))
    max_bytes = max(1, int(max_bytes))
    protected = protected_raw_log_paths()
    deleted = 0
    deleted_symlink = 0
    truncated = 0
    retained = 0
    for raw_dir in managed_raw_dirs():
        if not is_real_directory_no_symlink(raw_dir):
            continue
        try:
            raw_stat = raw_dir.lstat()
        except OSError:
            continue
        if stat_module.S_ISLNK(raw_stat.st_mode) or not stat_module.S_ISDIR(
            raw_stat.st_mode
        ):
            continue
        raw_fd = -1
        try:
            try:
                raw_fd = open_directory_no_follow_matching(
                    raw_dir,
                    raw_stat,
                    error_text="raw log directory unreadable",
                    changed_text="raw log directory changed",
                )
            except AgentError:
                continue
            raw_fd_path = Path(f"/proc/self/fd/{raw_fd}")
            logs: list[tuple[str, os.stat_result]] = []
            try:
                entry_names = sorted(
                    name for name in os.listdir(raw_fd) if name.endswith(".log")
                )
            except OSError:
                continue
            for name in entry_names:
                try:
                    current_stat = os.stat(name, dir_fd=raw_fd, follow_symlinks=False)
                except OSError:
                    continue
                if stat_module.S_ISLNK(current_stat.st_mode):
                    if unlink_raw_entry_at_dir_fd(raw_fd, name, current_stat):
                        deleted += 1
                        deleted_symlink += 1
                    continue
                if (
                    stat_module.S_ISREG(current_stat.st_mode)
                    and getattr(current_stat, "st_nlink", 1) > 1
                ):
                    if unlink_raw_entry_at_dir_fd(raw_fd, name, current_stat):
                        deleted += 1
                    continue
                if stat_module.S_ISREG(current_stat.st_mode):
                    logs.append((name, current_stat))
            logs = sorted(
                logs, key=lambda item: (item[1].st_mtime, item[0]), reverse=True
            )
            keep: set[Path] = set(protected)
            for name, _current_stat in logs[:max_files]:
                keep.add((raw_fd_path / name).resolve(strict=False))
            for name, current_stat in logs:
                path = raw_fd_path / name
                resolved = path.resolve(strict=False)
                harden_raw_log_at_dir_fd(raw_fd, name, current_stat)
                if resolved not in protected and current_stat.st_size > max_bytes:
                    if bound_raw_log_at_dir_fd(raw_fd, name, max_bytes):
                        truncated += 1
                        try:
                            current_stat = os.stat(
                                name, dir_fd=raw_fd, follow_symlinks=False
                            )
                        except OSError:
                            continue
                if resolved in keep:
                    retained += 1
                    continue
                if unlink_raw_entry_at_dir_fd(raw_fd, name, current_stat):
                    deleted += 1
        finally:
            if raw_fd >= 0:
                os.close(raw_fd)
    return {
        "max_files_per_dir": max_files,
        "max_bytes_per_file": max_bytes,
        "retained_count": retained,
        "deleted_count": deleted,
        "deleted_symlink_count": deleted_symlink,
        "truncated_count": truncated,
        "raw_output": "not_returned",
    }


def raw_log_retention_status() -> dict[str, Any]:
    file_count = 0
    total_bytes = 0
    oversized_count = 0
    for raw_dir in managed_raw_dirs():
        if not is_real_directory_no_symlink(raw_dir):
            continue
        for path in raw_dir.glob("*.log"):
            try:
                current_stat = path.lstat()
            except OSError:
                continue
            if not stat_module.S_ISREG(current_stat.st_mode):
                continue
            file_count += 1
            size = current_stat.st_size
            total_bytes += size
            oversized_count += int(size > MAX_RAW_LOG_BYTES)
    return {
        "managed_dirs": PATH_NOT_RETURNED,
        "managed_dir_count": len(managed_raw_dirs()),
        "max_files_per_dir": MAX_RAW_LOG_FILES,
        "max_bytes_per_file": MAX_RAW_LOG_BYTES,
        "file_count": file_count,
        "total_bytes": total_bytes,
        "oversized_count": oversized_count,
        "raw_output": "not_returned",
    }


def raw_log_writer_command(raw_log: Path) -> str:
    return shlex.join(
        [
            str(_runtime_mcp_entrypoint()),
            "raw-log-writer",
            str(raw_log),
            "--max-bytes",
            str(MAX_RAW_LOG_BYTES),
        ]
    )


def read_proc_environ(pid_dir: Path) -> dict[str, str] | None:
    try:
        raw = (pid_dir / "environ").read_bytes()
    except FileNotFoundError:
        return {}
    except OSError:
        return None
    env: dict[str, str] = {}
    for item in raw.split(b"\0"):
        if not item or b"=" not in item:
            continue
        key, value = item.split(b"=", 1)
        env[key.decode("utf-8", errors="replace")] = value.decode(
            "utf-8", errors="replace"
        )
    return env


def read_proc_status(pid_dir: Path) -> dict[str, str]:
    try:
        lines = (
            (pid_dir / "status")
            .read_text(encoding="utf-8", errors="replace")
            .splitlines()
        )
    except OSError:
        return {}
    result: dict[str, str] = {}
    for line in lines:
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        if key in {"Name", "State", "PPid", "Tgid", "Uid"}:
            result[key] = value.strip()
    return result


def read_proc_cmdline(pid_dir: Path) -> list[str]:
    try:
        raw = (pid_dir / "cmdline").read_bytes()
    except OSError:
        return []
    return [item.decode("utf-8", errors="replace") for item in raw.split(b"\0") if item]


def proc_is_codex_like(status: dict[str, str], argv: list[str]) -> bool:
    name = (status.get("Name") or "").lower()
    argv0_name = Path(argv[0]).name.lower() if argv else ""
    if (
        name == "codex"
        or name == "codex-code-mode-host"
        or name == "codex-code-mode"
        or name == "gemini"
        or argv0_name == "codex"
        or argv0_name == "gemini"
    ):
        return True
    if argv0_name not in {"node", "nodejs"} or len(argv) < 2:
        return False
    value_flags = (
        "-r",
        "--require",
        "--loader",
        "--experimental-loader",
        "--import",
        "-C",
        "--conditions",
    )
    entrypoint: str | None = None
    skip_next = False
    for index, arg in enumerate(argv[1:], start=1):
        if skip_next:
            skip_next = False
            continue
        if arg == "--":
            entrypoint = argv[index + 1] if index + 1 < len(argv) else None
            break
        if arg.startswith("--") and "=" in arg:
            flag, _ = arg.split("=", 1)
            if flag not in value_flags:
                return False
            continue
        if arg in value_flags:
            skip_next = True
            continue
        if arg == "--enable-source-maps":
            continue
        if arg.startswith("-"):
            return False
        entrypoint = arg
        break
    if not entrypoint:
        return False
    parts = Path(entrypoint.lower()).parts
    return any(
        (left == "@openai" and right == "codex")
        or (left == "@google" and right == "gemini-cli")
        for left, right in zip(parts, parts[1:])
    )


def resolve_proc_cwd(pid_dir: Path) -> tuple[Path | None, bool]:
    try:
        return (pid_dir / "cwd").resolve(strict=True), False
    except FileNotFoundError:
        return None, False
    except (OSError, RuntimeError):
        return None, True


def _proc_is_exact_inherited_home_session_helper(
    pid_dir: Path,
    status: dict[str, str],
    argv: list[str],
) -> bool:
    signatures = {
        ("/usr/bin/dbus-daemon", "--session"): Path("/usr/bin/dbus-daemon"),
        (
            "/usr/bin/dbus-daemon",
            "--syslog-only",
            "--fork",
            "--print-pid",
            "5",
            "--print-address",
            "7",
            "--session",
        ): Path("/usr/bin/dbus-daemon"),
        (
            "/usr/bin/gnome-keyring-daemon",
            "--start",
            "--foreground",
            "--components=secrets",
        ): Path("/usr/bin/gnome-keyring-daemon"),
    }
    expected_executable = signatures.get(tuple(argv))
    ppid_parts = status.get("PPid", "").split()
    if (
        expected_executable is None
        or len(ppid_parts) != 1
        or not ppid_parts[0].isdigit()
    ):
        return False
    parent_pid = int(ppid_parts[0])
    if parent_pid != 1:
        parent_dir = pid_dir.parent / str(parent_pid)
        parent_status = read_proc_status(parent_dir)
        if (
            parent_status.get("Name") != "systemd"
            or parent_status.get("PPid", "").split() != ["1"]
            or read_proc_cmdline(parent_dir) != ["/usr/lib/systemd/systemd", "--user"]
        ):
            return False
    try:
        executable = (pid_dir / "exe").resolve(strict=True)
        current_dir = (pid_dir / "cwd").resolve(strict=True)
    except (OSError, RuntimeError):
        return False
    return executable == expected_executable and current_dir == Path("/")


def same_path_text(left: str, right: Path) -> bool:
    if not isinstance(left, str) or not left.strip():
        return False
    try:
        return Path(left).expanduser().resolve(
            strict=False
        ) == right.expanduser().resolve(strict=False)
    except (OSError, RuntimeError):
        return False


def _managed_g5_native_pane_evidence(agent: str) -> tuple[int, int, int, str] | None:
    cfg = agent_config(agent)
    session = cfg.get("session")
    if not isinstance(session, str):
        return None
    attestation = _g5_native_runner_attestation(
        read_meta(agent), agent=agent, session=session
    )
    if attestation is None:
        return None
    pane_process_id = pane_pid(session)
    if type(pane_process_id) is not int or pane_process_id <= 0:
        return None
    device, inode, scope_unit = attestation
    return pane_process_id, device, inode, scope_unit


def _read_bounded_proc_evidence(
    pid_dir: Path, name: str, *, max_bytes: int
) -> bytes | None:
    if (
        name not in {"cgroup", "environ", "status"}
        or type(max_bytes) is not int
        or max_bytes <= 0
    ):
        return None
    descriptor = -1
    try:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(pid_dir / name, flags)
        before = os.fstat(descriptor)
        if not stat_module.S_ISREG(before.st_mode):
            return None
        payload = bytearray()
        while len(payload) <= max_bytes:
            chunk = os.read(descriptor, min(1024, max_bytes + 1 - len(payload)))
            if not chunk:
                break
            payload.extend(chunk)
        after = os.fstat(descriptor)
        if len(payload) > max_bytes or (before.st_dev, before.st_ino) != (
            after.st_dev,
            after.st_ino,
        ):
            return None
        return bytes(payload)
    except OSError:
        return None
    finally:
        if descriptor >= 0:
            with contextlib.suppress(OSError):
                os.close(descriptor)


def _proc_is_in_g5_scope(pid_dir: Path, scope_unit: str) -> bool:
    if not isinstance(scope_unit, str) or not scope_unit:
        return False
    cgroup = _read_bounded_proc_evidence(pid_dir, "cgroup", max_bytes=4096)
    expected_cgroup_suffix = f"/{scope_unit}\n".encode("ascii")
    return (
        cgroup is not None
        and cgroup.startswith(b"0::/")
        and cgroup.count(b"\n") == 1
        and cgroup.endswith(expected_cgroup_suffix)
    )


def _proc_has_exact_g5_home_evidence(
    pid_dir: Path, home: Path, *, require_markers: bool
) -> bool:
    raw = _read_bounded_proc_evidence(pid_dir, "environ", max_bytes=16 * 1024)
    if raw is None:
        return False
    expected = {b"CODEX_HOME", b"CODEX_MASTER_MCP", b"CODEX_AGENT_MCP"}
    values: dict[bytes, bytes] = {}
    for item in raw.split(b"\0"):
        if not item or b"=" not in item:
            continue
        key, value = item.split(b"=", 1)
        if key in expected:
            if key in values:
                return False
            values[key] = value
    try:
        codex_home = values[b"CODEX_HOME"].decode("utf-8")
    except (KeyError, UnicodeDecodeError):
        return False
    if not same_path_text(codex_home, home):
        return False
    return not require_markers or (
        values.get(b"CODEX_MASTER_MCP") == b"1"
        and values.get(b"CODEX_AGENT_MCP") == b"1"
    )


def _proc_parent_pid_from_bounded_status(pid_dir: Path) -> int | None:
    raw = _read_bounded_proc_evidence(pid_dir, "status", max_bytes=4096)
    if raw is None:
        return None
    try:
        lines = raw.decode("ascii").splitlines()
    except UnicodeDecodeError:
        return None
    values = [
        line.partition(":")[2].strip() for line in lines if line.startswith("PPid:")
    ]
    if (
        len(values) != 1
        or not values[0].isdigit()
        or (len(values[0]) > 1 and values[0][0] == "0")
    ):
        return None
    parent = int(values[0])
    return parent if 0 < parent <= (1 << 31) - 1 else None


def _proc_matches_g5_native_pane(
    pid_dir: Path,
    *,
    pid: int,
    pane_process_id: int,
    device: int,
    inode: int,
    scope_unit: str,
) -> bool:
    if pid != pane_process_id:
        return False
    try:
        executable = (pid_dir / "exe").stat()
    except OSError:
        return False
    return (
        stat_module.S_ISREG(executable.st_mode)
        and executable.st_mode & 0o111 != 0
        and (executable.st_dev, executable.st_ino) == (device, inode)
        and _proc_is_in_g5_scope(pid_dir, scope_unit)
    )


def _proc_matches_g5_native_descendant(
    pid_dir: Path,
    *,
    pid: int,
    pane_process_id: int,
    device: int,
    inode: int,
    scope_unit: str,
    home: Path,
) -> bool:
    if pid == pane_process_id or pid <= 0 or pane_process_id <= 0:
        return False
    if not _proc_has_exact_g5_home_evidence(pid_dir, home, require_markers=False):
        return False
    proc_root = pid_dir.parent
    current_pid = pid
    current_dir = pid_dir
    visited = {pid}
    for _depth in range(16):
        if not _proc_is_in_g5_scope(current_dir, scope_unit):
            return False
        parent_pid = _proc_parent_pid_from_bounded_status(current_dir)
        if parent_pid is None or parent_pid in visited:
            return False
        if parent_pid == pane_process_id:
            pane_dir = proc_root / str(pane_process_id)
            return _proc_has_exact_g5_home_evidence(
                pane_dir, home, require_markers=True
            ) and _proc_matches_g5_native_pane(
                pane_dir,
                pid=pane_process_id,
                pane_process_id=pane_process_id,
                device=device,
                inode=inode,
                scope_unit=scope_unit,
            )
        visited.add(parent_pid)
        current_pid = parent_pid
        current_dir = proc_root / str(current_pid)
    return False


def public_path(path: Any) -> str | None:
    if path is None or str(path) == "":
        return None
    return PATH_NOT_RETURNED


def public_path_state(path: Any) -> str:
    return "set" if public_path(path) is not None else "not_set"


def public_config_path_state(path: Any) -> str:
    return "configured" if public_path(path) is not None else "not_configured"


def agent_home_processes(
    agent: str, proc_root: Path = Path("/proc")
) -> list[dict[str, Any]] | None:
    agent = canonical_agent_id(agent)
    cfg = agent_config(agent)
    home = cfg["home"]
    native_g5_evidence = _managed_g5_native_pane_evidence(agent)
    processes: list[dict[str, Any]] = []
    if not proc_root.exists():
        return None
    try:
        pid_dirs = list(proc_root.iterdir())
    except OSError:
        return None
    for pid_dir in pid_dirs:
        if not pid_dir.name.isdigit():
            continue
        status = read_proc_status(pid_dir)
        if status.get("State", "").startswith("Z"):
            continue
        uid_parts = status.get("Uid", "").split()
        if uid_parts and uid_parts[0].isdigit() and int(uid_parts[0]) != os.getuid():
            continue
        try:
            pid = int(pid_dir.name)
        except ValueError:
            continue
        env = read_proc_environ(pid_dir)
        matches_home = False
        managed = False
        if env is None:
            argv = read_proc_cmdline(pid_dir)
            if proc_is_codex_like(status, argv):
                return None
            current_dir, unavailable = resolve_proc_cwd(pid_dir)
            if not unavailable and current_dir is not None:
                try:
                    matches_home = current_dir.resolve(
                        strict=False
                    ) == home.expanduser().resolve(strict=False)
                except (OSError, RuntimeError):
                    matches_home = False
        else:
            configured_home = env.get("CODEX_HOME", "") or env.get(
                "GEMINI_CLI_HOME", ""
            )
            if configured_home:
                try:
                    configured_path = Path(configured_home).expanduser()
                    if not configured_path.is_absolute():
                        current_dir, unavailable = resolve_proc_cwd(pid_dir)
                        if unavailable:
                            return None
                        if current_dir is None:
                            continue
                        configured_path = current_dir / configured_path
                    matches_home = configured_path.resolve(
                        strict=False
                    ) == home.expanduser().resolve(strict=False)
                except (OSError, RuntimeError):
                    matches_home = False
            else:
                current_dir, unavailable = resolve_proc_cwd(pid_dir)
                if unavailable:
                    return None
                if current_dir is not None:
                    try:
                        matches_home = current_dir.resolve(
                            strict=False
                        ) == home.expanduser().resolve(strict=False)
                    except (OSError, RuntimeError):
                        matches_home = False
            managed = (
                env.get("CODEX_AGENT_MCP") == "1" or env.get("CODEX_MASTER_MCP") == "1"
            ) and proc_is_codex_like(status, read_proc_cmdline(pid_dir))
            if native_g5_evidence is not None:
                pane_process_id, device, inode, scope_unit = native_g5_evidence
                managed = managed or (
                    _proc_has_exact_g5_home_evidence(
                        pid_dir, home, require_markers=True
                    )
                    and _proc_matches_g5_native_pane(
                        pid_dir,
                        pid=pid,
                        pane_process_id=pane_process_id,
                        device=device,
                        inode=inode,
                        scope_unit=scope_unit,
                    )
                )
        if not matches_home:
            continue
        if not managed and native_g5_evidence is not None:
            pane_process_id, device, inode, scope_unit = native_g5_evidence
            managed = _proc_matches_g5_native_descendant(
                pid_dir,
                pid=pid,
                pane_process_id=pane_process_id,
                device=device,
                inode=inode,
                scope_unit=scope_unit,
                home=home,
            )
        if (
            not managed
            and env is not None
            and bool(env.get("CODEX_HOME"))
            and env.get("CODEX_AGENT_MCP") == "1"
            and env.get("CODEX_MASTER_MCP") == "1"
            and _proc_is_exact_inherited_home_session_helper(
                pid_dir,
                status,
                read_proc_cmdline(pid_dir),
            )
        ):
            continue
        ppid_parts = status.get("PPid", "0").split()
        ppid = int(ppid_parts[0]) if ppid_parts and ppid_parts[0].isdigit() else None
        processes.append(
            {
                "pid": pid,
                "ppid": ppid,
                "name": status.get("Name") or "unknown",
                "state": status.get("State") or "unknown",
                "managed_by_masterjet": managed,
                "raw_output": "not_returned",
            }
        )
    return sorted(processes, key=lambda item: item["pid"])


def agent_home_process_summary(
    agent: str, proc_root: Path = Path("/proc")
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    processes = agent_home_processes(agent, proc_root)
    if processes is None:
        return {
            "agent": agent,
            "home": PATH_NOT_RETURNED,
            "home_kind": "managed_agent_home",
            "process_count": None,
            "external_process_count": None,
            "managed_process_count": None,
            "managed_process_ids": [],
            "external_processes": [],
            "external_processes_truncated": False,
            "raw_output": "not_returned",
        }
    managed = [item for item in processes if item["managed_by_masterjet"]]
    managed_process_ids = [item["pid"] for item in managed]
    managed_process_id_set = set(managed_process_ids)
    managed_root_process_ids = [
        item["pid"]
        for item in managed
        if item.get("ppid") not in managed_process_id_set
    ]
    external = [item for item in processes if not item["managed_by_masterjet"]]
    return {
        "agent": agent,
        "home": PATH_NOT_RETURNED,
        "home_kind": "managed_agent_home",
        "process_count": len(processes),
        "external_process_count": len(external),
        "managed_process_count": len(managed_root_process_ids),
        "managed_process_ids": managed_process_ids,
        "managed_root_process_ids": managed_root_process_ids,
        "external_processes": external[:10],
        "external_processes_truncated": len(external) > 10,
        "raw_output": "not_returned",
    }


def pool_home_processes(
    home: Path, proc_root: Path = Path("/proc")
) -> list[dict[str, Any]] | None:
    if not proc_root.exists():
        return None
    try:
        resolved_home = home.expanduser().resolve(strict=False)
        pid_dirs = list(proc_root.iterdir())
    except (OSError, RuntimeError):
        return None
    processes: list[dict[str, Any]] = []
    for pid_dir in pid_dirs:
        if not pid_dir.name.isdigit():
            continue
        status = read_proc_status(pid_dir)
        if status.get("State", "").startswith("Z"):
            continue
        uid_parts = status.get("Uid", "").split()
        if uid_parts and uid_parts[0].isdigit() and int(uid_parts[0]) != os.getuid():
            continue
        env = read_proc_environ(pid_dir)
        environment_unreadable = env is None
        matches_home = False
        managed = False
        current_dir: Path | None = None
        if env is None:
            argv = read_proc_cmdline(pid_dir)
            if proc_is_codex_like(status, argv):
                return None
        else:
            configured_home = env.get("CODEX_HOME", "") or env.get(
                "GEMINI_CLI_HOME", ""
            )
            if configured_home:
                try:
                    configured_path = Path(configured_home).expanduser()
                    if not configured_path.is_absolute():
                        current_dir, unavailable = resolve_proc_cwd(pid_dir)
                        if unavailable:
                            return None
                        if current_dir is None:
                            continue
                        configured_path = current_dir / configured_path
                    matches_home = path_is_within(
                        configured_path.resolve(strict=False), resolved_home
                    )
                except (OSError, RuntimeError, ValueError):
                    matches_home = False
            managed = (
                env.get("CODEX_AGENT_MCP") == "1" or env.get("CODEX_MASTER_MCP") == "1"
            ) and proc_is_codex_like(status, read_proc_cmdline(pid_dir))
        if not matches_home:
            if current_dir is None:
                current_dir, unavailable = resolve_proc_cwd(pid_dir)
                if unavailable:
                    if environment_unreadable:
                        continue
                    return None
            if current_dir is None:
                continue
            matches_home = path_is_within(current_dir, resolved_home)
        if not matches_home:
            continue
        try:
            pid = int(pid_dir.name)
        except ValueError:
            continue
        ppid_parts = status.get("PPid", "0").split()
        ppid = int(ppid_parts[0]) if ppid_parts and ppid_parts[0].isdigit() else None
        processes.append(
            {
                "pid": pid,
                "ppid": ppid,
                "name": status.get("Name") or "unknown",
                "state": status.get("State") or "unknown",
                "managed_by_masterjet": managed,
                "raw_output": "not_returned",
            }
        )
    return sorted(processes, key=lambda item: item["pid"])


def agent_identity_guard(
    running: bool,
    process_summary: dict[str, Any],
    *,
    pane_process_id: int | None = None,
) -> dict[str, Any]:
    process_count = process_summary.get("process_count")
    external_process_count = process_summary.get("external_process_count")
    managed_process_count = process_summary.get("managed_process_count")
    counts_available = all(
        isinstance(value, int) and not isinstance(value, bool) and value >= 0
        for value in (process_count, external_process_count, managed_process_count)
    )
    if counts_available:
        counts_available = (
            managed_process_count + external_process_count <= process_count
            and (managed_process_count > 0 or external_process_count == process_count)
        )
    managed_process_ids = process_summary.get("managed_process_ids")
    pane_process_identity_checked = running
    pane_process_identity_match: bool | None = None
    if pane_process_identity_checked:
        managed_process_ids_valid = (
            counts_available
            and isinstance(managed_process_ids, list)
            and managed_process_count <= len(managed_process_ids) <= process_count
            and all(
                isinstance(pid, int) and not isinstance(pid, bool) and pid > 0
                for pid in managed_process_ids
            )
            and len(managed_process_ids) == len(set(managed_process_ids))
        )
        pane_process_identity_match = (
            managed_process_ids_valid
            and isinstance(pane_process_id, int)
            and not isinstance(pane_process_id, bool)
            and pane_process_id > 0
            and pane_process_id in managed_process_ids
        )
    if not counts_available:
        state = "blocked_process_scan_unavailable"
        ok = False
    elif (
        running
        and managed_process_count == 1
        and pane_process_identity_checked
        and not pane_process_identity_match
    ):
        state = "blocked_tmux_session_identity_mismatch"
        ok = False
    elif external_process_count > 0:
        state = "blocked_external_home_user"
        ok = False
    elif not running and managed_process_count > 0:
        state = "blocked_orphaned_managed_home_process"
        ok = False
    elif running and managed_process_count == 0:
        state = "blocked_tmux_session_without_managed_process"
        ok = False
    elif running and managed_process_count > 1:
        state = "blocked_multiple_managed_home_processes"
        ok = False
    elif running:
        state = "managed_session_running"
        ok = True
    else:
        state = "clear"
        ok = True
    return {
        "ok": ok,
        "state": state,
        "single_identity_required": True,
        "tmux_session_running": running,
        "home_process_count": process_count,
        "home_managed_process_count": managed_process_count,
        "home_external_process_count": external_process_count,
        "pane_process_identity_checked": pane_process_identity_checked,
        "pane_process_identity_match": pane_process_identity_match,
        "raw_output": "not_returned",
    }


def require_managed_tmux_session(
    agent: str, process_summary: dict[str, Any] | None = None
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    summary = (
        process_summary
        if process_summary is not None
        else agent_home_process_summary(agent)
    )
    pane_process_id = (
        pane_pid(agent_config(agent)["session"])
        if "managed_process_ids" in summary
        else None
    )
    guard = agent_identity_guard(True, summary, pane_process_id=pane_process_id)
    if (
        not guard.get("ok")
        and summary.get("process_count") == 1
        and "managed_process_count" not in summary
        and "managed_process_ids" not in summary
    ):
        return {
            **guard,
            "ok": True,
            "state": "legacy_process_summary",
            "single_identity_required": True,
        }
    if guard["ok"]:
        return guard
    if guard["state"] == "blocked_process_scan_unavailable":
        raise AgentError(
            f"agent {agent} CODEX_HOME process scan is unavailable; retry before using tmux session"
        )
    if guard["state"] == "blocked_external_home_user":
        raise AgentError(
            f"agent {agent} CODEX_HOME is also used by an external process; stop it before using tmux session"
        )
    if guard["state"] == "blocked_multiple_managed_home_processes":
        raise AgentError(
            f"agent {agent} has multiple managed CODEX_HOME processes; stop orphaned processes before using tmux session"
        )
    if guard["state"] == "blocked_tmux_session_identity_mismatch":
        raise AgentError(
            f"agent {agent} tmux session process identity could not be verified"
        )
    raise AgentError(
        f"agent {agent} tmux session identity could not be verified; no managed CODEX_HOME process was detected"
    )


def empty_codex_process_summary(home_kind_counts: dict[str, int]) -> dict[str, Any]:
    return {
        "codex_client_process_count": 0,
        "mcp_server_process_count": 0,
        "home_kind_counts": home_kind_counts,
        "namespace_visibility": {
            "main_default_home_clients": 0,
            "custom_home_clients": 0,
            "managed_agent_home_clients": 0,
            "unknown_home_clients": 0,
            "custom_home_clients_need_own_mcp_config": False,
            "managed_agent_home_clients_expect_no_master_mcp": False,
            "unknown_home_clients_need_manual_check": False,
            "raw_output": "not_returned",
        },
        "raw_output": "not_returned",
    }


def codex_related_process_summary(proc_root: Path = Path("/proc")) -> dict[str, Any]:
    home_kind_counts = {
        "main_default_home": 0,
        "custom_home": 0,
        "managed_agent_home": 0,
        "unknown": 0,
    }
    client_count = 0
    mcp_server_count = 0
    if not proc_root.exists():
        return empty_codex_process_summary(home_kind_counts)

    try:
        pid_dirs = list(proc_root.iterdir())
    except OSError:
        return empty_codex_process_summary(home_kind_counts)

    for pid_dir in pid_dirs:
        if not pid_dir.name.isdigit():
            continue
        status = read_proc_status(pid_dir)
        argv = read_proc_cmdline(pid_dir)
        joined = "\0".join(argv).lower()
        if "codex_master.server" in joined or "codex-master-mcp" in joined:
            mcp_server_count += 1
            continue

        if not proc_is_codex_like(status, argv):
            continue

        client_count += 1
        env = read_proc_environ(pid_dir)
        if env:
            home_kind = str(classify_codex_home(env.get("CODEX_HOME"))["home_kind"])
        else:
            home_kind = "unknown"
        home_kind_counts[home_kind if home_kind in home_kind_counts else "unknown"] += 1

    return {
        "codex_client_process_count": client_count,
        "mcp_server_process_count": mcp_server_count,
        "home_kind_counts": home_kind_counts,
        "namespace_visibility": {
            "main_default_home_clients": home_kind_counts["main_default_home"],
            "custom_home_clients": home_kind_counts["custom_home"],
            "managed_agent_home_clients": home_kind_counts["managed_agent_home"],
            "unknown_home_clients": home_kind_counts["unknown"],
            "custom_home_clients_need_own_mcp_config": home_kind_counts["custom_home"]
            > 0,
            "managed_agent_home_clients_expect_no_master_mcp": home_kind_counts[
                "managed_agent_home"
            ]
            > 0,
            "unknown_home_clients_need_manual_check": home_kind_counts["unknown"] > 0,
            "raw_output": "not_returned",
        },
        "raw_output": "not_returned",
    }


def pane_pid(session: str) -> int | None:
    if not tmux_alive(session):
        return None
    cp = run_tmux(
        _tmux_args_for_session(
            session, ["display-message", "-p", "-t", session, "#{pane_pid}"]
        ),
        check=False,
    )
    if cp.returncode != 0:
        return None
    text = cp.stdout.strip()
    return pane_pid_from_text(text)


def cleanup_failed_start(session: str, raw_log: Path, *, kill_session: bool) -> None:
    if kill_session and tmux_alive(session):
        run_tmux(
            _tmux_args_for_session(session, ["kill-session", "-t", session]),
            check=False,
        )
    try:
        current = raw_log.lstat()
    except FileNotFoundError:
        return
    try:
        latest = raw_log.lstat()
    except FileNotFoundError:
        return
    if (
        not stat_module.S_ISREG(current.st_mode)
        or getattr(current, "st_nlink", 1) > 1
        or not source_identity_matches(latest, current)
    ):
        return
    try:
        parent_stat = raw_log.parent.lstat()
    except FileNotFoundError:
        return
    parent_fd = open_directory_no_follow_matching(
        raw_log.parent,
        parent_stat,
        error_text="raw log parent changed unexpectedly",
        changed_text="raw log parent changed unexpectedly",
    )
    try:
        latest = os.stat(raw_log.name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            not stat_module.S_ISREG(latest.st_mode)
            or getattr(latest, "st_nlink", 1) > 1
            or not source_identity_matches(latest, current)
        ):
            return
        os.unlink(raw_log.name, dir_fd=parent_fd)
    except FileNotFoundError:
        pass
    finally:
        os.close(parent_fd)


def release_start_lease_if_safe(
    agent: str,
    lease: dict[str, Any] | None,
    enabled: bool,
    *,
    existing_session: bool = False,
) -> None:
    if not enabled or not lease or not lease.get("held_by_this_server"):
        return
    current_lease = agent_lease_status(agent)
    if not current_lease.get("held_by_this_server"):
        return
    lease_id = lease.get("lease_id")
    current_lease_id = current_lease.get("lease_id")
    if (
        lease_id is not None
        and current_lease_id is not None
        and lease_id != current_lease_id
    ):
        return
    if not existing_session:
        process_count = agent_home_process_summary(agent).get("process_count")
        if (
            not isinstance(process_count, int)
            or isinstance(process_count, bool)
            or process_count != 0
        ):
            return
    release_agent(agent, force=True)


def _g5_start_scope(
    session: str, runner_target: RunnerExecutionTargetV1
) -> tuple[ResourceGateRuntime, PreparedAgentScope]:
    """Create only a newly verified injected scope; missing evidence remains a denial."""

    runtime = _RESOURCE_GATE_RUNTIME.get()
    if runtime is None:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["cgroup_preflight_failed"],
                "errors": spawn_error_details(["cgroup_preflight_failed"]),
            },
        )
    cgroup_runtime = _typed_g5_cgroup_runtime()
    if cgroup_runtime is None:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["cgroup_preflight_failed"],
                "errors": spawn_error_details(["cgroup_preflight_failed"]),
            },
        )
    try:
        scope = start_released_scope(
            cgroup_runtime[1],
            profile=cgroup_runtime[0],
            socket_name=f"g5-{uuid.uuid4().hex[:20]}",
            session_name=session,
            runner_target=runner_target,
        )
    except CgroupPreflightError as exc:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["cgroup_preflight_failed"],
                "errors": spawn_error_details(["cgroup_preflight_failed"]),
            },
        ) from exc
    return runtime, scope


def _g5_confirm_scope(runtime: ResourceGateRuntime, scope: PreparedAgentScope) -> None:
    """Publish a G5 scope only after its Gate attests the pinned runner exec."""

    adapter = runtime.cgroup_adapter
    if adapter is None:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["cgroup_preflight_failed"],
                "errors": spawn_error_details(["cgroup_preflight_failed"]),
            },
        )
    try:
        confirm_verified_scope(adapter, scope)
    except CgroupPreflightError as exc:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["cgroup_preflight_failed"],
                "errors": spawn_error_details(["cgroup_preflight_failed"]),
            },
        ) from exc


def _cleanup_g5_scope(
    runtime: ResourceGateRuntime | None, scope: PreparedAgentScope | None
) -> None:
    if runtime is None or scope is None:
        return
    with contextlib.suppress(Exception):
        run_tmux(
            ["-L", scope.socket_name, "kill-session", "-t", scope.session_name],
            check=False,
        )
    with contextlib.suppress(Exception):
        adapter = runtime.cgroup_adapter
        if adapter is not None:
            adapter.cleanup_new_scope(scope)


def _cleanup_failed_g5_start(
    runtime: ResourceGateRuntime | None,
    scope: PreparedAgentScope | None,
    raw_log: Path,
) -> None:
    """Best-effort cleanup bound to one newly created private G5 session."""

    _cleanup_g5_scope(runtime, scope)
    if scope is not None:
        with contextlib.suppress(Exception):
            cleanup_failed_start(scope.session_name, raw_log, kill_session=False)


def _start_g5_warmup(runtime: ResourceGateRuntime | None) -> None:
    global _SPAWN_WARMUP_UNTIL_NS
    if runtime is None:
        return
    try:
        now_ns = runtime.monotonic_ns()
    except Exception as exc:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["resource_monitor_unavailable"],
                "errors": spawn_error_details(["resource_monitor_unavailable"]),
            },
        ) from exc
    if type(now_ns) is not int or now_ns < 0:
        raise AgentCapacityError(
            "capacity unavailable",
            {
                "error_code": "spawn_capacity_unavailable",
                "retryable": True,
                "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                "reason_codes": ["resource_monitor_unavailable"],
                "errors": spawn_error_details(["resource_monitor_unavailable"]),
            },
        )
    _SPAWN_WARMUP_UNTIL_NS = now_ns + 15_000_000_000


def _reject_legacy_teamlead_start_target(agent_class: str | None) -> None:
    """Keep legacy inventory IDs out of the V2 Teamleiterin start path.

    Dynamic Teamleiterinnen require a V2 registry binding and a committed
    CHPB/2 home attestation.  The legacy ``start_agent`` path has neither, so
    it must stop before auth, routing, resolver, or home materialization.
    """

    if agent_class == "teamleiterin":
        raise AgentError("dynamic_teamlead_legacy_target_forbidden")


def start_agent(
    agent: str,
    cwd: str | None = None,
    prompt: str | None = None,
    lease: dict[str, Any] | None = None,
    release_lease_on_failure: bool = False,
    model: str = DEFAULT_AGENT_MODEL,
    model_reasoning_effort: str | None = None,
    agent_class: str | None = None,
    name: str | None = None,
    replacement_reservation_id: str | None = None,
    confirm_home_refresh: bool = False,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="agent_start")
    require_fleet_recovery_ready("agent_start")
    if type(confirm_home_refresh) is not bool:
        raise AgentError("confirm_home_refresh must be a boolean")
    agent = canonical_agent_id(agent)
    _reject_legacy_teamlead_start_target(agent_class)
    with agent_lifecycle_lock(agent):
        with hive_capacity_probe_guard("agent_start"):
            with _resource_gate_composer_scope():
                name_args = {"name": name} if name is not None else {}
                replacement_args = (
                    {"replacement_reservation_id": replacement_reservation_id}
                    if replacement_reservation_id is not None
                    else {}
                )
                home_refresh_args = (
                    {"confirm_home_refresh": True} if confirm_home_refresh else {}
                )
                return _start_agent_unlocked(
                    agent,
                    cwd,
                    prompt,
                    lease,
                    release_lease_on_failure,
                    model,
                    model_reasoning_effort,
                    agent_class,
                    **name_args,
                    **replacement_args,
                    **home_refresh_args,
                )


def _start_agent_unlocked(
    agent: str,
    cwd: str | None = None,
    prompt: str | None = None,
    lease: dict[str, Any] | None = None,
    release_lease_on_failure: bool = False,
    model: str = DEFAULT_AGENT_MODEL,
    model_reasoning_effort: str | None = None,
    agent_class: str | None = None,
    name: str | None = None,
    replacement_reservation_id: str | None = None,
    confirm_home_refresh: bool = False,
) -> dict[str, Any]:
    require_fleet_recovery_ready("agent_start")
    if type(confirm_home_refresh) is not bool:
        raise AgentError("confirm_home_refresh must be a boolean")
    agent = canonical_agent_id(agent)
    _reject_legacy_teamlead_start_target(agent_class)
    ollama_descriptor = _ollama_descriptor(agent)
    g5_runtime: ResourceGateRuntime | None = None
    g5_scope: PreparedAgentScope | None = None
    ensure_state()
    cfg = agent_config(agent)
    descriptor = current_agent_inventory().agents.get(agent)
    if (
        agent_class == "teamleiterin"
        and descriptor is not None
        and descriptor.series_prefix == "q"
    ):
        enroll_managed_principal(agent, "teamleiterin")
    runner = cfg["runner"]
    session = cfg["session"]
    managed_fleet_home = (
        descriptor is not None
        and descriptor.runner is RunnerKind.CODEX_CLI
        and descriptor.home == AGENT_POOL_ROOT / agent
    )
    managed_codex = managed_fleet_home or (
        descriptor is not None
        and descriptor.runner is RunnerKind.CODEX_CLI
        and _managed_codex_runner_candidate(runner)
    )
    if managed_codex:
        managed_home = _managed_codex_home(cfg["home"])
        managed_wrapper_snapshot = _managed_codex_wrapper_snapshot(runner)
        if agent_class is not None and managed_fleet_home:
            try:
                managed_pool_parent_stat = AGENT_POOL_ROOT.parent.lstat()
                managed_pool_root_stat = AGENT_POOL_ROOT.lstat()
                managed_home_stat = managed_home.lstat()
            except OSError as exc:
                raise AgentError("agent_class_materialization_changed") from exc
            if (
                descriptor.home != managed_home
                or descriptor.home != AGENT_POOL_ROOT / agent
            ):
                raise AgentError("agent_class_materialization_invalid")
            _fleet_private_directory_stat(
                managed_pool_root_stat,
                "agent_class_materialization_invalid",
            )
            _fleet_private_directory_stat(
                managed_home_stat,
                "agent_class_materialization_invalid",
            )
    else:
        try:
            runner_stat = runner.lstat()
        except OSError as exc:
            raise AgentError(
                f"runner for agent {agent} must be a regular executable file"
            ) from exc
        if (
            not stat_module.S_ISREG(runner_stat.st_mode)
            or getattr(runner_stat, "st_nlink", 1) > 1
            or not os.access(runner, os.X_OK)
        ):
            raise AgentError(
                f"runner for agent {agent} must be a regular executable file"
            )
    if tmux_alive(session):
        if replacement_reservation_id is not None:
            _raise_replacement_capacity_denied(
                {
                    "error_code": "spawn_capacity_unavailable",
                    "reason_codes": ["session_metrics_unavailable"],
                }
            )
        process_summary = agent_home_process_summary(agent)
        if process_summary["external_process_count"] is None:
            raise AgentError(
                f"agent {agent} CODEX_HOME process scan is unavailable; retry before starting"
            )
        if process_summary["external_process_count"]:
            raise AgentError(
                f"agent {agent} is already running in tmux, but CODEX_HOME is also used by "
                f"{process_summary['external_process_count']} external process(es); stop the external process(es) first"
            )
        require_managed_tmux_session(agent, process_summary)
        return {
            "agent": agent,
            "status": "already_running",
            "backend": "tmux",
            "session": session,
            "pid": pane_pid(session),
            "lease": agent_lease_status(agent),
            "meta": public_agent_meta(read_meta(agent)),
            "home_external_process_count": process_summary["external_process_count"],
            "raw_output": "not_returned",
        }

    with spawn_admission_lock():
        if replacement_reservation_id is not None:
            validation = require_managed_replacement_reservation(
                replacement_reservation_id, session
            )
            if validation.get("allowed") is not True:
                _raise_replacement_capacity_denied(validation)
        require_spawn_capacity(
            1,
            agent=agent if ollama_descriptor is not None else None,
            task=prompt if ollama_descriptor is not None else None,
            role="arbeitsbiene",
        )
        process_summary = agent_home_process_summary(agent)
        identity_guard = agent_identity_guard(False, process_summary)
        if process_summary["external_process_count"] is None:
            raise AgentError(
                f"agent {agent} CODEX_HOME process scan is unavailable; retry before starting"
            )
        if process_summary["external_process_count"]:
            raise AgentError(
                f"agent {agent} CODEX_HOME is already used by {process_summary['external_process_count']} external process(es); "
                "stop them or use a separate CODEX_HOME before starting through codex-master-mcp"
            )
        if not identity_guard["ok"]:
            raise AgentError(
                f"agent {agent} CODEX_HOME is already used by {process_summary['managed_process_count']} "
                "managed process(es) without the managed tmux session; stop the orphaned process(es) before starting "
                "through codex-master-mcp"
            )

        if managed_fleet_home and agent_class is not None:
            refresh_reasoning_effort = model_reasoning_effort or (
                WRITE_AGENT_MODEL_EFFORT
                if model == WRITE_AGENT_MODEL
                else DEFAULT_AGENT_MODEL_EFFORT
            )
            refreshed = _materialize_managed_codex_runtime_class(
                descriptor,
                agent_class,
                expected_pool_parent_stat=managed_pool_parent_stat,
                expected_pool_root_stat=managed_pool_root_stat,
                expected_home_stat=managed_home_stat,
                confirm_home_refresh=confirm_home_refresh,
                model_reasoning_effort=refresh_reasoning_effort,
            )
            if refreshed:
                managed_wrapper_snapshot = _managed_codex_wrapper_snapshot(runner)
        elif managed_fleet_home:
            _fleet_managed_home_state(
                AGENT_POOL_ROOT,
                descriptor,
                strict_contents=True,
            )

        close_runner_execution_fd(agent)
        cwd = (
            bounded_text(cwd, field="cwd", max_chars=MAX_PATH_TEXT)
            if cwd is not None
            else None
        )
        name = (
            bounded_text(name, field="name", max_chars=MAX_AGENTIN_NAME)
            if name is not None
            else None
        )
        prompt = (
            bounded_text(prompt, field="prompt", max_chars=MAX_SEND_TEXT, strip=False)
            if prompt is not None
            else None
        )
        prompt = apply_agent_introduction_policy(
            prompt, agent_class=agent_class, name=name
        )
        prompt = (
            bounded_text(prompt, field="prompt", max_chars=MAX_SEND_TEXT, strip=False)
            if prompt is not None
            else None
        )
        start_cwd = Path(cwd or os.getcwd()).expanduser().resolve()
        if not start_cwd.exists() or not start_cwd.is_dir():
            raise AgentError("cwd is not a directory")
        effective_model = (
            ollama_descriptor.model if ollama_descriptor is not None else model
        )
        reasoning_effort = (
            None
            if ollama_descriptor is not None
            else model_reasoning_effort
            or (
                WRITE_AGENT_MODEL_EFFORT
                if model == WRITE_AGENT_MODEL
                else DEFAULT_AGENT_MODEL_EFFORT
            )
        )
        routed_args = (
            ["--yolo", "-s", "danger-full-access"]
            if ollama_descriptor is not None
            else agent_base_args(
                model,
                reasoning_effort,
                agent_class=agent_class,
                service_tier=_service_tier_for_agent(agent),
            )
        )

        if managed_codex:
            execution_path, execution_stat = _managed_codex_native_path(
                agent,
                managed_home,
                runner,
                managed_wrapper_snapshot,
            )
            runner_target = open_runner_execution_path(
                agent,
                execution_path,
                execution_stat,
                require_elf=True,
                error_code="managed_codex_runner_changed",
            )
        else:
            runner_target = open_runner_execution_path(agent, runner, runner_stat)
        run_id = f"{now_id()}-{agent}"
        raw_log = RAW_DIR / f"{run_id}.log"
        raw_log_created = False
        try:
            write_private_new_bytes(raw_log, b"")
            raw_log_created = True
            prune_raw_logs()
        except Exception:
            if raw_log_created:
                with contextlib.suppress(Exception):
                    cleanup_failed_start(session, raw_log, kill_session=False)
            close_runner_execution_fd(agent)
            raise

        argv = [*routed_args]
        if prompt:
            argv.append(prompt)

        if managed_codex:
            command = (
                "env -u CODEX_ACCESS_TOKEN -u OPENAI_API_KEY "
                f"CODEX_HOME={shlex.quote(str(managed_home))} "
                'CODEX_MASTER_MCP=1 CODEX_AGENT_MCP=1 "${CODEX_MASTER_RUNNER_EXEC_PATH:?}"'
            )
        else:
            command = 'env CODEX_MASTER_MCP=1 CODEX_AGENT_MCP=1 "${CODEX_MASTER_RUNNER_EXEC_PATH:?}"'
        if argv:
            command += " " + shlex.join(argv)
        try:
            g5_runtime, g5_scope = _g5_start_scope(session, runner_target)
        except Exception:
            with contextlib.suppress(Exception):
                cleanup_failed_start(session, raw_log, kill_session=False)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise
        close_runner_execution_fd(agent)
        tmux_prefix = ["-L", g5_scope.socket_name]
        try:
            cp = run_tmux(
                [
                    *tmux_prefix,
                    "send-keys",
                    "-t",
                    session,
                    f"cd {shlex.quote(str(start_cwd))} && exec {command}",
                    "Enter",
                ],
                check=False,
            )
        except Exception:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            raise
        if cp.returncode != 0:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise AgentError(f"tmux start failed for agent {agent}")

        try:
            _g5_confirm_scope(g5_runtime, g5_scope)
        except Exception:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise

        try:
            pipe_command = raw_log_writer_command(raw_log)
            pipe = run_tmux(
                [*tmux_prefix, "pipe-pane", "-o", "-t", session, pipe_command],
                check=False,
            )
        except Exception:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise
        if pipe.returncode != 0:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise AgentError(f"tmux pipe-pane failed for agent {agent}")

        data = {
            "agent": agent,
            "backend": "tmux",
            "label": cfg["label"],
            "session": session,
            "home": str(cfg["home"]),
            "runner": str(runner),
            "cwd": str(start_cwd),
            "args": routed_args,
            "model": effective_model,
            "model_reasoning_effort": reasoning_effort,
            "agent_class": agent_class,
            "started_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
            "run_id": run_id,
            "raw_log": str(raw_log),
            "raw_log_policy": "local_only_bounded_not_returned_by_default",
            "raw_log_max_bytes": MAX_RAW_LOG_BYTES,
            G5_TMUX_SOCKET_META_KEY: g5_scope.socket_name,
        }
        if managed_codex:
            data[G5_NATIVE_RUNNER_META_KEY] = {
                "device": runner_target.device,
                "inode": runner_target.inode,
                "scope_unit": g5_scope.unit_name,
            }
        try:
            write_meta(agent, data)
            _start_g5_warmup(g5_runtime)
        except Exception:
            _cleanup_failed_g5_start(g5_runtime, g5_scope, raw_log)
            close_runner_execution_fd(agent)
            release_start_lease_if_safe(agent, lease, release_lease_on_failure)
            raise
        return {
            "agent": agent,
            "status": "started",
            "backend": "tmux",
            "session": session,
            "pid": None,
            "cwd": PATH_NOT_RETURNED,
            "cwd_state": "set",
            "lease": lease or agent_lease_status(agent),
            "model": model,
            "model_reasoning_effort": reasoning_effort,
            "raw_log": "not_returned",
            "raw_log_max_bytes": MAX_RAW_LOG_BYTES,
            "raw_output": "not_returned",
        }


def _headless_descriptor(
    agent: str, snapshot: InventorySnapshot | None = None
) -> AgentDescriptor | None:
    inventory = snapshot or current_agent_inventory()
    descriptor = inventory.agents.get(agent)
    if descriptor is None or descriptor.runner is not RunnerKind.GEMINI_CLI:
        return None
    return descriptor


def _headless_write_scope_store() -> HeadlessWriteScopeStore:
    """Return the durable write-boundary store for this server state root."""

    ensure_state()
    return HeadlessWriteScopeStore(
        STATE_ROOT / "headless-write-scope",
        git_runner=run_command,
    )


def _raise_headless_scope_failure(failure: HeadlessWriteScopeFailure) -> None:
    if failure.code == "headless_write_scope_unenforced":
        raise HeadlessWriteScopeError()
    raise AgentError(
        failure.code,
        {
            "code": failure.code,
            "explanation": failure.explanation,
            "action": failure.action,
        },
    )


def _public_headless_scope_result(result: ScopeResult) -> dict[str, Any]:
    """Expose counts and a stable code, never changed paths or filesystem paths."""

    return {
        "ok": result.ok,
        "code": result.code,
        "changed_count": result.changed_count,
        "attributed_count": result.attributed_count,
        "out_of_scope_count": result.out_of_scope_count,
        "paths": "not_returned",
        "raw_output": "not_returned",
    }


def _ollama_descriptor(
    agent: str, snapshot: InventorySnapshot | None = None
) -> AgentDescriptor | None:
    inventory = snapshot or current_agent_inventory()
    descriptor = inventory.agents.get(agent)
    if descriptor is None or descriptor.provider is not Provider.OLLAMA_LOCAL:
        return None
    return descriptor


def _headless_executable(descriptor: AgentDescriptor) -> Path:
    candidate = descriptor.runner_path or descriptor.home / "gemini"
    if not isinstance(candidate, Path) or not candidate.is_absolute():
        raise AgentError("headless_runner_unavailable")
    # The registry's runner_path points at the managed wrapper in the home.
    # Headless execution must pin the installed Gemini bundle that the wrapper
    # invokes, otherwise a refresh would generate a wrapper that execs itself.
    if candidate == descriptor.home / "gemini":
        found = shutil.which("gemini")
        if found is None:
            raise AgentError("headless_runner_unavailable")
        candidate = trusted_gemini_executable(Path(found))
    try:
        info = candidate.lstat()
    except OSError as exc:
        raise AgentError("headless_runner_unavailable") from exc
    if (
        stat_module.S_ISLNK(info.st_mode)
        or not stat_module.S_ISREG(info.st_mode)
        or getattr(info, "st_nlink", 1) > 1
        or info.st_uid not in {0, os.getuid() if hasattr(os, "getuid") else -1}
        or info.st_mode & 0o022
        or not directory_chain_is_real_no_symlink(candidate.parent)
        or not executable_directory_chain_is_trusted(candidate.parent)
    ):
        raise AgentError("headless_runner_unavailable")
    if not os.access(candidate, os.X_OK):
        raise AgentError("headless_runner_unavailable")
    return candidate


def _ensure_gemini_headless_retry_policy(home: Path) -> None:
    settings_path = home / ".gemini" / "settings.json"
    settings_text = fleet_read_optional_private_text(
        settings_path,
        256 * 1024,
        "headless_settings_invalid",
    )
    if settings_text is None:
        return
    try:
        document = json.loads(settings_text)
    except (json.JSONDecodeError, UnicodeError) as exc:
        raise AgentError("headless_settings_invalid") from exc
    if not isinstance(document, dict):
        raise AgentError("headless_settings_invalid")
    general = document.get("general")
    if general is None:
        general = {}
        document["general"] = general
    if not isinstance(general, dict):
        raise AgentError("headless_settings_invalid")
    if general.get("maxAttempts") == 1 and general.get("retryFetchErrors") is False:
        _refresh_gemini_fleet_marker_if_managed(home, settings_text)
        return
    general["maxAttempts"] = 1
    general["retryFetchErrors"] = False
    settings_text = json.dumps(document, indent=2, sort_keys=True) + "\n"
    replace_private_text(settings_path, settings_text)
    _refresh_gemini_fleet_marker_if_managed(home, settings_text)


def _refresh_gemini_fleet_marker_if_managed(home: Path, settings_text: str) -> None:
    try:
        (home / FLEET_AGENT_MARKER_FILE).lstat()
    except FileNotFoundError:
        return
    except OSError as exc:
        raise AgentError("headless_marker_invalid") from exc
    _refresh_gemini_fleet_marker(home, settings_text)


def _refresh_gemini_fleet_marker(home: Path, settings_text: str) -> None:
    """Keep the managed-home digest in sync with the bounded retry policy."""

    marker_record = _fleet_read_current_agent_marker(
        home,
        "headless_marker_invalid",
    )
    if marker_record is None:
        raise AgentError("headless_marker_invalid")
    _marker_bytes, marker, _projection = marker_record
    if marker["runner"] != RunnerKind.GEMINI_CLI.value:
        raise AgentError("headless_marker_invalid")
    files = marker["files"]
    if ".gemini/settings.json" not in files:
        raise AgentError("headless_marker_invalid")
    files[".gemini/settings.json"] = hashlib.sha256(
        settings_text.encode("utf-8")
    ).hexdigest()
    replace_private_text(
        home / FLEET_AGENT_MARKER_FILE,
        json.dumps(marker, indent=2, sort_keys=True) + "\n",
    )


def _headless_marker(agent: str) -> dict[str, Any]:
    value = read_meta(agent).get(HEADLESS_META_KEY)
    return dict(value) if isinstance(value, dict) else {}


def _write_headless_marker(agent: str, marker: dict[str, Any]) -> None:
    meta = read_meta(agent)
    if meta.get("meta_error"):
        raise AgentError("could_not_update_headless_metadata")
    meta[HEADLESS_META_KEY] = marker
    write_meta(agent, meta)


def _headless_public_gate(agent: str) -> dict[str, Any]:
    try:
        gate = _readonly_fleet_service().account_gate(agent)
    except Exception:
        return {
            "allowed": False,
            "reason": "account_gate_unavailable",
            "raw_output": "not_returned",
        }
    return {
        "allowed": gate.allowed,
        "reason": gate.reason,
        "raw_output": "not_returned",
    }


def _headless_admission_gate(
    agent: str,
    *,
    inventory: InventorySnapshot | None = None,
    probed_accounts: set[str] | None = None,
) -> Any:
    """Return a usable gate, probing one stale project only when needed."""
    service = current_fleet_service()
    try:
        gate = service.account_gate(agent, inventory=inventory)
    except TypeError:
        # Compatibility with the small service adapters used by embedders.
        gate = service.account_gate(agent)
    if gate.reason not in {"probe_stale", "limit_unknown"} or gate.account_id is None:
        return gate
    seen = probed_accounts if probed_accounts is not None else set()
    if gate.account_id not in seen:
        seen.add(gate.account_id)
        try:
            fleet_account_probe(
                account_id=gate.account_id,
                expected_generation=service.load().generation,
            )
        except Exception:
            # The authoritative gate below decides whether this project is
            # actually usable.  A failed probe is a reason to route away,
            # never a reason to expose a stale candidate.
            pass
        try:
            fresh = service.load()
            gate = service.account_gate(
                agent, inventory=build_inventory(fresh, AGENT_POOL_ROOT)
            )
        except Exception:
            gate = service.account_gate(agent)
    return gate


def _validate_headless_timeout(timeout_seconds: Any) -> None:
    if (
        isinstance(timeout_seconds, bool)
        or not isinstance(timeout_seconds, (int, float))
        or not 0 < timeout_seconds <= MAX_HEADLESS_TIMEOUT_SECONDS
    ):
        raise AgentError("headless_timeout_invalid")


def _headless_job_identity(process: object, home: Path) -> dict[str, Any]:
    pid = getattr(process, "pid", None)
    identity: dict[str, Any] = {
        "pid": pid if isinstance(pid, int) and pid > 0 else None,
        "pgid": None,
        "proc_start_ticks": None,
        "home_tag": hashlib.sha256(str(home).encode("utf-8")).hexdigest(),
    }
    if identity["pid"] is None:
        return identity
    try:
        identity["pgid"] = os.getpgid(identity["pid"])
    except OSError:
        return identity
    try:
        stat_text = Path(f"/proc/{identity['pid']}/stat").read_text(encoding="ascii")
        fields = stat_text.rsplit(")", 1)[-1].split()
        if len(fields) > 19 and fields[19].isdigit():
            identity["proc_start_ticks"] = int(fields[19])
    except (OSError, UnicodeError, ValueError):
        pass
    return identity


def headless_job_status(agent: str) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    current = HEADLESS_JOBS.status(agent)
    if current.get("status") in {"running", "cancelling"}:
        return {**current, "backend": "headless_job", "raw_output": "not_returned"}
    marker = _headless_marker(agent)
    state = marker.get("state")
    if state == "running":
        identity = _headless_recovery_identity(agent, marker)
        if identity is not None:
            return {
                "agent": agent,
                "assignment_id": marker.get("assignment_id"),
                "status": "running",
                "backend": "headless_job",
                "running": True,
                "pid": identity[0],
                "identity_verified": True,
                "raw_output": "not_returned",
            }
        return {
            "agent": agent,
            "assignment_id": marker.get("assignment_id"),
            "status": "identity_unverified",
            "backend": "headless_job",
            "running": False,
            "identity_verified": False,
            "raw_output": "not_returned",
        }
    if not isinstance(state, str):
        state = "not_started"
    return {
        "agent": agent,
        "assignment_id": marker.get("assignment_id"),
        "status": state,
        "backend": "headless_job",
        "running": state in {"running", "cancelling"},
        "raw_output": "not_returned",
    }


def _headless_process_start_ticks(pid: int) -> int | None:
    try:
        stat_text = Path(f"/proc/{pid}/stat").read_text(encoding="ascii")
        fields = stat_text.rsplit(")", 1)[-1].split()
        if len(fields) > 19 and fields[19].isdigit():
            return int(fields[19])
    except (OSError, UnicodeError, ValueError):
        pass
    return None


def _headless_recovery_identity(
    agent: str, marker: Mapping[str, Any]
) -> tuple[int, int] | None:
    descriptor = _headless_descriptor(agent)
    process = marker.get("process")
    if descriptor is None or not isinstance(process, Mapping):
        return None
    pid = process.get("pid")
    pgid = process.get("pgid")
    start_ticks = process.get("proc_start_ticks")
    home_tag = process.get("home_tag")
    if (
        isinstance(pid, bool)
        or not isinstance(pid, int)
        or pid <= 0
        or isinstance(pgid, bool)
        or not isinstance(pgid, int)
        or pgid <= 0
        or isinstance(start_ticks, bool)
        or not isinstance(start_ticks, int)
        or start_ticks <= 0
        or not isinstance(home_tag, str)
        or home_tag != hashlib.sha256(str(descriptor.home).encode("utf-8")).hexdigest()
    ):
        return None
    try:
        current_pgid = os.getpgid(pid)
    except OSError:
        return None
    if current_pgid != pgid or pgid == os.getpgrp():
        return None
    if _headless_process_start_ticks(pid) != start_ticks:
        return None
    return pid, pgid


def _recover_headless_process(agent: str, marker: Mapping[str, Any]) -> str:
    identity = _headless_recovery_identity(agent, marker)
    if identity is None:
        return "identity_unverified"
    _pid, pgid = identity
    try:
        os.killpg(pgid, signal.SIGTERM)
    except ProcessLookupError:
        return "already_gone"
    except OSError:
        return "identity_unverified"

    deadline = time.monotonic() + 1.0
    while time.monotonic() < deadline:
        try:
            os.killpg(pgid, 0)
        except ProcessLookupError:
            return "stopped"
        except OSError:
            return "identity_unverified"
        time.sleep(0.05)
    try:
        os.killpg(pgid, signal.SIGKILL)
    except ProcessLookupError:
        return "stopped"
    except OSError:
        return "identity_unverified"
    return "stopped"


def cancel_headless_job(agent: str, force: bool = False) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    result = HEADLESS_JOBS.request_cancel(agent, force=force)
    if result.get("status") in {"running", "cancelling"}:
        marker = _headless_marker(agent)
        marker.update({"state": "cancelling", "cancel_requested": True})
        _write_headless_marker(agent, marker)
    else:
        marker = _headless_marker(agent)
        if marker.get("state") in {"running", "cancelling"}:
            recovery = _recover_headless_process(agent, marker)
            if recovery == "identity_unverified":
                return {
                    "agent": agent,
                    "status": "identity_unverified",
                    "running": False,
                    "recovery": recovery,
                    "backend": "headless_job",
                    "raw_output": "not_returned",
                }
            is_recovered = recovery in {"stopped", "already_gone"}
            if is_recovered:
                released: dict[str, Any] | None = None
                reservation_id = marker.get("headless_inflight_reservation_id")
                assignment_id = marker.get("assignment_id")
                if isinstance(reservation_id, str) and isinstance(assignment_id, str):
                    with contextlib.suppress(Exception):
                        released = release_headless_inflight(
                            reservation_id, agent, assignment_id
                        )
                    if isinstance(released, dict):
                        marker.pop("headless_inflight_reservation_id", None)
            marker.update({"state": "cancelled" if is_recovered else "failed"})
            marker.pop("process", None)
            _write_headless_marker(agent, marker)
            result = {
                "agent": agent,
                "status": "cancelled" if is_recovered else "not_running",
                "running": False,
                "recovery": recovery,
                "raw_output": "not_returned",
            }
    return {**result, "backend": "headless_job", "raw_output": "not_returned"}


def _start_headless_agent_unlocked(agent: str) -> dict[str, Any]:
    """Create a ready headless slot only under the final capacity recheck."""

    require_resource_capacity_preflight(operation="agent_start")
    with hive_capacity_probe_guard("agent_start"):
        return _start_headless_agent_after_capacity_probe_unlocked(agent)


def _start_headless_agent_after_capacity_probe_unlocked(
    agent: str,
) -> dict[str, Any]:
    requested_agent = canonical_agent_id(agent)
    agent, descriptor, structured_gate, routing_gate = _resolve_gemini_headless_route(
        requested_agent
    )
    status = status_agent(agent, initialize_state=False)
    identity = status.get("identity_guard")
    if isinstance(identity, Mapping) and identity.get("ok") is not True:
        raise AgentError("headless_identity_unverified")
    gate = _headless_admission_gate(agent)
    if not gate.allowed:
        raise AgentError(gate.reason)
    if structured_gate.get("action") != "allow":
        return {
            "agent": agent,
            "requested_agent": requested_agent,
            "selected_agent": agent,
            "status": "deferred"
            if structured_gate.get("action") == "defer_until"
            else "failed",
            "backend": "headless_job",
            "model": descriptor.model,
            "gate": structured_gate,
            "routing_gate": routing_gate,
            "raw_output": "not_returned",
        }
    marker = _headless_marker(agent)
    current = HEADLESS_JOBS.status(agent)
    if current.get("status") in {"running", "cancelling"}:
        return {
            "agent": agent,
            "requested_agent": requested_agent,
            "selected_agent": agent,
            "status": "already_running",
            "backend": "headless_job",
            "job": current,
            "account_gate": _headless_public_gate(agent),
            "gate": structured_gate,
            "routing_gate": routing_gate,
            "raw_output": "not_returned",
        }
    marker = {
        "agent": agent,
        "backend": "headless_job",
        "state": "ready",
        "assignment_id": None,
        "generation": gate.generation,
        "started_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "raw_output": "not_returned",
    }
    _write_headless_marker(agent, marker)
    return {
        "agent": agent,
        "requested_agent": requested_agent,
        "selected_agent": agent,
        "status": "ready",
        "backend": "headless_job",
        "model": descriptor.model,
        "lease": agent_lease_status(agent),
        "account_gate": _headless_public_gate(agent),
        "gate": structured_gate,
        "routing_gate": routing_gate,
        "raw_output": "not_returned",
    }


def _headless_scope_result_error(result: ScopeResult | None) -> AgentError | None:
    if result is None or result.ok:
        return None
    return AgentError(
        result.code,
        {
            "code": result.code,
            "explanation": "headless write attribution failed",
            "action": "discard the assignment and inspect the bound worktree",
            "changed_count": result.changed_count,
            "out_of_scope_count": result.out_of_scope_count,
        },
    )


def _run_headless_process(
    agent: str,
    prompt: str,
    lease: Mapping[str, Any],
    timeout_seconds: float,
    *,
    role: str = "arbeitsbiene",
    assignment_id: str | None = None,
    release_lease_on_completion: bool = True,
    reservation: object | None = None,
    headless_inflight_reservation: object | None = None,
    structured_gate: Mapping[str, Any] | None = None,
    write_scope_binding: ScopeBinding | None = None,
    write_scope_store: HeadlessWriteScopeStore | None = None,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="headless_assignment")
    headless_inflight_reservation_id = (
        headless_inflight_reservation.get("reservation_id")
        if isinstance(headless_inflight_reservation, Mapping)
        else None
    )
    release_bound_headless_inflight_called = False
    terminal: str | None = None
    scope_result: ScopeResult | None = None
    normal_return = False
    active_write_scope_store = write_scope_store
    role = role.strip().lower()
    if role not in {"exploriererin", "arbeitsbiene"}:
        raise AgentError("role must be 'exploriererin' or 'arbeitsbiene'")
    if role == "arbeitsbiene" and write_scope_binding is None:
        raise HeadlessWriteScopeError()

    def release_bound_headless_inflight() -> None:
        nonlocal release_bound_headless_inflight_called
        if release_bound_headless_inflight_called:
            return
        if not isinstance(headless_inflight_reservation_id, str):
            return
        release_bound_headless_inflight_called = True
        released: dict[str, Any] | None = None
        marker: dict[str, Any] | None = None
        with contextlib.suppress(Exception):
            marker_value = _headless_marker(agent)
            if isinstance(marker_value, dict):
                marker = marker_value
        with contextlib.suppress(Exception):
            released = release_headless_inflight(
                headless_inflight_reservation_id,
                agent,
                assignment_id,
            )
        if (
            isinstance(released, dict)
            and marker is not None
            and isinstance(marker.get("assignment_id"), str)
            and marker.get("assignment_id") == assignment_id
            and marker.get("headless_inflight_reservation_id")
            == headless_inflight_reservation_id
        ):
            marker.pop("headless_inflight_reservation_id", None)
            with contextlib.suppress(Exception):
                _write_headless_marker(agent, marker)

    def consume_write_scope() -> ScopeResult | None:
        """Consume binding once, including failures before process launch."""

        nonlocal active_write_scope_store, scope_result
        if write_scope_binding is None or scope_result is not None:
            return scope_result
        if active_write_scope_store is None:
            try:
                active_write_scope_store = _headless_write_scope_store()
            except Exception as exc:
                raise AgentError("headless_write_scope_unenforced") from exc
        try:
            scope_result = active_write_scope_store.finalize(write_scope_binding)
        except HeadlessWriteScopeFailure as exc:
            scope_result = ScopeResult(False, exc.code, 0, 0, 0)
        except Exception:
            scope_result = ScopeResult(
                False, "headless_write_attribution_unverified", 0, 0, 0
            )
        return scope_result

    try:
        service = current_fleet_service()
    except Exception:
        finished_scope = consume_write_scope()
        release_bound_headless_inflight()
        scope_error = _headless_scope_result_error(finished_scope)
        if scope_error is not None:
            raise scope_error from None
        raise
    try:
        descriptor = _headless_descriptor(agent)
        if descriptor is None:
            raise AgentError("headless_runner_unavailable")
        prompt = (
            bounded_text(
                prompt, field="prompt", max_chars=MAX_ASSIGNMENT_TEXT, required=True
            )
            or ""
        )
        _validate_headless_timeout(timeout_seconds)
        if lease.get("state") != "held" or lease.get("held_by_this_server") is not True:
            raise AgentError("headless_lease_not_held")
        marker = _headless_marker(agent)
        if marker.get("state") not in {"ready", "running"}:
            raise AgentError("headless_slot_not_ready")
    except Exception:
        finished_scope = consume_write_scope()
        release_bound_headless_inflight()
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(reservation, outcome="provider_error")
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                release_agent(agent, force=True)
        scope_error = _headless_scope_result_error(finished_scope)
        if scope_error is not None:
            raise scope_error from None
        raise
    try:
        structured_gate = dict(
            _gemini_headless_gate(agent) if structured_gate is None else structured_gate
        )
    except Exception:
        finished_scope = consume_write_scope()
        release_bound_headless_inflight()
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(reservation, outcome="provider_error")
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                release_agent(agent, force=True)
        scope_error = _headless_scope_result_error(finished_scope)
        if scope_error is not None:
            raise scope_error from None
        raise
    if structured_gate.get("action") != "allow":
        finished_scope = consume_write_scope()
        account_id = structured_gate.get("account_id")
        gate_code = structured_gate.get("diagnostic_code")
        with contextlib.suppress(Exception):
            if isinstance(account_id, str) and isinstance(gate_code, str):
                service.record_gemini_usage(
                    account_id,
                    model=descriptor.model,
                    status="failed",
                    gate_action=str(structured_gate.get("action")),
                    gate_code=gate_code,
                    next_reset_at_utc=structured_gate.get("defer_until"),
                )
                service.record_gemini_event(
                    event_type="headless_gate",
                    agent_id=agent,
                    account_id=account_id,
                    assignment_id=assignment_id,
                    status="deferred"
                    if structured_gate.get("action") == "defer_until"
                    else "failed",
                    reason=gate_code,
                    model=descriptor.model,
                    gate_action=str(structured_gate.get("action")),
                    gate_code=gate_code,
                    next_reset_at_utc=structured_gate.get("defer_until"),
                )
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(reservation, outcome="provider_error")
        release_bound_headless_inflight()
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                release_agent(agent, force=True)
        scope_error = (
            {
                "kind": finished_scope.code,
                "retryable": False,
                "changed_count": finished_scope.changed_count,
                "out_of_scope_count": finished_scope.out_of_scope_count,
            }
            if finished_scope is not None and not finished_scope.ok
            else None
        )
        return {
            "agent": agent,
            "assignment_id": assignment_id,
            "status": "failed"
            if scope_error is not None
            else "deferred"
            if structured_gate.get("action") == "defer_until"
            else "failed",
            "model": descriptor.model,
            "response": "",
            "gate": structured_gate,
            "error": scope_error,
            "write_scope": (
                _public_headless_scope_result(finished_scope)
                if finished_scope is not None
                else None
            ),
            "raw_output": "not_returned",
        }
    gate_action = structured_gate.get("action")
    gate_code = structured_gate.get("diagnostic_code")
    if not isinstance(gate_action, str) or not isinstance(gate_code, str):
        finished_scope = consume_write_scope()
        release_bound_headless_inflight()
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(reservation, outcome="provider_error")
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                release_agent(agent, force=True)
        scope_error = _headless_scope_result_error(finished_scope)
        if scope_error is not None:
            raise scope_error from None
        raise AgentError("headless_gate_invalid")
    try:
        status = status_agent(agent, initialize_state=False)
        identity = status.get("identity_guard")
        if isinstance(identity, Mapping) and identity.get("ok") is not True:
            raise AgentError("headless_identity_unverified")
        gate = _headless_admission_gate(agent)
        if not gate.allowed or gate.account_id is None:
            raise AgentError(gate.reason)
        if structured_gate.get("account_id") != gate.account_id:
            raise AgentError("headless_gate_binding_changed")
        fresh_snapshot = service.load()
        fresh_inventory = build_inventory(fresh_snapshot, AGENT_POOL_ROOT)
        fresh_descriptor = fresh_inventory.agents.get(agent)
        if (
            fresh_descriptor is None
            or fresh_descriptor.runner is not descriptor.runner
            or fresh_descriptor.provider is not descriptor.provider
            or fresh_descriptor.model != descriptor.model
            or fresh_descriptor.account_id != descriptor.account_id
        ):
            raise AgentError("headless_binding_changed")
        executable = _headless_executable(descriptor)
        _ensure_gemini_headless_retry_policy(descriptor.home)
        plan = build_runner_plan(descriptor, executable)
        child_env = dict(os.environ)
        for name in plan.unset_env | {"CODEX_HOME"}:
            child_env.pop(name, None)
        child_env.update(plan.env)
        if plan.secret_env_name is None:
            raise AgentError("headless_secret_binding_missing")
        argv = list(plan.argv)
        argv.append(
            "--approval-mode=plan"
            if role == "exploriererin"
            else "--approval-mode=auto_edit"
        )
        assignment_id = assignment_id or f"{now_id()}-{agent}"
    except Exception:
        finished_scope = consume_write_scope()
        release_bound_headless_inflight()
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(reservation, outcome="provider_error")
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                release_agent(agent, force=True)
        scope_error = _headless_scope_result_error(finished_scope)
        if scope_error is not None:
            raise scope_error from None
        raise
    process: object | None = None
    job: HeadlessJob | None = None
    result: HeadlessProcessResult | None = None
    parsed = None
    popen_env: dict[str, str] | None = None
    worktree_fd = -1
    process_end_confirmed = False
    rate_outcome = "provider_error"
    rate_reset_at_utc: str | None = None
    secret = ""
    try:
        try:
            if reservation is None and gate.account_id is not None:
                with hive_capacity_probe_guard("headless_assignment"):
                    reservation = service.reserve_gemini_request(
                        gate.account_id, model=descriptor.model
                    )
            secret = service.read_secret(
                gate.account_id, expected_generation=gate.generation
            )
            child_env[plan.secret_env_name] = secret
            run_cwd = descriptor.home
            if write_scope_binding is not None:
                active_write_scope_store = (
                    active_write_scope_store or _headless_write_scope_store()
                )
                try:
                    verified_attestation = active_write_scope_store.revalidate(
                        write_scope_binding,
                        repo_root(),
                        provider_generation=gate.generation,
                    )
                except HeadlessWriteScopeFailure as exc:
                    _raise_headless_scope_failure(exc)
                try:
                    verified_worktree = Path(verified_attestation.worktree_path)
                    expected_device = verified_attestation.worktree_device
                    expected_inode = verified_attestation.worktree_inode
                except (AttributeError, TypeError) as exc:
                    raise AgentError("headless_worktree_identity_changed") from exc
                if (
                    type(expected_device) is not int
                    or type(expected_inode) is not int
                    or expected_device < 0
                    or expected_inode <= 0
                ):
                    raise AgentError("headless_worktree_identity_changed")
                try:
                    expected_worktree_stat = os.stat(
                        verified_worktree, follow_symlinks=False
                    )
                except OSError as exc:
                    raise AgentError("headless_worktree_identity_changed") from exc
                worktree_fd = open_directory_chain_no_follow_matching(
                    verified_worktree,
                    expected_worktree_stat,
                    error_text="headless_worktree_identity_changed",
                    changed_text="headless_worktree_identity_changed",
                )
                opened_worktree_stat = os.fstat(worktree_fd)
                if (
                    opened_worktree_stat.st_dev != expected_device
                    or opened_worktree_stat.st_ino != expected_inode
                ):
                    raise AgentError("headless_worktree_identity_changed")
                run_cwd = Path(f"/proc/self/fd/{worktree_fd}")
            popen_env = dict(child_env)
            popen_kwargs: dict[str, Any] = {
                "stdin": subprocess.PIPE,
                "stdout": subprocess.PIPE,
                "stderr": subprocess.PIPE,
                "env": popen_env,
                "cwd": run_cwd,
                "shell": False,
                "start_new_session": True,
            }
            if worktree_fd >= 0:
                popen_kwargs["pass_fds"] = (worktree_fd,)
            try:
                with hive_capacity_probe_guard("headless_assignment"):
                    process = subprocess.Popen(
                        tuple(argv),
                        **popen_kwargs,
                    )
            except (OSError, ValueError) as exc:
                raise AgentError("headless_start_failed") from exc
        except Exception:
            consume_write_scope()
            release_bound_headless_inflight()
            raise
        job = HeadlessJob(
            agent, assignment_id, process, time.monotonic(), gate.generation
        )
        HEADLESS_JOBS.register(job)
        running_marker = {
            "agent": agent,
            "backend": "headless_job",
            "state": "running",
            "assignment_id": assignment_id,
            "generation": gate.generation,
            "process": _headless_job_identity(process, descriptor.home),
            "started_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        }
        if isinstance(headless_inflight_reservation_id, str):
            running_marker["headless_inflight_reservation_id"] = (
                headless_inflight_reservation_id
            )
        _write_headless_marker(agent, running_marker)
        child_env.pop(plan.secret_env_name, None)
        popen_env.clear()
        popen_env = None
        secret = ""
        result = run_bounded_process(
            job,
            tuple(argv),
            prompt,
            child_env,
            HEADLESS_JOBS,
            timeout_seconds=timeout_seconds,
        )
        try:
            parsed = parse_gemini_jsonl(result.stdout.decode("utf-8").splitlines())
        except (FleetRunnerError, UnicodeDecodeError) as exc:
            _write_headless_marker(
                agent,
                {
                    "agent": agent,
                    "backend": "headless_job",
                    "state": "failed",
                    "assignment_id": assignment_id,
                    "generation": gate.generation,
                    "error": "invalid_headless_output",
                    **(
                        {
                            "headless_inflight_reservation_id": headless_inflight_reservation_id
                        }
                        if isinstance(headless_inflight_reservation_id, str)
                        else {}
                    ),
                },
            )
            raise AgentError("invalid_headless_output") from exc
        quota_observation = (
            parsed.error.quota_observation
            if parsed.error is not None
            and parsed.error.kind == "account_limited"
            and isinstance(
                parsed.error.quota_observation, ProviderErrorQuotaObservation
            )
            else None
        )
        model_scope_quota_observation = (
            quota_observation
            if isinstance(quota_observation, ProviderErrorQuotaObservation)
            and quota_observation.scope == "model"
            and isinstance(quota_observation.retry_after_seconds, int)
            and not isinstance(quota_observation.retry_after_seconds, bool)
            and quota_observation.retry_after_seconds > 0
            else None
        )
        if (
            parsed.error is not None
            and parsed.error.kind == "account_limited"
            and model_scope_quota_observation is None
        ):
            rate_outcome = "rate_limited"
            rate_reset_at_utc = parsed.error.reset_at_utc
            try:
                service.mark_limited(
                    gate.account_id,
                    reset_at_utc=parsed.error.reset_at_utc,
                    reason="gemini_resource_exhausted",
                )
            except Exception as exc:
                raise AgentError("headless_limit_mark_failed") from exc
        if (
            parsed.error is not None
            and parsed.error.kind == "account_limited"
            and model_scope_quota_observation is not None
        ):
            rate_reset_at_utc = None
        terminal = (
            "timeout"
            if result.timed_out
            else "cancelled"
            if result.cancelled
            else (
                "completed"
                if result.returncode == 0
                and parsed.error is None
                and not result.stdout_truncated
                and not result.stderr_truncated
                else "failed"
            )
        )
        if write_scope_binding is not None:
            finished_scope = consume_write_scope()
            if finished_scope is None:
                raise AgentError("headless_write_scope_unenforced")
            if not finished_scope.ok:
                terminal = "failed"
        usage_status = (
            "rate_limited"
            if parsed.error is not None and parsed.error.kind == "account_limited"
            else terminal
        )
        terminal_marker = {
            "agent": agent,
            "backend": "headless_job",
            "state": terminal,
            "assignment_id": assignment_id,
            "generation": gate.generation,
            "returncode": result.returncode,
            "stdout_truncated": result.stdout_truncated,
            "stderr_truncated": result.stderr_truncated,
        }
        if scope_result is not None:
            terminal_marker["write_scope"] = _public_headless_scope_result(scope_result)
        if isinstance(headless_inflight_reservation_id, str):
            terminal_marker["headless_inflight_reservation_id"] = (
                headless_inflight_reservation_id
            )
        _write_headless_marker(agent, terminal_marker)
        with contextlib.suppress(Exception):
            service.record_gemini_usage(
                gate.account_id,
                model=parsed.model or descriptor.model,
                input_tokens=parsed.input_tokens,
                output_tokens=parsed.output_tokens,
                status=usage_status,
                tool_call_count=parsed.tool_call_count,
                gate_action=gate_action,
                gate_code=gate_code,
                next_reset_at_utc=rate_reset_at_utc,
                quota_observation=quota_observation,
            )
        with contextlib.suppress(Exception):
            service.record_gemini_event(
                event_type="headless_result",
                agent_id=agent,
                account_id=gate.account_id,
                assignment_id=assignment_id,
                status=usage_status,
                reason=parsed.error.kind if parsed.error is not None else None,
                model=parsed.model or descriptor.model,
                input_tokens=parsed.input_tokens,
                output_tokens=parsed.output_tokens,
                tool_call_count=parsed.tool_call_count,
                gate_action=gate_action,
                gate_code=gate_code,
                next_reset_at_utc=rate_reset_at_utc,
            )
        response = parsed.response if terminal == "completed" else ""
        if terminal == "completed":
            rate_outcome = "completed"
        normal_return = True
        return {
            "agent": agent,
            "assignment_id": assignment_id,
            "status": terminal,
            "model": parsed.model or descriptor.model,
            "response": response,
            "gate": structured_gate,
            "session_id": parsed.session_id,
            "input_tokens": parsed.input_tokens,
            "output_tokens": parsed.output_tokens,
            "tool_call_count": parsed.tool_call_count,
            "event_count": parsed.event_count,
            "unknown_event_count": parsed.unknown_event_count,
            "error": (
                {
                    "kind": scope_result.code,
                    "retryable": False,
                    "changed_count": scope_result.changed_count,
                    "out_of_scope_count": scope_result.out_of_scope_count,
                }
                if scope_result is not None and not scope_result.ok
                else (
                    {
                        "kind": parsed.error.kind,
                        "retryable": parsed.error.retryable,
                        "status_code": parsed.error.status_code,
                        "reset_at_utc": parsed.error.reset_at_utc,
                    }
                    if parsed.error is not None
                    else None
                )
            ),
            "write_scope": (
                _public_headless_scope_result(scope_result)
                if scope_result is not None
                else None
            ),
            "raw_output": "not_returned",
        }
    except Exception as exc:
        usage_status = (
            "rate_limited" if isinstance(exc, FleetRateLimitError) else "failed"
        )
        if isinstance(exc, FleetRateLimitError):
            release_bound_headless_inflight()
        with contextlib.suppress(Exception):
            service.record_gemini_usage(
                gate.account_id,
                model=descriptor.model,
                status=usage_status,
                gate_action=gate_action,
                gate_code=gate_code,
                next_reset_at_utc=rate_reset_at_utc,
            )
        with contextlib.suppress(Exception):
            service.record_gemini_event(
                event_type="headless_exception",
                agent_id=agent,
                account_id=gate.account_id,
                assignment_id=assignment_id,
                status=usage_status,
                reason=(
                    exc.reason
                    if isinstance(exc, FleetRateLimitError)
                    else "secret_missing"
                    if isinstance(exc, FleetSecretError)
                    else "runner_failed"
                ),
                model=descriptor.model,
                gate_action=gate_action,
                gate_code=gate_code,
                next_reset_at_utc=rate_reset_at_utc,
            )
        raise
    finally:
        if plan.secret_env_name is not None:
            child_env.pop(plan.secret_env_name, None)
        if popen_env is not None:
            popen_env.clear()
        secret = ""
        if reservation is not None:
            with contextlib.suppress(Exception):
                service.release_gemini_request(
                    reservation,
                    outcome=rate_outcome,
                    reset_at_utc=rate_reset_at_utc,
                )
        finished_result = result
        if job is not None and result is None:
            process_returncode: int | None = None
            with contextlib.suppress(Exception):
                HEADLESS_JOBS.request_cancel(agent, force=True)
            if process is not None:
                wait = getattr(process, "wait", None)
                if callable(wait):
                    with contextlib.suppress(Exception):
                        try:
                            process_returncode = wait(timeout=5)
                        except TypeError:
                            with contextlib.suppress(Exception):
                                process_returncode = wait()
                if not isinstance(process_returncode, int) or isinstance(
                    process_returncode, bool
                ):
                    poll = getattr(process, "poll", None)
                    if callable(poll):
                        with contextlib.suppress(Exception):
                            process_returncode = poll()
                if isinstance(process_returncode, int) and not isinstance(
                    process_returncode, bool
                ):
                    terminal = "completed" if process_returncode == 0 else "failed"
                    process_end_confirmed = True
                    finished_result = HeadlessProcessResult(
                        process_returncode,
                        b"",
                        b"",
                        False,
                        False,
                        False,
                        True,
                    )
        if process_end_confirmed:
            _write_headless_marker(
                agent,
                {
                    "agent": agent,
                    "backend": "headless_job",
                    "state": "failed" if write_scope_binding is not None else terminal,
                    "assignment_id": assignment_id,
                    "generation": gate.generation,
                    "returncode": finished_result.returncode
                    if finished_result is not None
                    else None,
                    "stdout_truncated": False,
                    "stderr_truncated": False,
                    **(
                        {
                            "headless_inflight_reservation_id": headless_inflight_reservation_id
                        }
                        if isinstance(headless_inflight_reservation_id, str)
                        else {}
                    ),
                },
            )
        if write_scope_binding is not None and scope_result is None:
            try:
                scope_result = consume_write_scope()
            except Exception:
                scope_result = ScopeResult(
                    False, "headless_write_attribution_unverified", 0, 0, 0
                )
        scope_failed = scope_result is not None and not scope_result.ok
        if scope_failed:
            terminal = "failed"
            if finished_result is not None:
                finished_result = dataclass_replace(finished_result, returncode=1)
            with contextlib.suppress(Exception):
                current_marker = _headless_marker(agent)
                current_marker.update(
                    {
                        "state": "failed",
                        "assignment_id": assignment_id,
                        "write_scope": _public_headless_scope_result(scope_result),
                    }
                )
                _write_headless_marker(agent, current_marker)
            with contextlib.suppress(Exception):
                service.record_gemini_usage(
                    gate.account_id,
                    model=descriptor.model,
                    status="failed",
                    gate_action=gate_action,
                    gate_code=gate_code,
                )
            with contextlib.suppress(Exception):
                service.record_gemini_event(
                    event_type="headless_scope_failure",
                    agent_id=agent,
                    account_id=gate.account_id,
                    assignment_id=assignment_id,
                    status="failed",
                    reason=scope_result.code,
                    model=descriptor.model,
                    gate_action=gate_action,
                    gate_code=gate_code,
                )
        if job is not None and finished_result is not None:
            HEADLESS_JOBS.finish(job, finished_result)
            release_bound_headless_inflight()
        if release_lease_on_completion:
            with contextlib.suppress(Exception):
                current_lease = agent_lease_status(agent)
                if current_lease.get("held_by_this_server") and (
                    lease.get("lease_id") is None
                    or lease.get("lease_id") == current_lease.get("lease_id")
                ):
                    release_agent(agent, force=True)
        if worktree_fd >= 0:
            with contextlib.suppress(OSError):
                os.close(worktree_fd)
        if scope_failed and not normal_return:
            scope_error = _headless_scope_result_error(scope_result)
            if scope_error is not None:
                raise scope_error from None


def run_headless_assignment(
    agent: str,
    prompt: str,
    lease: Mapping[str, Any],
    timeout_seconds: float,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="headless_assignment")
    agent = canonical_agent_id(agent)
    with hive_capacity_probe_guard("headless_assignment"):
        return _run_headless_process(
            agent,
            prompt,
            lease,
            timeout_seconds,
            role="exploriererin",
        )


def _headless_route_candidates(
    agent: str, skill: str | None, required_skills: list[str] | None = None
) -> list[str]:
    """Return only the explicitly requested identity; fallback needs opt-in."""

    del skill, required_skills
    return [canonical_agent_id(agent)]


def _gemini_headless_gate(agent: str) -> dict[str, Any]:
    """Return FleetService's redacted, pre-process Gemini gate decision."""

    return current_fleet_service().gemini_headless_gate(agent).public()


def _resolve_gemini_headless_route(
    requested_agent: str,
) -> tuple[str, AgentDescriptor, dict[str, Any], dict[str, Any] | None]:
    """Resolve one explicit Gemini target without crossing provider boundaries."""

    requested_agent = canonical_agent_id(requested_agent)
    descriptor = _headless_descriptor(requested_agent)
    if descriptor is None:
        raise AgentError("headless_runner_unavailable")
    gate = _gemini_headless_gate(requested_agent)
    if gate.get("action") not in {"rotate_account", "rotate_model"}:
        return requested_agent, descriptor, gate, None
    target = gate.get("target_agent_id")
    if not isinstance(target, str):
        raise AgentError("headless_rotation_target_invalid")
    try:
        target = canonical_agent_id(target)
    except AgentError as exc:
        raise AgentError("headless_rotation_target_invalid") from exc
    target_descriptor = _headless_descriptor(target)
    if (
        descriptor.provider is not Provider.GEMINI_API
        or descriptor.runner is not RunnerKind.GEMINI_CLI
        or target_descriptor is None
        or target_descriptor.provider is not Provider.GEMINI_API
        or target_descriptor.runner is not RunnerKind.GEMINI_CLI
    ):
        raise AgentError("headless_rotation_target_invalid")
    return target, target_descriptor, _gemini_headless_gate(target), gate


def _assign_headless_agent(
    agent: str,
    *,
    role: str,
    task: Any,
    scope: Any,
    skill: str | None = None,
    write_paths: Any = None,
    context: Any = None,
    forbidden: Any = None,
    name: str | None = None,
    group_id: str | None = None,
    job_id: str | None = None,
    enter: bool = True,
    allow_missing_skill: bool = False,
    allow_subagents: bool = False,
    allow_unauthenticated: bool = False,
    requires_search: bool = False,
    live_data_topic: str | None = None,
    timeout_seconds: float = DEFAULT_HEADLESS_TIMEOUT_SECONDS,
    operation: str = "agent_assign",
    required_skills: Any = None,
) -> dict[str, Any]:
    del operation, allow_unauthenticated
    require_resource_capacity_preflight(operation="agent_assign")
    requested_agent = canonical_agent_id(agent)
    agent = requested_agent
    descriptor = _headless_descriptor(requested_agent)
    if descriptor is None:
        raise AgentError("headless_runner_unavailable")
    _validate_headless_timeout(timeout_seconds)
    role = role.strip().lower()
    if role not in {"exploriererin", "arbeitsbiene"}:
        raise AgentError("role must be 'exploriererin' or 'arbeitsbiene'")
    task = (
        bounded_text(task, field="task", max_chars=MAX_TASK_TEXT, required=True) or ""
    )
    skill = (
        bounded_text(skill, field="skill", max_chars=MAX_SKILL_REF)
        if skill is not None
        else None
    )
    required_skills = as_string_list(
        required_skills, field="required_skills", max_chars=MAX_SKILL_REF
    )
    if skill and skill not in required_skills:
        required_skills.insert(0, skill)
    name = (
        bounded_text(name, field="name", max_chars=MAX_AGENTIN_NAME)
        if name is not None
        else None
    )
    group_id = normalize_routing_context_id(group_id, field="group_id")
    job_id = normalize_routing_context_id(job_id, field="job_id")
    scope = as_string_list(scope, field="scope", max_chars=MAX_PATH_TEXT)
    write_paths = as_string_list(
        write_paths, field="write_paths", max_chars=MAX_PATH_TEXT
    )
    context = as_string_list(context, field="context")
    forbidden = as_string_list(forbidden, field="forbidden")
    if len(task) + sum(len(item) for item in context) > MAX_HEADLESS_CONTEXT_CHARS:
        raise AgentError("headless_context_budget_exceeded")
    live_data_topic = (
        bounded_text(
            live_data_topic,
            field="live_data_topic",
            max_chars=MAX_LIVE_DATA_TOPIC,
        )
        if live_data_topic is not None
        else None
    )
    if role == "exploriererin" and write_paths:
        raise AgentError("exploriererin assignments must not include write paths")
    if role == "arbeitsbiene" and not write_paths:
        raise AgentError(
            "arbeitsbiene assignments require at least one explicit write path"
        )
    write_scope_store: HeadlessWriteScopeStore | None = None
    write_scope_binding: ScopeBinding | None = None
    if role == "arbeitsbiene":
        write_scope_store = _headless_write_scope_store()
        try:
            available = write_scope_store.has_available(requested_agent)
        except HeadlessWriteScopeFailure as exc:
            _raise_headless_scope_failure(exc)
        if not available:
            raise HeadlessWriteScopeError()
    agent, descriptor, gate, routing_gate = _resolve_gemini_headless_route(
        requested_agent
    )
    matches = skill_matches(agent, skill) if skill else []
    missing_skills = [
        item for item in required_skills if not skill_matches(agent, item)
    ]
    if missing_skills and not allow_missing_skill:
        raise AgentError(f"skill not found for agent {agent}")
    subagent_admission = spawn_admission_decision(1) if allow_subagents else None
    prompt = assignment_prompt(
        agent=agent,
        role=role,
        task=task,
        scope=scope,
        skill=skill,
        write_paths=write_paths,
        context=context,
        forbidden=forbidden,
        name=name,
        model=descriptor.model,
        allow_subagents=allow_subagents,
        subagent_admission=subagent_admission,
        requires_search=requires_search,
        live_data_topic=live_data_topic,
        required_skills=required_skills,
    )
    if len(prompt) > MAX_ASSIGNMENT_TEXT:
        raise AgentError(f"assignment prompt exceeds {MAX_ASSIGNMENT_TEXT} characters")
    if gate.get("action") != "allow":
        return {
            "agent": agent,
            "requested_agent": requested_agent,
            "selected_agent": agent,
            "status": "deferred" if gate.get("action") == "defer_until" else "failed",
            "model": descriptor.model,
            "gate": gate,
            "routing_gate": routing_gate,
            "raw_output": "not_returned",
        }
    account_id = gate.get("account_id")
    if not isinstance(account_id, str) or account_id != getattr(
        descriptor, "account_id", None
    ):
        raise AgentError("headless_gate_binding_changed")
    if role == "arbeitsbiene":
        scope_result = scope_check(scope, write_paths, cwd=repo_root())
        if (
            not isinstance(scope_result, Mapping)
            or scope_result.get("allowed") is not True
        ):
            violations = (
                scope_result.get("violations", [])
                if isinstance(scope_result, Mapping)
                else []
            )
            raise AgentError(
                "headless_write_scope_violation",
                {
                    "code": "headless_write_scope_violation",
                    "explanation": "declared write paths are outside the assignment scope",
                    "action": "declare only repository-relative paths inside the assignment scope",
                    "violations": violations,
                },
            )
    assignment_id = f"{now_id()}-{agent}"
    headless_inflight_reservation: dict[str, Any] | None = None
    try:
        with spawn_admission_lock():
            require_spawn_capacity(1, agent=agent, task=task, role=role)
            if role == "arbeitsbiene":
                assert write_scope_store is not None
                try:
                    if agent != requested_agent and not write_scope_store.has_available(
                        agent
                    ):
                        raise HeadlessWriteScopeFailure(
                            "headless_write_scope_unenforced",
                            "headless writes lack isolated worktree and diff attribution",
                            "use an isolated worktree or submit a read-only headless assignment",
                        )
                    snapshot = current_fleet_service().load()
                    current_generation = getattr(snapshot, "generation", None)
                    if current_generation is None:
                        raise AgentError("headless_assignment_generation_invalid")
                    write_scope_binding = write_scope_store.bind(
                        agent,
                        repo_root(),
                        write_paths,
                        assignment_id=assignment_id,
                        provider_generation=current_generation,
                    )
                except HeadlessWriteScopeFailure as exc:
                    _raise_headless_scope_failure(exc)
            headless_inflight_reservation = reserve_headless_inflight(
                agent, assignment_id
            )
            if headless_inflight_reservation is None:
                raise AgentCapacityError(
                    "capacity unavailable",
                    {
                        "error_code": "spawn_capacity_unavailable",
                        "retryable": True,
                        "retry_after_seconds": SPAWN_OFFER_RETRY_AFTER_SECONDS,
                        "reason_codes": ["session_metrics_unavailable"],
                        "errors": spawn_error_details(["session_metrics_unavailable"]),
                    },
                )
    except Exception:
        if write_scope_binding is not None and write_scope_store is not None:
            with contextlib.suppress(Exception):
                write_scope_store.finalize(write_scope_binding)
        raise
    headless_inflight_reservation_id = (
        headless_inflight_reservation.get("reservation_id")
        if isinstance(headless_inflight_reservation, Mapping)
        else None
    )

    def release_headless_inflight_claim() -> None:
        if not isinstance(headless_inflight_reservation_id, str):
            return
        with contextlib.suppress(Exception):
            release_headless_inflight(
                headless_inflight_reservation_id, agent, assignment_id
            )

    release_on_completion = False
    try:
        with agent_lifecycle_lock(agent):
            claim = _claim_agent_unlocked(agent)
            lease = claim["lease"]
            release_on_completion = claim["status"] in {"claimed", "claimed_expired"}
            assignment_record = {
                "assignment_id": assignment_id,
                "created_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
                "agent": agent,
                "role": role,
                "name": name or default_agentin_name(agent),
                "model": descriptor.model,
                "group_id": group_id,
                "job_id": job_id,
                "skill": {
                    "requested": skill,
                    "available": bool(matches) if skill else None,
                    "match_count": len(matches),
                },
                "scope": redact_list(scope),
                "write_paths": redact_list(write_paths),
                "context_count": len(context),
                "forbidden_count": len(forbidden),
                "write_policy": "read_only"
                if role == "exploriererin"
                else "explicit_paths_only",
                "write_scope": (
                    {
                        "state": "bound",
                        "attestation_id": write_scope_binding.attestation_id,
                        "raw_output": "not_returned",
                    }
                    if write_scope_binding is not None
                    else None
                ),
                "allow_subagents": allow_subagents,
                "requires_search": requires_search,
                "live_data": {
                    "required": requires_search,
                    "topic_state": "set" if live_data_topic else "task",
                    "raw_output": "not_returned",
                },
                "lease": lease,
                "submitted": enter,
                "prompt_chars": len(prompt),
                "prompt_output": "not_returned",
                "response_output": "not_returned",
            }
            with hive_capacity_probe_guard("agent_assign"):
                record_assignment(assignment_record)
                marker = _headless_marker(agent)
                marker.update({"state": "ready", "assignment_id": assignment_id})
                _write_headless_marker(agent, marker)
    except Exception:
        if write_scope_binding is not None and write_scope_store is not None:
            with contextlib.suppress(Exception):
                write_scope_store.finalize(write_scope_binding)
        release_headless_inflight_claim()
        if release_on_completion:
            with contextlib.suppress(Exception):
                release_start_lease_if_safe(agent, lease, True)
        raise
    try:
        result = _run_headless_process(
            agent,
            prompt,
            lease,
            timeout_seconds,
            role=role,
            assignment_id=assignment_id,
            headless_inflight_reservation=headless_inflight_reservation,
            release_lease_on_completion=release_on_completion,
            structured_gate=gate,
            write_scope_binding=write_scope_binding,
            write_scope_store=write_scope_store,
        )
    except FleetRateLimitError as exc:
        result = {
            "agent": agent,
            "assignment_id": assignment_id,
            "status": "failed",
            "model": descriptor.model,
            "response": "",
            "error": {"kind": exc.reason, "retryable": True},
            "raw_output": "not_returned",
        }
    except Exception:
        raise
    result_write_scope = result.get("write_scope")
    if result_write_scope is None and write_scope_binding is not None:
        result_write_scope = {
            "state": "bound",
            "attestation_id": write_scope_binding.attestation_id,
            "raw_output": "not_returned",
        }
    result.update(
        {
            "role": role,
            "requested_agent": requested_agent,
            "selected_agent": agent,
            "routed_from": requested_agent if requested_agent != agent else None,
            "gate": result.get("gate", gate),
            "routing_gate": routing_gate,
            "name": name or default_agentin_name(agent),
            "scope_count": len(scope),
            "write_path_count": len(write_paths),
            "write_scope": result_write_scope,
            "prompt_chars": len(prompt),
            "result_tool": "agent_assignment_report",
            "prompt_output": "not_returned",
            "response_output": "not_returned",
        }
    )
    return result


def start_agent_with_lease(
    agent: str,
    cwd: Any = None,
    prompt: Any = None,
    *,
    allow_unauthenticated: bool = False,
    agent_class: str | None = None,
    lifecycle: str | None = None,
    model: str | None = None,
    reasoning_effort: str | None = None,
    complexity: str = "unknown",
    name: str | None = None,
    confirm_home_refresh: bool = False,
) -> dict[str, Any]:
    require_resource_capacity_preflight(operation="agent_start")
    require_fleet_recovery_ready("agent_start")
    if type(confirm_home_refresh) is not bool:
        raise AgentError("confirm_home_refresh must be a boolean")
    agent = canonical_agent_id(agent)
    with agent_lifecycle_lock(agent):
        with hive_capacity_probe_guard("agent_start"):
            with _resource_gate_composer_scope():
                name_args = {"name": name} if name is not None else {}
                home_refresh_args = (
                    {"confirm_home_refresh": True} if confirm_home_refresh else {}
                )
                return _start_agent_with_lease_unlocked(
                    agent,
                    cwd,
                    prompt,
                    allow_unauthenticated=allow_unauthenticated,
                    agent_class=agent_class,
                    lifecycle=lifecycle,
                    model=model,
                    reasoning_effort=reasoning_effort,
                    complexity=complexity,
                    **name_args,
                    **home_refresh_args,
                )


def _start_agent_with_lease_unlocked(
    agent: str,
    cwd: Any = None,
    prompt: Any = None,
    *,
    allow_unauthenticated: bool = False,
    agent_class: str | None = None,
    lifecycle: str | None = None,
    model: str | None = None,
    reasoning_effort: str | None = None,
    complexity: str = "unknown",
    authority_class: str | None = None,
    name: str | None = None,
    confirm_home_refresh: bool = False,
) -> dict[str, Any]:
    require_fleet_recovery_ready("agent_start")
    if type(confirm_home_refresh) is not bool:
        raise AgentError("confirm_home_refresh must be a boolean")
    agent = canonical_agent_id(agent)
    _reject_legacy_teamlead_start_target(agent_class)
    headless_descriptor = _headless_descriptor(agent)
    if headless_descriptor is not None:
        if confirm_home_refresh:
            raise AgentError("agent_home_refresh_not_supported_for_headless")
        return _start_headless_agent_unlocked(agent)
    task_profile = classify_runtime_task(
        TaskClassificationRequest(
            objective="agent_start",
            scope_kind="write",
            changed_files=(),
            task_phase="unknown",
            complexity_override=_complexity_override(complexity),
        )
    )
    ollama_descriptor = _ollama_descriptor(agent)
    selection: ResolutionDecision | None = None
    if ollama_descriptor is not None:
        auth_gate = {
            "authenticated": True,
            "provider": Provider.OLLAMA_LOCAL.value,
            "state": "not_applicable",
            "raw_output": "not_returned",
        }
        selected_model = ollama_descriptor.model
        selected_effort = None
    else:
        auth_gate = require_authenticated_agent_for_mutation(
            agent,
            operation="agent_start",
            allow_unauthenticated=allow_unauthenticated,
        )
        ensure_agent_not_blocked_by_codex_usage(agent)
        requested_target_class, resolver_authority = _resolver_target_selection_inputs(
            agent,
            agent_class,
            authority_class,
        )
        selection = resolve_runtime_agent_selection(
            role="arbeitsbiene",
            routing=None,
            task_profile=task_profile,
            requested_class=requested_target_class,
            requested_lifecycle=lifecycle,
            requested_model=model,
            requested_reasoning=reasoning_effort,
            authority_class=resolver_authority,
        )
        _reject_legacy_teamlead_start_target(selection.class_id)
        selected_model = selection.model
        selected_effort = selection.reasoning

    def validate_existing_session(result: dict[str, Any]) -> None:
        if result.get("status") != "already_running":
            return
        active_meta = result.get("meta") if isinstance(result.get("meta"), dict) else {}
        active_model = active_meta.get("model") or (
            ollama_descriptor.model
            if ollama_descriptor is not None
            else DEFAULT_AGENT_MODEL
        )
        active_effort = active_meta.get("model_reasoning_effort") or (
            None
            if ollama_descriptor is not None
            else WRITE_AGENT_MODEL_EFFORT
            if active_model == WRITE_AGENT_MODEL
            else DEFAULT_AGENT_MODEL_EFFORT
        )
        active_class = read_meta(agent).get("agent_class")
        if (
            active_model != selected_model
            or active_effort != selected_effort
            or (
                selection is not None
                and active_class is not None
                and active_class != selection.class_id
            )
        ):
            raise AgentError(
                "routed model or class differs from active session; controlled restart requires "
                "an inactive Agentin"
            )

    claim = claim_agent(agent)
    lease = claim["lease"]
    release_on_completion = claim["status"] in {"claimed", "claimed_expired"}
    name_args = {"name": name} if name is not None else {}
    result: dict[str, Any] | None = None

    def invoke_start() -> dict[str, Any]:
        home_refresh_args = (
            {"confirm_home_refresh": True} if confirm_home_refresh else {}
        )
        return start_agent(
            agent,
            cwd,
            prompt,
            lease=lease,
            release_lease_on_failure=release_on_completion,
            model=selected_model,
            model_reasoning_effort=selected_effort,
            agent_class=selection.class_id if selection is not None else None,
            **name_args,
            **home_refresh_args,
        )

    if tmux_alive(agent_config(agent)["session"]):
        try:
            result = invoke_start()
            validate_existing_session(result)
        except Exception:
            if isinstance(result, dict) and result.get("status") == "started":
                raw_log = read_meta(agent).get("raw_log")
                raw_log_identity = allowed_agent_raw_log_identity(agent, raw_log)
                raw_log_path = (
                    raw_log_identity[0] if raw_log_identity is not None else None
                )
                if raw_log_path is not None:
                    cleanup_failed_start(
                        agent_config(agent)["session"], raw_log_path, kill_session=True
                    )
                else:
                    session = agent_config(agent)["session"]
                    run_tmux(
                        _tmux_args_for_session(
                            session, ["kill-session", "-t", session]
                        ),
                        check=False,
                    )
            release_start_lease_if_safe(
                agent,
                lease,
                release_on_completion,
                existing_session=isinstance(result, dict)
                and result.get("status") == "already_running",
            )
            raise
        if release_on_completion and agent_lease_status(agent).get(
            "held_by_this_server"
        ):
            release = release_agent(agent, force=True)
            result["lease"] = release["lease"]
        result["auth_gate"] = auth_gate
        result["selection"] = public_resolution_decision(selection)
        return result
    try:
        result = invoke_start()
    except Exception:
        release_start_lease_if_safe(
            agent,
            lease,
            release_on_completion,
            existing_session=isinstance(result, dict)
            and result.get("status") == "already_running",
        )
        raise
    try:
        validate_existing_session(result)
    except Exception:
        if isinstance(result, dict) and result.get("status") == "started":
            raw_log = read_meta(agent).get("raw_log")
            raw_log_identity = allowed_agent_raw_log_identity(agent, raw_log)
            raw_log_path = raw_log_identity[0] if raw_log_identity is not None else None
            if raw_log_path is not None:
                cleanup_failed_start(
                    agent_config(agent)["session"], raw_log_path, kill_session=True
                )
            else:
                session = agent_config(agent)["session"]
                run_tmux(
                    _tmux_args_for_session(session, ["kill-session", "-t", session]),
                    check=False,
                )
        release_start_lease_if_safe(agent, lease, release_on_completion)
        raise
    if release_on_completion and agent_lease_status(agent).get("held_by_this_server"):
        release = release_agent(agent, force=True)
        result["lease"] = release["lease"]
    result["auth_gate"] = auth_gate
    result["selection"] = public_resolution_decision(selection)
    return result


def stop_agent(
    agent: str,
    force: bool = False,
    *,
    timeout_seconds: float | None = None,
) -> dict[str, Any]:
    with agent_lifecycle_lock(agent, timeout_seconds=timeout_seconds):
        return _stop_agent_unlocked(agent, force=force)


def _stop_agent_unlocked(agent: str, force: bool = False) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if _headless_descriptor(agent) is not None:
        current = HEADLESS_JOBS.status(agent)
        if current.get("status") in {"running", "cancelling"}:
            cancelled = cancel_headless_job(agent, force=force)
            return {
                "agent": agent,
                "status": "cancelling",
                "backend": "headless_job",
                "job": cancelled,
                "lease": agent_lease_status(agent),
                "raw_output": "not_returned",
            }
        marker = _headless_marker(agent)
        if marker.get("state") in {"running", "cancelling"}:
            if not force:
                return {
                    "agent": agent,
                    "status": "identity_unverified",
                    "backend": "headless_job",
                    "lease": agent_lease_status(agent),
                    "raw_output": "not_returned",
                }
            recovery = _recover_headless_process(agent, marker)
            if recovery == "identity_unverified":
                return {
                    "agent": agent,
                    "status": "identity_unverified",
                    "backend": "headless_job",
                    "lease": agent_lease_status(agent),
                    "raw_output": "not_returned",
                }
            if recovery in {"stopped", "already_gone"}:
                released: dict[str, Any] | None = None
                reservation_id = marker.get("headless_inflight_reservation_id")
                assignment_id = marker.get("assignment_id")
                if isinstance(reservation_id, str) and isinstance(assignment_id, str):
                    with contextlib.suppress(Exception):
                        released = release_headless_inflight(
                            reservation_id, agent, assignment_id
                        )
                    if isinstance(released, dict):
                        marker.pop("headless_inflight_reservation_id", None)
        marker.update(
            {"state": "disabled", "assignment_id": marker.get("assignment_id")}
        )
        _write_headless_marker(agent, marker)
        current_lease = agent_lease_status(agent)
        release = (
            release_agent(agent, force=True)
            if force
            or current_lease.get("held_by_this_server")
            or current_lease.get("state") == "expired"
            else {
                "status": "skipped",
                "lease": current_lease,
                "raw_output": "not_returned",
            }
        )
        return {
            "agent": agent,
            "status": "stopped",
            "backend": "headless_job",
            "lease": release["lease"],
            "raw_output": "not_returned",
        }
    cfg = agent_config(agent)
    session = cfg["session"]
    was_running = tmux_alive(session)
    if was_running:
        require_managed_tmux_session(agent)
        ensure_agent_lease_available(agent, force=force)
    if was_running:
        cp = run_tmux(
            _tmux_args_for_session(session, ["kill-session", "-t", session]),
            check=False,
        )
        if cp.returncode != 0:
            if cp.returncode in {
                COMMAND_TIMEOUT_RETURN_CODE,
                COMMAND_UNAVAILABLE_RETURN_CODE,
            } or tmux_alive(session):
                raise AgentError(f"tmux stop failed for agent {agent}")
        process_count = agent_home_process_summary(agent).get("process_count")
        if (
            not isinstance(process_count, int)
            or isinstance(process_count, bool)
            or process_count != 0
        ):
            raise AgentError(f"tmux stop failed for agent {agent}")
        release = release_agent(agent, force=True)
    else:
        current_lease = agent_lease_status(agent)
        if (
            force
            or current_lease["held_by_this_server"]
            or current_lease["state"] == "expired"
        ):
            process_count = agent_home_process_summary(agent).get("process_count")
            if (
                not isinstance(process_count, int)
                or isinstance(process_count, bool)
                or process_count != 0
            ):
                raise AgentError(f"tmux stop failed for agent {agent}")
            release = release_agent(agent, force=True)
        else:
            release = {
                "status": "skipped",
                "lease": current_lease,
                "raw_output": "not_returned",
            }
    close_runner_execution_fd(agent)
    return {
        "agent": agent,
        "status": "stopped" if was_running else "not_running",
        "session": session,
        "lease": release["lease"],
        "raw_output": "not_returned",
    }


def require_running_agent(agent: str) -> None:
    agent = canonical_agent_id(agent)
    if not tmux_alive(agent_config(agent)["session"]):
        raise AgentError(f"agent {agent} is not running")


def run_with_agent_lease(agent: str, fn: Any) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    ensure_agent_not_blocked_by_codex_usage(agent)
    lease, release_on_failure = claim_for_agent_mutation(agent)
    try:
        return fn(lease)
    except Exception:
        if release_on_failure:
            release_start_lease_if_safe(agent, lease, True)
        raise


def raw_log_metadata(
    raw_log_path: Path | None,
    *,
    expected_stat: os.stat_result | None = None,
) -> dict[str, Any]:
    if raw_log_path is None:
        return {"bytes": None, "updated_at_utc": None, "idle_seconds": None}
    try:
        current_stat = raw_log_path.lstat()
    except OSError:
        return {"bytes": None, "updated_at_utc": None, "idle_seconds": None}
    if not stat_module.S_ISREG(current_stat.st_mode) or (
        expected_stat is not None
        and not source_identity_matches(current_stat, expected_stat)
    ):
        return {"bytes": None, "updated_at_utc": None, "idle_seconds": None}
    try:
        updated = _dt.datetime.fromtimestamp(current_stat.st_mtime, _dt.timezone.utc)
        now = time.time()
        idle_seconds = (
            None
            if current_stat.st_mtime > now
            else max(0, int(now - current_stat.st_mtime))
        )
    except (OverflowError, OSError, ValueError):
        return {
            "bytes": current_stat.st_size,
            "updated_at_utc": None,
            "idle_seconds": None,
        }
    return {
        "bytes": current_stat.st_size,
        "updated_at_utc": updated.isoformat(),
        "idle_seconds": idle_seconds,
    }


def latest_assignment_summary(
    agent: str, *, initialize_state: bool = True
) -> dict[str, Any] | None:
    try:
        result = list_assignments(agent, 1, initialize_state=initialize_state)
    except AgentError:
        return None
    records = result.get("records")
    if not isinstance(records, list) or not records:
        return None
    record = records[-1]
    if not isinstance(record, dict):
        return None
    return {
        "assignment_id": record.get("assignment_id"),
        "created_at_utc": record.get("created_at_utc"),
        "role": record.get("role"),
        "model": record.get("model"),
        "raw_output": "not_returned",
    }


def limit_model_pool(model: Any) -> str:
    text = str(model or "").lower()
    if "spark" in text or WRITE_AGENT_MODEL in text:
        return "spark_write_model"
    if DEFAULT_AGENT_MODEL in text or "5.4" in text:
        return "default_agent_model"
    return "unknown"


LIMIT_TEXT_PATTERNS = (
    r"\brate[- ]limited\b(?!\s+to\b)",
    r"\brate limits?\b.{0,80}\b(?:reached|exceeded|hit|error|retry|again)\b",
    r"\brate-limits?\b.{0,80}\b(?:reached|exceeded|hit|error|retry|again)\b",
    r"\busage limit\b.{0,80}\b(?:reached|exceeded|hit|blocked|retry|again)\b",
    r"\blimit (?:reached|exceeded|hit)\b",
    r"\bquota (?:exceeded|reached)\b",
    r"\btoo many requests\b",
    r"\bout of tokens\b",
    r"\btoken (?:limit|budget|quota)\b.{0,80}\b(?:exceeded|reached|hit|full|blocked|retry|again)\b",
    r"\bcontext (?:length|window).{0,80}\b(?:exceeded|full|too long|overflow)\b",
)
LIMIT_CLEAR_TEXT_PATTERNS = (
    r"\blimit\b.{0,40}\b(?:not|isn't|is not|hasn't|has not)\b",
    r"\b(?:not|isn't|is not|hasn't|has not|no|without)\b.{0,40}\b(?:limit|quota|tokens?)\b",
    r"\b(?:not|isn't|is not|hasn't|has not|no|without)\b.{0,40}\brate[- ]limited\b",
    r"\b(?:not|isn't|is not|hasn't|has not|no|without)\b.{0,40}\b(?:full|exceeded|reached|blocked|overflow|too long|too many requests)\b",
)


def model_from_status_text(text: str) -> str | None:
    lowered = text.lower()
    if re.search(
        r"\b(?:gpt[- ]?5\.3[- ]?codex[- ]?spark|codex[- ]?spark|spark)\b", lowered
    ):
        return WRITE_AGENT_MODEL
    if re.search(r"\b(?:gpt[- ]?5\.4[- ]?mini|gpt[- ]?5\.4|5\.4[- ]?mini)\b", lowered):
        return DEFAULT_AGENT_MODEL
    return None


def first_limit_evidence(text: str) -> str:
    offset = 0
    for raw_line in text.splitlines(keepends=True):
        line = raw_line.rstrip("\r\n")
        lowered = line.lower()
        if any(re.search(pattern, lowered) for pattern in LIMIT_CLEAR_TEXT_PATTERNS):
            offset += len(raw_line)
            continue
        for pattern in LIMIT_TEXT_PATTERNS:
            match = re.search(pattern, lowered)
            if match:
                start = max(offset, offset + match.start() - 160)
                end = min(offset + len(line), offset + match.end() + 160)
                return text[start:end]
        offset += len(raw_line)
    return ""


def infer_limit_model_info(
    text: str,
    meta: dict[str, Any],
    latest_assignment: dict[str, Any] | None,
    *,
    detected: bool,
) -> tuple[str, str]:
    assignment_model = latest_assignment.get("model") if latest_assignment else None
    session_model = meta.get("model") if isinstance(meta.get("model"), str) else None

    if detected:
        evidence_model = model_from_status_text(first_limit_evidence(text))
        if evidence_model:
            return evidence_model, "limit_evidence_text"
        if isinstance(assignment_model, str):
            return assignment_model, "assignment_metadata"
        if isinstance(session_model, str):
            return session_model, "session_metadata"

    status_model = model_from_status_text(text)
    if status_model:
        return status_model, "status_text"
    if latest_assignment and isinstance(latest_assignment.get("model"), str):
        return latest_assignment["model"], "assignment_metadata"
    if isinstance(session_model, str):
        return session_model, "session_metadata"
    return "unknown", "unknown"


def infer_limit_model(
    text: str, meta: dict[str, Any], latest_assignment: dict[str, Any] | None
) -> str:
    return infer_limit_model_info(text, meta, latest_assignment, detected=True)[0]


def classify_limit_text(
    text: str,
    meta: dict[str, Any] | None = None,
    latest_assignment: dict[str, Any] | None = None,
) -> dict[str, Any]:
    meta = meta or {}
    cleaned = strip_ansi(text)
    lowered = cleaned.lower()
    limit_lines = lowered.splitlines() or [lowered]
    has_limit = any(
        any(re.search(pattern, line) for pattern in LIMIT_TEXT_PATTERNS)
        and not any(re.search(pattern, line) for pattern in LIMIT_CLEAR_TEXT_PATTERNS)
        for line in limit_lines
    )
    limit_evidence = first_limit_evidence(cleaned) if has_limit else ""
    classification_text = limit_evidence.lower() if limit_evidence else lowered
    window = "unknown"
    if re.search(r"\b(?:daily|per day|today|24h|24 hours)\b", classification_text):
        window = "daily"
    elif re.search(r"\b(?:weekly|per week|this week|7d|7 days)\b", classification_text):
        window = "weekly"

    limit_kind = "unknown"
    if re.search(r"\b(?:token|context length|context window)\b", classification_text):
        limit_kind = "token"
    elif re.search(r"\brate[- ]limit|too many requests\b", classification_text):
        limit_kind = "rate"
    elif re.search(r"\bquota\b", classification_text):
        limit_kind = "quota"
    elif has_limit:
        limit_kind = "usage"

    detected = has_limit
    model, model_source = infer_limit_model_info(
        cleaned, meta, latest_assignment, detected=detected
    )
    session_model = (
        meta.get("model") if isinstance(meta.get("model"), str) else "unknown"
    )
    assignment_model = latest_assignment.get("model") if latest_assignment else None
    assignment_model_pool = (
        limit_model_pool(assignment_model) if assignment_model else "none"
    )
    role = latest_assignment.get("role") if latest_assignment else "unknown"
    if role not in {"exploriererin", "arbeitsbiene"}:
        role = "unknown"

    return {
        "limited": detected,
        "window": window if detected else "none",
        "kind": limit_kind if detected else "none",
        "model": model,
        "model_source": model_source,
        "model_pool": limit_model_pool(model),
        "session_model": session_model,
        "session_model_pool": limit_model_pool(session_model),
        "assignment_model": assignment_model,
        "assignment_model_pool": assignment_model_pool,
        "role": role,
        "source": "classified_from_bounded_status_text"
        if cleaned
        else "no_status_text",
        "evidence": "not_returned",
        "raw_output": "not_returned",
    }


def classify_tui_context(text: str, running: bool) -> dict[str, Any]:
    if not running:
        state = "not_running"
        source = "not_running"
    else:
        cleaned = strip_ansi(text)
        lowered = re.sub(r"\s+", " ", cleaned.lower())
        starter_patterns = (
            r"\bfind and fix a bug in @filename\b",
            r"\bimprove documentation in @filename\b",
            r"\bwhat can i help(?: you)?(?: with)?\b",
            r"\bask me anything\b",
        )
        if codex_update_prompt_visible(cleaned):
            state = "update_prompt"
            source = "classified_from_bounded_pane_text"
        elif any(re.search(pattern, lowered) for pattern in starter_patterns):
            state = "starter_placeholder"
            source = "classified_from_bounded_pane_text"
        elif cleaned.strip():
            state = "unknown"
            source = "classified_from_bounded_pane_text"
        else:
            state = "no_pane_text"
            source = "no_status_text"
    return {
        "state": state,
        "source": source,
        "evidence": "not_returned",
        "raw_output": "not_returned",
    }


def agent_limit_state(
    agent: str,
    *,
    running: bool,
    meta: dict[str, Any],
    raw_log_path: Path | None,
    raw_log_expected_stat: os.stat_result | None = None,
    latest_assignment: dict[str, Any] | None,
    pane_text: str | None = None,
) -> dict[str, Any]:
    samples: list[str] = []
    if running:
        samples.append(
            pane_text if pane_text is not None else pane_tail(agent, MAX_TAIL_LINES)
        )
    if raw_log_path:
        samples.append(
            read_log_tail(
                raw_log_path,
                MAX_LIMIT_STATUS_BYTES,
                expected_stat=raw_log_expected_stat,
            )
        )
    return classify_limit_text(
        "\n".join(item for item in samples if item), meta, latest_assignment
    )


def agent_response_state(
    running: bool,
    limit_state: dict[str, Any],
    raw_log_info: dict[str, Any],
    tui_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if limit_state.get("limited"):
        state = "blocked_by_limit"
    elif not running:
        state = "not_running"
    elif (tui_context or {}).get("state") == "update_prompt":
        state = "running_tui_update_prompt"
    elif (tui_context or {}).get("state") == "starter_placeholder":
        state = "running_tui_starter_context"
    elif raw_log_info.get("idle_seconds") is None:
        state = "running_no_output_observed"
    elif int(raw_log_info["idle_seconds"]) >= IDLE_RESPONSE_SECONDS:
        state = "running_idle"
    else:
        state = "running_recent_output"
    return {
        "state": state,
        "idle_threshold_seconds": IDLE_RESPONSE_SECONDS,
        "response_output": "not_returned",
        "raw_output": "not_returned",
    }


def wait_terminal_status(
    status: dict[str, Any], initial: dict[str, Any], *, now: float | None = None
) -> str | None:
    if not status.get("running"):
        return "not_running"
    identity_guard = status.get("identity_guard")
    if isinstance(identity_guard, dict) and identity_guard.get("ok") is False:
        return "identity_unverified"
    if (status.get("limit_state") or {}).get("limited"):
        return "blocked_by_limit"
    latest_assignment = (
        status.get("last_assignment")
        if isinstance(status.get("last_assignment"), dict)
        else {}
    )
    initial_assignment = (
        initial.get("last_assignment")
        if isinstance(initial.get("last_assignment"), dict)
        else {}
    )
    assignment_changed = latest_assignment.get(
        "assignment_id"
    ) != initial_assignment.get("assignment_id") or latest_assignment.get(
        "created_at_utc"
    ) != initial_assignment.get("created_at_utc")
    assignment_created = parse_utc_timestamp(latest_assignment.get("created_at_utc"))
    raw_log_updated = parse_utc_timestamp(status.get("raw_log_updated_at_utc"))
    current_response_state = (status.get("response_state") or {}).get("state")
    current = time.time() if now is None else now
    assignment_has_recent_output = (
        assignment_created is not None
        and raw_log_updated is not None
        and raw_log_updated <= current
        and raw_log_updated > assignment_created
    )
    if assignment_has_recent_output and (
        assignment_changed or current_response_state == "running_idle"
    ):
        return "activity_observed"
    current_raw_log_bytes = status.get("raw_log_bytes")
    initial_raw_log_bytes = initial.get("raw_log_bytes")
    if (
        isinstance(current_raw_log_bytes, int)
        and not isinstance(current_raw_log_bytes, bool)
        and isinstance(initial_raw_log_bytes, int)
        and not isinstance(initial_raw_log_bytes, bool)
        and current_raw_log_bytes != initial_raw_log_bytes
        and (raw_log_updated is None or raw_log_updated <= current)
    ):
        return "activity_observed"
    initial_raw_log_updated = parse_utc_timestamp(initial.get("raw_log_updated_at_utc"))
    if (
        initial_raw_log_updated is not None
        and raw_log_updated is not None
        and raw_log_updated <= current
        and raw_log_updated != initial_raw_log_updated
    ):
        return "activity_observed"
    initial_response_state = (initial.get("response_state") or {}).get("state")
    if (
        initial_response_state == "running_tui_starter_context"
        and current_response_state != initial_response_state
    ):
        return "activity_observed"
    if (
        (status.get("response_state") or {}).get("state")
    ) == "running_tui_starter_context":
        if assignment_created is not None:
            return None
        return "tui_starter_context"
    return None


def wait_terminal_visible_input_status(
    agent: str,
    status: dict[str, Any],
    initial: dict[str, Any],
    *,
    now: float | None = None,
) -> str | None:
    latest_assignment = (
        status.get("last_assignment")
        if isinstance(status.get("last_assignment"), dict)
        else {}
    )
    initial_assignment = (
        initial.get("last_assignment")
        if isinstance(initial.get("last_assignment"), dict)
        else {}
    )
    assignment_changed = latest_assignment.get(
        "assignment_id"
    ) != initial_assignment.get("assignment_id") or latest_assignment.get(
        "created_at_utc"
    ) != initial_assignment.get("created_at_utc")
    assignment_created = parse_utc_timestamp(latest_assignment.get("created_at_utc"))
    raw_log_updated = parse_utc_timestamp(status.get("raw_log_updated_at_utc"))
    current_response_state = (status.get("response_state") or {}).get("state")
    current = time.time() if now is None else now
    if (
        current_response_state != "running_tui_starter_context"
        or assignment_created is None
        or raw_log_updated is None
        or raw_log_updated > current
        or raw_log_updated <= assignment_created
        or assignment_changed
    ):
        return None
    visible_pane_text = pane_tail(agent, 24, visible_only=True, verify_identity=True)
    if tui_accepts_input(visible_pane_text):
        return "activity_observed"
    return None


def wait_agent(
    agent: str,
    timeout_seconds: int = DEFAULT_WAIT_SECONDS,
    poll_interval_seconds: int = DEFAULT_WAIT_POLL_SECONDS,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    timeout_seconds = normalize_int_field(
        timeout_seconds,
        field="timeout_seconds",
        minimum=0,
        maximum=MAX_WAIT_SECONDS,
    )
    poll_interval_seconds = normalize_poll_interval_seconds(poll_interval_seconds)
    if _headless_descriptor(agent) is not None:
        started = time.monotonic()
        initial = status_agent(agent)
        current = initial
        polls = 0
        terminal = (current.get("headless_job") or {}).get("status")
        deadline = started + timeout_seconds
        while terminal in {"running", "cancelling"} and time.monotonic() < deadline:
            remaining = max(0.0, deadline - time.monotonic())
            time.sleep(min(float(poll_interval_seconds), remaining))
            polls += 1
            current = status_agent(agent)
            terminal = (current.get("headless_job") or {}).get("status")
        if terminal in {"running", "cancelling"}:
            terminal = "timeout"
        latest = (
            current.get("last_assignment")
            if isinstance(current.get("last_assignment"), dict)
            else {}
        )
        assignment_id = latest.get("assignment_id")
        if not isinstance(assignment_id, str) or not assignment_id:
            assignment_id = (current.get("headless_job") or {}).get("assignment_id")
        return {
            "agent": agent,
            "status": terminal or "not_started",
            "assignment_id": assignment_id,
            "result_tool": "agent_assignment_report" if assignment_id else None,
            "timeout_seconds": timeout_seconds,
            "poll_interval_seconds": poll_interval_seconds,
            "poll_count": polls,
            "elapsed_seconds": max(0, int(time.monotonic() - started)),
            "initial": initial,
            "current": current,
            "raw_output": "not_returned",
            "response_output": "not_returned",
        }
    started = time.monotonic()
    deadline = started + timeout_seconds
    initial = status_agent(agent)
    current = initial
    polls = 0
    status = wait_terminal_status(current, initial)
    if status is None:
        status = wait_terminal_visible_input_status(agent, current, initial)
    while status is None and time.monotonic() < deadline:
        remaining = max(0.0, deadline - time.monotonic())
        time.sleep(min(float(poll_interval_seconds), remaining))
        polls += 1
        current = status_agent(agent)
        status = wait_terminal_status(current, initial)
        if status is None:
            status = wait_terminal_visible_input_status(agent, current, initial)
    if status is None:
        status = "timeout"
    latest_assignment = (
        current.get("last_assignment")
        if isinstance(current.get("last_assignment"), dict)
        else {}
    )
    assignment_id = latest_assignment.get("assignment_id")
    if not isinstance(assignment_id, str) or not assignment_id:
        assignment_id = None
    return {
        "agent": agent,
        "status": status,
        "assignment_id": assignment_id,
        "result_tool": "agent_assignment_report" if assignment_id else None,
        "timeout_seconds": timeout_seconds,
        "poll_interval_seconds": poll_interval_seconds,
        "poll_count": polls,
        "elapsed_seconds": max(0, int(time.monotonic() - started)),
        "initial": initial,
        "current": current,
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }


def status_agent(
    agent: str,
    *,
    initialize_state: bool = True,
    snapshot: FleetWatchdogSnapshot | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if initialize_state:
        ensure_state()
    headless_descriptor = _headless_descriptor(agent)
    if headless_descriptor is not None:
        # Resolve the configuration from the same live registry snapshot that
        # identified the headless descriptor.  This also keeps status checks
        # coherent during registry-backed tests and migrations where the
        # legacy AGENTS mapping is intentionally not populated.
        inventory = current_agent_inventory()
        live_descriptor = inventory.agents.get(agent)
        if live_descriptor is not None:
            cfg = {
                "label": live_descriptor.label,
                "runner": live_descriptor.runner_path
                or live_descriptor.home / "gemini",
                "home": live_descriptor.home,
                "session": live_descriptor.session,
                "enabled": live_descriptor.enabled,
            }
        else:
            cfg = agent_config(agent)
        marker = _headless_marker(agent)
        job = headless_job_status(agent)
        latest_assignment = latest_assignment_summary(
            agent, initialize_state=initialize_state
        )
        state = job.get("status")
        running = state in {"running", "cancelling"}
        headless_gate = _headless_public_gate(agent)
        gate_reason = headless_gate.get("reason")
        gate_state = (
            "ready"
            if headless_gate.get("allowed") is True
            else "limited"
            if gate_reason == "limit_active"
            else "disabled"
            if gate_reason in {"account_disabled", "series_disabled"}
            else "unknown"
        )
        usage_reader = getattr(current_fleet_service(), "gemini_usage_status", None)
        usage = (
            usage_reader(headless_descriptor.account_id or "unknown")
            if callable(usage_reader)
            else {
                "probe_state": "unknown",
                "rpm_observed": None,
                "tpm_observed": None,
                "rpd_observed": None,
            }
        )
        try:
            lease_status = agent_lease_status(agent, initialize_state=initialize_state)
        except TypeError:
            # Preserve compatibility with small read-only embedding adapters.
            lease_status = agent_lease_status(agent)
        return {
            "agent": agent,
            "label": cfg["label"],
            "backend": "headless_job",
            "running": running,
            "session": cfg["session"],
            "pid": None,
            "home": PATH_NOT_RETURNED,
            "home_kind": "managed_agent_home",
            "runner": PATH_NOT_RETURNED,
            "runner_state": public_config_path_state(cfg["runner"]),
            "started_at_utc": marker.get("started_at_utc"),
            "cwd": None,
            "cwd_state": "not_set",
            "model": headless_descriptor.model,
            "model_reasoning_effort": None,
            "lease": lease_status,
            "last_assignment": latest_assignment,
            "headless_job": job,
            "limit_state": {
                **headless_gate,
                "state": gate_state,
                "limited": gate_state == "limited",
            },
            "usage": usage,
            "usage_watchdog": {
                "state": "active"
                if usage.get("probe_state") == "fresh"
                else "probe_deferred_until_invocation",
                "provider": "gemini_api",
                "account_id": headless_descriptor.account_id,
                "probe_state": usage.get("probe_state"),
                "rpm_observed": usage.get("rpm_observed"),
                "tpm_observed": usage.get("tpm_observed"),
                "rpd_observed": usage.get("rpd_observed"),
                "raw_output": "not_returned",
            },
            "response_state": {
                "state": f"headless_{state or 'unknown'}",
                "raw_output": "not_returned",
            },
            "raw_log": None,
            "raw_log_bytes": None,
            "raw_log_updated_at_utc": None,
            "raw_log_idle_seconds": None,
            "raw_log_max_bytes": 0,
            "raw_log_policy": "not_applicable",
            "raw_log_path_valid": True,
            "home_process_count": None,
            "home_managed_process_count": None,
            "home_external_process_count": None,
            "home_external_processes_truncated": False,
            "identity_guard": {
                "ok": state != "identity_unverified",
                "backend": "headless_job",
            },
            "tmux_scan_available": None,
            "auth": {"state": "not_applicable", "raw_output": "not_returned"},
            "raw_output": "not_returned",
        }
    cfg = agent_config(agent)
    ollama_descriptor = _ollama_descriptor(agent)
    ollama_resource_decision = (
        ollama_resource_status(agent) if ollama_descriptor is not None else None
    )
    ollama_resource = (
        _public_resource_gate_status(ollama_resource_decision)
        if ollama_resource_decision is not None
        else None
    )
    session = cfg["session"]
    meta = read_meta(agent)
    raw_log = meta.get("raw_log")
    raw_log_identity = allowed_agent_raw_log_identity(agent, raw_log)
    raw_log_path = raw_log_identity[0] if raw_log_identity is not None else None
    process_summary = (
        summarize_agent_processes(snapshot, agent)
        if snapshot is not None
        else agent_home_process_summary(agent)
    )
    session_snapshot = (
        snapshot.tmux_sessions.get(session) if snapshot is not None else None
    )
    tmux_scan_available = snapshot.tmux_scan_available if snapshot is not None else None
    tmux_routing_unavailable = False
    if session_snapshot is not None:
        running = session_snapshot.alive
    else:
        observed_running = _observational_tmux_alive(session)
        tmux_routing_unavailable = observed_running is None
        running = observed_running is True
        if tmux_routing_unavailable:
            tmux_scan_available = False
    session_pid = (
        session_snapshot.pane_pid
        if session_snapshot is not None
        and running
        and "managed_process_ids" in process_summary
        else pane_pid(session)
        if running and "managed_process_ids" in process_summary
        else None
    )
    identity_guard = agent_identity_guard(
        running, process_summary, pane_process_id=session_pid
    )
    if tmux_routing_unavailable:
        identity_guard = {
            **identity_guard,
            "ok": False,
            "state": "tmux_routing_unavailable",
            "tmux_session_running": False,
            "pane_process_identity_checked": False,
            "pane_process_identity_match": None,
        }
    if (
        running
        and identity_guard["ok"]
        and (raw_log_identity is None or raw_log_identity[1] is None)
    ):
        recovered_path = latest_managed_raw_log(
            agent,
            include_legacy=raw_log_identity_is_legacy(raw_log_identity),
        )
        recovered_identity = (
            allowed_agent_raw_log_identity(agent, str(recovered_path))
            if recovered_path is not None
            else None
        )
        raw_log_identity = recovered_identity
        raw_log_path = recovered_identity[0] if recovered_identity is not None else None
    raw_log_expected_stat = (
        raw_log_identity[1] if raw_log_identity is not None else None
    )
    raw_log_info = raw_log_metadata(raw_log_path, expected_stat=raw_log_expected_stat)
    latest_assignment = latest_assignment_summary(
        agent, initialize_state=initialize_state
    )
    auth = agent_auth_status(agent)
    pane_is_managed = running and identity_guard["ok"]
    pane_text = (
        pane_tail(agent, MAX_TAIL_LINES, verify_identity=True)
        if pane_is_managed
        else ""
    )
    visible_pane_text = (
        pane_tail(agent, 24, visible_only=True, verify_identity=True)
        if pane_is_managed
        else ""
    )
    tui_context = classify_tui_context(visible_pane_text, running)
    limit_state = agent_limit_state(
        agent,
        running=running,
        meta=meta,
        raw_log_path=raw_log_path,
        raw_log_expected_stat=raw_log_expected_stat,
        latest_assignment=latest_assignment,
        pane_text=pane_text,
    )
    if ollama_descriptor is not None:
        limit_state = {
            "allowed": bool(ollama_resource and ollama_resource.get("allowed") is True),
            "limited": bool(
                ollama_resource and ollama_resource.get("allowed") is not True
            ),
            "reason_codes": ollama_resource.get("reason_codes", [])
            if ollama_resource
            else [],
            "state": "resource_gate",
            "raw_output": "not_returned",
        }
        usage_watchdog = {
            "provider": Provider.OLLAMA_LOCAL.value,
            "state": "not_applicable",
            "reason": "local_resource_gate",
            "raw_output": "not_returned",
        }
    else:
        usage_watchdog = codex_usage_watchdog_status(agent)
    response_state = agent_response_state(
        running, limit_state, raw_log_info, tui_context
    )
    if tmux_routing_unavailable:
        response_state = {**response_state, "state": "tmux_routing_unavailable"}
    elif running and not identity_guard["ok"]:
        response_state = {**response_state, "state": "identity_unverified"}
    return {
        "agent": agent,
        "label": cfg["label"],
        "backend": "tmux",
        "running": running,
        "session": session,
        "pid": session_pid if pane_is_managed else None,
        "home": PATH_NOT_RETURNED,
        "home_kind": "managed_agent_home",
        "runner": PATH_NOT_RETURNED,
        "runner_state": public_config_path_state(cfg["runner"]),
        "started_at_utc": meta.get("started_at_utc"),
        "cwd": public_path(meta.get("cwd")),
        "cwd_state": public_path_state(meta.get("cwd")),
        "model": ollama_descriptor.model
        if ollama_descriptor is not None
        else meta.get("model") or DEFAULT_AGENT_MODEL,
        "model_reasoning_effort": (
            None
            if ollama_descriptor is not None
            else meta.get("model_reasoning_effort") or DEFAULT_AGENT_MODEL_EFFORT
        ),
        "provider": ollama_descriptor.provider.value
        if ollama_descriptor is not None
        else Provider.OPENAI_CHATGPT.value,
        "task_profile": ollama_descriptor.task_profile
        if ollama_descriptor is not None
        else "standard",
        "resource_gate": ollama_resource,
        "lease": agent_lease_status(agent, initialize_state=initialize_state),
        "last_assignment": latest_assignment,
        "tui_context": tui_context,
        "limit_state": limit_state,
        "usage_watchdog": usage_watchdog,
        "response_state": response_state,
        "raw_log": "not_returned" if raw_log or raw_log_path is not None else None,
        "raw_log_bytes": raw_log_info["bytes"],
        "raw_log_updated_at_utc": raw_log_info["updated_at_utc"],
        "raw_log_idle_seconds": raw_log_info["idle_seconds"],
        "raw_log_max_bytes": MAX_RAW_LOG_BYTES,
        "raw_log_policy": "local_only_bounded_not_returned_by_default",
        "raw_log_path_valid": (raw_log_path is not None) if raw_log else True,
        "home_process_count": process_summary["process_count"],
        "home_managed_process_count": process_summary["managed_process_count"],
        "home_external_process_count": process_summary["external_process_count"],
        "home_external_processes_truncated": process_summary[
            "external_processes_truncated"
        ],
        "identity_guard": identity_guard,
        "tmux_scan_available": tmux_scan_available,
        "auth": (
            {
                "state": "not_applicable",
                "provider": Provider.OLLAMA_LOCAL.value,
                "raw_output": "not_returned",
            }
            if ollama_descriptor is not None
            else auth
        ),
        "raw_output": "not_returned",
    }


def require_invocation_status(
    agent: str,
    *,
    operation: str,
    enforce_identity: bool = True,
) -> dict[str, Any]:
    """Take a cheap, fresh status snapshot immediately before invocation."""

    descriptor = current_agent_inventory().agents.get(agent)
    if descriptor is None:
        raise AgentError(f"{operation} blocked by unknown agent status")
    running = tmux_alive(descriptor.session)
    process_summary = agent_home_process_summary(agent)
    pane_process_identity = (
        pane_pid(descriptor.session)
        if running and "managed_process_ids" in process_summary
        else None
    )
    identity = agent_identity_guard(
        running,
        process_summary,
        pane_process_id=pane_process_identity,
    )
    # A few embedders expose only the historical process_count field.  The
    # real scanner always emits the complete managed/external fields; accept
    # this explicitly identified compatibility shape while retaining the
    # strict identity guard for actual scanner output.
    if (
        not identity.get("ok")
        and process_summary.get("process_count") == 1
        and "managed_process_count" not in process_summary
        and "managed_process_ids" not in process_summary
    ):
        identity = {
            **identity,
            "ok": running,
            "state": "legacy_process_summary",
            "single_identity_required": True,
        }
    if enforce_identity and running and identity.get("ok") is not True:
        raise AgentError(f"{operation}: session identity could not be verified")
    if descriptor.provider is Provider.OLLAMA_LOCAL:
        resource = ollama_resource_status(agent)
        limit_state = {
            "allowed": resource.get("allowed") is True,
            "limited": resource.get("allowed") is not True,
            "reason_codes": resource.get("reason_codes", []),
        }
    else:
        meta = read_meta(agent)
        raw_log = meta.get("raw_log")
        raw_log_identity = allowed_agent_raw_log_identity(agent, raw_log)
        limit_state = agent_limit_state(
            agent,
            running=running,
            meta=meta,
            raw_log_path=raw_log_identity[0] if raw_log_identity is not None else None,
            raw_log_expected_stat=raw_log_identity[1]
            if raw_log_identity is not None
            else None,
            latest_assignment=latest_assignment_summary(agent, initialize_state=False),
            pane_text="",
        )
    if limit_state.get("limited") is True:
        raise AgentError(f"{operation} blocked by agent status limit_state")
    return {
        "agent": agent,
        "running": running,
        "identity_guard": identity,
        "limit_state": limit_state,
        "provider": descriptor.provider.value,
        "raw_output": "not_returned",
    }


def applet_status(
    selected_agents: list[str] | tuple[str, ...] | None = None,
    *,
    schema_version: int = 1,
) -> dict[str, Any]:
    """Return a bounded, read-only snapshot for the Cinnamon adapter."""

    if (
        isinstance(schema_version, bool)
        or not isinstance(schema_version, int)
        or schema_version not in (1, 2, 3, 4)
    ):
        raise AgentError("schema_version must be 1, 2, 3, or 4")
    if schema_version == 1:
        return applet_status_v1(selected_agents)
    if schema_version == 2:
        return applet_status_v2(selected_agents)
    if schema_version == 4:
        result = applet_status_v2(selected_agents)
        result["schema_version"] = 4
        result["resource"] = _applet_resource_projection()
        return result
    inventory, _published = published_agent_inventory()
    selected = tuple(selected_agents or ())
    if len(selected) > MAX_FLEET_AGENTS:
        selected = selected[:MAX_FLEET_AGENTS]
    selected_set = {
        item
        for item in selected
        if isinstance(item, str) and len(item) <= MAX_AGENT_SELECTOR_TEXT
    }
    fleet_service = None
    fleet_snapshot = None
    fleet_inventory = None
    generation = 0
    fleet_snapshot_degraded = False
    try:
        fleet_service = _readonly_fleet_service()
        fleet_snapshot = fleet_service.load()
        fleet_inventory = build_inventory(fleet_snapshot, AGENT_POOL_ROOT)
        generation = fleet_snapshot.generation
    except (AgentError, FleetValidationError, OSError, ValueError):
        fleet_snapshot_degraded = True
    enabled_ids = tuple(
        agent_id
        for agent_id in inventory.agent_ids
        if inventory.agents[agent_id].enabled
    )
    selected_enabled_ids = tuple(
        agent_id
        for agent_id in selected
        if isinstance(agent_id, str)
        and agent_id in inventory.agents
        and inventory.agents[agent_id].enabled
    )
    remaining_enabled_ids = tuple(
        agent_id for agent_id in enabled_ids if agent_id not in selected_set
    )
    status_poll_ids = frozenset(
        (*selected_enabled_ids, *remaining_enabled_ids)[:MAX_APPLET_STATUS_AGENTS]
    )
    watchdog_snapshot = None
    watchdog_snapshot_degraded = False
    try:
        watchdog_snapshot = create_fleet_snapshot(
            agent_homes={
                agent_id: inventory.agents[agent_id].home
                for agent_id in status_poll_ids
            },
            agent_sessions={
                agent_id: inventory.agents[agent_id].session
                for agent_id in status_poll_ids
            },
            tmux_runner=run_tmux,
        )
    except (AgentError, OSError, RuntimeError, ValueError):
        watchdog_snapshot_degraded = True
    rows: list[dict[str, Any]] = []
    dispatch_targets: list[str] = []
    dynamic_agent_ids = (
        frozenset(fleet_inventory.agent_ids)
        if fleet_inventory is not None
        else frozenset()
    )
    native_ids = tuple(
        agent_id
        for agent_id in enabled_ids
        if (fleet_inventory is None or agent_id not in dynamic_agent_ids)
    )[:MAX_FLEET_AGENTS]
    native_id_set = frozenset(native_ids)
    for prefix in inventory.series_prefixes[:MAX_FLEET_SERIES_PREFIXES]:
        ids = tuple(
            agent_id
            for agent_id in inventory.by_series.get(f"{prefix}-series", ())
            if agent_id not in native_id_set
        )[:MAX_FLEET_AGENTS]
        if not ids:
            continue
        running_count = 0
        eligible_count = 0
        polled_count = 0
        limit_states: list[str] = []
        blocked_until: str | None = None
        blocked_until_timestamp: float | None = None
        for agent_id in ids:
            if not inventory.agents[agent_id].enabled:
                continue
            if agent_id not in status_poll_ids:
                continue
            try:
                status = status_agent(agent_id, snapshot=watchdog_snapshot)
            except AgentError:
                continue
            polled_count += 1
            if status.get("running") is True:
                running_count += 1
            limit = (
                status.get("limit_state")
                if isinstance(status.get("limit_state"), dict)
                else {}
            )
            state = (
                limit.get("state") if isinstance(limit.get("state"), str) else "unknown"
            )
            try:
                if (
                    fleet_service is None
                    or fleet_snapshot is None
                    or fleet_inventory is None
                ):
                    raise AgentError("account_gate_unavailable")
                gate = fleet_service.account_gate(
                    agent_id,
                    snapshot=fleet_snapshot,
                    inventory=fleet_inventory,
                )
                state = (
                    "ready"
                    if gate.allowed
                    else "limited"
                    if gate.reason == "limit_active"
                    else "disabled"
                    if gate.reason in {"account_disabled", "series_disabled"}
                    else "unknown"
                )
            except Exception:
                if limit.get("limited") is True:
                    state = "limited"
            limit_states.append(state)
            if state not in {"limited", "disabled", "unknown", "blocked"}:
                eligible_count += 1
                if (
                    agent_id in selected_set
                    and len(dispatch_targets) < MAX_APPLET_DISPATCH_TARGETS
                ):
                    dispatch_targets.append(agent_id)
            reset = limit.get("blocked_until_utc") or limit.get("reset_at_utc")
            reset_timestamp = parse_utc_timestamp(reset)
            if reset_timestamp is not None and (
                blocked_until_timestamp is None
                or reset_timestamp < blocked_until_timestamp
            ):
                blocked_until = reset
                blocked_until_timestamp = reset_timestamp
        limit_state = "unknown"
        if limit_states and all(item == "limited" for item in limit_states):
            limit_state = "limited"
        elif limit_states and all(item == "ready" for item in limit_states):
            limit_state = "ready"
        rows.append(
            {
                "prefix": prefix,
                "display_name": prefix.upper(),
                "count": len(ids),
                "polled_count": polled_count,
                "running_count": running_count,
                "eligible_count": eligible_count,
                "limit_state": limit_state,
                "blocked_until_utc": blocked_until,
                "generation": generation,
            }
        )
    native_agents: list[dict[str, Any]] = []
    for agent_id in native_ids:
        descriptor = inventory.agents[agent_id]
        running = False
        state = "unknown"
        if agent_id in status_poll_ids:
            try:
                status = status_agent(agent_id, snapshot=watchdog_snapshot)
            except AgentError:
                status = {}
            running = status.get("running") is True
            limit = (
                status.get("limit_state")
                if isinstance(status.get("limit_state"), dict)
                else {}
            )
            state = (
                limit.get("state") if isinstance(limit.get("state"), str) else "unknown"
            )
            if state not in {"ready", "limited", "unknown", "probing", "disabled"}:
                state = "unknown"
        if (
            state == "ready"
            and agent_id in selected_set
            and len(dispatch_targets) < MAX_APPLET_DISPATCH_TARGETS
        ):
            dispatch_targets.append(agent_id)
        native_agents.append(
            {
                "id": agent_id,
                "label": descriptor.label,
                "running": running,
                "limit_state": state,
            }
        )
    result = {
        "schema_version": schema_version,
        "generation": generation,
        "fleet_snapshot_degraded": fleet_snapshot_degraded,
        "watchdog_snapshot_degraded": watchdog_snapshot_degraded,
        "dispatch_targets": dispatch_targets,
        "raw_output": "not_returned",
    }
    if schema_version >= 2:
        result["series"] = rows
        result["native_agents"] = native_agents
    return result


def _unavailable_applet_resource_projection() -> dict[str, Any]:
    return {
        "schema_version": 1,
        "generation": 0,
        "state": "unavailable",
        "bottleneck": "unknown",
        "trend": {},
        "confidence": "low",
        "preferred_profiles": [],
        "avoid_profiles": [],
        "raw_output": "not_returned",
    }


def _applet_resource_projection() -> dict[str, Any]:
    try:
        status = _read_resource_operator_status()
        if status.schema_version != 1:
            raise AgentError("resource_status_unavailable")
        return {
            "schema_version": status.schema_version,
            "generation": status.generation,
            "state": status.state,
            "bottleneck": status.bottleneck,
            "trend": dict(status.trend),
            "confidence": status.confidence,
            "preferred_profiles": list(status.preferred_profiles),
            "avoid_profiles": list(status.avoid_profiles),
            "raw_output": "not_returned",
        }
    except Exception:
        return _unavailable_applet_resource_projection()


def watchdog_marker(meta: dict[str, Any]) -> dict[str, Any]:
    value = meta.get("watchdog")
    return value if isinstance(value, dict) else {}


def update_watchdog_marker(agent: str, marker: dict[str, Any] | None) -> None:
    meta = read_meta(agent)
    if meta.get("meta_error"):
        raise AgentError("could_not_update_watchdog_metadata")
    if marker is None:
        meta.pop("watchdog", None)
    else:
        meta["watchdog"] = marker
    write_meta(agent, meta)


def _attested_usage_watchdog_state(
    agent: str,
    account: str | None,
    series_prefix: str | None,
    evidence: UsageEvidenceV2,
    *,
    now: _dt.datetime,
) -> dict[str, Any]:
    base = {
        "agent": agent,
        "account": account,
        "account_mapping": "inventory",
        "usage_status": evidence.status,
        "blocked_until_utc": None,
        "reason": None,
        "source": "v2",
        "raw_output": "not_returned",
    }
    if evidence.status != "complete" or account is None:
        return {**base, "state": "missing", "blocked": False}
    account_evidence = next(
        (item for item in evidence.accounts if item.account_id == account), None
    )
    if account_evidence is None:
        return {**base, "state": "missing", "blocked": False}
    automatic = {
        (item.pool, item.window_seconds, item.reset_generation)
        for item in derive_limit_decisions(evidence, now=now)
        if item.account_id == account and item.automatic
    }
    limits = [
        item
        for item in account_evidence.limits
        if (item.pool, item.window_seconds, item.reset_generation) in automatic
    ]
    if not limits:
        return {**base, "state": "missing", "blocked": False}
    exhausted = [
        item for item in limits if item.remaining_percent <= 0 and item.reset_at > now
    ]
    q_weekly = next(
        (
            item
            for item in limits
            if series_prefix == "q"
            and item.pool == "main"
            and item.window_seconds == 604800
            and item.remaining_percent < Q_WEEKLY_THRESHOLD_PERCENT
            and item.reset_at > now
        ),
        None,
    )
    if q_weekly is not None:
        return {
            **base,
            "state": "blocked",
            "blocked": True,
            "blocked_until_utc": q_weekly.reset_at.isoformat(),
            "reason": "verified q-series weekly remaining below threshold",
            "reason_code": "q_weekly_remaining_below_threshold",
            "remaining_percent": q_weekly.remaining_percent,
            "threshold_percent": Q_WEEKLY_THRESHOLD_PERCENT,
            "fallback_hint": "use a non-q series or wait for the verified q-series weekly reset",
        }
    if exhausted:
        reset_at = min(item.reset_at for item in exhausted)
        return {
            **base,
            "state": "blocked",
            "blocked": True,
            "blocked_until_utc": reset_at.isoformat(),
            "reason": "codex usage window exhausted",
        }
    return {**base, "state": "clear", "blocked": False}


def codex_usage_watchdog_status(agent: str) -> dict[str, Any]:
    """Evaluate one attested V2 evidence value without legacy state or fallback."""

    agent = canonical_agent_id(agent)
    descriptor = current_agent_inventory().agents.get(agent)
    account = getattr(descriptor, "account_id", None)
    series_prefix = getattr(descriptor, "series_prefix", None)
    now = _dt.datetime.now(_dt.timezone.utc)
    evidence = read_usage_evidence_v2(clock=lambda: now)
    return _attested_usage_watchdog_state(
        agent,
        account if isinstance(account, str) else None,
        series_prefix if isinstance(series_prefix, str) else None,
        evidence,
        now=now,
    )


def ensure_agent_not_blocked_by_codex_usage(agent: str) -> dict[str, Any]:
    status = codex_usage_watchdog_status(agent)
    if status.get("blocked"):
        blocked_until = status.get("blocked_until_utc")
        reason = status.get("reason") or "codex usage limit reached"
        detail = f"; blocked_until_utc={blocked_until}" if blocked_until else ""
        payload = None
        if status.get("reason_code") == "q_weekly_remaining_below_threshold":
            payload = {
                "error_code": "q_weekly_remaining_below_threshold",
                "reason_code": status["reason_code"],
                "reason": reason,
                "blocked_until": blocked_until,
                "remaining_percent": status.get("remaining_percent"),
                "threshold_percent": status.get("threshold_percent"),
                "fallback_hint": status.get("fallback_hint"),
            }
        raise AgentError(
            f"agent {canonical_agent_id(agent)} is blocked by codex-usage watchdog: {reason}{detail}",
            payload,
        )
    return status


def _emergency_queen_agent_candidates() -> list[str]:
    """Return dedicated materialized runtime targets for a Queen lease.

    Current q-homes carry Teamleiterin profiles, not a materialized Queen
    runtime. Never promote them by series or provider inference.
    """

    return []


def ensure_emergency_queen(*, dry_run: bool = False) -> dict[str, Any] | None:
    """Materialize one requested emergency Queen, or persist a blocker."""

    state = emergency_queen_status()
    if state["state"] in {"running", "finishing", "next", "draining"}:
        return {
            "status": "already_active",
            "state": state,
            "raw_output": "not_returned",
        }
    if state["state"] != "requested":
        return {"status": "not_requested", "state": state, "raw_output": "not_returned"}
    candidates = _emergency_queen_agent_candidates()
    if not candidates:
        if dry_run:
            return {
                "status": "would_block",
                "error_code": "queen_spawn_unavailable",
                "reason": "hive_queen_runtime_not_materialized",
                "state": state,
                "raw_output": "not_returned",
            }
        blocked = set_emergency_queen_blocked(
            int(state["generation"]),
            "queen_spawn_unavailable:hive_queen_runtime_not_materialized",
        )
        return {
            "status": "blocked",
            "error_code": "queen_spawn_unavailable",
            "reason": "hive_queen_runtime_not_materialized",
            "state": blocked.get("state", state),
            "raw_output": "not_returned",
        }
    queen_agent = candidates[0]
    if dry_run:
        return {
            "status": "would_start",
            "agent": queen_agent,
            "state": state,
            "raw_output": "not_returned",
        }
    require_resource_capacity_preflight(operation="emergency_queen_start")
    prompt = (
        "Du bist die Notfall-Königin des codex-master-Repositories. "
        "Arbeite ausschließlich den aktuell zugewiesenen freigegebenen Plan ab: "
        f"{state['current_plan'] or 'kein Plan ausgewählt'}. "
        "Nach vollständigem Abschluss melde den Planabschluss an Masterjet."
    )
    try:
        result = start_agent_with_lease(
            queen_agent,
            cwd=str(repo_root()),
            prompt=prompt,
            agent_class="koenigin",
            lifecycle="persistent",
            complexity="complex",
            name="Notfall-Königin",
        )
    except Exception as exc:
        blocked = set_emergency_queen_blocked(
            int(state["generation"]),
            f"queen_spawn_failed:{type(exc).__name__}",
        )
        return {
            "status": "blocked",
            "error_code": "queen_spawn_failed",
            "reason": type(exc).__name__,
            "state": blocked.get("state", state),
            "raw_output": "not_returned",
        }
    if result.get("status") not in {"started", "already_running"}:
        blocked = set_emergency_queen_blocked(
            int(state["generation"]),
            "queen_spawn_rejected:" + str(result.get("status", "unknown"))[:120],
        )
        return {
            "status": "blocked",
            "error_code": "queen_spawn_rejected",
            "reason": result.get("status"),
            "state": blocked.get("state", state),
            "raw_output": "not_returned",
        }
    running = set_emergency_queen_running(int(state["generation"]), queen_agent)
    return {
        "status": "started" if result.get("status") == "started" else "already_running",
        "agent": queen_agent,
        "state": running.get("state", state),
        "raw_output": "not_returned",
    }


def watchdog_effective_idle(
    status: dict[str, Any], *, now: float | None = None
) -> dict[str, Any]:
    current = time.time() if now is None else now
    raw_idle = status.get("raw_log_idle_seconds")
    raw_log_updated = parse_utc_timestamp(status.get("raw_log_updated_at_utc"))
    raw_log_is_current = raw_log_updated is None or raw_log_updated <= current
    latest_assignment = (
        status.get("last_assignment")
        if isinstance(status.get("last_assignment"), dict)
        else {}
    )
    assignment_value = latest_assignment.get("created_at_utc")
    assignment_created = parse_utc_timestamp(assignment_value)
    assignment_age = age_seconds_from_utc(assignment_value, now=current)
    assignment_is_current = (
        assignment_created is not None and assignment_created <= current
    )
    if (
        isinstance(raw_idle, int)
        and not isinstance(raw_idle, bool)
        and raw_log_is_current
        and (
            assignment_age is None
            or not assignment_is_current
            or max(0, raw_idle) <= assignment_age
        )
    ):
        return {
            "effective_idle_seconds": max(0, raw_idle),
            "activity_source": "raw_log",
            "activity_at_utc": status.get("raw_log_updated_at_utc"),
            "raw_output": "not_returned",
        }
    if assignment_age is not None and assignment_is_current:
        return {
            "effective_idle_seconds": assignment_age,
            "activity_source": "last_assignment_age",
            "activity_at_utc": latest_assignment.get("created_at_utc"),
            "raw_output": "not_returned",
        }
    started_at = status.get("started_at_utc")
    started_timestamp = parse_utc_timestamp(started_at)
    if started_timestamp is not None and started_timestamp <= current:
        return {
            "effective_idle_seconds": max(0, int(current - started_timestamp)),
            "activity_source": "session_start_age",
            "activity_at_utc": started_at,
            "raw_output": "not_returned",
        }
    return {
        "effective_idle_seconds": None,
        "activity_source": "insufficient_idle_evidence",
        "activity_at_utc": None,
        "raw_output": "not_returned",
    }


def watchdog_marker_lease_matches(
    marker: dict[str, Any],
    *,
    assignment_id: Any,
    session_started_at: Any,
    lease_id: Any = None,
) -> bool:
    if (
        marker.get("phase") != "report_requested"
        or marker.get("assignment_id") != assignment_id
    ):
        return False
    marker_lease_id = marker.get("lease_id")
    if marker_lease_id is not None or lease_id is not None:
        if (
            not isinstance(marker_lease_id, str)
            or not isinstance(lease_id, str)
            or marker_lease_id != lease_id
        ):
            return False
    marker_started_at = parse_utc_timestamp(marker.get("started_at_utc"))
    current_started_at = parse_utc_timestamp(session_started_at)
    session_identity_present = (
        marker.get("started_at_utc") is not None or session_started_at is not None
    )
    return not session_identity_present or (
        marker_started_at is not None
        and current_started_at is not None
        and marker_started_at == current_started_at
    )


def watchdog_marker_matches(
    marker: dict[str, Any],
    *,
    action: str,
    assignment_id: Any,
    session_started_at: Any = None,
    lease_id: Any = None,
    now: float | None = None,
) -> bool:
    if marker.get("planned_action") != action:
        return False
    if not watchdog_marker_lease_matches(
        marker,
        assignment_id=assignment_id,
        session_started_at=session_started_at,
        lease_id=lease_id,
    ):
        return False
    requested_at = parse_utc_timestamp(marker.get("requested_at_utc"))
    current = time.time() if now is None else now
    return requested_at is not None and requested_at <= current


def watchdog_output_changed_since_marker(
    status: dict[str, Any], marker: dict[str, Any], *, now: float | None = None
) -> bool:
    marker_bytes = marker.get("raw_log_bytes")
    current_bytes = status.get("raw_log_bytes")
    requested_at = parse_utc_timestamp(marker.get("requested_at_utc"))
    activity_at = parse_utc_timestamp(status.get("raw_log_updated_at_utc"))
    current = time.time() if now is None else now
    if (
        isinstance(marker_bytes, int)
        and not isinstance(marker_bytes, bool)
        and isinstance(current_bytes, int)
        and not isinstance(current_bytes, bool)
        and current_bytes > marker_bytes
        and (activity_at is None or activity_at <= current)
    ):
        return True
    return bool(
        requested_at is not None
        and activity_at is not None
        and activity_at <= current
        and activity_at > requested_at
    )


def public_watchdog_report_result(result: dict[str, Any]) -> dict[str, Any]:
    send = result.get("send") if isinstance(result.get("send"), dict) else {}
    return {
        "status": result.get("status"),
        "submitted": result.get("submitted"),
        "assignment_id": result.get("assignment_id"),
        "send_status": send.get("status"),
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }


def public_watchdog_action_result(result: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": result.get("status"),
        "lease": result.get("lease"),
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }


def watchdog_release_identity_is_current(agent: str, *, expected_running: bool) -> bool:
    """Re-check the live tmux/home identity before a watchdog release."""

    if not isinstance(expected_running, bool):
        return False
    agent = canonical_agent_id(agent)
    try:
        running = tmux_alive(agent_config(agent)["session"])
        process_summary = agent_home_process_summary(agent)
    except (AgentError, OSError, RuntimeError):
        return False
    if running != expected_running:
        return False
    if not expected_running:
        return all(
            process_summary.get(field) == 0
            for field in (
                "process_count",
                "external_process_count",
                "managed_process_count",
            )
        )
    try:
        guard = require_managed_tmux_session(agent, process_summary=process_summary)
    except AgentError:
        return False
    return not isinstance(guard, dict) or guard.get("ok") is not False


def watchdog_release_if_current(
    agent: str,
    *,
    force: bool,
    expected_running: bool,
) -> dict[str, Any]:
    if not watchdog_release_identity_is_current(
        agent, expected_running=expected_running
    ):
        return {
            "agent": canonical_agent_id(agent),
            "status": "skipped_identity_changed",
            "raw_output": "not_returned",
        }
    return release_agent(agent, force=force)


def watchdog_action(
    agent: str,
    action: str,
    *,
    release_after_interrupt: bool,
    release_lease_id: str | None = None,
) -> dict[str, Any]:
    if action == "none":
        return {"agent": agent, "status": "no_action", "raw_output": "not_returned"}
    if action == "interrupt":
        result = interrupt_agent(agent, force=False)
        current_lease = agent_lease_status(agent) if release_after_interrupt else {}
        if current_lease.get("held_by_this_server"):
            current_lease_id = current_lease.get("lease_id")
            if release_lease_id is None or release_lease_id == current_lease_id:
                result["watchdog_release"] = watchdog_release_if_current(
                    agent,
                    force=True,
                    expected_running=True,
                )
        return result
    if action == "stop":
        return stop_agent(agent, force=False)
    if action == "release":
        return watchdog_release_if_current(agent, force=False, expected_running=True)
    raise AgentError("watchdog action must be interrupt, stop, release, or none")


def watchdog_agent(
    agent: str,
    *,
    idle_seconds: int,
    action: str,
    report_grace_seconds: int,
    require_lease: bool,
    manage_unclaimed: bool,
    dry_run: bool,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    safe_shutdown_only = (
        _fleet_safe_shutdown_only("fleet_watchdog")
        if not dry_run and action != "none"
        else False
    )
    with agent_lifecycle_lock(agent):
        return _watchdog_agent_unlocked(
            agent,
            idle_seconds=idle_seconds,
            action=action,
            report_grace_seconds=report_grace_seconds,
            require_lease=require_lease,
            manage_unclaimed=manage_unclaimed,
            dry_run=dry_run,
            safe_shutdown_only=safe_shutdown_only,
        )


def _watchdog_agent_unlocked(
    agent: str,
    *,
    idle_seconds: int,
    action: str,
    report_grace_seconds: int,
    require_lease: bool,
    manage_unclaimed: bool,
    dry_run: bool,
    snapshot: FleetWatchdogSnapshot | None = None,
    safe_shutdown_only: bool = False,
) -> dict[str, Any]:
    now = time.time()
    observed_snapshot = snapshot if snapshot is not None else _WATCHDOG_SNAPSHOT.get()
    if observed_snapshot is None:
        status = status_agent(agent, initialize_state=not dry_run)
    else:
        status = status_agent(
            agent, initialize_state=not dry_run, snapshot=observed_snapshot
        )
    lease = status.get("lease") if isinstance(status.get("lease"), dict) else {}
    response_state = (status.get("response_state") or {}).get("state")
    latest_assignment = (
        status.get("last_assignment")
        if isinstance(status.get("last_assignment"), dict)
        else {}
    )
    assignment_id = latest_assignment.get("assignment_id")
    idle = watchdog_effective_idle(status, now=now)
    lease_state = lease.get("state")
    held_by_this_server = bool(lease.get("held_by_this_server"))
    unclaimed_or_expired = lease_state in {"unclaimed", "expired"}
    lease_allowed = held_by_this_server or (manage_unclaimed and unclaimed_or_expired)
    base = {
        "agent": agent,
        "running": bool(status.get("running")),
        "lease_state": lease_state,
        "held_by_this_server": held_by_this_server,
        "manage_unclaimed": manage_unclaimed,
        "response_state": response_state,
        "effective_idle_seconds": idle["effective_idle_seconds"],
        "activity_source": idle["activity_source"],
        "idle_threshold_seconds": idle_seconds,
        "report_grace_seconds": report_grace_seconds,
        "planned_action": action,
        "dry_run": dry_run,
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }
    identity_guard = status.get("identity_guard")
    if (
        status.get("running")
        and isinstance(identity_guard, dict)
        and identity_guard.get("ok") is False
    ):
        return {
            **base,
            "identity_guard": identity_guard,
            "watchdog_state": "skipped_identity_unverified",
            "action_taken": "none",
        }
    if status.get("tmux_scan_available") is False:
        return {
            **base,
            "watchdog_state": "skipped_tmux_scan_unavailable",
            "action_taken": "none",
        }
    if not status.get("running"):
        if not dry_run and not safe_shutdown_only:
            marker = watchdog_marker(read_meta(agent))
            marker_lease_matches = watchdog_marker_lease_matches(
                marker,
                assignment_id=assignment_id,
                session_started_at=status.get("started_at_utc"),
                lease_id=lease.get("lease_id"),
            )
            home_process_count = status.get("home_process_count")
            home_processes_clear = (
                isinstance(home_process_count, int)
                and not isinstance(home_process_count, bool)
                and home_process_count == 0
            )
            if marker:
                if (
                    marker.get("release_lease_after_action") is True
                    and marker_lease_matches
                    and home_processes_clear
                    and agent_lease_status(agent).get("held_by_this_server")
                ):
                    released = watchdog_release_if_current(
                        agent,
                        force=True,
                        expected_running=False,
                    )
                    released_lease = (
                        released.get("lease") if isinstance(released, dict) else None
                    )
                    if isinstance(released_lease, dict):
                        base["lease_state"] = released_lease.get("state")
                        base["held_by_this_server"] = bool(
                            released_lease.get("held_by_this_server")
                        )
                update_watchdog_marker(agent, None)
        return {**base, "watchdog_state": "skipped_not_running", "action_taken": "none"}
    if lease_state == "held" and not held_by_this_server:
        return {
            **base,
            "watchdog_state": "skipped_not_leased_by_this_server",
            "action_taken": "none",
        }
    if require_lease and not lease_allowed:
        return {
            **base,
            "watchdog_state": "skipped_not_leased_by_this_server",
            "action_taken": "none",
        }
    effective_idle = idle["effective_idle_seconds"]
    if effective_idle is None:
        return {
            **base,
            "watchdog_state": "skipped_insufficient_idle_evidence",
            "action_taken": "none",
        }
    if effective_idle < idle_seconds and response_state != "blocked_by_limit":
        meta = read_meta(agent)
        marker = watchdog_marker(meta)
        if marker and not dry_run and lease_allowed and not safe_shutdown_only:
            marker_lease_matches = watchdog_marker_lease_matches(
                marker,
                assignment_id=assignment_id,
                session_started_at=status.get("started_at_utc"),
                lease_id=lease.get("lease_id"),
            )
            if (
                marker.get("release_lease_after_action") is True
                and marker_lease_matches
                and agent_lease_status(agent).get("held_by_this_server")
            ):
                released = watchdog_release_if_current(
                    agent,
                    force=True,
                    expected_running=True,
                )
                released_lease = (
                    released.get("lease") if isinstance(released, dict) else None
                )
                if isinstance(released_lease, dict):
                    base["lease_state"] = released_lease.get("state")
                    base["held_by_this_server"] = bool(
                        released_lease.get("held_by_this_server")
                    )
            update_watchdog_marker(agent, None)
        return {**base, "watchdog_state": "active", "action_taken": "none"}

    meta = read_meta(agent)
    marker = watchdog_marker(meta)
    marker_lease_matches = watchdog_marker_lease_matches(
        marker,
        assignment_id=assignment_id,
        session_started_at=status.get("started_at_utc"),
        lease_id=lease.get("lease_id"),
    )
    release_watchdog_lease = (
        marker.get("release_lease_after_action") is True and marker_lease_matches
    )
    marker_is_current = watchdog_marker_matches(
        marker,
        action=action,
        assignment_id=assignment_id,
        session_started_at=status.get("started_at_utc"),
        lease_id=lease.get("lease_id"),
        now=now,
    )
    output_changed = marker_is_current and watchdog_output_changed_since_marker(
        status, marker, now=now
    )
    if marker_is_current and output_changed:
        if not dry_run and not safe_shutdown_only:
            update_watchdog_marker(agent, None)
        marker_is_current = False

    if action != "none" and not marker_is_current:
        if safe_shutdown_only:
            return {
                **base,
                "watchdog_state": "skipped_probe_blocked_without_report",
                "action_taken": "none",
            }
        if dry_run:
            return {
                **base,
                "watchdog_state": "would_request_report",
                "action_taken": "none",
            }
        report_lease_claimed = False
        if not held_by_this_server and lease_state in {"unclaimed", "expired"}:
            claim = claim_agent(agent)
            lease = claim["lease"]
            report_lease_claimed = claim["status"] in {"claimed", "claimed_expired"}
            release_watchdog_lease = report_lease_claimed
            base["lease_state"] = lease.get("state")
            base["held_by_this_server"] = bool(lease.get("held_by_this_server"))
        report: dict[str, Any] | None = None
        try:
            report = request_agent_report(
                agent, assignment_id=assignment_id, lease=lease
            )
            requested_at_utc = _dt.datetime.now(_dt.timezone.utc).isoformat()
            marker_to_write = {
                "phase": "report_requested",
                "requested_at_utc": requested_at_utc,
                "assignment_id": assignment_id,
                "planned_action": action,
                "started_at_utc": status.get("started_at_utc"),
                "raw_log_bytes": status.get("raw_log_bytes"),
                "raw_log_updated_at_utc": status.get("raw_log_updated_at_utc"),
                "idle_seconds": effective_idle,
                "idle_threshold_seconds": idle_seconds,
                "report_grace_seconds": report_grace_seconds,
                "release_lease_after_action": release_watchdog_lease,
            }
            if isinstance(lease.get("lease_id"), str):
                marker_to_write["lease_id"] = lease["lease_id"]
            update_watchdog_marker(agent, marker_to_write)
        except Exception as exc:
            report_sent = (
                isinstance(report, dict)
                and isinstance(report.get("send"), dict)
                and report["send"].get("status") == "sent"
            )
            if (
                report_lease_claimed
                and not report_sent
                and agent_lease_status(agent).get("held_by_this_server")
            ):
                watchdog_release_if_current(
                    agent,
                    force=True,
                    expected_running=True,
                )
            if isinstance(exc, AgentInputNotReadyError):
                report_error = public_error_payload(exc)
                release_after_interrupt = action == "interrupt" and (
                    (manage_unclaimed and unclaimed_or_expired)
                    or release_watchdog_lease
                )
                try:
                    action_result = watchdog_action(
                        agent,
                        action,
                        release_after_interrupt=release_after_interrupt,
                        release_lease_id=lease.get("lease_id")
                        if release_watchdog_lease
                        else None,
                    )
                    update_watchdog_marker(agent, None)
                except Exception:
                    if report_lease_claimed and agent_lease_status(agent).get(
                        "held_by_this_server"
                    ):
                        watchdog_release_if_current(
                            agent,
                            force=True,
                            expected_running=True,
                        )
                    raise
                return {
                    **base,
                    "watchdog_state": "action_sent"
                    if action != "none"
                    else "no_action",
                    "action_taken": action,
                    "report_error": report_error,
                    "action_result": public_watchdog_action_result(action_result),
                }
            raise
        return {
            **base,
            "watchdog_state": "report_requested",
            "action_taken": "report_request",
            "report_request": public_watchdog_report_result(report),
            "next_action_after_seconds": report_grace_seconds,
        }

    if marker_is_current:
        elapsed = age_seconds_from_utc(marker.get("requested_at_utc"), now=now)
        if elapsed is None:
            elapsed = 0
        if elapsed < report_grace_seconds:
            return {
                **base,
                "watchdog_state": "waiting_for_report",
                "action_taken": "none",
                "report_elapsed_seconds": elapsed,
                "next_action_after_seconds": max(0, report_grace_seconds - elapsed),
            }

    if dry_run:
        return {**base, "watchdog_state": f"would_{action}", "action_taken": "none"}
    if safe_shutdown_only:
        if not held_by_this_server:
            return {
                **base,
                "watchdog_state": "skipped_probe_blocked_without_lease",
                "action_taken": "none",
            }
        result = watchdog_action(
            agent,
            action,
            release_after_interrupt=False,
            release_lease_id=None,
        )
        return {
            **base,
            "watchdog_state": "action_sent" if action != "none" else "no_action",
            "action_taken": action,
            "action_result": public_watchdog_action_result(result),
        }
    if (
        action == "none"
        and release_watchdog_lease
        and agent_lease_status(agent).get("held_by_this_server")
    ):
        released = watchdog_release_if_current(
            agent,
            force=True,
            expected_running=True,
        )
        released_lease = released.get("lease") if isinstance(released, dict) else None
        if isinstance(released_lease, dict):
            base["lease_state"] = released_lease.get("state")
            base["held_by_this_server"] = bool(
                released_lease.get("held_by_this_server")
            )
    release_after_interrupt = action == "interrupt" and (
        (manage_unclaimed and unclaimed_or_expired) or release_watchdog_lease
    )
    result = watchdog_action(
        agent,
        action,
        release_after_interrupt=release_after_interrupt,
        release_lease_id=lease.get("lease_id") if release_watchdog_lease else None,
    )
    update_watchdog_marker(agent, None)
    return {
        **base,
        "watchdog_state": "action_sent" if action != "none" else "no_action",
        "action_taken": action,
        "action_result": public_watchdog_action_result(result),
    }


def usage_watchdog_agent(agent: str, *, dry_run: bool) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if dry_run:
        return _usage_watchdog_agent_unlocked(agent, dry_run=True)
    safe_shutdown_only = _fleet_safe_shutdown_only("fleet_watchdog")
    with agent_lifecycle_lock(agent):
        return _usage_watchdog_agent_unlocked(
            agent,
            dry_run=False,
            safe_shutdown_only=safe_shutdown_only,
        )


def _usage_watchdog_agent_unlocked(
    agent: str,
    *,
    dry_run: bool,
    safe_shutdown_only: bool = False,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if not dry_run:
        ensure_state()
    cfg = agent_config(agent)
    session = cfg["session"]
    running = tmux_alive(session)
    lease = agent_lease_status(agent, initialize_state=not dry_run)
    base = {
        "agent": agent,
        "running": running,
        "session": session,
        "lease_state": lease.get("state"),
        "held_by_this_server": bool(lease.get("held_by_this_server")),
        "dry_run": dry_run,
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }
    if running:
        process_summary = agent_home_process_summary(agent)
        identity_guard = agent_identity_guard(
            True,
            process_summary,
            pane_process_id=(
                pane_pid(session) if "managed_process_ids" in process_summary else None
            ),
        )
        if not identity_guard["ok"]:
            base["identity_guard"] = identity_guard
            base["usage_watchdog"] = codex_usage_watchdog_status(agent)
            return {
                **base,
                "usage_watchdog_state": "skipped_identity_unverified",
                "action_taken": "none",
            }
    usage_watchdog = codex_usage_watchdog_status(agent)
    base["usage_watchdog"] = usage_watchdog

    if usage_watchdog.get("blocked"):
        if not running:
            return {
                **base,
                "usage_watchdog_state": "blocked",
                "action_taken": "none",
            }
        if lease.get("state") == "unreadable":
            return {
                **base,
                "usage_watchdog_state": "skipped_lease_unreadable",
                "action_taken": "none",
            }
        if not lease.get("held_by_this_server") and lease.get("state") == "held":
            return {
                **base,
                "usage_watchdog_state": "skipped_not_leased_by_this_server",
                "action_taken": "none",
            }
        if dry_run:
            return {
                **base,
                "usage_watchdog_state": "would_stop",
                "action_taken": "none",
            }
        if safe_shutdown_only and not lease.get("held_by_this_server"):
            return {
                **base,
                "usage_watchdog_state": "skipped_probe_blocked_without_lease",
                "action_taken": "none",
            }
        claimed_for_watchdog = False
        if (
            not safe_shutdown_only
            and not lease.get("held_by_this_server")
            and lease.get("state")
            in {
                "unclaimed",
                "expired",
            }
        ):
            claim = claim_agent(agent)
            lease = claim["lease"]
            claimed_for_watchdog = claim["status"] in {"claimed", "claimed_expired"}
            base["lease_state"] = lease.get("state")
            base["held_by_this_server"] = bool(lease.get("held_by_this_server"))
        try:
            result = stop_agent(agent, force=False)
        except Exception:
            if claimed_for_watchdog:
                current_lease = agent_lease_status(agent)
                claimed_lease_id = lease.get("lease_id")
                current_lease_id = current_lease.get("lease_id")
                lease_is_current = current_lease.get("held_by_this_server") and (
                    (claimed_lease_id is None and current_lease_id is None)
                    or (
                        isinstance(claimed_lease_id, str)
                        and claimed_lease_id == current_lease_id
                    )
                )
                if lease_is_current:
                    watchdog_release_if_current(
                        agent,
                        force=True,
                        expected_running=False,
                    )
            raise
        return {
            **base,
            "usage_watchdog_state": "stopped",
            "action_taken": "stop",
            "action_result": public_watchdog_action_result(result),
        }

    return {**base, "usage_watchdog_state": "clear", "action_taken": "none"}


def fleet_usage_watchdog(
    agent: str = "all", *, dry_run: bool = False
) -> dict[str, Any]:
    safe_shutdown_only = (
        _fleet_safe_shutdown_only("fleet_watchdog") if not dry_run else False
    )
    selected = agent_ids(agent)
    run_agent = (
        (lambda item: usage_watchdog_agent(item, dry_run=True))
        if dry_run
        else lambda item: call_agent_lifecycle(
            item,
            lambda: _usage_watchdog_agent_unlocked(
                item,
                dry_run=False,
                safe_shutdown_only=safe_shutdown_only,
            ),
        )
    )
    results = multi_agent_result(
        selected,
        run_agent,
    )["results"]
    try:
        gemini_usage = current_fleet_service().gemini_usage_watchdog()
    except Exception:
        gemini_usage = {
            "provider": "gemini_api",
            "state": "unknown",
            "accounts": [],
            "stale_or_unknown_accounts": [],
            "raw_output": "not_returned",
        }
    return {
        "agent": agent,
        "dry_run": dry_run,
        "results": results,
        "result_count": len(results),
        "total_count": len(selected),
        "gemini": gemini_usage,
        "raw_output": "not_returned",
    }


def fleet_watchdog(
    agent: str = "all",
    *,
    idle_seconds: int = DEFAULT_WATCHDOG_IDLE_SECONDS,
    poll_interval_seconds: int = DEFAULT_WATCHDOG_POLL_SECONDS,
    action: str = "interrupt",
    report_grace_seconds: int = DEFAULT_WATCHDOG_REPORT_GRACE_SECONDS,
    require_lease: bool = True,
    manage_unclaimed: bool = False,
    dry_run: bool = False,
) -> dict[str, Any]:
    selected = agent_ids(agent)
    idle_seconds = normalize_watchdog_idle_seconds(idle_seconds)
    poll_interval_seconds = normalize_poll_interval_seconds(poll_interval_seconds)
    report_grace_seconds = normalize_watchdog_report_grace_seconds(report_grace_seconds)
    if action not in {"interrupt", "stop", "release", "none"}:
        raise AgentError("watchdog action must be interrupt, stop, release, or none")
    safe_shutdown_only = (
        _fleet_safe_shutdown_only("fleet_watchdog")
        if not dry_run and action != "none"
        else False
    )
    inventory = current_agent_inventory()
    configs = {item: agent_config(item, inventory) for item in selected}
    try:
        snapshot = create_fleet_snapshot(
            agent_homes={
                item: Path(config["home"]) for item, config in configs.items()
            },
            agent_sessions={
                item: str(config["session"]) for item, config in configs.items()
            },
            tmux_runner=run_tmux,
        )
    except Exception:
        snapshot = None
    run_agent = (
        (
            lambda item: _watchdog_agent_unlocked(
                item,
                idle_seconds=idle_seconds,
                action=action,
                report_grace_seconds=report_grace_seconds,
                require_lease=require_lease,
                manage_unclaimed=manage_unclaimed,
                dry_run=True,
                snapshot=snapshot,
            )
        )
        if dry_run
        else (
            lambda item: call_agent_lifecycle(
                item,
                lambda: _watchdog_agent_unlocked(
                    item,
                    idle_seconds=idle_seconds,
                    action=action,
                    report_grace_seconds=report_grace_seconds,
                    require_lease=require_lease,
                    manage_unclaimed=manage_unclaimed,
                    dry_run=False,
                    snapshot=snapshot,
                    safe_shutdown_only=safe_shutdown_only,
                ),
            )
        )
    )
    snapshot_token = _WATCHDOG_SNAPSHOT.set(snapshot)
    try:
        results = multi_agent_result(
            selected,
            run_agent,
        )["results"]
    finally:
        _WATCHDOG_SNAPSHOT.reset(snapshot_token)
    return {
        "status": "ok",
        "agent": agent,
        "idle_seconds": idle_seconds,
        "poll_interval_seconds": poll_interval_seconds,
        "report_grace_seconds": report_grace_seconds,
        "action": action,
        "require_lease": require_lease,
        "manage_unclaimed": manage_unclaimed,
        "dry_run": dry_run,
        "results": results,
        "raw_output": "not_returned",
        "response_output": "not_returned",
    }


def skill_scan_roots(home: Path) -> list[tuple[str, Path]]:
    return [
        ("system", home / "skills"),
        ("plugin_cache", home / "plugins" / "cache"),
        ("tmp_plugin_cache", home / ".tmp" / "plugins"),
    ]


def safe_relative(path: Path, base: Path) -> str:
    try:
        return str(path.relative_to(base))
    except ValueError:
        return str(path)


def parse_skill_path(home: Path, path: Path) -> dict[str, str]:
    rel = path.relative_to(home)
    parts = rel.parts
    info = {"name": path.parent.name, "source": "unknown", "plugin": ""}

    if len(parts) >= 4 and parts[0] == "skills" and parts[1] == ".system":
        return {"name": parts[2], "source": "system", "plugin": ""}

    if len(parts) >= 4 and parts[:2] == ("skills", ".portable"):
        namespace = parts[2]
        if namespace == "plugins" and len(parts) >= 5:
            name = parts[4]
            plugin = f"portable:{parts[3]}"
        else:
            name = parts[3]
            plugin = ""
        return {"name": name, "source": "portable", "plugin": plugin}

    if len(parts) >= 6 and parts[:3] == ("plugins", "cache", "openai-curated"):
        return {
            "name": path.parent.name,
            "source": "plugin_cache",
            "plugin": f"{parts[3]}@openai-curated",
        }

    if len(parts) >= 6 and parts[:3] == (".tmp", "plugins", "plugins"):
        return {
            "name": path.parent.name,
            "source": "tmp_plugin_cache",
            "plugin": f"{parts[3]}@tmp",
        }

    if len(parts) >= 6 and parts[:4] == (".tmp", "plugins", ".agents", "skills"):
        return {"name": parts[4], "source": "tmp_agent_skills", "plugin": "agents@tmp"}

    return info


def list_skill_files(root: Path) -> list[Path]:
    if not is_real_directory_no_symlink(root):
        return []
    return sorted(
        path for path in root.rglob("SKILL.md") if is_regular_file_no_symlink(path)
    )


def paged_mapping(
    items: dict[str, int], offset: int, limit: int
) -> tuple[dict[str, int], bool]:
    offset = normalize_int_field(
        offset, field="offset", minimum=0, maximum=MAX_PAGED_OFFSET
    )
    limit = normalize_int_field(
        limit, field="limit", minimum=0, maximum=MAX_PAGED_OFFSET
    )
    sorted_items = sorted(items.items())
    page = dict(sorted_items[offset : offset + limit])
    return page, offset + limit < len(sorted_items)


def skills_agent(
    agent: str,
    include_names: bool = False,
    limit: int = 80,
    names_offset: int = 0,
    plugins_offset: int = 0,
    plugins_limit: int = MAX_CAPABILITY_PLUGINS,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    cfg = agent_config(agent)
    home = cfg["home"]
    limit = normalize_int_field(
        limit, field="limit", minimum=0, maximum=MAX_SKILL_NAMES
    )
    names_offset = normalize_int_field(
        names_offset, field="names_offset", minimum=0, maximum=MAX_PAGED_OFFSET
    )
    plugins_offset = normalize_int_field(
        plugins_offset,
        field="plugins_offset",
        minimum=0,
        maximum=MAX_PAGED_OFFSET,
    )
    plugins_limit = normalize_int_field(
        plugins_limit,
        field="plugins_limit",
        minimum=0,
        maximum=MAX_SKILL_NAMES,
    )
    home_is_real = is_real_directory_no_symlink(home)

    all_paths: list[Path] = []
    roots: list[dict[str, Any]] = []
    for kind, root in skill_scan_roots(home):
        paths = list_skill_files(root) if home_is_real else []
        roots.append(
            {
                "kind": kind,
                "path": PATH_NOT_RETURNED,
                "path_state": "configured",
                "exists": home_is_real and is_real_directory_no_symlink(root),
                "skill_count": len(paths),
            }
        )
        all_paths.extend(paths)

    by_source: dict[str, int] = {}
    by_plugin: dict[str, int] = {}
    system_skills: list[str] = []
    names: list[dict[str, str]] = []

    unique_paths = sorted(set(all_paths))
    for index, path in enumerate(unique_paths):
        parsed = parse_skill_path(home, path)
        source = parsed["source"]
        by_source[source] = by_source.get(source, 0) + 1
        if parsed["plugin"]:
            by_plugin[parsed["plugin"]] = by_plugin.get(parsed["plugin"], 0) + 1
        if source == "system":
            system_skills.append(parsed["name"])
        if include_names and index >= names_offset and len(names) < limit:
            names.append(
                {
                    "name": parsed["name"],
                    "source": source,
                    "plugin": parsed["plugin"],
                    "path": safe_relative(path, home),
                }
            )

    plugins, plugins_truncated = paged_mapping(by_plugin, plugins_offset, plugins_limit)
    result: dict[str, Any] = {
        "agent": agent,
        "label": cfg["label"],
        "home": PATH_NOT_RETURNED,
        "home_kind": "managed_agent_home",
        "total": len(set(all_paths)),
        "roots": roots,
        "by_source": dict(sorted(by_source.items())),
        "system_skills": sorted(set(system_skills)),
        "plugin_count": len(by_plugin),
        "plugins_offset": plugins_offset,
        "plugins_limit": plugins_limit,
        "plugins": plugins,
        "plugins_truncated": plugins_truncated,
        "skill_file_contents": "not_returned",
        "raw_output": "not_returned",
    }
    if include_names:
        result["names_total"] = len(unique_paths)
        result["names_offset"] = names_offset
        result["names_limit"] = limit
        result["names"] = names
        result["names_truncated"] = names_offset + len(names) < len(unique_paths)
    return result


def bounded_text(
    value: Any,
    *,
    field: str,
    max_chars: int,
    required: bool = False,
    strip: bool = True,
) -> str | None:
    if value is None:
        if required:
            raise AgentError(f"{field} must be a non-empty string")
        return None
    if not isinstance(value, str):
        raise AgentError(f"{field} must be a string")
    text = value.strip() if strip else value
    if required and not text.strip():
        raise AgentError(f"{field} must be a non-empty string")
    if len(text) > max_chars:
        raise AgentError(f"{field} exceeds {max_chars} characters")
    return text


def as_string_list(
    value: Any,
    *,
    field: str,
    max_items: int = MAX_ASSIGNMENT_LIST_ITEMS,
    max_chars: int = MAX_TEXT_FIELD,
) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        text = value.strip()
        if len(text) > max_chars:
            raise AgentError(f"{field} items must not exceed {max_chars} characters")
        return [text] if text else []
    if not isinstance(value, list):
        raise AgentError(f"{field} must be a string or list of strings")
    if len(value) > max_items:
        raise AgentError(f"{field} must contain at most {max_items} items")
    result: list[str] = []
    for item in value:
        if not isinstance(item, str):
            raise AgentError(f"{field} must contain only strings")
        text = item.strip()
        if len(text) > max_chars:
            raise AgentError(f"{field} items must not exceed {max_chars} characters")
        if text:
            result.append(text)
    return result


def skill_matches(agent: str, skill_ref: str, limit: int = 8) -> list[dict[str, str]]:
    agent = canonical_agent_id(agent)
    cfg = agent_config(agent)
    home = cfg["home"]
    wanted = skill_ref.strip().lower()
    matches: list[dict[str, str]] = []
    if not is_real_directory_no_symlink(home):
        return matches

    for _kind, root in skill_scan_roots(home):
        for path in list_skill_files(root):
            parsed = parse_skill_path(home, path)
            name = parsed["name"].lower()
            plugin = parsed["plugin"].lower()
            plugin_base = plugin.split("@", 1)[0] if plugin else ""
            candidates = {name}
            if plugin_base:
                candidates.add(f"{plugin_base}:{name}")
                candidates.add(f"{plugin_base}/{name}")
            if plugin:
                candidates.add(f"{plugin}:{name}")
                candidates.add(f"{plugin}/{name}")
            if wanted in candidates:
                matches.append(
                    {
                        "name": parsed["name"],
                        "source": parsed["source"],
                        "plugin": parsed["plugin"],
                        "path": safe_relative(path, home),
                    }
                )
                if len(matches) >= limit:
                    return matches
    return matches


def skill_match_agent(agent: str, skill_ref: Any, limit: int = 8) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    skill_ref = (
        bounded_text(skill_ref, field="skill", max_chars=MAX_SKILL_REF, required=True)
        or ""
    )
    limit = normalize_int_field(
        limit, field="limit", minimum=1, maximum=MAX_SKILL_NAMES
    )
    matches = skill_matches(agent, skill_ref, limit)
    skill_safe, _changed = redact(skill_ref)
    return {
        "agent": agent,
        "skill": trim_chars(skill_safe, 300),
        "available": bool(matches),
        "match_count": len(matches),
        "matches": matches,
        "skill_file_contents": "not_returned",
        "raw_output": "not_returned",
    }


def capabilities_agent(agent: str) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    inventory = skills_agent(agent, include_names=False)
    return {
        "agent": agent,
        "label": agent_config(agent)["label"],
        "home": PATH_NOT_RETURNED,
        "home_kind": "managed_agent_home",
        "models": {
            "default": DEFAULT_AGENT_MODEL,
            "read_only": DEFAULT_AGENT_MODEL,
            "write": WRITE_AGENT_MODEL,
            "default_reasoning_effort": DEFAULT_AGENT_MODEL_EFFORT,
            "write_reasoning_effort": WRITE_AGENT_MODEL_EFFORT,
        },
        "skill_count": inventory["total"],
        "system_skills": inventory["system_skills"],
        "plugin_count": inventory["plugin_count"],
        "plugin_page_count": len(inventory["plugins"]),
        "plugins_offset": inventory["plugins_offset"],
        "plugins_limit": inventory["plugins_limit"],
        "plugins": inventory["plugins"],
        "plugins_truncated": inventory["plugins_truncated"],
        "master_mcp_tools": "not_configured_for_agent",
        "native_subagents": "assignment_gated",
        "write_policy": "explicit_paths_only",
        "raw_output": "not_returned",
    }


def normalize_scope_path(item: str, cwd: Path) -> Path | None:
    text = item.strip()
    if not text or "://" in text:
        return None
    path = Path(text).expanduser()
    if not path.is_absolute():
        path = cwd / path
    return path.resolve(strict=False)


def path_is_within(path: Path, scope: Path) -> bool:
    try:
        path.relative_to(scope)
        return True
    except ValueError:
        return False


def scope_check(
    scope: list[str], write_paths: list[str], cwd: Any = None
) -> dict[str, Any]:
    if isinstance(cwd, os.PathLike):
        cwd = os.fspath(cwd)
    cwd = (
        bounded_text(cwd, field="cwd", max_chars=MAX_PATH_TEXT)
        if cwd is not None
        else None
    )
    base = Path(cwd or os.getcwd()).expanduser().resolve(strict=False)
    cwd_valid = base.is_dir()
    scope_paths = (
        [
            path
            for item in scope
            if (path := normalize_scope_path(item, base)) is not None
        ]
        if cwd_valid
        else []
    )
    violations: list[str] = []

    if write_paths and (not cwd_valid or not scope_paths):
        violations = redact_list(write_paths)
    else:
        for original in write_paths:
            write_path = normalize_scope_path(original, base)
            if write_path is None or not any(
                path_is_within(write_path, scope_path) for scope_path in scope_paths
            ):
                violations.append(redact_list([original])[0])

    return {
        "cwd": PATH_NOT_RETURNED,
        "cwd_state": "set" if cwd_valid else "invalid",
        "allowed": not violations,
        "scope": redact_list(scope),
        "write_paths": redact_list(write_paths),
        "violations": violations,
        "raw_output": "not_returned",
    }


def bullet_block(items: list[str], fallback: str = "-") -> str:
    if not items:
        return fallback
    return "\n".join(f"- {item}" for item in items)


def assignment_prompt(
    *,
    agent: str,
    role: str,
    task: str,
    scope: list[str],
    skill: str | None,
    write_paths: list[str],
    context: list[str],
    forbidden: list[str],
    name: str | None,
    model: str,
    allow_subagents: bool,
    subagent_admission: dict[str, Any] | None,
    requires_search: bool = False,
    live_data_topic: str | None = None,
    required_skills: list[str] | None = None,
    agent_class: str | None = None,
) -> str:
    display_name = (name or default_agentin_name(agent)).strip()
    required = list(required_skills or [])
    if skill and skill not in required:
        required.insert(0, skill.strip())
    skill_line = ", ".join(required) if required else "kein spezieller Skill vorgegeben"
    legacy_skill_line = f"Skill: {skill}" if skill else "Skill: keiner"
    search_lines: list[str] = []
    if requires_search:
        topic = live_data_topic.strip() if live_data_topic else task
        search_lines = [
            "Live-/Webdatenauftrag: ja",
            f"Aktualitaetsfrage: {topic}",
            "Muss Websuche/aktuelle Quellen nutzen, bevor eine sachliche Antwort gegeben wird.",
            "Muss Quellen und Zeitbezug knapp nennen, soweit verfuegbar.",
            "Wenn aktuelle Daten nicht verfuegbar sind, nicht raten; als Tooling-/Zugriffslimit berichten.",
        ]
    search_block = bullet_block(search_lines)
    subagents_permitted = bool(
        allow_subagents
        and isinstance(subagent_admission, dict)
        and subagent_admission.get("allowed") is True
    )
    subagent_reason_codes = (
        [
            reason
            for reason in subagent_admission.get("reason_codes", [])
            if isinstance(reason, str) and reason in RESOURCE_REASON_CODES
        ]
        if isinstance(subagent_admission, dict)
        and isinstance(subagent_admission.get("reason_codes"), list)
        else []
    )
    subagent_permission = "Darf eigene Subagentinnen starten: nein"
    if subagents_permitted:
        scope_limit = (
            "nur lesend im Scope"
            if role == "exploriererin"
            else "nur innerhalb Scope und Schreibpfaden"
        )
        subagent_permission = f"Darf eigene Subagentinnen starten: ja, {scope_limit}"
    subagent_lines = [subagent_permission]
    if subagents_permitted:
        subagent_lines.extend(
            [
                "Vor jedem Spawn frische gemeinsame Ressourcen-Admission pruefen; Druck-, Scope- und Capability-Gates bleiben fail-closed.",
                "Es gibt keine numerische Flotten-, Serien- oder Provider-Spawn-Grenze.",
            ]
        )
    elif allow_subagents and subagent_reason_codes:
        subagent_lines.append(f"Ressourcenfreigabe: {', '.join(subagent_reason_codes)}")

    if role == "exploriererin":
        lines = [
            "[EXPLORER_BEE_TASK]",
            f"Name: {display_name}",
            "Rolle: Exploriererin",
            f"Modell: {model}",
            legacy_skill_line,
            f"Mindestskills: {skill_line}",
            f"Scope:\n{bullet_block(scope)}",
            "Darf schreiben: nein",
            *subagent_lines,
            f"Web-/Live-Daten:\n{search_block}",
            f"Stabiler Kontext:\n{bullet_block(context)}",
            f"Aufgabe: {task}",
            f"Blacklist / Grenzen:\n{bullet_block(forbidden)}",
            "Rueckgabe: knappe Fakten, relevante Dateien/Zeilen, Empfehlung",
        ]
    else:
        lines = [
            "[WORK_BEE_TASK]",
            f"Name: {display_name}",
            "Rolle: Arbeitsbiene",
            f"Modell: {model}",
            legacy_skill_line,
            f"Mindestskills: {skill_line}",
            f"Scope:\n{bullet_block(scope)}",
            f"Darf schreiben: ja, nur:\n{bullet_block(write_paths)}",
            *subagent_lines,
            f"Web-/Live-Daten:\n{search_block}",
            f"Stabiler Kontext:\n{bullet_block(context)}",
            f"Aktuelle Aufgabe: {task}",
            f"Blacklist / Grenzen:\n{bullet_block(forbidden)}",
            "Rueckgabe: Root Cause, Aenderung, Tests, offene Risiken",
        ]
    return apply_agent_introduction_policy(
        "\n".join(lines),
        agent_class=agent_class,
        name=name,
    )


def ensure_assignment_session_model(
    agent: str,
    *,
    model: str,
    reasoning_effort: str | None,
    lease: dict[str, Any],
    release_lease_on_failure: bool = False,
    agent_class: str | None = None,
    name: str | None = None,
    lease_acquisition: list[bool] | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    cfg = agent_config(agent)
    if not tmux_alive(cfg["session"]):
        raise AgentError(f"agent {agent} is not running")
    require_managed_tmux_session(agent)
    ollama_descriptor = _ollama_descriptor(agent)
    meta = read_meta(agent)
    current_model = meta.get("model") or (
        ollama_descriptor.model
        if ollama_descriptor is not None
        else DEFAULT_AGENT_MODEL
    )
    current_reasoning_effort = meta.get("model_reasoning_effort") or (
        None
        if ollama_descriptor is not None
        else WRITE_AGENT_MODEL_EFFORT
        if current_model == WRITE_AGENT_MODEL
        else DEFAULT_AGENT_MODEL_EFFORT
    )
    current_agent_class = meta.get("agent_class")
    if (
        current_model == model
        and current_reasoning_effort == reasoning_effort
        and (
            agent_class is None
            or current_agent_class is None
            or current_agent_class == agent_class
        )
    ):
        return {
            "status": "unchanged",
            "previous_model": current_model,
            "model": model,
            "raw_output": "not_returned",
        }
    return _restart_assignment_session_after_capacity_probe(
        agent,
        cfg=cfg,
        model=model,
        reasoning_effort=reasoning_effort,
        lease=lease,
        release_lease_on_failure=release_lease_on_failure,
        agent_class=agent_class,
        name=name,
        previous_model=current_model,
        cwd=meta.get("cwd"),
        lease_acquisition=lease_acquisition,
    )


def _restart_assignment_session_after_capacity_probe(
    agent: str,
    *,
    cfg: Mapping[str, Any],
    model: str,
    reasoning_effort: str | None,
    lease: dict[str, Any],
    release_lease_on_failure: bool,
    agent_class: str | None,
    name: str | None,
    previous_model: str,
    cwd: Any,
    lease_acquisition: list[bool] | None,
) -> dict[str, Any]:
    """Perform the restart-only assignment branch under the capacity guard."""

    with hive_capacity_probe_guard("agent_assign"):
        return _restart_assignment_session_after_capacity_probe_unlocked(
            agent,
            cfg=cfg,
            model=model,
            reasoning_effort=reasoning_effort,
            lease=lease,
            release_lease_on_failure=release_lease_on_failure,
            agent_class=agent_class,
            name=name,
            previous_model=previous_model,
            cwd=cwd,
            lease_acquisition=lease_acquisition,
        )


def _restart_assignment_session_after_capacity_probe_unlocked(
    agent: str,
    *,
    cfg: Mapping[str, Any],
    model: str,
    reasoning_effort: str | None,
    lease: dict[str, Any],
    release_lease_on_failure: bool,
    agent_class: str | None,
    name: str | None,
    previous_model: str,
    cwd: Any,
    lease_acquisition: list[bool] | None,
) -> dict[str, Any]:
    claimed_for_restart = False
    if lease.get("state") != "held" or lease.get("held_by_this_server") is not True:
        claim, claimed = claim_for_agent_mutation(agent)
        lease.clear()
        lease.update(claim)
        claimed_for_restart = claimed
        if lease_acquisition is not None:
            lease_acquisition.append(claimed)
        release_lease_on_failure = claimed
    try:
        return _restart_assignment_session_with_lease_unlocked(
            agent,
            cfg=cfg,
            model=model,
            reasoning_effort=reasoning_effort,
            lease=lease,
            release_lease_on_failure=release_lease_on_failure,
            agent_class=agent_class,
            name=name,
            previous_model=previous_model,
            cwd=cwd,
        )
    except Exception:
        if claimed_for_restart:
            with contextlib.suppress(Exception):
                release_start_lease_if_safe(agent, lease, True)
        raise


def _restart_assignment_session_with_lease_unlocked(
    agent: str,
    *,
    cfg: Mapping[str, Any],
    model: str,
    reasoning_effort: str | None,
    lease: dict[str, Any],
    release_lease_on_failure: bool,
    agent_class: str | None,
    name: str | None,
    previous_model: str,
    cwd: Any,
) -> dict[str, Any]:
    status = status_agent(agent)
    response_state = (status.get("response_state") or {}).get("state")
    if response_state not in {"running_tui_starter_context", "running_idle"}:
        raise AgentError(
            "routed model or class differs from active session; controlled restart requires "
            f"an inactive Agentin; current_state={response_state}"
        )
    with spawn_admission_lock():
        replacement = reserve_managed_replacement(cfg["session"])
        if replacement.get("allowed") is not True:
            _raise_replacement_capacity_denied(replacement)
        replacement_id = replacement["reservation_id"]
        cp = run_tmux(
            _tmux_args_for_session(
                cfg["session"], ["kill-session", "-t", cfg["session"]]
            ),
            check=False,
        )
        if cp.returncode != 0:
            raise AgentError(f"tmux model-switch stop failed for agent {agent}")
        name_args = {"name": name} if name is not None else {}
        restarted = start_agent(
            agent,
            cwd=cwd,
            lease=lease,
            release_lease_on_failure=release_lease_on_failure,
            model=model,
            model_reasoning_effort=reasoning_effort,
            agent_class=agent_class,
            replacement_reservation_id=replacement_id,
            **name_args,
        )
        complete_managed_replacement(
            reservation_id=replacement_id, managed_session=cfg["session"]
        )
    return {
        "status": "restarted",
        "previous_model": previous_model,
        "model": model,
        "start_status": restarted.get("status"),
        "raw_output": "not_returned",
    }


def assign_agent(agent: str, **kwargs: Any) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    if _headless_descriptor(agent) is not None:
        require_resource_capacity_preflight(operation="agent_assign")
        require_fleet_recovery_ready("agent_assign")
        return _assign_headless_agent(agent, **kwargs)
    with agent_lifecycle_lock(agent):
        return _call_with_resource_gate_composer(
            lambda: _assign_agent_unlocked(agent, **kwargs)
        )


def _assign_agent_unlocked(
    agent: str,
    *,
    role: str,
    task: Any,
    scope: Any,
    skill: str | None = None,
    write_paths: Any = None,
    context: Any = None,
    forbidden: Any = None,
    name: str | None = None,
    group_id: str | None = None,
    job_id: str | None = None,
    enter: bool = True,
    allow_missing_skill: bool = False,
    allow_subagents: bool = False,
    allow_unauthenticated: bool = False,
    requires_search: bool = False,
    live_data_topic: str | None = None,
    operation: str = "agent_assign",
    lease: dict[str, Any] | None = None,
    required_skills: Any = None,
    agent_class: str | None = None,
    lifecycle: str | None = None,
    requested_model: str | None = None,
    requested_reasoning: str | None = None,
    complexity: str = "unknown",
    task_phase: str = "unknown",
    fully_specified: bool = False,
    reversible: bool = False,
    low_risk: bool = False,
    root_cause_known: bool = False,
    security_sensitive: bool = False,
    concurrency: bool = False,
    migration: bool = False,
    data_change: bool = False,
    cross_repository: bool = False,
    architecture: bool = False,
    ci_or_release: bool = False,
    authority_class: str | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    ollama_descriptor = _ollama_descriptor(agent)
    admission: dict[str, Any] | None = None
    if ollama_descriptor is not None:
        auth_gate = {
            "authenticated": True,
            "provider": Provider.OLLAMA_LOCAL.value,
            "state": "not_applicable",
            "raw_output": "not_returned",
        }
    else:
        auth_gate = require_authenticated_agent_for_mutation(
            agent,
            operation=operation,
            allow_unauthenticated=allow_unauthenticated,
        )
    role = role.strip().lower()
    if role not in {"exploriererin", "arbeitsbiene"}:
        raise AgentError("role must be 'exploriererin' or 'arbeitsbiene'")
    task = (
        bounded_text(task, field="task", max_chars=MAX_TASK_TEXT, required=True) or ""
    )
    skill = (
        bounded_text(skill, field="skill", max_chars=MAX_SKILL_REF)
        if skill is not None
        else None
    )
    required_skills = as_string_list(
        required_skills, field="required_skills", max_chars=MAX_SKILL_REF
    )
    if skill and skill not in required_skills:
        required_skills.insert(0, skill)
    name = (
        bounded_text(name, field="name", max_chars=MAX_AGENTIN_NAME)
        if name is not None
        else None
    )
    group_id = normalize_routing_context_id(group_id, field="group_id")
    job_id = normalize_routing_context_id(job_id, field="job_id")
    scope = as_string_list(scope, field="scope", max_chars=MAX_PATH_TEXT)
    write_paths = as_string_list(
        write_paths, field="write_paths", max_chars=MAX_PATH_TEXT
    )
    context = as_string_list(context, field="context")
    forbidden = as_string_list(forbidden, field="forbidden")
    live_data_topic = (
        bounded_text(
            live_data_topic, field="live_data_topic", max_chars=MAX_LIVE_DATA_TOPIC
        )
        if live_data_topic is not None
        else None
    )
    if ollama_descriptor is not None and (requires_search or allow_subagents):
        raise AgentError("ollama_simple_task_only")
    if role == "exploriererin" and write_paths:
        raise AgentError("exploriererin assignments must not include write paths")
    if role == "arbeitsbiene" and not write_paths:
        raise AgentError(
            "arbeitsbiene assignments require at least one explicit write path"
        )
    if ollama_descriptor is not None:
        admission = spawn_admission_decision(agent=agent, task=task, role=role)
        if admission.get("allowed") is not True:
            _raise_ollama_admission_denied(admission)
    scope_result = scope_check(scope, write_paths)
    if role == "arbeitsbiene" and not scope_result["allowed"]:
        raise AgentError("write paths must stay inside scope")
    complexity_override = _complexity_override(complexity)
    task_profile = classify_runtime_task(
        TaskClassificationRequest(
            objective=task,
            scope_kind="read" if role == "exploriererin" else "write",
            changed_files=tuple(write_paths),
            requires_subagents=allow_subagents,
            complexity_override=complexity_override,
            task_phase=task_phase,
            fully_specified=fully_specified,
            reversible=reversible,
            low_risk=low_risk,
            root_cause_known=root_cause_known,
            security_sensitive=security_sensitive,
            concurrency=concurrency,
            migration=migration,
            data_change=data_change,
            cross_repository=cross_repository,
            architecture=architecture,
            ci_or_release=ci_or_release,
        )
    )

    matches: list[dict[str, str]] = []
    if skill:
        matches = skill_matches(agent, skill)
    missing_skills = [
        item for item in required_skills if not skill_matches(agent, item)
    ]
    if missing_skills and not allow_missing_skill:
        raise AgentError(f"skill not found for agent {agent}")

    selection: ResolutionDecision | None = None
    if ollama_descriptor is not None:
        model = ollama_descriptor.model
        reasoning_effort = None
    else:
        ensure_agent_not_blocked_by_codex_usage(agent)
        requested_target_class, resolver_authority = _resolver_target_selection_inputs(
            agent,
            agent_class,
            authority_class,
        )
        selection = resolve_runtime_agent_selection(
            role=role,
            routing=None,
            task_profile=task_profile,
            requested_class=requested_target_class,
            requested_lifecycle=lifecycle,
            requested_model=requested_model,
            requested_reasoning=requested_reasoning,
            authority_class=resolver_authority,
        )
        model = selection.model
        reasoning_effort = selection.reasoning
        if agent_class is None and authority_class == "teamleiterin":
            descriptor = current_agent_inventory().agents.get(agent)
            active_meta = read_meta(agent)
            if (
                getattr(descriptor, "skill_profile", None) == "teamleiterin"
                and active_meta.get("model") == "gpt-5.6-terra"
                and active_meta.get("model_reasoning_effort") == "xhigh"
            ):
                model = "gpt-5.6-terra"
                reasoning_effort = "xhigh"
    subagent_admission = (
        admission
        if allow_subagents and admission is not None
        else spawn_admission_decision(1)
        if allow_subagents
        else None
    )
    subagents_permitted = bool(
        allow_subagents
        and isinstance(subagent_admission, dict)
        and subagent_admission.get("allowed") is True
    )
    subagent_reason_codes = (
        [
            reason
            for reason in subagent_admission.get("reason_codes", [])
            if isinstance(reason, str) and reason in RESOURCE_REASON_CODES
        ]
        if isinstance(subagent_admission, dict)
        and isinstance(subagent_admission.get("reason_codes"), list)
        else []
    )
    prompt = assignment_prompt(
        agent=agent,
        role=role,
        task=task,
        scope=scope,
        skill=skill,
        write_paths=write_paths,
        context=context,
        forbidden=forbidden,
        name=name,
        model=model,
        allow_subagents=allow_subagents,
        subagent_admission=subagent_admission,
        requires_search=requires_search,
        live_data_topic=live_data_topic,
        required_skills=required_skills,
        agent_class=(
            selection.class_id
            if selection is not None
            else resolver_class_for_agent(
                agent,
                agent_class,
                authority_class=authority_class,
            )
        ),
    )
    if len(prompt) > MAX_ASSIGNMENT_TEXT:
        raise AgentError(f"assignment prompt exceeds {MAX_ASSIGNMENT_TEXT} characters")

    release_on_failure = False
    lease_acquisition: list[bool] = []
    if lease is None:
        lease = agent_lease_status(agent)
    model_switch: dict[str, Any] | None = None
    sent: dict[str, Any] | None = None
    try:
        name_args = {"name": name} if name is not None else {}
        if admission is None:
            model_switch = ensure_assignment_session_model(
                agent,
                model=model,
                reasoning_effort=reasoning_effort,
                lease=lease,
                release_lease_on_failure=release_on_failure,
                agent_class=agent_class,
                lease_acquisition=lease_acquisition,
                **name_args,
            )
        else:
            with _resource_admission_scope(admission):
                model_switch = ensure_assignment_session_model(
                    agent,
                    model=model,
                    reasoning_effort=reasoning_effort,
                    lease=lease,
                    release_lease_on_failure=release_on_failure,
                    agent_class=agent_class,
                    lease_acquisition=lease_acquisition,
                    **name_args,
                )
        release_on_failure = any(lease_acquisition)
        sent = send_agent(agent, prompt, enter, operation=operation)
    except Exception:
        release_on_failure = release_on_failure or any(lease_acquisition)
        if release_on_failure and not (
            isinstance(sent, dict) and sent.get("status") == "sent"
        ):
            release_start_lease_if_safe(agent, lease, True)
        raise
    assignment_id = f"{now_id()}-{agent}"
    assignment_record = {
        "assignment_id": assignment_id,
        "created_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "agent": agent,
        "role": role,
        "name": name or default_agentin_name(agent),
        "model": model,
        "model_reasoning_effort": reasoning_effort,
        "model_switch": model_switch,
        "selection": public_resolution_decision(selection),
        "task_profile": public_task_profile(task_profile),
        "group_id": group_id,
        "job_id": job_id,
        "skill": {
            "requested": skill,
            "available": bool(matches) if skill else None,
            "match_count": len(matches),
        },
        "scope": redact_list(scope),
        "write_paths": redact_list(write_paths),
        "context_count": len(context),
        "forbidden_count": len(forbidden),
        "write_policy": "read_only"
        if role == "exploriererin"
        else "explicit_paths_only",
        "allow_subagents": subagents_permitted,
        "subagents": {
            "requested": allow_subagents,
            "permitted": subagents_permitted,
            "policy": "resource_and_assignment_gated",
            "reason_codes": subagent_reason_codes,
        },
        "requires_search": requires_search,
        "live_data": {
            "required": requires_search,
            "topic_state": "set" if live_data_topic else "task",
            "raw_output": "not_returned",
        },
        "lease": {
            "state": lease.get("state"),
            "holder": lease.get("holder"),
            "held_by_this_server": lease.get("held_by_this_server"),
            "expires_at_utc": lease.get("expires_at_utc"),
            "raw_output": "not_returned",
        },
        "submitted": enter,
        "prompt_chars": len(prompt),
        "prompt_output": "not_returned",
        "response_output": "not_returned",
    }
    try:
        record_assignment(assignment_record)
    except Exception:
        if release_on_failure and not (
            isinstance(sent, dict) and sent.get("status") == "sent"
        ):
            release_start_lease_if_safe(agent, lease, True)
        raise
    return {
        "assignment_id": assignment_id,
        "agent": agent,
        "status": "assigned",
        "role": role,
        "name": name or default_agentin_name(agent),
        "model": model,
        "model_reasoning_effort": reasoning_effort,
        "model_switch": model_switch,
        "selection": public_resolution_decision(selection),
        "task_profile": public_task_profile(task_profile),
        "group_id": group_id,
        "job_id": job_id,
        "skill": {
            "requested": skill,
            "available": bool(matches) if skill else None,
            "matches": matches[:5],
        },
        "scope_count": len(scope),
        "write_policy": "read_only"
        if role == "exploriererin"
        else "explicit_paths_only",
        "write_path_count": len(write_paths),
        "subagents_allowed": subagents_permitted,
        "requires_search": requires_search,
        "live_data": {
            "required": requires_search,
            "topic_state": "set" if live_data_topic else "task",
            "raw_output": "not_returned",
        },
        "auth_gate": auth_gate,
        "lease": lease,
        "prompt_chars": len(prompt),
        "result_tool": "agent_assignment_report",
        "prompt_output": "not_returned",
        "response_output": "not_returned",
        "send": sent,
    }


def redact_list(items: list[str], max_items: int = 50) -> list[str]:
    safe_items = []
    for item in items[:max_items]:
        redacted, _changed = redact(item)
        safe_items.append(trim_chars(redacted, 300))
    return safe_items


_RESOLUTION_SELECTION_REASON_CODES = frozenset(
    {
        "class_auto_selected",
        "default_model_unavailable",
        "lifecycle_alias_normalized",
        "lifecycle_defaulted",
        "model_defaulted",
        "requested_class_unavailable",
        "requested_lifecycle_outside_class",
        "requested_model_below_task_minimum",
        "requested_model_capability_mismatch",
        "requested_model_outside_class",
        "requested_model_unavailable",
        "requested_model_unknown",
        "requested_reasoning_outside_limits",
        "requested_reasoning_unsupported",
        "reasoning_defaulted",
        "spark_model_capability_mismatch",
    }
)


def _sanitize_assignment_selection(value: Any) -> dict[str, Any] | None:
    schema_version = value.get("schema_version") if isinstance(value, dict) else None
    if (
        not isinstance(schema_version, int)
        or isinstance(schema_version, bool)
        or schema_version != 1
    ):
        return None

    try:
        class_catalog = load_agent_class_catalog(
            repo_root() / "codex-agent-classes.json"
        )
        classes, models = policies_from_catalogs(
            class_catalog,
            load_model_policy(repo_root() / "codex-model-policy.json"),
        )
    except Exception:
        return None

    classes_by_id = {item.class_id: item for item in classes}
    models_by_id = {item.model_id: item for item in models}
    effective_values = {
        key: value.get(key) for key in ("class", "lifecycle", "model", "reasoning")
    }
    if any(not isinstance(item, str) for item in effective_values.values()):
        return None

    class_policy = classes_by_id.get(effective_values["class"])
    model_policy = models_by_id.get(effective_values["model"])
    if class_policy is None or model_policy is None:
        return None
    scope_kind = "write" if "write" in class_policy.supported_scopes else "read"
    try:
        decision = resolve_agent_selection(
            ResolutionRequest(
                scope_kind=scope_kind,
                complexity="simple" if model_policy.family == "spark" else "complex",
                requested_class=effective_values["class"],
                requested_lifecycle=effective_values["lifecycle"],
                requested_model=effective_values["model"],
                requested_reasoning=effective_values["reasoning"],
                spark_eligible=model_policy.family == "spark",
            ),
            classes=classes,
            models=models,
            available_models={item.model_id for item in models},
        )
    except Exception:
        return None
    if (
        decision.class_id != effective_values["class"]
        or decision.lifecycle != effective_values["lifecycle"]
        or decision.model != effective_values["model"]
        or decision.reasoning != effective_values["reasoning"]
    ):
        return None

    sanitized: dict[str, Any] = {
        "schema_version": 1,
        "class": decision.class_id,
        "lifecycle": decision.lifecycle,
        "model": decision.model,
        "reasoning": decision.reasoning,
    }

    requested = value.get("requested")
    if isinstance(requested, dict):
        requested_safe: dict[str, Any] = {}
        requested_class = requested.get("class")
        if requested_class is None:
            requested_safe["class"] = None
        elif isinstance(requested_class, str) and requested_class in classes_by_id:
            requested_safe["class"] = requested_class

        requested_lifecycle = requested.get("lifecycle")
        if requested_lifecycle is None:
            requested_safe["lifecycle"] = None
        elif isinstance(requested_lifecycle, str) and (
            requested_lifecycle in LIFECYCLE_RANK
            or requested_lifecycle in LIFECYCLE_ALIASES
        ):
            requested_safe["lifecycle"] = requested_lifecycle

        requested_model = requested.get("model")
        if requested_model is None:
            requested_safe["model"] = None
        elif isinstance(requested_model, str) and requested_model in models_by_id:
            requested_safe["model"] = requested_model

        requested_reasoning = requested.get("reasoning")
        if requested_reasoning is None:
            requested_safe["reasoning"] = None
        elif (
            isinstance(requested_reasoning, str)
            and requested_reasoning in REASONING_RANK
        ):
            requested_model_policy = (
                models_by_id.get(requested_model)
                if isinstance(requested_model, str)
                else None
            ) or model_policy
            if requested_reasoning in requested_model_policy.reasoning_levels:
                requested_safe["reasoning"] = requested_reasoning

        if requested_safe:
            sanitized["requested"] = requested_safe

    fallback = value.get("fallback")
    if isinstance(fallback, bool):
        sanitized["fallback"] = fallback

    reason_codes = value.get("reason_codes")
    if isinstance(reason_codes, list):
        sanitized["reason_codes"] = list(
            dict.fromkeys(
                code
                for code in reason_codes
                if isinstance(code, str) and code in _RESOLUTION_SELECTION_REASON_CODES
            )
        )[:32]

    sanitized["raw_output"] = "not_returned"
    return sanitized


def sanitize_assignment_record(record: dict[str, Any]) -> dict[str, Any]:
    sanitized = {
        key: record[key]
        for key in (
            "assignment_id",
            "created_at_utc",
            "agent",
            "role",
            "name",
            "model",
            "model_reasoning_effort",
            "model_switch",
            "routing",
            "selection",
            "task_profile",
            "group_id",
            "job_id",
            "skill",
            "scope",
            "write_paths",
            "context_count",
            "forbidden_count",
            "write_policy",
            "allow_subagents",
            "subagents",
            "requires_search",
            "live_data",
            "lease",
            "submitted",
            "prompt_chars",
            "prompt_output",
            "response_output",
        )
        if key in record
    }
    for key in ("scope", "write_paths"):
        values = sanitized.get(key)
        if isinstance(values, list):
            sanitized[key] = redact_list(
                [item for item in values if isinstance(item, str)],
                max_items=MAX_ASSIGNMENT_LIST_ITEMS,
            )
    for key, allowed_keys in {
        "model_switch": ("status", "previous_model", "model", "raw_output"),
        "routing": (
            "schema_version",
            "account",
            "backend_account_id",
            "role",
            "decision",
            "model",
            "reason",
            "usage_state",
            "paid_overage_allowed",
            "policy_source",
            "raw_output",
        ),
        "skill": ("requested", "available", "match_count"),
        "subagents": ("requested", "permitted", "policy", "reason_codes"),
        "live_data": ("required", "topic_state", "raw_output"),
        "lease": (
            "state",
            "holder",
            "held_by_this_server",
            "expires_at_utc",
            "lease_id",
            "raw_output",
        ),
    }.items():
        value = sanitized.get(key)
        if not isinstance(value, dict):
            sanitized.pop(key, None)
            continue
        safe_value = {}
        for nested_key in allowed_keys:
            if nested_key not in value:
                continue
            nested_value = value[nested_key]
            if nested_key == "raw_output":
                safe_value[nested_key] = "not_returned"
            elif isinstance(nested_value, str):
                safe_value[nested_key] = redact(nested_value)[0]
            elif nested_key == "reason_codes" and isinstance(nested_value, list):
                safe_value[nested_key] = [
                    reason
                    for reason in nested_value
                    if isinstance(reason, str) and reason in RESOURCE_REASON_CODES
                ]
            elif nested_value is None or isinstance(nested_value, (bool, int)):
                safe_value[nested_key] = nested_value
        sanitized[key] = safe_value
    selection = _sanitize_assignment_selection(sanitized.get("selection"))
    if selection is None:
        sanitized.pop("selection", None)
    else:
        sanitized["selection"] = selection
    profile = sanitized.get("task_profile")
    if isinstance(profile, dict):
        reason_codes = profile.get("reason_codes")
        required_capabilities = profile.get("required_capabilities")
        sanitized["task_profile"] = {
            "schema_version": profile.get("schema_version")
            if isinstance(profile.get("schema_version"), int)
            else 1,
            "complexity": profile.get("complexity")
            if isinstance(profile.get("complexity"), str)
            else "unknown",
            "spark_eligible": profile.get("spark_eligible")
            if isinstance(profile.get("spark_eligible"), bool)
            else False,
            "reason_codes": [item for item in reason_codes if isinstance(item, str)][
                :32
            ]
            if isinstance(reason_codes, list)
            else [],
            "required_capabilities": [
                item for item in required_capabilities if isinstance(item, str)
            ][:32]
            if isinstance(required_capabilities, list)
            else [],
            "raw_output": "not_returned",
        }
    else:
        sanitized.pop("task_profile", None)
    sanitized["prompt_output"] = "not_returned"
    sanitized["response_output"] = "not_returned"
    return sanitized


def record_assignment(record: dict[str, Any]) -> None:
    ensure_state()
    with assignment_log_lock():
        _prune_assignment_log(pending_record=record)


def prune_assignment_log(max_records: int | None = None) -> None:
    with assignment_log_lock():
        _prune_assignment_log(max_records)


def _prune_assignment_log(
    max_records: int | None = None,
    *,
    pending_record: dict[str, Any] | None = None,
) -> None:
    default_max_records = MAX_ASSIGNMENT_LOG_RECORDS
    max_records = normalize_int_field(
        max_records if max_records is not None else default_max_records,
        field="max_records",
        minimum=1,
        maximum=default_max_records,
    )
    assignment_log_present = path_present_no_follow(ASSIGNMENT_LOG)
    if not assignment_log_present and pending_record is None:
        return
    if assignment_log_present:
        try:
            current_stat = ASSIGNMENT_LOG.lstat()
        except OSError as exc:
            raise AgentError("could_not_read_assignment_log") from exc
        if (
            not stat_module.S_ISREG(current_stat.st_mode)
            or getattr(current_stat, "st_nlink", 1) > 1
        ):
            with open_private_regular_update(ASSIGNMENT_LOG):
                pass
    lines = (
        read_private_regular_text(
            ASSIGNMENT_LOG,
            MAX_ASSIGNMENT_LOG_BYTES,
            "could_not_read_assignment_log",
        ).splitlines()
        if assignment_log_present
        else []
    )

    valid_records: list[str] = []
    for line in lines:
        if not line.strip():
            continue
        try:
            parsed = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            valid_records.append(json.dumps(parsed, sort_keys=True))

    if pending_record is not None:
        valid_records.append(json.dumps(pending_record, sort_keys=True))
    kept = valid_records[-max_records:]
    while kept:
        text = "\n".join(kept) + "\n"
        if len(text.encode("utf-8")) <= MAX_ASSIGNMENT_LOG_BYTES:
            break
        if len(kept) == 1:
            raise AgentError("assignment record exceeds log size limit")
        kept.pop(0)
    text = "\n".join(kept) + ("\n" if kept else "")
    replace_private_text(ASSIGNMENT_LOG, text)


def list_assignments(
    agent: str = "all",
    limit: int = 20,
    *,
    initialize_state: bool = True,
) -> dict[str, Any]:
    if initialize_state:
        ensure_state()
    selected = agent_ids(agent)
    selected_records = set(selected)
    for selected_agent in selected:
        selected_records.update(agent_record_aliases(selected_agent))
    limit = normalize_int_field(
        limit, field="limit", minimum=1, maximum=MAX_ASSIGNMENT_RECORDS
    )
    records: list[dict[str, Any]] = []
    if not initialize_state:
        lines = (
            read_private_regular_text(
                ASSIGNMENT_LOG,
                MAX_ASSIGNMENT_LOG_BYTES,
                "could_not_read_assignment_log",
            ).splitlines()
            if path_present_no_follow(ASSIGNMENT_LOG)
            else []
        )
    else:
        with assignment_log_lock():
            lines = (
                read_private_regular_text(
                    ASSIGNMENT_LOG,
                    MAX_ASSIGNMENT_LOG_BYTES,
                    "could_not_read_assignment_log",
                ).splitlines()
                if path_present_no_follow(ASSIGNMENT_LOG)
                else []
            )
    for line in lines:
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(record, dict):
            continue
        record_agent = record.get("agent")
        if isinstance(record_agent, str) and record_agent in selected_records:
            records.append(sanitize_assignment_record(record))
    return {
        "agent": agent,
        "selected_count": len(selected),
        "limit": limit,
        "records": records[-limit:],
        "record_count": len(records[-limit:]),
        "retained_count": len(records),
        "retention_limit": MAX_ASSIGNMENT_LOG_RECORDS,
        "records_truncated": len(records) > limit,
        "log_path": "not_returned",
        "prompt_output": "not_returned",
        "response_output": "not_returned",
        "raw_output": "not_returned",
    }


def command_excerpt(text: str, chars: int = 1200) -> tuple[str, bool]:
    cleaned = strip_ansi(text)
    cleaned, redacted = redact(cleaned)
    return trim_chars(cleaned, chars), redacted


def last_assignment_status(agent: str) -> dict[str, Any]:
    result = list_assignments(agent, 1)
    return {
        "agent": agent,
        "status": "found" if result["records"] else "none",
        "record": result["records"][0] if result["records"] else None,
        "prompt_output": "not_returned",
        "response_output": "not_returned",
        "raw_output": "not_returned",
    }


def _is_assignment_report_output_meaningful(output: str, *, running: bool) -> bool:
    cleaned = strip_ansi(output).strip()
    if not cleaned:
        return False
    lines = [line.strip() for line in cleaned.splitlines() if line.strip()]
    if not lines:
        return False
    tui_context = classify_tui_context(cleaned, running=running)
    if tui_context.get("state") in {
        "starter_placeholder",
        "update_prompt",
        "not_running",
    }:
        return False
    for line in lines:
        if not any(pattern.search(line) for pattern in ASSIGNMENT_REPORT_NOISE_TEXT_RE):
            return True
    return False


def assignment_report(
    agent: str,
    assignment_id: Any,
    lines: int = 40,
    chars: int = 4000,
    source: str = "pane",
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    lines = normalize_int_field(lines, field="lines", minimum=1, maximum=MAX_TAIL_LINES)
    chars = normalize_int_field(chars, field="chars", minimum=1, maximum=MAX_TAIL_CHARS)
    if source not in ("pane", "log"):
        raise AgentError("source must be 'pane' or 'log'")
    assignment_id = (
        bounded_text(
            assignment_id,
            field="assignment_id",
            max_chars=MAX_ASSIGNMENT_ID,
            required=True,
        )
        or ""
    )
    records = list_assignments(agent, MAX_ASSIGNMENT_RECORDS).get("records", [])
    assignment = next(
        (
            record
            for record in records
            if isinstance(record, dict) and record.get("assignment_id") == assignment_id
        ),
        None,
    )
    if assignment is None:
        raise AgentError("assignment report not found")
    assignment_position = next(
        (
            index
            for index, record in enumerate(records)
            if isinstance(record, dict) and record.get("assignment_id") == assignment_id
        ),
        None,
    )
    latest_assignment_id = (
        records[-1].get("assignment_id")
        if records and isinstance(records[-1], dict)
        else None
    )
    status = status_agent(agent, initialize_state=False)
    assignment_created_at = parse_utc_timestamp(assignment.get("created_at_utc"))
    raw_log_updated_at = parse_utc_timestamp(status.get("raw_log_updated_at_utc"))
    session_started_at = parse_utc_timestamp(status.get("started_at_utc"))
    latest_assignment_created_at = parse_utc_timestamp(
        records[-1].get("created_at_utc")
        if records and isinstance(records[-1], dict)
        else None
    )
    newer_assignment_output_boundary = None
    if latest_assignment_id != assignment_id:
        if assignment_created_at is None:
            newer_assignment_output_boundary = {
                "status": "report_blocked_unknown_assignment_created_at",
                "detail": "requested assignment has no parseable created_at_utc",
            }
        elif assignment_position is None:
            newer_assignment_output_boundary = {
                "status": "report_blocked_unknown_assignment_position",
                "detail": "requested assignment index was not resolved for boundary check",
            }
        else:
            for candidate in records[assignment_position + 1 :]:
                if not isinstance(candidate, dict):
                    continue
                candidate_id = candidate.get("assignment_id")
                candidate_created_at = parse_utc_timestamp(
                    candidate.get("created_at_utc")
                )
                if candidate_created_at is None:
                    newer_assignment_output_boundary = {
                        "status": "report_blocked_unknown_later_assignment",
                        "detail": f"later assignment {candidate_id} missing parseable created_at_utc",
                    }
                    break
                if candidate_created_at >= assignment_created_at or (
                    latest_assignment_created_at is not None
                    and candidate_created_at >= latest_assignment_created_at
                ):
                    newer_assignment_output_boundary = {
                        "status": "report_blocked_by_superseded_assignment",
                        "detail": f"later assignment {candidate_id} at/after requested assignment",
                    }
                    break
    current_time = time.time()
    lease = status.get("lease") if isinstance(status.get("lease"), dict) else None
    base_result = {
        "agent": agent,
        "assignment_id": assignment_id,
        "assignment_created_at_utc": assignment.get("created_at_utc"),
        "role": assignment.get("role"),
        "model": assignment.get("model"),
        "source": source,
        "lines_limit": lines,
        "chars_limit": chars,
        "lease": lease,
        "report_status_detail": None,
    }
    if latest_assignment_id != assignment_id and source != "log":
        return {
            **base_result,
            "report_status": "no_output",
            "redaction_applied": False,
            "output_chars": 0,
            "output_lines": 0,
            "output_truncated": False,
            "output_truncated_by_lines": False,
            "output_truncated_by_chars": False,
            "output": "",
        }
    if source == "log" and newer_assignment_output_boundary is not None:
        return {
            **base_result,
            "report_status": newer_assignment_output_boundary["status"],
            "report_status_detail": newer_assignment_output_boundary["detail"],
            "redaction_applied": False,
            "output_chars": 0,
            "output_lines": 0,
            "output_truncated": False,
            "output_truncated_by_lines": False,
            "output_truncated_by_chars": False,
            "output": "",
        }
    has_fresh_output = (
        assignment_created_at is not None
        and assignment_created_at <= current_time
        and (session_started_at is None or assignment_created_at >= session_started_at)
        and raw_log_updated_at is not None
        and raw_log_updated_at <= current_time
        and raw_log_updated_at > assignment_created_at
    )
    if not has_fresh_output:
        return {
            **base_result,
            "report_status": "no_output",
            "redaction_applied": False,
            "output_chars": 0,
            "output_lines": 0,
            "output_truncated": False,
            "output_truncated_by_lines": False,
            "output_truncated_by_chars": False,
            "output": "",
        }
    if source == "pane" and status.get("running"):
        visible_pane_text = pane_tail(
            agent, 24, visible_only=True, verify_identity=True
        )
        response_state = (status.get("response_state") or {}).get("state")
        visible_pane_ready = tui_accepts_input(visible_pane_text)
        is_active_pane_work = "esc to interrupt" in visible_pane_text.lower()
        if visible_pane_ready:
            if (
                has_fresh_output
                and response_state == "running_recent_output"
                and not is_active_pane_work
            ):
                source = "log"
        else:
            return {
                **base_result,
                "report_status": "pending",
                "redaction_applied": False,
                "output_chars": 0,
                "output_lines": 0,
                "output_truncated": False,
                "output_truncated_by_lines": False,
                "output_truncated_by_chars": False,
                "output": "",
            }
    excerpt = safe_tail(agent, lines, chars, source)
    output = excerpt.get("output") if isinstance(excerpt.get("output"), str) else ""
    return {
        **base_result,
        "report_status": "excerpt_available"
        if output.strip()
        else "no_output_observed",
        "source": excerpt.get("source"),
        "lines_limit": excerpt.get("lines_limit"),
        "chars_limit": excerpt.get("chars_limit"),
        "redaction_applied": excerpt.get("redaction_applied"),
        "output_chars": excerpt.get("output_chars"),
        "output_lines": excerpt.get("output_lines"),
        "output_truncated": excerpt.get("output_truncated"),
        "output_truncated_by_lines": excerpt.get("output_truncated_by_lines"),
        "output_truncated_by_chars": excerpt.get("output_truncated_by_chars"),
        "output": output,
        "lease": excerpt.get("lease"),
    }


def request_agent_report(
    agent: str,
    assignment_id: Any = None,
    enter: bool = True,
    lease: dict[str, Any] | None = None,
) -> dict[str, Any]:
    agent = canonical_agent_id(agent)
    with agent_lifecycle_lock(agent):
        return _request_agent_report_unlocked(agent, assignment_id, enter, lease=lease)


def _request_agent_report_unlocked(
    agent: str,
    assignment_id: Any = None,
    enter: bool = True,
    lease: dict[str, Any] | None = None,
) -> dict[str, Any]:
    resolved_assignment_id = None
    if assignment_id:
        resolved_assignment_id = (
            bounded_text(
                assignment_id, field="assignment_id", max_chars=MAX_ASSIGNMENT_ID
            )
            or ""
        )
    else:
        latest = list_assignments(agent, 1).get("records", [])
        if latest and isinstance(latest[0], dict):
            candidate = latest[0].get("assignment_id")
            if isinstance(candidate, str) and candidate:
                resolved_assignment_id = candidate
    if resolved_assignment_id:
        safe_id, _changed = redact(resolved_assignment_id)
        text = (
            "Bitte liefere einen knappen Bericht zum Assignment "
            f"{trim_chars(safe_id, 200)}: Status, relevante Dateien/Zeilen, Tests, offene Risiken. "
            "Keine Rohlogs und keine langen Ausgaben."
        )
    else:
        text = "Bitte liefere einen knappen Statusbericht: Aufgabe, Stand, Tests, offene Risiken. Keine Rohlogs."
    lease = lease or agent_lease_status(agent)
    sent = send_agent(agent, text, enter, operation="agent_report_request")
    return {
        "agent": agent,
        "status": "report_requested",
        "submitted": enter,
        "assignment_id": resolved_assignment_id,
        "lease": lease,
        "result_tool": "agent_assignment_report",
        "prompt_output": "not_returned",
        "response_output": "not_returned",
        "send": sent,
    }


def git_excerpt(
    args: list[str], *, cwd: Path | None = None, chars: int = 4000
) -> dict[str, Any]:
    cp = run_command(["git", *args], cwd=cwd or repo_root())
    output, redacted = command_excerpt(cp.stdout + cp.stderr, chars)
    return {
        "ok": cp.returncode == 0,
        "returncode": cp.returncode,
        "output_excerpt": output,
        "redaction_applied": redacted,
    }


def repo_relative_public_path(path: Path, repo: Path) -> str | None:
    try:
        rel = path.relative_to(repo)
    except ValueError:
        return None
    text = rel.as_posix()
    return text or "."


def normalize_git_base_ref(value: Any) -> str | None:
    if value is None:
        return None
    ref = bounded_text(value, field="base_ref", max_chars=MAX_GIT_REF_TEXT)
    if not ref:
        return None
    if not GIT_BASE_REF_RE.fullmatch(ref):
        raise AgentError("base_ref contains unsupported characters")
    return ref


def normalize_git_branch_name(value: str) -> str:
    if (
        not GIT_BRANCH_NAME_RE.fullmatch(value)
        or ".." in value
        or value.endswith(".")
        or value.endswith(".lock")
        or "@{" in value
    ):
        raise AgentError("worktree path basename is not a supported git branch name")
    return value


def _headless_rollback_directory(*, create: bool) -> tuple[Path, os.stat_result] | None:
    root = Path(STATE_ROOT).expanduser()
    if not root.is_absolute():
        root = Path.cwd() / root
    root = Path(os.path.abspath(root))
    try:
        root_stat = root.lstat()
    except FileNotFoundError:
        if not create:
            return None
        ensure_private_dir(root)
        try:
            root_stat = root.lstat()
        except OSError as exc:
            raise AgentError("headless_attestation_rollback_incomplete") from exc
    except OSError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    if (
        stat_module.S_ISLNK(root_stat.st_mode)
        or not stat_module.S_ISDIR(root_stat.st_mode)
        or root_stat.st_uid != os.getuid()
        or stat_module.S_IMODE(root_stat.st_mode) != 0o700
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    directory = root / HEADLESS_ROLLBACK_DIR_NAME
    try:
        directory_stat = directory.lstat()
    except FileNotFoundError:
        if not create:
            return None
        try:
            os.mkdir(directory, 0o700)
            directory_stat = directory.lstat()
        except FileExistsError:
            try:
                directory_stat = directory.lstat()
            except OSError as exc:
                raise AgentError("headless_attestation_rollback_incomplete") from exc
        except OSError as exc:
            raise AgentError("headless_attestation_rollback_incomplete") from exc
    except OSError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    if (
        stat_module.S_ISLNK(directory_stat.st_mode)
        or not stat_module.S_ISDIR(directory_stat.st_mode)
        or directory_stat.st_uid != os.getuid()
        or stat_module.S_IMODE(directory_stat.st_mode) != 0o700
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    return directory, directory_stat


def _headless_rollback_directory_fd(*, create: bool) -> tuple[Path, int] | None:
    resolved = _headless_rollback_directory(create=create)
    if resolved is None:
        return None
    directory, expected_stat = resolved
    try:
        fd = open_directory_chain_no_follow_matching(
            directory,
            expected_stat,
            error_text="headless_attestation_rollback_incomplete",
            changed_text="headless_attestation_rollback_incomplete",
        )
    except AgentError:
        raise
    return directory, fd


def _headless_rollback_record_names(directory_fd: int) -> list[str]:
    names: list[str] = []
    try:
        with os.scandir(f"/proc/self/fd/{directory_fd}") as entries:
            for index, entry in enumerate(entries):
                if index >= MAX_HEADLESS_ROLLBACK_RECORDS * 2:
                    raise AgentError("headless_attestation_rollback_incomplete")
                if not entry.name.startswith("rollback-"):
                    continue
                if HEADLESS_ROLLBACK_RECORD_RE.fullmatch(entry.name) is None:
                    raise AgentError("headless_attestation_rollback_incomplete")
                names.append(entry.name)
                if len(names) > MAX_HEADLESS_ROLLBACK_RECORDS:
                    raise AgentError("headless_attestation_rollback_incomplete")
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    return sorted(names)


def _headless_verify_rollback_record_stat(
    info: os.stat_result,
) -> None:
    if (
        not stat_module.S_ISREG(info.st_mode)
        or info.st_uid != os.getuid()
        or stat_module.S_IMODE(info.st_mode) != 0o600
        or info.st_nlink != 1
        or info.st_size > MAX_HEADLESS_ROLLBACK_RECORD_BYTES
    ):
        raise AgentError("headless_attestation_rollback_incomplete")


def _headless_read_rollback_record(
    directory_fd: int, name: str
) -> tuple[os.stat_result, dict[str, Any]]:
    try:
        info = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        _headless_verify_rollback_record_stat(info)
        fd = os.open(
            name,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=directory_fd,
        )
    except (OSError, AgentError) as exc:
        if isinstance(exc, AgentError):
            raise
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    try:
        opened = os.fstat(fd)
        if (
            not source_identity_matches(opened, info)
            or opened.st_uid != os.getuid()
            or stat_module.S_IMODE(opened.st_mode) != 0o600
            or opened.st_nlink != 1
        ):
            raise AgentError("headless_attestation_rollback_incomplete")
        with os.fdopen(fd, "rb") as stream:
            fd = -1
            raw = stream.read(MAX_HEADLESS_ROLLBACK_RECORD_BYTES + 1)
        if len(raw) > MAX_HEADLESS_ROLLBACK_RECORD_BYTES:
            raise AgentError("headless_attestation_rollback_incomplete")
        latest = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        _headless_verify_rollback_record_stat(latest)
        if not source_identity_matches(latest, info):
            raise AgentError("headless_attestation_rollback_incomplete")
    except AgentError:
        raise
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    finally:
        if fd >= 0:
            os.close(fd)
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    if not isinstance(payload, dict):
        raise AgentError("headless_attestation_rollback_incomplete")
    return info, payload


def _headless_rollback_record_payload(
    agent: str,
    repository: Path,
    target: Path,
    target_stat: os.stat_result | None,
    parent_stat: os.stat_result | None,
    *,
    registered: bool,
    reason: str,
) -> bytes:
    repository_stat: os.stat_result | None
    try:
        repository_stat = repository.lstat()
    except OSError:
        repository_stat = None
    payload = {
        "schema_version": HEADLESS_ROLLBACK_SCHEMA_VERSION,
        "state": "pending",
        "agent": agent,
        "repository": str(repository),
        "repository_device": (
            int(repository_stat.st_dev) if repository_stat is not None else None
        ),
        "repository_inode": (
            int(repository_stat.st_ino) if repository_stat is not None else None
        ),
        "target": str(target),
        "target_device": int(target_stat.st_dev) if target_stat is not None else None,
        "target_inode": int(target_stat.st_ino) if target_stat is not None else None,
        "parent_device": int(parent_stat.st_dev) if parent_stat is not None else None,
        "parent_inode": int(parent_stat.st_ino) if parent_stat is not None else None,
        "registered": registered,
        "reason": reason,
        "created_at_utc": _dt.datetime.now(_dt.timezone.utc).isoformat(),
    }
    raw = (json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n").encode(
        "utf-8"
    )
    if len(raw) > MAX_HEADLESS_ROLLBACK_RECORD_BYTES:
        raise AgentError("headless_attestation_rollback_incomplete")
    return raw


def _persist_headless_rollback_state(
    agent: str,
    repository: Path,
    target: Path,
    target_stat: os.stat_result | None,
    parent_stat: os.stat_result | None,
    *,
    registered: bool,
    reason: str,
) -> None:
    directory_info = _headless_rollback_directory_fd(create=True)
    if directory_info is None:
        raise AgentError("headless_attestation_rollback_incomplete")
    _directory, directory_fd = directory_info
    try:
        names = _headless_rollback_record_names(directory_fd)
        if len(names) >= MAX_HEADLESS_ROLLBACK_RECORDS:
            raise AgentError("headless_attestation_rollback_incomplete")
        for existing_name in names:
            _headless_read_rollback_record(directory_fd, existing_name)
        raw = _headless_rollback_record_payload(
            agent,
            repository,
            target,
            target_stat,
            parent_stat,
            registered=registered,
            reason=reason,
        )
        name = f"rollback-{now_id()}-{uuid.uuid4().hex}.json"
        write_private_new_bytes(Path(name), raw, mode=0o600, dir_fd=directory_fd)
        info = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        _headless_verify_rollback_record_stat(info)
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)


def _headless_remove_rollback_record(directory_fd: int, name: str) -> None:
    info, _payload = _headless_read_rollback_record(directory_fd, name)
    try:
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if not source_identity_matches(current, info):
            raise AgentError("headless_attestation_rollback_incomplete")
        os.unlink(name, dir_fd=directory_fd)
        os.fsync(directory_fd)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc


def _headless_resume_rollback_payload(
    directory_fd: int, name: str, payload: Mapping[str, Any]
) -> None:
    if (
        payload.get("schema_version") != HEADLESS_ROLLBACK_SCHEMA_VERSION
        or payload.get("state") != "pending"
        or not isinstance(payload.get("agent"), str)
        or not isinstance(payload.get("repository"), str)
        or not isinstance(payload.get("target"), str)
        or type(payload.get("registered")) is not bool
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    repository = Path(payload["repository"])
    target = Path(payload["target"])
    if (
        not repository.is_absolute()
        or not target.is_absolute()
        or len(str(repository)) > MAX_PATH_TEXT
        or len(str(target)) > MAX_PATH_TEXT
        or any(part in {".", ".."} for part in repository.parts[1:])
        or any(part in {".", ".."} for part in target.parts[1:])
        or target == repository
        or not directory_chain_is_real_no_symlink(repository)
        or not directory_chain_is_real_no_symlink(target.parent)
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    try:
        target.relative_to(repository)
    except ValueError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    repository_device = payload.get("repository_device")
    repository_inode = payload.get("repository_inode")
    target_device = payload.get("target_device")
    target_inode = payload.get("target_inode")
    parent_device = payload.get("parent_device")
    parent_inode = payload.get("parent_inode")
    if any(
        type(value) is not int or value < 0
        for value in (repository_device, repository_inode, parent_device, parent_inode)
    ) or any(
        type(value) is not int or value <= 0
        for value in (repository_inode, parent_inode)
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    target_identity_available = (
        type(target_device) is int
        and target_device >= 0
        and type(target_inode) is int
        and target_inode > 0
    )
    if (target_device is None) != (target_inode is None) or (
        target_device is not None and not target_identity_available
    ):
        raise AgentError("headless_attestation_rollback_incomplete")
    try:
        repository_stat = repository.lstat()
        if (
            stat_module.S_ISLNK(repository_stat.st_mode)
            or not stat_module.S_ISDIR(repository_stat.st_mode)
            or repository_stat.st_dev != repository_device
            or repository_stat.st_ino != repository_inode
        ):
            raise AgentError("headless_attestation_rollback_incomplete")
        repository_fd = open_directory_chain_no_follow_matching(
            repository,
            repository_stat,
            error_text="headless_attestation_rollback_incomplete",
            changed_text="headless_attestation_rollback_incomplete",
        )
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("headless_attestation_rollback_incomplete") from exc
    target_fd = -1
    parent_fd = -1
    try:
        try:
            target_stat = target.lstat()
        except FileNotFoundError:
            if not payload["registered"]:
                _headless_remove_rollback_record(directory_fd, name)
                return
            raise AgentError("headless_attestation_rollback_incomplete")
        except OSError as exc:
            raise AgentError("headless_attestation_rollback_incomplete") from exc
        if not target_identity_available or (
            stat_module.S_ISLNK(target_stat.st_mode)
            or not stat_module.S_ISDIR(target_stat.st_mode)
            or target_stat.st_dev != target_device
            or target_stat.st_ino != target_inode
        ):
            raise AgentError("headless_attestation_rollback_incomplete")
        target_fd = open_directory_chain_no_follow_matching(
            target,
            target_stat,
            error_text="headless_attestation_rollback_incomplete",
            changed_text="headless_attestation_rollback_incomplete",
        )
        parent = target.parent
        try:
            parent_stat = parent.lstat()
        except OSError as exc:
            raise AgentError("headless_attestation_rollback_incomplete") from exc
        if (
            stat_module.S_ISLNK(parent_stat.st_mode)
            or not stat_module.S_ISDIR(parent_stat.st_mode)
            or parent_stat.st_dev != parent_device
            or parent_stat.st_ino != parent_inode
        ):
            raise AgentError("headless_attestation_rollback_incomplete")
        parent_fd = open_directory_chain_no_follow_matching(
            parent,
            parent_stat,
            error_text="headless_attestation_rollback_incomplete",
            changed_text="headless_attestation_rollback_incomplete",
        )
        if payload["registered"]:
            cleanup = run_command(
                [
                    "git",
                    "worktree",
                    "remove",
                    "--force",
                    "--",
                    f"/proc/self/fd/{target_fd}",
                ],
                cwd=Path(f"/proc/self/fd/{repository_fd}"),
                pass_fds=(repository_fd, target_fd),
            )
            returncode = getattr(cleanup, "returncode", None)
            if (
                not isinstance(returncode, int)
                or isinstance(returncode, bool)
                or returncode != 0
            ):
                raise AgentError("headless_attestation_rollback_incomplete")
        else:
            try:
                os.rmdir(target.name, dir_fd=parent_fd)
            except OSError as exc:
                raise AgentError("headless_attestation_rollback_incomplete") from exc
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            _headless_remove_rollback_record(directory_fd, name)
            return
        except OSError as exc:
            raise AgentError("headless_attestation_rollback_incomplete") from exc
        raise AgentError("headless_attestation_rollback_incomplete")
    finally:
        if target_fd >= 0:
            os.close(target_fd)
        if parent_fd >= 0:
            os.close(parent_fd)
        os.close(repository_fd)


def _resume_headless_rollback_records() -> list[str]:
    directory_info = _headless_rollback_directory_fd(create=False)
    if directory_info is None:
        return []
    _directory, directory_fd = directory_info
    try:
        names = _headless_rollback_record_names(directory_fd)
        for name in names:
            _info, payload = _headless_read_rollback_record(directory_fd, name)
            _headless_resume_rollback_payload(directory_fd, name, payload)
        return []
    finally:
        os.close(directory_fd)


def worktree_create_for_agent(
    agent: str, path: Any = None, base_ref: Any = None
) -> dict[str, Any]:
    _resume_headless_rollback_records()
    require_fleet_recovery_ready("worktree_create_for_agent")
    agent = canonical_agent_id(agent)
    path = (
        bounded_text(path, field="path", max_chars=MAX_PATH_TEXT)
        if path is not None
        else None
    )
    base_ref = normalize_git_base_ref(base_ref)
    repo = repo_root().resolve(strict=False)
    target = (
        Path(path).expanduser()
        if path
        else repo / ".codex-master-worktrees" / f"agent-{agent}-{now_id()}"
    )
    if not target.is_absolute():
        target = repo / target
    target = target.absolute()
    scoped_target = target.resolve(strict=False)
    if not path_is_within(scoped_target, repo):
        raise AgentError("worktree path must stay inside repo")
    branch_name = normalize_git_branch_name(target.name) if base_ref is None else None
    if path_present_no_follow(target):
        raise AgentError("worktree path already exists")
    try:
        parent_stat = target.parent.lstat()
    except FileNotFoundError:
        parent_stat = None
    except OSError as exc:
        raise AgentError(
            "worktree parent directories must be real directories"
        ) from exc
    ensure_directory_chain_no_symlink(
        target.parent, "worktree parent directories must be real directories"
    )
    resolved_target = target.resolve(strict=False)
    if not path_is_within(resolved_target, repo):
        raise AgentError("worktree path must stay inside repo")
    if parent_stat is None:
        try:
            parent_stat = target.parent.lstat()
        except OSError as exc:
            raise AgentError(
                "worktree parent directories must be real directories"
            ) from exc
    parent_fd = open_directory_chain_no_follow_matching(
        target.parent,
        parent_stat,
        error_text="worktree parent directories must be real directories",
        changed_text="worktree parent directories changed unexpectedly",
    )
    target_fd = -1
    target_stat: os.stat_result | None = None
    created_target = False
    cp: subprocess.CompletedProcess[str] | None = None
    worktree_registered = False

    def raise_rollback_incomplete(
        reason: str, cause: BaseException | None = None
    ) -> None:
        try:
            _persist_headless_rollback_state(
                agent,
                repo,
                target,
                target_stat,
                parent_stat,
                registered=worktree_registered,
                reason=reason,
            )
        except Exception as exc:
            raise AgentError(
                "headless_attestation_rollback_incomplete",
                {"recovery_state": "unavailable"},
            ) from exc
        error = AgentError(
            "headless_attestation_rollback_incomplete",
            {"recovery_state": "pending"},
        )
        if cause is None:
            raise error
        raise error from cause

    def rollback_registered_worktree() -> None:
        if not worktree_registered:
            return
        if target_stat is None or target_fd < 0:
            raise_rollback_incomplete("target_identity_unavailable")
        try:
            current_path = os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError as exc:
            raise_rollback_incomplete("target_path_missing", exc)
        except OSError as exc:
            raise_rollback_incomplete("target_path_stat_failed", exc)
        if not stat_module.S_ISDIR(current_path.st_mode) or not source_identity_matches(
            current_path, target_stat
        ):
            raise_rollback_incomplete("target_path_identity_changed")
        try:
            current_target = os.fstat(target_fd)
        except OSError as exc:
            raise_rollback_incomplete("target_fstat_failed", exc)
        if not stat_module.S_ISDIR(
            current_target.st_mode
        ) or not source_identity_matches(current_target, target_stat):
            raise_rollback_incomplete("target_identity_changed")
        try:
            cleanup = run_command(
                [
                    "git",
                    "worktree",
                    "remove",
                    "--force",
                    "--",
                    f"/proc/self/fd/{target_fd}",
                ],
                cwd=repo,
                pass_fds=(target_fd,),
            )
        except Exception as exc:
            raise_rollback_incomplete("rollback_command_failed", exc)
        returncode = getattr(cleanup, "returncode", None)
        if (
            not isinstance(returncode, int)
            or isinstance(returncode, bool)
            or returncode != 0
        ):
            raise_rollback_incomplete("rollback_command_failed")
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return
        except OSError as exc:
            raise_rollback_incomplete("target_path_stat_failed", exc)
        raise_rollback_incomplete("rollback_target_still_exists")

    try:
        try:
            os.mkdir(target.name, 0o755, dir_fd=parent_fd)
        except FileExistsError as exc:
            raise AgentError("worktree path already exists") from exc
        except OSError as exc:
            raise AgentError("worktree path could not be created") from exc
        created_target = True
        try:
            target_stat = os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError as exc:
            raise AgentError("worktree path must be a real directory") from exc
        target_fd = open_directory_no_follow_matching(
            target.name,
            target_stat,
            error_text="worktree path must be a real directory",
            changed_text="worktree path changed unexpectedly",
            dir_fd=parent_fd,
        )
        operation_cwd = Path(f"/proc/self/fd/{target_fd}")
        if base_ref:
            args = ["worktree", "add", ".", base_ref]
        else:
            branch_check = run_command(
                ["git", "show-ref", "--verify", "--quiet", f"refs/heads/{branch_name}"],
                cwd=operation_cwd,
            )
            args = (
                ["worktree", "add", ".", branch_name]
                if branch_check.returncode == 0
                else ["worktree", "add", "-b", branch_name, "."]
            )
        cp = run_command(["git", *args], cwd=operation_cwd)
        if cp.returncode != 0:
            try:
                registration = run_command(
                    ["git", "worktree", "list", "--porcelain"], cwd=repo
                )
            except Exception:
                worktree_registered = True
            else:
                if registration.returncode != 0 or not isinstance(
                    registration.stdout, str
                ):
                    worktree_registered = True
                else:
                    target_text = str(target)
                    worktree_registered = any(
                        line.startswith("worktree ") and line[9:] == target_text
                        for line in registration.stdout.splitlines()
                    )
            raise AgentError("git worktree add failed")
        worktree_registered = True
        try:
            final_target_stat = os.stat(
                target.name, dir_fd=parent_fd, follow_symlinks=False
            )
        except OSError as exc:
            raise AgentError("headless_attestation_invalid") from exc
        if (
            target_stat is None
            or not stat_module.S_ISDIR(final_target_stat.st_mode)
            or not source_identity_matches(final_target_stat, target_stat)
        ):
            raise AgentError("headless_attestation_invalid")
        ensure_directory_chain_no_symlink(
            target.parent, "worktree parent directories must be real directories"
        )
        resolved_target = target.resolve(strict=False)
        if resolved_target != target or not path_is_within(resolved_target, repo):
            raise AgentError("headless_attestation_invalid")
        public_path = repo_relative_public_path(resolved_target, repo)
        write_scope: dict[str, Any] = {
            "state": "unavailable",
            "raw_output": "not_returned",
        }
        git_metadata = resolved_target / ".git"
        try:
            metadata_stat = git_metadata.lstat()
        except FileNotFoundError:
            metadata_stat = None
        except OSError as exc:
            raise AgentError("headless_attestation_invalid") from exc
        if (
            metadata_stat is None
            or stat_module.S_ISLNK(metadata_stat.st_mode)
            or not (
                stat_module.S_ISREG(metadata_stat.st_mode)
                or stat_module.S_ISDIR(metadata_stat.st_mode)
            )
        ):
            raise AgentError("headless_attestation_invalid")
        try:
            attestation = _headless_write_scope_store().create(
                agent,
                repo,
                resolved_target,
                base_ref=base_ref,
            )
        except HeadlessWriteScopeFailure as exc:
            _raise_headless_scope_failure(exc)
        write_scope = {
            "state": "available",
            "attestation_id": attestation.attestation_id,
            "raw_output": "not_returned",
        }
        return {
            "agent": agent,
            "path": public_path or PATH_NOT_RETURNED,
            "path_state": "set" if public_path else "not_returned",
            "path_kind": "repo_relative" if public_path else "not_returned",
            "base_ref": PATH_NOT_RETURNED if base_ref else None,
            "base_ref_state": "set" if base_ref else "not_set",
            "status": "created",
            "write_scope": write_scope,
            "raw_output": "not_returned",
        }
    except Exception:
        if worktree_registered:
            rollback_registered_worktree()
        elif created_target:
            if target_stat is None:
                raise_rollback_incomplete("target_identity_unavailable")
            try:
                current_target = os.stat(
                    target.name, dir_fd=parent_fd, follow_symlinks=False
                )
                if not source_identity_matches(current_target, target_stat):
                    raise_rollback_incomplete("target_identity_changed")
                os.rmdir(target.name, dir_fd=parent_fd)
            except FileNotFoundError:
                pass
            except AgentError:
                raise
            except OSError as exc:
                raise_rollback_incomplete("rollback_directory_remove_failed", exc)
        raise
    finally:
        if target_fd >= 0:
            os.close(target_fd)
        os.close(parent_fd)


def worktree_status(path: Any = None) -> dict[str, Any]:
    path = (
        bounded_text(path, field="path", max_chars=MAX_PATH_TEXT)
        if path is not None
        else None
    )
    repo = repo_root().resolve(strict=False)
    target = Path(path).expanduser() if path else repo
    if not target.is_absolute():
        target = repo / target
    target = target.absolute()
    scoped_target = target.resolve(strict=False)
    if not path_is_within(scoped_target, repo):
        raise AgentError("worktree status path must stay inside repo")
    if not directory_chain_is_real_no_symlink(target.parent):
        raise AgentError("worktree status parent directories must be real directories")
    try:
        target_stat = target.lstat()
    except OSError as exc:
        raise AgentError("worktree status path must be a real directory") from exc
    if stat_module.S_ISLNK(target_stat.st_mode) or not stat_module.S_ISDIR(
        target_stat.st_mode
    ):
        raise AgentError("worktree status path must be a real directory")
    target_fd = open_directory_chain_no_follow_matching(
        target,
        target_stat,
        error_text="worktree status path must be a real directory",
        changed_text="worktree status path changed unexpectedly",
    )
    try:
        return {
            "path": PATH_NOT_RETURNED,
            "path_state": "set",
            "status": git_excerpt(
                ["status", "--short"], cwd=Path(f"/proc/self/fd/{target_fd}")
            ),
            "worktrees": git_excerpt(["worktree", "list", "--porcelain"], cwd=repo),
            "raw_output": "not_returned",
        }
    finally:
        os.close(target_fd)


def ensure_real_parent(path: Path, error_text: str) -> os.stat_result:
    try:
        parent_stat = path.parent.lstat()
    except FileNotFoundError:
        parent_stat = None
    except OSError as exc:
        raise AgentError(error_text) from exc
    ensure_directory_chain_no_symlink(path.parent, error_text)
    if parent_stat is None:
        try:
            parent_stat = path.parent.lstat()
        except OSError as exc:
            raise AgentError(error_text) from exc
    return parent_stat


def integration_status() -> dict[str, Any]:
    return {
        "repo": PATH_NOT_RETURNED,
        "repo_state": "set",
        "status": git_excerpt(["status", "--short"]),
        "diff_stat": git_excerpt(["diff", "--stat"]),
        "assignments": list_assignments("all", 10),
        "raw_output": "not_returned",
    }


def commit_ready_check(run_tests: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    repo = repo_root()
    env = os.environ.copy()
    env["PYTHONPATH"] = (
        "src" if not env.get("PYTHONPATH") else f"src{os.pathsep}{env['PYTHONPATH']}"
    )
    commands = [
        ("diff_check", ["git", "diff", "--check"]),
        ("compileall", [sys.executable, "-m", "compileall", "-q", "src", "tests"]),
    ]
    if run_tests:
        commands.append(
            (
                "unittest",
                [sys.executable, "-m", "unittest", "discover", "-s", "tests", "-v"],
            )
        )
    for name, command in commands:
        cp = run_command(command, cwd=repo, env=env)
        output, redacted = command_excerpt(cp.stdout + cp.stderr, 6000)
        checks.append(
            {
                "name": name,
                "ok": cp.returncode == 0,
                "returncode": cp.returncode,
                "output_excerpt": output,
                "redaction_applied": redacted,
            }
        )
    return {
        "ok": all(check["ok"] for check in checks),
        "checks": checks,
        "raw_output": "not_returned",
    }


def repo_file_status(path: Path) -> dict[str, Any]:
    try:
        current = path.lstat()
    except FileNotFoundError:
        return {
            "path": PATH_NOT_RETURNED,
            "path_state": "missing",
            "exists": False,
            "regular_file": False,
        }
    except OSError:
        return {
            "path": PATH_NOT_RETURNED,
            "path_state": "error",
            "exists": False,
            "regular_file": False,
        }
    return {
        "path": PATH_NOT_RETURNED,
        "path_state": "set",
        "exists": True,
        "regular_file": stat_module.S_ISREG(current.st_mode),
        "symlink": stat_module.S_ISLNK(current.st_mode),
    }


def read_repo_json_object(path: Path, label: str) -> dict[str, Any]:
    text = read_private_regular_text(
        path, MAX_PLUGIN_MANIFEST_BYTES, f"{label} could not be read"
    )
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as exc:
        raise AgentError(f"{label} must contain valid JSON") from exc
    if not isinstance(payload, dict):
        raise AgentError(f"{label} must contain a JSON object")
    return payload


def public_plugin_version(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    version = value.strip()
    if not PLUGIN_VERSION_RE.fullmatch(version):
        return None
    return version


def plugin_manifest_version(root: Path | None = None) -> dict[str, Any]:
    manifest = (root or repo_root()) / ".codex-plugin" / "plugin.json"
    status = repo_file_status(manifest)
    result: dict[str, Any] = {
        "path": PATH_NOT_RETURNED,
        "path_state": status["path_state"],
        "exists": status["exists"],
        "version": "",
        "version_state": "missing",
        "name_matches": False,
        "ok": False,
        "raw_output": "not_returned",
    }
    if not status["regular_file"]:
        result["reason"] = "plugin_manifest_not_regular_file"
        return result
    try:
        payload = read_repo_json_object(manifest, "plugin manifest")
    except AgentError as exc:
        result["reason"] = safe_error_text(exc)
        return result
    version = public_plugin_version(payload.get("version"))
    name_matches = payload.get("name") == APP_BRIDGE_NAME
    result.update(
        {
            "version": version or "",
            "version_state": "set" if version else "invalid_or_missing",
            "name_matches": name_matches,
            "ok": bool(version) and name_matches,
        }
    )
    if not result["ok"]:
        result["reason"] = "plugin_manifest_name_or_version_invalid"
    return result


def normalize_plugin_contract_path(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    path = Path(value)
    if path.is_absolute():
        return None
    normalized = path.as_posix().rstrip("/")
    return normalized or None


def plugin_declares_mcp_manifest(root: Path) -> dict[str, Any]:
    manifest = root / ".codex-plugin" / "plugin.json"
    status = repo_file_status(manifest)
    result: dict[str, Any] = {
        "path": PATH_NOT_RETURNED,
        "path_state": status["path_state"],
        "exists": status["exists"],
        "declared": False,
        "ok": False,
        "raw_output": "not_returned",
    }
    if not status["regular_file"]:
        result["reason"] = "plugin_manifest_not_regular_file"
        return result
    try:
        payload = read_repo_json_object(manifest, "plugin manifest")
    except AgentError as exc:
        result["reason"] = safe_error_text(exc)
        return result
    normalized = normalize_plugin_contract_path(payload.get("mcpServers"))
    result.update(
        {
            "declared": normalized is not None,
            "target": normalized or "",
            "ok": normalized == ".mcp.json",
        }
    )
    if not result["ok"]:
        result["reason"] = "plugin_mcp_manifest_reference_invalid"
    return result


def plugin_declares_app_manifest(root: Path) -> dict[str, Any]:
    manifest = root / ".codex-plugin" / "plugin.json"
    status = repo_file_status(manifest)
    result: dict[str, Any] = {
        "path": PATH_NOT_RETURNED,
        "path_state": status["path_state"],
        "exists": status["exists"],
        "declared": False,
        "ok": False,
        "raw_output": "not_returned",
    }
    if not status["regular_file"]:
        result["reason"] = "plugin_manifest_not_regular_file"
        return result
    try:
        payload = read_repo_json_object(manifest, "plugin manifest")
    except AgentError as exc:
        result["reason"] = safe_error_text(exc)
        return result
    normalized = normalize_plugin_contract_path(payload.get("apps"))
    result.update(
        {
            "declared": normalized is not None,
            "target": normalized or "",
            "ok": normalized == ".app.json",
        }
    )
    return result


def codex_plugin_cache_root() -> Path:
    codex_home = os.environ.get("CODEX_HOME")
    root = Path(codex_home).expanduser() if codex_home else Path.home() / ".codex"
    if not root.is_absolute():
        root = Path.cwd() / root
    return root / "plugins" / "cache" / "personal" / APP_BRIDGE_NAME


def normalize_plugin_cache_root(cache_root: Path | None = None) -> Path:
    target_cache = cache_root or codex_plugin_cache_root()
    target_cache = target_cache.expanduser()
    if not target_cache.is_absolute():
        target_cache = Path.cwd() / target_cache
    return target_cache.absolute()


def plugin_cache_status(
    root: Path | None = None, cache_root: Path | None = None
) -> dict[str, Any]:
    repo_version = plugin_manifest_version(root)
    target_cache = normalize_plugin_cache_root(cache_root)
    result: dict[str, Any] = {
        "marketplace": "personal",
        "plugin_name": APP_BRIDGE_NAME,
        "path": PATH_NOT_RETURNED,
        "path_state": "missing",
        "exists": False,
        "directory": False,
        "symlink": False,
        "repo_manifest": repo_version,
        "repo_version_installed": False,
        "installed_version_count": 0,
        "installed_versions": [],
        "installed_versions_truncated": False,
        "symlink_entry_count": 0,
        "invalid_entry_count": 0,
        "unreadable_entry_count": 0,
        "ok": False,
        "raw_output": "not_returned",
    }
    try:
        current = target_cache.lstat()
    except FileNotFoundError:
        result["reason"] = "plugin_cache_missing"
        return result
    except OSError:
        result["path_state"] = "error"
        result["reason"] = "plugin_cache_unreadable"
        return result
    result.update(
        {
            "path_state": "set",
            "exists": True,
            "directory": stat_module.S_ISDIR(current.st_mode),
            "symlink": stat_module.S_ISLNK(current.st_mode),
        }
    )
    if result["symlink"] or not result["directory"]:
        result["reason"] = "plugin_cache_not_real_directory"
        return result

    versions: list[str] = []
    cache_fd = -1
    try:
        cache_fd = open_directory_no_follow_matching(
            target_cache,
            current,
            error_text="plugin_cache_unreadable",
            changed_text="plugin_cache_changed",
        )
        entry_names = sorted(os.listdir(cache_fd))
    except AgentError as exc:
        result["reason"] = "plugin_cache_unreadable"
        if "changed" in str(exc):
            result["reason"] = "plugin_cache_changed"
        return result
    except OSError:
        result["reason"] = "plugin_cache_unreadable"
        return result
    finally:
        if cache_fd >= 0:
            os.close(cache_fd)

    cache_fd = -1
    try:
        cache_fd = open_directory_no_follow_matching(
            target_cache,
            current,
            error_text="plugin_cache_unreadable",
            changed_text="plugin_cache_changed",
        )
        for entry_name in entry_names:
            try:
                entry_stat = os.stat(entry_name, dir_fd=cache_fd, follow_symlinks=False)
            except OSError:
                result["unreadable_entry_count"] += 1
                continue
            if stat_module.S_ISLNK(entry_stat.st_mode):
                result["symlink_entry_count"] += 1
                continue
            if not stat_module.S_ISDIR(entry_stat.st_mode):
                result["invalid_entry_count"] += 1
                continue
            entry_version = public_plugin_version(entry_name)
            if not entry_version:
                result["invalid_entry_count"] += 1
                continue

            entry_fd = -1
            plugin_dir_fd = -1
            try:
                entry_fd = open_directory_no_follow_matching(
                    entry_name,
                    entry_stat,
                    error_text="plugin_cache_entry_unreadable",
                    changed_text="plugin_cache_entry_changed",
                    dir_fd=cache_fd,
                )
                try:
                    plugin_dir_stat = os.stat(
                        ".codex-plugin", dir_fd=entry_fd, follow_symlinks=False
                    )
                except OSError:
                    result["unreadable_entry_count"] += 1
                    continue
                if stat_module.S_ISLNK(
                    plugin_dir_stat.st_mode
                ) or not stat_module.S_ISDIR(plugin_dir_stat.st_mode):
                    result["invalid_entry_count"] += 1
                    continue
                plugin_dir_fd = open_directory_no_follow_matching(
                    ".codex-plugin",
                    plugin_dir_stat,
                    error_text="plugin_cache_entry_unreadable",
                    changed_text="plugin_cache_entry_changed",
                    dir_fd=entry_fd,
                )
                payload = read_json_object_from_dir_fd(
                    plugin_dir_fd, "plugin.json", "cached plugin manifest"
                )
            except AgentError:
                result["unreadable_entry_count"] += 1
                continue
            finally:
                if plugin_dir_fd >= 0:
                    os.close(plugin_dir_fd)
                if entry_fd >= 0:
                    os.close(entry_fd)
            cached_version = public_plugin_version(payload.get("version"))
            if (
                payload.get("name") != APP_BRIDGE_NAME
                or cached_version != entry_version
            ):
                result["invalid_entry_count"] += 1
                continue
            versions.append(entry_version)
    except AgentError as exc:
        result["reason"] = (
            "plugin_cache_changed"
            if "changed" in str(exc)
            else "plugin_cache_unreadable"
        )
        return result
    finally:
        if cache_fd >= 0:
            os.close(cache_fd)

    versions = sorted(set(versions))
    repo_version_text = repo_version.get("version") if repo_version.get("ok") else ""
    repo_version_installed = bool(repo_version_text) and repo_version_text in versions
    result.update(
        {
            "repo_version_installed": repo_version_installed,
            "installed_version_count": len(versions),
            "installed_versions": versions[-MAX_PLUGIN_CACHE_VERSIONS:],
            "installed_versions_truncated": len(versions) > MAX_PLUGIN_CACHE_VERSIONS,
            "ok": repo_version_installed,
        }
    )
    if not result["ok"]:
        result["reason"] = "repo_plugin_version_not_installed"
    return result


def source_identity_matches(
    opened_stat: os.stat_result,
    expected_stat: os.stat_result | FileIdentity | None,
) -> bool:
    if expected_stat is None:
        return False
    if isinstance(expected_stat, FileIdentity):
        return (
            opened_stat.st_ino == expected_stat.ino
            and opened_stat.st_dev == expected_stat.dev
        )
    return (
        opened_stat.st_ino == expected_stat.st_ino
        and opened_stat.st_dev == expected_stat.st_dev
    )


def source_identity_with_snapshot_matches(
    opened_stat: os.stat_result,
    expected_stat: os.stat_result,
) -> bool:
    return (
        source_identity_matches(opened_stat, expected_stat)
        and opened_stat.st_size == expected_stat.st_size
        and opened_stat.st_mtime_ns == expected_stat.st_mtime_ns
    )


def open_directory_no_follow_matching(
    path: Path | str,
    expected_stat: os.stat_result,
    *,
    error_text: str,
    changed_text: str,
    dir_fd: int | None = None,
) -> int:
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    proc_fd_number: int | None = None
    try:
        path_parts = Path(path).parts
        if (
            dir_fd is None
            and len(path_parts) == 5
            and path_parts[:4] == ("/", "proc", "self", "fd")
            and path_parts[4].isdigit()
        ):
            proc_fd_number = int(path_parts[4])
            fd = os.dup(proc_fd_number)
        else:
            fd = (
                os.open(path, flags)
                if dir_fd is None
                else os.open(path, flags, dir_fd=dir_fd)
            )
    except OSError as exc:
        raise AgentError(error_text) from exc
    try:
        opened_stat = os.fstat(fd)
        expected_for_compare = expected_stat
        if proc_fd_number is not None and stat_module.S_ISLNK(expected_stat.st_mode):
            expected_for_compare = os.fstat(proc_fd_number)
        if not stat_module.S_ISDIR(opened_stat.st_mode) or not source_identity_matches(
            opened_stat, expected_for_compare
        ):
            raise AgentError(changed_text)
        return fd
    except Exception:
        os.close(fd)
        raise


def open_directory_chain_no_follow_matching(
    path: Path,
    expected_stat: os.stat_result,
    *,
    error_text: str,
    changed_text: str,
) -> int:
    if not path.is_absolute():
        raise AgentError(error_text)
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(path.anchor, flags)
        for part in path.parts[1:]:
            child_fd = os.open(part, flags, dir_fd=fd)
            os.close(fd)
            fd = child_fd
        opened_stat = os.fstat(fd)
        if not stat_module.S_ISDIR(opened_stat.st_mode) or not source_identity_matches(
            opened_stat, expected_stat
        ):
            raise AgentError(changed_text)
        result = fd
        fd = -1
        return result
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error_text) from exc
    finally:
        if fd >= 0:
            os.close(fd)


def read_json_object_from_dir_fd(dir_fd: int, name: str, label: str) -> dict[str, Any]:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(name, flags, dir_fd=dir_fd)
        current = os.fstat(fd)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or current.st_size > MAX_PLUGIN_MANIFEST_BYTES
        ):
            raise AgentError(f"{label} could not be read")
        raw = b""
        remaining = MAX_PLUGIN_MANIFEST_BYTES + 1
        while remaining > 0:
            chunk = os.read(fd, min(remaining, RAW_LOG_CHUNK_BYTES))
            if not chunk:
                break
            raw += chunk
            remaining -= len(chunk)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(f"{label} could not be read") from exc
    finally:
        if fd >= 0:
            os.close(fd)
    if len(raw) > MAX_PLUGIN_MANIFEST_BYTES:
        raise AgentError(f"{label} could not be read")
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AgentError(f"{label} must contain valid JSON") from exc
    if not isinstance(payload, dict):
        raise AgentError(f"{label} must contain a JSON object")
    return payload


def copy_regular_plugin_file_no_follow(
    src: Path, dst: Path, expected_stat: os.stat_result
) -> None:
    source_flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        source_flags |= os.O_NOFOLLOW
    src_fd = -1
    dst_fd = -1
    dst_created = False
    dst_stat: os.stat_result | None = None
    try:
        src_fd = os.open(src, source_flags)
        opened_stat = os.fstat(src_fd)
        if (
            not stat_module.S_ISREG(opened_stat.st_mode)
            or getattr(opened_stat, "st_nlink", 1) > 1
            or not source_identity_with_snapshot_matches(opened_stat, expected_stat)
        ):
            raise AgentError("plugin source changed during copy")
        mode = stat_module.S_IMODE(opened_stat.st_mode)
        target_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_NOFOLLOW"):
            target_flags |= os.O_NOFOLLOW
        dst_fd = os.open(dst, target_flags, mode)
        dst_created = True
        dst_stat = os.fstat(dst_fd)
        while True:
            chunk = os.read(src_fd, RAW_LOG_CHUNK_BYTES)
            if not chunk:
                break
            offset = 0
            while offset < len(chunk):
                written = os.write(dst_fd, chunk[offset:])
                if written <= 0:
                    raise OSError("plugin cache copy made no progress")
                offset += written
        os.fchmod(dst_fd, mode)
        os.utime(dst_fd, ns=(opened_stat.st_atime_ns, opened_stat.st_mtime_ns))
        dst_created = False
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    finally:
        if src_fd >= 0:
            os.close(src_fd)
        if dst_fd >= 0:
            os.close(dst_fd)
        if dst_created:
            remove_created_plugin_file_if_same(dst, dst_stat)


def remove_created_plugin_file_if_same(
    path: Path, expected_stat: os.stat_result | None
) -> None:
    if expected_stat is None:
        return
    try:
        current = path.lstat()
    except OSError:
        return
    if not source_identity_matches(current, expected_stat):
        return
    with contextlib.suppress(OSError):
        path.unlink()


def open_plugin_source_dir_no_follow(src: Path, expected_stat: os.stat_result) -> int:
    return open_directory_no_follow_matching(
        src,
        expected_stat,
        error_text="could_not_sync_plugin_cache",
        changed_text="plugin source changed during copy",
    )


@contextlib.contextmanager
def plugin_source_root_operation(root: Path, expected_stat: os.stat_result) -> Any:
    source_fd = -1
    try:
        source_fd = open_plugin_source_dir_no_follow(root, expected_stat)
        yield Path(f"/proc/self/fd/{source_fd}")
    finally:
        if source_fd >= 0:
            os.close(source_fd)


def copy_regular_plugin_file_from_dir_no_follow(
    src_dir_fd: int, name: str, dst: Path, expected_stat: os.stat_result
) -> None:
    source_flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        source_flags |= os.O_NOFOLLOW
    src_fd = -1
    dst_fd = -1
    dst_created = False
    dst_stat: os.stat_result | None = None
    try:
        src_fd = os.open(name, source_flags, dir_fd=src_dir_fd)
        opened_stat = os.fstat(src_fd)
        if (
            not stat_module.S_ISREG(opened_stat.st_mode)
            or getattr(opened_stat, "st_nlink", 1) > 1
            or not source_identity_with_snapshot_matches(opened_stat, expected_stat)
        ):
            raise AgentError("plugin source changed during copy")
        mode = stat_module.S_IMODE(opened_stat.st_mode)
        target_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_NOFOLLOW"):
            target_flags |= os.O_NOFOLLOW
        dst_fd = os.open(dst, target_flags, mode)
        dst_created = True
        dst_stat = os.fstat(dst_fd)
        while True:
            chunk = os.read(src_fd, RAW_LOG_CHUNK_BYTES)
            if not chunk:
                break
            offset = 0
            while offset < len(chunk):
                written = os.write(dst_fd, chunk[offset:])
                if written <= 0:
                    raise OSError("plugin cache copy made no progress")
                offset += written
        os.fchmod(dst_fd, mode)
        os.utime(dst_fd, ns=(opened_stat.st_atime_ns, opened_stat.st_mtime_ns))
        dst_created = False
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    finally:
        if src_fd >= 0:
            os.close(src_fd)
        if dst_fd >= 0:
            os.close(dst_fd)
        if dst_created:
            remove_created_plugin_file_if_same(dst, dst_stat)


def open_plugin_destination_parent(path: Path) -> int:
    try:
        parent_stat = path.parent.lstat()
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    return open_directory_no_follow_matching(
        path.parent,
        parent_stat,
        error_text="could_not_sync_plugin_cache",
        changed_text="could_not_sync_plugin_cache",
    )


def open_plugin_destination_directory(path: Path, *, create: bool) -> int:
    parent_fd = -1
    directory_fd = -1
    try:
        parent_fd = open_plugin_destination_parent(path)
        if create:
            try:
                os.mkdir(path.name, 0o755, dir_fd=parent_fd)
            except OSError as exc:
                raise AgentError("could_not_sync_plugin_cache") from exc
        try:
            current = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError as exc:
            raise AgentError("could_not_sync_plugin_cache") from exc
        if stat_module.S_ISLNK(current.st_mode) or not stat_module.S_ISDIR(
            current.st_mode
        ):
            raise AgentError("could_not_sync_plugin_cache")
        directory_fd = open_directory_no_follow_matching(
            path.name,
            current,
            error_text="could_not_sync_plugin_cache",
            changed_text="could_not_sync_plugin_cache",
            dir_fd=parent_fd,
        )
        result = directory_fd
        directory_fd = -1
        return result
    finally:
        if directory_fd >= 0:
            os.close(directory_fd)
        if parent_fd >= 0:
            os.close(parent_fd)


def open_plugin_destination_directory_at(parent_fd: int, name: str) -> int:
    directory_fd = -1
    try:
        try:
            os.mkdir(name, 0o755, dir_fd=parent_fd)
            current = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError as exc:
            raise AgentError("could_not_sync_plugin_cache") from exc
        if stat_module.S_ISLNK(current.st_mode) or not stat_module.S_ISDIR(
            current.st_mode
        ):
            raise AgentError("could_not_sync_plugin_cache")
        directory_fd = open_directory_no_follow_matching(
            name,
            current,
            error_text="could_not_sync_plugin_cache",
            changed_text="could_not_sync_plugin_cache",
            dir_fd=parent_fd,
        )
        result = directory_fd
        directory_fd = -1
        return result
    finally:
        if directory_fd >= 0:
            os.close(directory_fd)


def copy_plugin_cache_dir_fd(
    src_fd: int, dst: Path, *, dst_fd: int | None = None
) -> dict[str, int]:
    owned_dst_fd = dst_fd is None
    if dst_fd is None:
        dst_fd = open_plugin_destination_directory(dst, create=False)
    dst_view = Path(f"/proc/self/fd/{dst_fd}")
    try:
        entry_names = sorted(os.listdir(src_fd))
    except OSError as exc:
        if owned_dst_fd:
            os.close(dst_fd)
        raise AgentError("could_not_sync_plugin_cache") from exc
    counts = {"files": 0, "directories": 0}
    try:
        for name in entry_names:
            if plugin_cache_name_excluded(name):
                continue
            try:
                entry_stat = os.stat(name, dir_fd=src_fd, follow_symlinks=False)
            except OSError as exc:
                raise AgentError("could_not_sync_plugin_cache") from exc
            if stat_module.S_ISLNK(entry_stat.st_mode):
                raise AgentError("plugin source contains unsupported symlink")
            child_dst = dst_view / name
            if stat_module.S_ISDIR(entry_stat.st_mode):
                child_fd = -1
                try:
                    child_fd = open_plugin_destination_directory_at(dst_fd, name)
                    source_child_fd = -1
                    try:
                        source_child_fd = os.open(
                            name,
                            os.O_RDONLY
                            | (os.O_DIRECTORY if hasattr(os, "O_DIRECTORY") else 0)
                            | (os.O_NOFOLLOW if hasattr(os, "O_NOFOLLOW") else 0),
                            dir_fd=src_fd,
                        )
                        opened_stat = os.fstat(source_child_fd)
                        if not stat_module.S_ISDIR(
                            opened_stat.st_mode
                        ) or not source_identity_with_snapshot_matches(
                            opened_stat, entry_stat
                        ):
                            raise AgentError("plugin source changed during copy")
                        child_counts = copy_plugin_cache_dir_fd(
                            source_child_fd,
                            child_dst,
                            dst_fd=child_fd,
                        )
                    finally:
                        if source_child_fd >= 0:
                            os.close(source_child_fd)
                except AgentError:
                    raise
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                finally:
                    if child_fd >= 0:
                        os.close(child_fd)
                counts["directories"] += 1 + child_counts["directories"]
                counts["files"] += child_counts["files"]
                continue
            if stat_module.S_ISREG(entry_stat.st_mode):
                if getattr(entry_stat, "st_nlink", 1) > 1:
                    raise AgentError("plugin source contains unsupported hardlink")
                copy_regular_plugin_file_from_dir_no_follow(
                    src_fd, name, child_dst, entry_stat
                )
                counts["files"] += 1
                continue
            raise AgentError("plugin source contains unsupported file type")
        return counts
    finally:
        if owned_dst_fd:
            os.close(dst_fd)


def copy_plugin_cache_path(src: Path, dst: Path) -> dict[str, int]:
    try:
        src_stat = src.lstat()
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    if stat_module.S_ISLNK(src_stat.st_mode):
        raise AgentError("plugin source contains unsupported symlink")
    if stat_module.S_ISDIR(src_stat.st_mode):
        dst_fd = open_plugin_destination_directory(dst, create=True)
        counts = {"files": 0, "directories": 1}
        src_fd = -1
        try:
            src_fd = open_plugin_source_dir_no_follow(src, src_stat)
            child_counts = copy_plugin_cache_dir_fd(src_fd, dst, dst_fd=dst_fd)
        finally:
            if src_fd >= 0:
                os.close(src_fd)
            os.close(dst_fd)
        counts["files"] += child_counts["files"]
        counts["directories"] += child_counts["directories"]
        return counts
    if stat_module.S_ISREG(src_stat.st_mode):
        if getattr(src_stat, "st_nlink", 1) > 1:
            raise AgentError("plugin source contains unsupported hardlink")
        parent_fd = open_plugin_destination_parent(dst)
        try:
            copy_regular_plugin_file_no_follow(
                src, Path(f"/proc/self/fd/{parent_fd}") / dst.name, src_stat
            )
        finally:
            os.close(parent_fd)
        return {"files": 1, "directories": 0}
    raise AgentError("plugin source contains unsupported file type")


def plugin_cache_name_excluded(name: str) -> bool:
    return (
        name in PLUGIN_CACHE_EXCLUDED_NAMES
        or name.startswith(".")
        or name.startswith("#")
        or name.startswith(".#")
        or name.endswith(PLUGIN_CACHE_EXCLUDED_SUFFIXES)
    )


def remove_real_plugin_cache_dir(path: Path) -> None:
    path = path.expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    path = path.absolute()
    try:
        current = path.lstat()
    except FileNotFoundError:
        return
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    if stat_module.S_ISLNK(current.st_mode) or not stat_module.S_ISDIR(current.st_mode):
        raise AgentError("plugin cache entry is not a real directory")
    if not getattr(shutil.rmtree, "avoids_symlink_attacks", False):
        raise AgentError("safe plugin cache removal is unavailable")
    parent_fd = -1
    entry_fd = -1
    try:
        try:
            parent_stat = path.parent.lstat()
        except OSError as exc:
            raise AgentError("plugin cache entry changed during removal") from exc
        parent_parts = path.parent.parts
        if (
            len(parent_parts) == 5
            and parent_parts[:4] == ("/", "proc", "self", "fd")
            and parent_parts[4].isdigit()
        ):
            try:
                parent_fd = os.dup(int(parent_parts[4]))
                opened_parent = os.fstat(parent_fd)
            except OSError as exc:
                if parent_fd >= 0:
                    os.close(parent_fd)
                raise AgentError("plugin cache entry changed during removal") from exc
            if not stat_module.S_ISDIR(opened_parent.st_mode):
                raise AgentError("plugin cache entry changed during removal")
        else:
            parent_fd = open_directory_no_follow_matching(
                path.parent,
                parent_stat,
                error_text="could_not_sync_plugin_cache",
                changed_text="plugin cache entry changed during removal",
            )
        latest = os.lstat(path.name, dir_fd=parent_fd)
        if not source_identity_matches(latest, current) or not stat_module.S_ISDIR(
            latest.st_mode
        ):
            raise AgentError("plugin cache entry changed during removal")
        entry_fd = open_directory_no_follow_matching(
            path.name,
            current,
            error_text="could_not_sync_plugin_cache",
            changed_text="plugin cache entry changed during removal",
            dir_fd=parent_fd,
        )

        def ignore_top_rmdir(func: Any, error_path: Any, exc_info: Any) -> None:
            if func is os.rmdir and error_path in {".", b"."}:
                return
            raise exc_info[1]

        shutil.rmtree(".", dir_fd=entry_fd, onerror=ignore_top_rmdir)
        latest = os.lstat(path.name, dir_fd=parent_fd)
        if not source_identity_matches(latest, current) or not stat_module.S_ISDIR(
            latest.st_mode
        ):
            raise AgentError("plugin cache entry changed during removal")
        os.rmdir(path.name, dir_fd=parent_fd)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    finally:
        if entry_fd >= 0:
            os.close(entry_fd)
        if parent_fd >= 0:
            os.close(parent_fd)


def valid_plugin_cache_entry_version(entry: Path) -> str | None:
    try:
        entry_stat = entry.lstat()
    except OSError:
        return None
    if stat_module.S_ISLNK(entry_stat.st_mode) or not stat_module.S_ISDIR(
        entry_stat.st_mode
    ):
        return None
    entry_version = public_plugin_version(entry.name)
    if not entry_version:
        return None
    plugin_dir = entry / ".codex-plugin"
    try:
        plugin_dir_stat = plugin_dir.lstat()
    except OSError:
        return None
    if stat_module.S_ISLNK(plugin_dir_stat.st_mode) or not stat_module.S_ISDIR(
        plugin_dir_stat.st_mode
    ):
        return None
    try:
        payload = read_repo_json_object(
            plugin_dir / "plugin.json", "cached plugin manifest"
        )
    except AgentError:
        return None
    cached_version = public_plugin_version(payload.get("version"))
    if payload.get("name") != APP_BRIDGE_NAME or cached_version != entry_version:
        return None
    return entry_version


def _prune_plugin_cache_versions_unlocked(
    cache_root: Path,
    *,
    keep_version: str,
    max_versions: int = MAX_PLUGIN_CACHE_RETAINED_VERSIONS,
) -> dict[str, Any]:
    max_versions = normalize_int_field(
        max_versions, field="max_versions", minimum=1, maximum=MAX_PLUGIN_CACHE_VERSIONS
    )
    try:
        cache_stat = cache_root.lstat()
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    if stat_module.S_ISLNK(cache_stat.st_mode) or not stat_module.S_ISDIR(
        cache_stat.st_mode
    ):
        raise AgentError("could_not_sync_plugin_cache")

    cache_fd = -1
    try:
        cache_fd = open_directory_no_follow_matching(
            cache_root,
            cache_stat,
            error_text="could_not_sync_plugin_cache",
            changed_text="plugin cache root changed during retention",
        )
        cache_fd_path = Path(f"/proc/self/fd/{cache_fd}")
        entries = [cache_fd_path / name for name in sorted(os.listdir(cache_fd))]
        candidates: list[tuple[float, str, str]] = []
        keep_entry = cache_fd_path / keep_version
        current_version_retained = bool(valid_plugin_cache_entry_version(keep_entry))
        for entry in entries:
            version = valid_plugin_cache_entry_version(entry)
            if not version or version == keep_version:
                continue
            try:
                modified = entry.lstat().st_mtime
            except OSError:
                continue
            candidates.append((modified, version, entry.name))
        candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
        keep_slots = max(0, max_versions - 1)
        to_prune = candidates[keep_slots:]
        for _, _, entry_name in to_prune:
            remove_real_plugin_cache_dir(cache_fd_path / entry_name)
        retained_old_count = len(candidates) - len(to_prune)
    except OSError as exc:
        raise AgentError("could_not_sync_plugin_cache") from exc
    finally:
        if cache_fd >= 0:
            os.close(cache_fd)
    return {
        "max_versions": max_versions,
        "current_version_retained": current_version_retained,
        "retained_old_version_count": retained_old_count,
        "pruned_version_count": len(to_prune),
        "raw_output": "not_returned",
    }


def prune_plugin_cache_versions(
    cache_root: Path,
    *,
    keep_version: str,
    max_versions: int = MAX_PLUGIN_CACHE_RETAINED_VERSIONS,
) -> dict[str, Any]:
    with plugin_cache_lock():
        return _prune_plugin_cache_versions_unlocked(
            cache_root,
            keep_version=keep_version,
            max_versions=max_versions,
        )


def _sync_plugin_cache_from_repo_unlocked(
    root: Path | None = None,
    cache_root: Path | None = None,
    retained_versions: int = MAX_PLUGIN_CACHE_RETAINED_VERSIONS,
) -> dict[str, Any]:
    context = codex_home_context()
    if not context.get("ok"):
        raise AgentError(
            "plugin cache install is not allowed from a managed Agentin home"
        )

    source_root = root or repo_root()
    source_root = source_root.expanduser()
    if not source_root.is_absolute():
        source_root = Path.cwd() / source_root
    source_root = source_root.absolute()
    if not is_real_directory_no_symlink(source_root):
        raise AgentError("plugin source root must be a real directory")

    try:
        source_stat = source_root.lstat()
    except OSError as exc:
        raise AgentError("plugin source root must be a real directory") from exc
    with plugin_source_root_operation(source_root, source_stat) as source_view:
        manifest = plugin_manifest_version(source_view)
    if not manifest.get("ok"):
        raise AgentError("plugin manifest name or version is invalid")
    version = manifest["version"]
    target_cache = normalize_plugin_cache_root(cache_root)
    expected_parent_stat = ensure_real_parent(
        target_cache,
        "plugin cache parent directories must be real directories",
    )
    parent_fd = -1
    cache_fd = -1
    try:
        parent_fd = open_directory_no_follow_matching(
            target_cache.parent,
            expected_parent_stat,
            error_text="could_not_sync_plugin_cache",
            changed_text="could_not_sync_plugin_cache",
        )
        try:
            target_stat = os.stat(
                target_cache.name, dir_fd=parent_fd, follow_symlinks=False
            )
        except FileNotFoundError:
            try:
                os.mkdir(target_cache.name, mode=0o755, dir_fd=parent_fd)
                target_stat = os.stat(
                    target_cache.name, dir_fd=parent_fd, follow_symlinks=False
                )
            except OSError as exc:
                raise AgentError("could_not_sync_plugin_cache") from exc
        except OSError as exc:
            raise AgentError("could_not_sync_plugin_cache") from exc
        if stat_module.S_ISLNK(target_stat.st_mode) or not stat_module.S_ISDIR(
            target_stat.st_mode
        ):
            raise AgentError("plugin cache root must be a real directory")
        cache_fd = open_directory_no_follow_matching(
            target_cache.name,
            target_stat,
            error_text="could_not_sync_plugin_cache",
            changed_text="plugin cache root changed during sync",
            dir_fd=parent_fd,
        )
    finally:
        if parent_fd >= 0:
            os.close(parent_fd)

    tmp_name = f".{version}.tmp.{now_id()}.{uuid.uuid4().hex}"
    copied_files = 0
    copied_directories = 0
    tmp_entry_created = False
    backup_entry_created = False
    backup_name: str | None = None
    source_entry_stats: dict[str, os.stat_result] = {}
    try:
        cache_fd_path = Path(f"/proc/self/fd/{cache_fd}")
        tmp_entry = cache_fd_path / tmp_name
        try:
            os.mkdir(tmp_name, mode=0o755, dir_fd=cache_fd)
        except OSError as exc:
            raise AgentError("could_not_sync_plugin_cache") from exc
        tmp_entry_created = True
        copied_directories += 1
        with plugin_source_root_operation(source_root, source_stat) as source_view:
            for name in PLUGIN_CACHE_ALLOWED_FILES:
                original_src = source_root / name
                if not path_present_no_follow(original_src):
                    if name in PLUGIN_CACHE_OPTIONAL_FILES:
                        continue
                    raise AgentError("plugin source is missing a required file")
                try:
                    source_entry_stats[name] = original_src.lstat()
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                if stat_module.S_ISLNK(source_entry_stats[name].st_mode):
                    raise AgentError("plugin source contains unsupported symlink")
                src = source_view / name
                try:
                    current_stat = src.lstat()
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                if not source_identity_with_snapshot_matches(
                    current_stat, source_entry_stats[name]
                ):
                    raise AgentError("plugin source changed during copy")
                counts = copy_plugin_cache_path(src, tmp_entry / name)
                copied_files += counts["files"]
                copied_directories += counts["directories"]
            for name in PLUGIN_CACHE_ALLOWED_DIRS:
                original_src = source_root / name
                if not path_present_no_follow(original_src):
                    if name in PLUGIN_CACHE_OPTIONAL_DIRS:
                        continue
                    raise AgentError("plugin source is missing a required directory")
                try:
                    source_entry_stats[name] = original_src.lstat()
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                if stat_module.S_ISLNK(source_entry_stats[name].st_mode):
                    raise AgentError("plugin source contains unsupported symlink")
                src = source_view / name
                try:
                    current_stat = src.lstat()
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                if not source_identity_with_snapshot_matches(
                    current_stat, source_entry_stats[name]
                ):
                    raise AgentError("plugin source changed during copy")
                counts = copy_plugin_cache_path(src, tmp_entry / name)
                copied_files += counts["files"]
                copied_directories += counts["directories"]
            for name, expected_stat in source_entry_stats.items():
                try:
                    current_stat = (source_root / name).lstat()
                except OSError as exc:
                    raise AgentError("could_not_sync_plugin_cache") from exc
                if not source_identity_with_snapshot_matches(
                    current_stat, expected_stat
                ):
                    raise AgentError("plugin source changed during copy")

        try:
            existing_version_stat = os.lstat(version, dir_fd=cache_fd)
        except FileNotFoundError:
            existing_version_stat = None
        except OSError as exc:
            raise AgentError("could_not_sync_plugin_cache") from exc
        if existing_version_stat is not None:
            if stat_module.S_ISLNK(
                existing_version_stat.st_mode
            ) or not stat_module.S_ISDIR(existing_version_stat.st_mode):
                raise AgentError("plugin cache entry is not a real directory")
            if not getattr(shutil.rmtree, "avoids_symlink_attacks", False):
                raise AgentError("safe plugin cache removal is unavailable")
            try:
                latest_version_stat = os.lstat(version, dir_fd=cache_fd)
            except OSError as exc:
                raise AgentError("plugin cache entry changed during sync") from exc
            if not source_identity_matches(latest_version_stat, existing_version_stat):
                raise AgentError("plugin cache entry changed during sync")
            backup_name = f".{version}.backup.{now_id()}.{uuid.uuid4().hex}"
            try:
                os.rename(
                    version, backup_name, src_dir_fd=cache_fd, dst_dir_fd=cache_fd
                )
            except OSError as exc:
                raise AgentError("could_not_sync_plugin_cache") from exc
            backup_entry_created = True
        try:
            os.replace(tmp_name, version, src_dir_fd=cache_fd, dst_dir_fd=cache_fd)
            tmp_entry_created = False
        except OSError as exc:
            if backup_entry_created and backup_name is not None:
                backup_entry_created = False
                try:
                    os.rename(
                        backup_name, version, src_dir_fd=cache_fd, dst_dir_fd=cache_fd
                    )
                except OSError as restore_exc:
                    raise AgentError("could_not_sync_plugin_cache") from restore_exc
            raise AgentError("could_not_sync_plugin_cache") from exc
        if backup_entry_created and backup_name is not None:
            backup_entry_created = False
            remove_real_plugin_cache_dir(cache_fd_path / backup_name)
    except Exception:
        if tmp_entry_created:
            with contextlib.suppress(Exception):
                remove_real_plugin_cache_dir(tmp_entry)
        raise
    finally:
        if cache_fd >= 0:
            os.close(cache_fd)

    retention = prune_plugin_cache_versions(
        target_cache, keep_version=version, max_versions=retained_versions
    )
    with plugin_source_root_operation(source_root, source_stat) as source_view:
        status = plugin_cache_status(source_view, target_cache)
    return {
        "ok": bool(status.get("ok")),
        "status": "synced" if status.get("ok") else "sync_incomplete",
        "marketplace": "personal",
        "plugin_name": APP_BRIDGE_NAME,
        "version": version,
        "cache_entry": PATH_NOT_RETURNED,
        "cache_entry_state": "set",
        "copied_files": copied_files,
        "copied_directories": copied_directories,
        "excluded_artifacts": [
            "git",
            "bytecode",
            "test_cache",
            "repo_tests",
            "hidden_files",
            "editor_swap",
            "backup_artifacts",
            "hardlinks_rejected",
        ],
        "retention": retention,
        "plugin_cache": status,
        "raw_output": "not_returned",
    }


def sync_plugin_cache_from_repo(
    root: Path | None = None,
    cache_root: Path | None = None,
    retained_versions: int = MAX_PLUGIN_CACHE_RETAINED_VERSIONS,
) -> dict[str, Any]:
    with plugin_cache_lock():
        return _sync_plugin_cache_from_repo_unlocked(
            root, cache_root, retained_versions
        )


def app_id_kind(app_id: str) -> str:
    if app_id.startswith("connector_"):
        return "connector"
    if app_id.startswith("asdk_app_"):
        return "app"
    return "custom"


def master_app_bridge_status() -> dict[str, Any]:
    root = repo_root()
    manifest = root / ".app.json"
    app_manifest = repo_file_status(manifest)
    plugin_apps = plugin_declares_app_manifest(root)
    result: dict[str, Any] = {
        "ok": False,
        "app_name": APP_BRIDGE_NAME,
        "app_manifest": app_manifest,
        "plugin_apps": plugin_apps,
        "registration_mode": "local_plugin_app_manifest",
        "chatgpt_connector_registration": "create_or_refresh_in_chatgpt_developer_mode",
        "raw_output": "not_returned",
    }
    if not app_manifest["regular_file"]:
        result["reason"] = "app_manifest_not_regular_file"
        return result
    try:
        payload = read_repo_json_object(manifest, "app manifest")
    except AgentError as exc:
        result["reason"] = safe_error_text(exc)
        return result
    apps = payload.get("apps")
    if not isinstance(apps, dict):
        result["reason"] = "apps_not_object"
        return result
    app_entry = apps.get(APP_BRIDGE_NAME)
    if not isinstance(app_entry, dict):
        result["reason"] = "codex_master_app_missing"
        return result
    connector_id = app_entry.get("id")
    if not isinstance(connector_id, str) or not connector_id.strip():
        result["reason"] = "connector_id_missing"
        return result
    connector_id = connector_id.strip()
    id_prefix_ok = any(
        connector_id.startswith(prefix) and len(connector_id) > len(prefix)
        for prefix in APP_BRIDGE_ID_PREFIXES
    )
    result.update(
        {
            "connector_id": connector_id,
            "connector_id_kind": app_id_kind(connector_id),
            "connector_id_format_ok": id_prefix_ok,
            "ok": id_prefix_ok and bool(plugin_apps.get("ok")),
        }
    )
    if not result["ok"]:
        result["reason"] = "plugin_or_connector_id_not_ready"
    return result


def plugin_mcp_manifest_status(root: Path | None = None) -> dict[str, Any]:
    manifest = (root or repo_root()) / ".mcp.json"
    status = repo_file_status(manifest)
    result: dict[str, Any] = {
        "path": PATH_NOT_RETURNED,
        "path_state": status["path_state"],
        "exists": status["exists"],
        "regular_file": status["regular_file"],
        "server_declared": False,
        "ok": False,
        "raw_output": "not_returned",
    }
    if not status["regular_file"]:
        result["reason"] = "mcp_manifest_not_regular_file"
        return result
    try:
        payload = read_repo_json_object(manifest, "MCP manifest")
    except AgentError as exc:
        result["reason"] = safe_error_text(exc)
        return result
    servers = payload.get("mcpServers")
    server = servers.get(MCP_SERVER_NAME) if isinstance(servers, dict) else None
    if not isinstance(server, dict):
        result["reason"] = "mcp_server_declaration_missing"
        return result
    result["server_declared"] = True
    command = server.get("command")
    if not isinstance(command, str) or not command.strip():
        result["reason"] = "mcp_server_command_missing"
        return result
    result["ok"] = True
    return result


def master_plugin_status() -> dict[str, Any]:
    entrypoint = _runtime_mcp_entrypoint()
    root = repo_root()
    manifest = root / ".codex-plugin" / "plugin.json"
    app_manifest = root / ".app.json"
    skill = root / "skills" / "codex-master-fleet" / "SKILL.md"
    mcp_manifest_declaration = plugin_declares_mcp_manifest(root)
    mcp_manifest_status = plugin_mcp_manifest_status(root)
    app_bridge = master_app_bridge_status()
    health = _read_bound_mcp_health(entrypoint)
    mcp_registration = health.registration
    client_config = health.client_config
    startup_self_test = mcp_command_startup_self_test(entrypoint)
    cache_status = plugin_cache_status(root)
    return {
        "ok": (
            bool(app_bridge.get("ok"))
            and bool(mcp_registration.get("ok"))
            and bool(startup_self_test.get("ok"))
            and bool(cache_status.get("ok"))
            and bool(client_config.get("ok"))
            and bool(mcp_manifest_declaration.get("ok"))
            and bool(mcp_manifest_status.get("ok"))
        ),
        "repo": PATH_NOT_RETURNED,
        "repo_state": "set",
        "plugin_manifest": repo_file_status(manifest),
        "plugin_manifest_version": plugin_manifest_version(root),
        "plugin_mcp_manifest": mcp_manifest_declaration,
        "plugin_cache": cache_status,
        "mcp_manifest": mcp_manifest_status,
        "app_manifest": repo_file_status(app_manifest),
        "skill": repo_file_status(skill),
        "app_bridge": app_bridge,
        "mcp_registration": mcp_registration,
        "client_config": client_config,
        "startup_self_test": startup_self_test,
        "codex_home_context": codex_home_context(),
        "raw_output": "not_returned",
    }


def version_without_build_metadata(version: str) -> str:
    return version.split("+", 1)[0]


def git_first_line(args: list[str], *, cwd: Path | None = None) -> str:
    cp = run_command(["git", *args], cwd=cwd or repo_root())
    if cp.returncode != 0:
        return ""
    return cp.stdout.splitlines()[0].strip() if cp.stdout.splitlines() else ""


def git_count(args: list[str], *, cwd: Path | None = None) -> int | None:
    text = git_first_line(args, cwd=cwd)
    try:
        return int(text)
    except (TypeError, ValueError):
        return None


def git_release_tags(root: Path) -> list[str]:
    cp = run_command(
        ["git", "tag", "--merged", "HEAD", "--sort=-v:refname", "--list", "v[0-9]*"],
        cwd=root,
    )
    if cp.returncode != 0:
        return []
    return [
        line.strip()
        for line in cp.stdout.splitlines()
        if RELEASE_TAG_RE.fullmatch(line.strip())
    ]


def github_release_tags(root: Path) -> dict[str, Any]:
    if not shutil.which("gh"):
        return {
            "available": False,
            "status": "gh_unavailable",
            "tags": [],
            "raw_output": "not_returned",
        }
    cp = run_command(["gh", "release", "list", "--limit", "100"], cwd=root)
    if cp.returncode != 0:
        return {
            "available": False,
            "status": "gh_release_list_failed",
            "tags": [],
            "raw_output": "not_returned",
        }
    tags: list[str] = []
    for line in cp.stdout.splitlines():
        columns = [column.strip() for column in line.split("\t") if column.strip()]
        tag = next(
            (column for column in columns if RELEASE_TAG_RE.fullmatch(column)), None
        )
        if tag and tag not in tags:
            tags.append(tag)
    return {
        "available": True,
        "status": "ok",
        "tags": tags,
        "raw_output": "not_returned",
    }


def master_release_status() -> dict[str, Any]:
    root = repo_root()
    package_version = __version__
    plugin_manifest = plugin_manifest_version(root)
    plugin_version = plugin_manifest.get("version") if plugin_manifest.get("ok") else ""
    plugin_base_version = (
        version_without_build_metadata(str(plugin_version)) if plugin_version else ""
    )
    expected_tag = f"v{package_version}"
    local_tags = git_release_tags(root)
    head_commit = git_first_line(["rev-parse", "HEAD"], cwd=root)
    current_tag_exists = expected_tag in local_tags
    current_tag_commit = (
        git_first_line(["rev-list", "-n", "1", expected_tag], cwd=root)
        if current_tag_exists
        else ""
    )
    current_tag_points_at_head = bool(
        current_tag_commit and head_commit and current_tag_commit == head_commit
    )
    latest_local_tag = local_tags[0] if local_tags else ""
    commits_since_latest_local_tag = (
        git_count(["rev-list", "--count", f"{latest_local_tag}..HEAD"], cwd=root)
        if latest_local_tag
        else None
    )
    gh_releases = github_release_tags(root)
    github_tags = gh_releases["tags"]
    latest_github_release_tag = github_tags[0] if github_tags else ""
    commits_since_latest_github_release = (
        git_count(
            ["rev-list", "--count", f"{latest_github_release_tag}..HEAD"], cwd=root
        )
        if latest_github_release_tag
        else None
    )
    local_without_github = (
        [tag for tag in local_tags if tag not in set(github_tags)]
        if gh_releases["available"]
        else []
    )
    blockers: list[str] = []
    warnings: list[str] = []
    if plugin_base_version != package_version:
        blockers.append("plugin_version_mismatch")
    if not current_tag_exists:
        blockers.append("current_version_tag_missing")
    elif not current_tag_points_at_head:
        blockers.append("current_version_tag_not_at_head")
    if gh_releases["available"] and expected_tag not in github_tags:
        blockers.append("github_release_missing_for_current_version")
    if commits_since_latest_github_release:
        warnings.append("latest_github_release_behind_head")
    if local_without_github:
        warnings.append("local_tags_without_github_release")
    return {
        "ok": not blockers,
        "release_needed": bool(blockers or commits_since_latest_github_release),
        "package_version": package_version,
        "plugin_version": plugin_version,
        "plugin_base_version": plugin_base_version,
        "expected_tag": expected_tag,
        "current_tag_exists": current_tag_exists,
        "current_tag_points_at_head": current_tag_points_at_head,
        "latest_local_tag": latest_local_tag,
        "commits_since_latest_local_tag": commits_since_latest_local_tag,
        "latest_github_release_tag": latest_github_release_tag,
        "commits_since_latest_github_release": commits_since_latest_github_release,
        "github_release_status": gh_releases["status"],
        "github_release_available": gh_releases["available"],
        "current_version_has_github_release": expected_tag in github_tags,
        "local_tag_without_github_release_count": len(local_without_github),
        "local_tags_without_github_release": local_without_github[:10],
        "blockers": blockers,
        "warnings": warnings,
        "raw_output": "not_returned",
    }


def parse_systemctl_show(output: str) -> dict[str, str]:
    result: dict[str, str] = {}
    for line in output.splitlines():
        key, separator, value = line.partition("=")
        if separator and key:
            result[key] = value
    return result


def systemctl_user_show(unit: str, properties: tuple[str, ...]) -> dict[str, Any]:
    command = ["systemctl", "--user", "show", unit, "--no-pager"]
    for prop in properties:
        command.extend(["--property", prop])
    cp = run_command(command)
    parsed = parse_systemctl_show(cp.stdout)
    return {
        "ok": cp.returncode == 0,
        "unit": unit,
        "returncode": cp.returncode,
        "properties": {prop: parsed.get(prop, "") for prop in properties},
        "raw_output": "not_returned",
    }


def safe_unit_text(path: Path, status: dict[str, Any]) -> tuple[str, bool]:
    if not status.get("regular_file") or status.get("symlink"):
        return "", False
    try:
        return read_private_regular_text(
            path, MAX_SYSTEMD_UNIT_BYTES, "systemd unit could not be read"
        ), True
    except AgentError:
        return "", False


def _resource_monitor_unit_path(root: Path, name: str) -> Path:
    if name not in RESOURCE_MONITOR_UNIT_NAMES:
        raise AgentError("resource_monitor_unit_invalid")
    return root / "systemd" / "user" / name


def _resource_monitor_stat_identity(current: os.stat_result) -> dict[str, int]:
    return {
        "dev": int(current.st_dev),
        "ino": int(current.st_ino),
        "mode": int(current.st_mode),
        "size": int(current.st_size),
        "mtime_ns": int(current.st_mtime_ns),
    }


def _resource_monitor_stat_matches_identity(
    current: os.stat_result,
    expected: Mapping[str, Any],
) -> bool:
    return _resource_monitor_stat_identity(current) == {
        "dev": int(expected.get("dev", -1)),
        "ino": int(expected.get("ino", -1)),
        "mode": int(expected.get("mode", -1)),
        "size": int(expected.get("size", -1)),
        "mtime_ns": int(expected.get("mtime_ns", -1)),
    }


def _resource_monitor_validate_directory_stat(
    current: os.stat_result, *, final: bool = False
) -> None:
    if not stat_module.S_ISDIR(current.st_mode) or stat_module.S_ISLNK(current.st_mode):
        raise AgentError("resource_monitor_systemd_directory_untrusted")
    current_uid = os.getuid() if hasattr(os, "getuid") else -1
    if final and current.st_uid != current_uid:
        raise AgentError("resource_monitor_systemd_directory_untrusted")
    sticky_shared = bool(
        current.st_mode & 0o002 and current.st_mode & stat_module.S_ISVTX
    )
    if current.st_uid not in {0, current_uid} or (
        current.st_mode & 0o022 and (final or not sticky_shared)
    ):
        raise AgentError("resource_monitor_systemd_directory_untrusted")


def _resource_monitor_open_directory(path: Path) -> int:
    if not isinstance(path, Path) or not path.is_absolute():
        raise AgentError("resource_monitor_systemd_directory_untrusted")
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    directory_fd = -1
    try:
        directory_fd = os.open(path.anchor, flags)
        components = path.parts[1:]
        for index, part in enumerate(components):
            created = False
            try:
                current = os.stat(part, dir_fd=directory_fd, follow_symlinks=False)
            except FileNotFoundError:
                os.mkdir(part, 0o700, dir_fd=directory_fd)
                current = os.stat(part, dir_fd=directory_fd, follow_symlinks=False)
                created = True
                if not stat_module.S_ISDIR(current.st_mode):
                    raise AgentError("resource_monitor_systemd_directory_untrusted")
            _resource_monitor_validate_directory_stat(
                current, final=index == len(components) - 1
            )
            child_fd = os.open(part, flags, dir_fd=directory_fd)
            opened = os.fstat(child_fd)
            if opened.st_dev != current.st_dev or opened.st_ino != current.st_ino:
                os.close(child_fd)
                raise AgentError("resource_monitor_systemd_directory_changed")
            if created:
                os.fchmod(child_fd, 0o700)
            os.close(directory_fd)
            directory_fd = child_fd
        final_stat = os.fstat(directory_fd)
        _resource_monitor_validate_directory_stat(final_stat, final=True)
        chained_fd = open_directory_chain_no_follow_matching(
            path,
            final_stat,
            error_text="resource_monitor_systemd_directory_untrusted",
            changed_text="resource_monitor_systemd_directory_changed",
        )
        chained_stat = os.fstat(chained_fd)
        if (
            chained_stat.st_dev != final_stat.st_dev
            or chained_stat.st_ino != final_stat.st_ino
        ):
            os.close(chained_fd)
            raise AgentError("resource_monitor_systemd_directory_changed")
        os.close(directory_fd)
        return chained_fd
    except AgentError:
        if directory_fd >= 0:
            os.close(directory_fd)
        raise
    except (FileNotFoundError, OSError) as exc:
        if directory_fd >= 0:
            os.close(directory_fd)
        raise AgentError("resource_monitor_systemd_directory_untrusted") from exc


def _resource_monitor_reopen_directory(path: Path, expected: tuple[int, int]) -> None:
    try:
        current = path.lstat()
        fd = open_directory_chain_no_follow_matching(
            path,
            current,
            error_text="target_parent_rebound",
            changed_text="target_parent_rebound",
        )
    except (AgentError, OSError) as exc:
        raise AgentError("target_parent_rebound") from exc
    try:
        opened = os.fstat(fd)
        _resource_monitor_validate_directory_stat(opened, final=True)
        if (opened.st_dev, opened.st_ino) != expected:
            raise AgentError("target_parent_rebound")
    finally:
        os.close(fd)


def _resource_monitor_read_regular_at_fd(
    directory_fd: int,
    name: str,
    *,
    missing_ok: bool,
) -> tuple[bytes | None, os.stat_result | None]:
    try:
        before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        if missing_ok:
            return None, None
        raise AgentError("resource_monitor_unit_invalid") from None
    except OSError as exc:
        raise AgentError("resource_monitor_unit_unreadable") from exc
    if (
        not stat_module.S_ISREG(before.st_mode)
        or getattr(before, "st_nlink", 1) != 1
        or before.st_size > MAX_SYSTEMD_UNIT_BYTES
    ):
        raise AgentError("resource_monitor_unit_must_be_regular")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    fd = -1
    try:
        fd = os.open(name, flags, dir_fd=directory_fd)
        opened = os.fstat(fd)
        if not _resource_monitor_stat_matches_identity(
            opened, _resource_monitor_stat_identity(before)
        ):
            raise AgentError("resource_monitor_unit_changed")
        raw = bytearray()
        while len(raw) <= MAX_SYSTEMD_UNIT_BYTES:
            chunk = os.read(fd, min(8192, MAX_SYSTEMD_UNIT_BYTES + 1 - len(raw)))
            if not chunk:
                break
            raw.extend(chunk)
        after = os.fstat(fd)
        if not _resource_monitor_stat_matches_identity(
            after, _resource_monitor_stat_identity(before)
        ):
            raise AgentError("resource_monitor_unit_changed")
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("resource_monitor_unit_unreadable") from exc
    finally:
        if fd >= 0:
            os.close(fd)
    if len(raw) > MAX_SYSTEMD_UNIT_BYTES:
        raise AgentError("resource_monitor_unit_too_large")
    return bytes(raw), after


def _resource_monitor_read_source(path: Path) -> tuple[bytes, os.stat_result]:
    try:
        parent_stat = path.parent.lstat()
    except OSError as exc:
        raise AgentError("resource_monitor_source_invalid") from exc
    if not directory_chain_is_real_no_symlink(path.parent):
        raise AgentError("resource_monitor_source_invalid")
    parent_fd = open_directory_no_follow_matching(
        path.parent,
        parent_stat,
        error_text="resource_monitor_source_invalid",
        changed_text="resource_monitor_source_changed",
    )
    try:
        raw, current = _resource_monitor_read_regular_at_fd(
            parent_fd, path.name, missing_ok=False
        )
    finally:
        os.close(parent_fd)
    assert raw is not None and current is not None
    return raw, current


def _resource_monitor_read_sources(root: Path) -> dict[str, dict[str, Any]]:
    sources: dict[str, dict[str, Any]] = {}
    for name in RESOURCE_MONITOR_UNIT_NAMES:
        raw, current = _resource_monitor_read_source(
            _resource_monitor_unit_path(root, name)
        )
        sources[name] = {
            "bytes": raw,
            "mode": stat_module.S_IMODE(current.st_mode),
            "stat": current,
        }
    return sources


def _resource_monitor_temp_bytes(
    directory_fd: int,
    name: str,
    data: bytes,
    mode: int,
) -> tuple[str, os.stat_result]:
    temp_name = f".{name}.{uuid.uuid4().hex}.stage"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    fd = -1
    created = False
    keep = False
    try:
        fd = os.open(temp_name, flags, 0o600, dir_fd=directory_fd)
        created = True
        os.fchmod(fd, mode)
        view = memoryview(data)
        while view:
            view = view[os.write(fd, view) :]
        os.fsync(fd)
        os.close(fd)
        fd = -1
        current = os.stat(temp_name, dir_fd=directory_fd, follow_symlinks=False)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
            or current.st_size != len(data)
        ):
            raise AgentError("resource_monitor_unit_stage_failed")
        keep = True
        return temp_name, current
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("resource_monitor_unit_stage_failed") from exc
    finally:
        if fd >= 0:
            os.close(fd)
        if created and not keep:
            with contextlib.suppress(OSError):
                os.unlink(temp_name, dir_fd=directory_fd)


def _resource_monitor_fsync_directory(directory_fd: int) -> None:
    os.fsync(directory_fd)


def _resource_monitor_journal_mark(
    journal: dict[str, Any], field: str, value: Any = True
) -> None:
    journal[field] = value


def _resource_monitor_snapshot_targets(
    directory_fd: int,
) -> dict[str, os.stat_result | None]:
    snapshots: dict[str, os.stat_result | None] = {}
    for name in RESOURCE_MONITOR_UNIT_NAMES:
        try:
            current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            snapshots[name] = None
            continue
        except OSError as exc:
            raise AgentError("resource_monitor_unit_unreadable") from exc
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
            or current.st_size > MAX_SYSTEMD_UNIT_BYTES
        ):
            raise AgentError("resource_monitor_unit_must_be_regular")
        snapshots[name] = current
    return snapshots


def _resource_monitor_new_journal(
    name: str,
    original: os.stat_result | None,
    staged_name: str,
    staged: os.stat_result,
) -> dict[str, Any]:
    token = uuid.uuid4().hex
    return {
        "name": name,
        "original_present": original is not None,
        "original_identity": None
        if original is None
        else _resource_monitor_stat_identity(original),
        "backup_name": f".{name}.{token}.backup" if original is not None else None,
        "backup_identity": None,
        "original_moved": False,
        "staged_name": staged_name,
        "staged_identity": _resource_monitor_stat_identity(staged),
        "staged_linked": False,
        "staged_durable": False,
        "link_durable": False,
        "stage_cleaned": False,
        "installed_identity": None,
        "cleanup_name": f".{name}.{token}.cleanup",
        "installed_moved": False,
        "cleanup_done": False,
        "cleanup_quarantine_name": None,
        "cleanup_moved": False,
        "cleanup_removed": False,
        "cleanup_restored": False,
        "restored": False,
        "manual_recovery": False,
    }


def _resource_monitor_name_must_be_absent(directory_fd: int, name: str) -> None:
    try:
        os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return
    except OSError as exc:
        raise AgentError("resource_monitor_transaction_name_unreadable") from exc
    raise AgentError("resource_monitor_transaction_name_collision")


def _resource_monitor_error_append(journal: dict[str, Any], code: str) -> None:
    journal["manual_recovery"] = True
    journal.setdefault("errors", []).append(_resource_monitor_error(code))


def _resource_monitor_remove_exact_identity(
    directory_fd: int,
    name: str,
    expected: Mapping[str, Any],
    *,
    journal: dict[str, Any] | None = None,
    missing_ok: bool = True,
) -> list[dict[str, Any]]:
    try:
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return (
            []
            if missing_ok
            else [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]
        )
    except OSError:
        return [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]
    if not stat_module.S_ISREG(
        current.st_mode
    ) or not _resource_monitor_stat_matches_identity(current, expected):
        if journal is not None:
            _resource_monitor_error_append(journal, "manual_recovery_required")
        return [_resource_monitor_error("manual_recovery_required")]

    quarantine_name = ""
    quarantine_fd = -1
    quarantine_created = False
    moved = False
    removed = False
    for _ in range(8):
        candidate = f".{name}.{uuid.uuid4().hex}.quarantine"
        try:
            os.mkdir(candidate, 0o700, dir_fd=directory_fd)
            quarantine_name = candidate
            quarantine_created = True
            break
        except FileExistsError:
            continue
        except OSError:
            return [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]
    if not quarantine_created:
        return [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]

    try:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        quarantine_fd = os.open(quarantine_name, flags, dir_fd=directory_fd)
        quarantine_stat = os.fstat(quarantine_fd)
        if (
            not stat_module.S_ISDIR(quarantine_stat.st_mode)
            or stat_module.S_IMODE(quarantine_stat.st_mode) & 0o077
        ):
            return [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]
        os.rename(
            name,
            "object",
            src_dir_fd=directory_fd,
            dst_dir_fd=quarantine_fd,
        )
        moved = True
        if journal is not None:
            journal["cleanup_quarantine_name"] = quarantine_name
            _resource_monitor_journal_mark(journal, "cleanup_moved", True)
        moved_stat = os.stat("object", dir_fd=quarantine_fd, follow_symlinks=False)
        moved_identity = _resource_monitor_stat_identity(moved_stat)
        if stat_module.S_ISREG(
            moved_stat.st_mode
        ) and _resource_monitor_stat_matches_identity(moved_stat, expected):
            os.unlink("object", dir_fd=quarantine_fd)
            os.fsync(quarantine_fd)
            os.close(quarantine_fd)
            quarantine_fd = -1
            os.rmdir(quarantine_name, dir_fd=directory_fd)
            os.fsync(directory_fd)
            removed = True
            if journal is not None:
                _resource_monitor_journal_mark(journal, "cleanup_removed", True)
            return []

        try:
            os.link(
                "object",
                name,
                src_dir_fd=quarantine_fd,
                dst_dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileExistsError:
            if journal is not None:
                _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        restored = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if not _resource_monitor_stat_matches_identity(restored, moved_identity):
            if journal is not None:
                _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        moved_again = os.stat("object", dir_fd=quarantine_fd, follow_symlinks=False)
        if not _resource_monitor_stat_matches_identity(moved_again, moved_identity):
            if journal is not None:
                _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        os.unlink("object", dir_fd=quarantine_fd)
        os.fsync(quarantine_fd)
        os.close(quarantine_fd)
        quarantine_fd = -1
        os.rmdir(quarantine_name, dir_fd=directory_fd)
        os.fsync(directory_fd)
        removed = True
        if journal is not None:
            _resource_monitor_journal_mark(journal, "cleanup_restored", True)
        return [_resource_monitor_error("manual_recovery_required")]
    except (AgentError, OSError):
        return [_resource_monitor_error("resource_monitor_exact_cleanup_failed")]
    finally:
        if quarantine_fd >= 0:
            os.close(quarantine_fd)
        if quarantine_created and not moved and not removed:
            with contextlib.suppress(OSError):
                os.rmdir(quarantine_name, dir_fd=directory_fd)


def _resource_monitor_restore_backup_no_overwrite(
    directory_fd: int,
    journal: dict[str, Any],
) -> list[dict[str, Any]]:
    backup_name = journal.get("backup_name")
    if not backup_name:
        return []
    errors: list[dict[str, Any]] = []
    original_identity = journal.get("original_identity")
    try:
        backup = os.stat(backup_name, dir_fd=directory_fd, follow_symlinks=False)
        if not isinstance(
            original_identity, Mapping
        ) or not _resource_monitor_stat_matches_identity(backup, original_identity):
            _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        try:
            os.link(
                backup_name,
                journal["name"],
                src_dir_fd=directory_fd,
                dst_dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileExistsError:
            _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        restored = os.stat(journal["name"], dir_fd=directory_fd, follow_symlinks=False)
        if not _resource_monitor_stat_matches_identity(restored, original_identity):
            _resource_monitor_error_append(journal, "manual_recovery_required")
            return [_resource_monitor_error("manual_recovery_required")]
        journal["cleanup_kind"] = "restore"
        cleanup_errors = _resource_monitor_remove_exact_identity(
            directory_fd,
            backup_name,
            original_identity,
            journal=journal,
            missing_ok=False,
        )
        if cleanup_errors:
            return cleanup_errors
        _resource_monitor_journal_mark(journal, "restored")
        return errors
    except (AgentError, OSError):
        errors.append(_resource_monitor_error("resource_monitor_backup_restore_failed"))
        return errors


def _resource_monitor_displace_original(
    directory_fd: int,
    journal: dict[str, Any],
) -> None:
    if not journal["original_present"]:
        return
    backup_name = journal["backup_name"]
    _resource_monitor_name_must_be_absent(directory_fd, backup_name)
    os.rename(
        journal["name"],
        backup_name,
        src_dir_fd=directory_fd,
        dst_dir_fd=directory_fd,
    )
    _resource_monitor_journal_mark(journal, "backup_exists", True)
    backup = os.stat(backup_name, dir_fd=directory_fd, follow_symlinks=False)
    journal["backup_identity"] = _resource_monitor_stat_identity(backup)
    if not _resource_monitor_stat_matches_identity(
        backup, journal["original_identity"]
    ):
        errors = _resource_monitor_restore_backup_no_overwrite(directory_fd, journal)
        if errors:
            journal.setdefault("errors", []).extend(errors)
        raise AgentError("resource_monitor_target_changed")
    _resource_monitor_journal_mark(journal, "original_moved")
    _resource_monitor_fsync_directory(directory_fd)


def _resource_monitor_link_staged(
    directory_fd: int,
    journal: dict[str, Any],
) -> None:
    try:
        os.link(
            journal["staged_name"],
            journal["name"],
            src_dir_fd=directory_fd,
            dst_dir_fd=directory_fd,
            follow_symlinks=False,
        )
    except FileExistsError as exc:
        _resource_monitor_error_append(journal, "manual_recovery_required")
        raise AgentError("resource_monitor_target_changed") from exc
    installed = os.stat(journal["name"], dir_fd=directory_fd, follow_symlinks=False)
    if not _resource_monitor_stat_matches_identity(
        installed, journal["staged_identity"]
    ):
        _resource_monitor_error_append(journal, "manual_recovery_required")
        raise AgentError("resource_monitor_target_changed")
    journal["installed_identity"] = _resource_monitor_stat_identity(installed)
    _resource_monitor_journal_mark(journal, "staged_linked")
    _resource_monitor_fsync_directory(directory_fd)
    _resource_monitor_journal_mark(journal, "link_durable")
    stage = os.stat(journal["staged_name"], dir_fd=directory_fd, follow_symlinks=False)
    if not _resource_monitor_stat_matches_identity(stage, journal["staged_identity"]):
        _resource_monitor_error_append(journal, "manual_recovery_required")
        raise AgentError("resource_monitor_target_changed")
    journal["cleanup_kind"] = "stage"
    cleanup_errors = _resource_monitor_remove_exact_identity(
        directory_fd,
        journal["staged_name"],
        journal["staged_identity"],
        journal=journal,
        missing_ok=False,
    )
    if cleanup_errors:
        journal.setdefault("errors", []).extend(cleanup_errors)
        raise AgentError("resource_monitor_target_changed")
    _resource_monitor_journal_mark(journal, "stage_cleaned")


def _resource_monitor_mutate_unit(directory_fd: int, journal: dict[str, Any]) -> None:
    _resource_monitor_displace_original(directory_fd, journal)
    _resource_monitor_link_staged(directory_fd, journal)


def _resource_monitor_remove_installed(
    directory_fd: int,
    journal: dict[str, Any],
) -> list[dict[str, Any]]:
    if not journal.get("staged_linked") or not journal.get("installed_identity"):
        return []
    cleanup_name = journal["cleanup_name"]
    errors: list[dict[str, Any]] = []
    try:
        _resource_monitor_name_must_be_absent(directory_fd, cleanup_name)
        os.rename(
            journal["name"],
            cleanup_name,
            src_dir_fd=directory_fd,
            dst_dir_fd=directory_fd,
        )
        _resource_monitor_journal_mark(journal, "installed_moved")
        moved = os.stat(cleanup_name, dir_fd=directory_fd, follow_symlinks=False)
        if not _resource_monitor_stat_matches_identity(
            moved, journal["installed_identity"]
        ):
            _resource_monitor_error_append(journal, "manual_recovery_required")
            return _resource_monitor_remove_exact_identity(
                directory_fd,
                cleanup_name,
                journal["installed_identity"],
                journal=journal,
                missing_ok=False,
            )
        journal["cleanup_kind"] = "installed"
        cleanup_errors = _resource_monitor_remove_exact_identity(
            directory_fd,
            cleanup_name,
            journal["installed_identity"],
            journal=journal,
            missing_ok=False,
        )
        if cleanup_errors:
            return cleanup_errors
        _resource_monitor_journal_mark(journal, "cleanup_done")
        _resource_monitor_fsync_directory(directory_fd)
    except FileNotFoundError:
        return []
    except (AgentError, OSError):
        errors.append(
            _resource_monitor_error("resource_monitor_installed_cleanup_failed")
        )
    return errors


def _resource_monitor_cleanup_stage(
    directory_fd: int,
    journal: dict[str, Any],
) -> list[dict[str, Any]]:
    if journal.get("stage_cleaned"):
        return []
    try:
        stage = os.stat(
            journal["staged_name"], dir_fd=directory_fd, follow_symlinks=False
        )
    except FileNotFoundError:
        _resource_monitor_journal_mark(journal, "stage_cleaned")
        return []
    except OSError:
        return [_resource_monitor_error("resource_monitor_temp_cleanup_failed")]
    if not _resource_monitor_stat_matches_identity(stage, journal["staged_identity"]):
        _resource_monitor_error_append(journal, "manual_recovery_required")
        return [_resource_monitor_error("manual_recovery_required")]
    journal["cleanup_kind"] = "stage"
    errors = _resource_monitor_remove_exact_identity(
        directory_fd,
        journal["staged_name"],
        journal["staged_identity"],
        journal=journal,
        missing_ok=False,
    )
    if errors:
        return errors
    _resource_monitor_journal_mark(journal, "stage_cleaned")
    return []


def _resource_monitor_rollback_unit(
    directory_fd: int,
    journal: dict[str, Any],
) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    errors.extend(_resource_monitor_cleanup_stage(directory_fd, journal))
    errors.extend(_resource_monitor_remove_installed(directory_fd, journal))
    if journal.get("backup_exists") or journal.get("original_moved"):
        errors.extend(
            _resource_monitor_restore_backup_no_overwrite(directory_fd, journal)
        )
    errors.extend(journal.get("errors", []))
    return errors


def _resource_monitor_commit_backups(
    directory_fd: int,
    journals: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    changed = False
    for journal in journals:
        backup_name = journal.get("backup_name")
        if not backup_name:
            continue
        try:
            backup = os.stat(backup_name, dir_fd=directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            continue
        except OSError:
            errors.append(
                _resource_monitor_error("resource_monitor_backup_cleanup_failed")
            )
            continue
        if not _resource_monitor_stat_matches_identity(
            backup, journal.get("original_identity", {})
        ):
            errors.append(_resource_monitor_error("manual_recovery_required"))
            continue
        journal["cleanup_kind"] = "backup"
        cleanup_errors = _resource_monitor_remove_exact_identity(
            directory_fd,
            backup_name,
            journal.get("original_identity", {}),
            journal=journal,
            missing_ok=False,
        )
        if cleanup_errors:
            errors.extend(cleanup_errors)
        else:
            journal["backup_cleaned"] = True
            changed = True
    if changed:
        try:
            _resource_monitor_fsync_directory(directory_fd)
        except OSError:
            errors.append(
                _resource_monitor_error("resource_monitor_backup_cleanup_failed")
            )
    return errors


def _resource_monitor_systemctl_show(unit: str) -> dict[str, Any]:
    properties = (
        "LoadState",
        "ActiveState",
        "SubState",
        "UnitFileState",
        "FragmentPath",
        "ControlGroup",
        "TasksCurrent",
        "MainPID",
    )
    cp = run_command(
        [
            "systemctl",
            "--user",
            "show",
            unit,
            "--no-pager",
            *(argument for prop in properties for argument in ("--property", prop)),
        ],
        timeout=RESOURCE_MONITOR_SYSTEMCTL_TIMEOUT_SECONDS,
    )
    parsed = parse_systemctl_show(cp.stdout)
    return {
        "ok": cp.returncode == 0,
        "returncode": cp.returncode,
        "properties": {prop: parsed.get(prop, "") for prop in properties},
    }


def _resource_monitor_systemctl(
    operation: list[str],
) -> subprocess.CompletedProcess[str]:
    return run_command(
        ["systemctl", "--user", *operation],
        timeout=RESOURCE_MONITOR_SYSTEMCTL_TIMEOUT_SECONDS,
    )


def _resource_monitor_canonical_surface_check(
    *,
    target_dir: Path,
    target_identity: tuple[int, int],
    directory_fd: int,
    lock_fd: int,
    lock_path: Path,
    journals: list[dict[str, Any]],
) -> None:
    try:
        pinned = os.fstat(directory_fd)
    except OSError as exc:
        raise AgentError("target_parent_rebound") from exc
    _resource_monitor_validate_directory_stat(pinned, final=True)
    if (pinned.st_dev, pinned.st_ino) != target_identity:
        raise AgentError("target_parent_rebound")
    _resource_monitor_reopen_directory(target_dir, target_identity)

    try:
        lock_stat = os.fstat(lock_fd)
        canonical_lock = os.stat(lock_path, follow_symlinks=False)
    except OSError as exc:
        raise AgentError("install_lock_rebound") from exc
    if (
        not stat_module.S_ISREG(lock_stat.st_mode)
        or not stat_module.S_ISREG(canonical_lock.st_mode)
        or getattr(lock_stat, "st_nlink", 1) != 1
        or getattr(canonical_lock, "st_nlink", 1) != 1
        or (lock_stat.st_dev, lock_stat.st_ino)
        != (canonical_lock.st_dev, canonical_lock.st_ino)
    ):
        raise AgentError("install_lock_rebound")

    for journal in journals:
        name = journal.get("name")
        installed_identity = journal.get("installed_identity")
        if (
            name not in RESOURCE_MONITOR_UNIT_NAMES
            or not journal.get("staged_linked")
            or not isinstance(installed_identity, Mapping)
        ):
            _resource_monitor_error_append(journal, "manual_recovery_required")
            raise AgentError("resource_monitor_unit_identity_mismatch")
        try:
            current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        except OSError as exc:
            _resource_monitor_error_append(journal, "manual_recovery_required")
            raise AgentError("resource_monitor_unit_identity_mismatch") from exc
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
            or not _resource_monitor_stat_matches_identity(current, installed_identity)
        ):
            _resource_monitor_error_append(journal, "manual_recovery_required")
            raise AgentError("resource_monitor_unit_identity_mismatch")


def _resource_monitor_error(code: str, returncode: int | None = None) -> dict[str, Any]:
    error: dict[str, Any] = {"code": code}
    if returncode is not None:
        error["returncode"] = int(returncode)
    return error


_RESOURCE_MONITOR_SUPPORTED_UNIT_FILE_STATES = frozenset(
    {"not-found", "enabled", "enabled-runtime", "disabled", "static"}
)
_RESOURCE_MONITOR_SUPPORTED_ACTIVE_STATES = frozenset({"active", "inactive"})


def _resource_monitor_previous_state(show: Mapping[str, Any]) -> dict[str, Any]:
    properties = show.get("properties") if isinstance(show, Mapping) else None
    if not isinstance(properties, Mapping):
        properties = {}
    load_state = properties.get("LoadState")
    raw_unit_file_state = properties.get("UnitFileState")
    active_state = properties.get("ActiveState")
    if not show.get("ok", True) and load_state != "not-found":
        raise AgentError("resource_monitor_service_state_unknown")
    if active_state not in _RESOURCE_MONITOR_SUPPORTED_ACTIVE_STATES:
        raise AgentError("resource_monitor_service_state_unknown")
    if (
        load_state == "not-found"
        and raw_unit_file_state in {"", None}
        and active_state == "inactive"
    ):
        unit_file_state = "not-found"
    elif load_state != "not-found" and raw_unit_file_state in {
        "enabled",
        "enabled-runtime",
        "disabled",
        "static",
    }:
        unit_file_state = raw_unit_file_state
    else:
        raise AgentError("resource_monitor_service_state_unknown")
    return {
        "load_state": load_state,
        "unit_file_state": unit_file_state,
        "active_state": active_state,
        "enabled": unit_file_state in {"enabled", "enabled-runtime"},
        "active": active_state == "active",
    }


def _resource_monitor_restore_service_state(
    previous: Mapping[str, Any],
) -> list[dict[str, Any]]:
    previous_unit_file_state = previous.get("unit_file_state")
    previous_active_state = previous.get("active_state")
    if (
        previous_unit_file_state not in _RESOURCE_MONITOR_SUPPORTED_UNIT_FILE_STATES
        or previous_active_state not in _RESOURCE_MONITOR_SUPPORTED_ACTIVE_STATES
    ):
        raise AgentError("rollback_service_state_unknown")
    try:
        current = _resource_monitor_previous_state(
            _resource_monitor_systemctl_show(RESOURCE_MONITOR_SERVICE_NAME)
        )
    except AgentError as exc:
        if str(exc) == "resource_monitor_service_state_unknown":
            return [_resource_monitor_error("rollback_service_state_unknown")]
        raise

    errors: list[dict[str, Any]] = []

    def run(operation: list[str]) -> None:
        try:
            result = _resource_monitor_systemctl(operation)
            if result.returncode != 0:
                errors.append(
                    _resource_monitor_error(
                        "resource_monitor_rollback_state_failed", result.returncode
                    )
                )
        except Exception:
            errors.append(
                _resource_monitor_error("resource_monitor_rollback_state_failed")
            )

    current_unit_file_state = current["unit_file_state"]
    if previous_unit_file_state in {"not-found", "disabled"}:
        if current_unit_file_state == "enabled":
            run(["disable", RESOURCE_MONITOR_SERVICE_NAME])
        elif current_unit_file_state == "enabled-runtime":
            run(["disable", "--runtime", RESOURCE_MONITOR_SERVICE_NAME])
    elif previous_unit_file_state == "enabled":
        if current_unit_file_state in {"enabled-runtime", "disabled", "not-found"}:
            run(["enable", RESOURCE_MONITOR_SERVICE_NAME])
    elif previous_unit_file_state == "enabled-runtime":
        if current_unit_file_state in {"disabled", "not-found"}:
            run(["enable", "--runtime", RESOURCE_MONITOR_SERVICE_NAME])
        elif current_unit_file_state == "enabled":
            run(["disable", RESOURCE_MONITOR_SERVICE_NAME])
            run(["enable", "--runtime", RESOURCE_MONITOR_SERVICE_NAME])

    if previous_active_state == "active" and current["active_state"] == "inactive":
        run(["start", RESOURCE_MONITOR_SERVICE_NAME])
    elif previous_active_state == "inactive" and current["active_state"] == "active":
        run(["stop", RESOURCE_MONITOR_SERVICE_NAME])
    return errors


def _resource_monitor_rollback_result(
    primary_error: dict[str, Any],
    *,
    directory_fd: int,
    journals: list[dict[str, Any]],
    activation_attempted: bool,
    previous_service_state: Mapping[str, Any],
    preexisting_rollback_errors: list[dict[str, Any]] | None = None,
    rollback_reload_allowed: bool = True,
    external_ops_allowed: bool = True,
) -> dict[str, Any]:
    rollback_errors: list[dict[str, Any]] = list(preexisting_rollback_errors or [])
    for journal in reversed(journals):
        try:
            rollback_errors.extend(
                _resource_monitor_rollback_unit(directory_fd, journal)
            )
        except Exception:
            rollback_errors.append(
                _resource_monitor_error("resource_monitor_rollback_unit_failed")
            )
    if rollback_reload_allowed and external_ops_allowed:
        try:
            reload_result = _resource_monitor_systemctl(["daemon-reload"])
            if reload_result.returncode != 0:
                rollback_errors.append(
                    _resource_monitor_error(
                        "rollback_daemon_reload_failed", reload_result.returncode
                    )
                )
        except Exception:
            rollback_errors.append(
                _resource_monitor_error("rollback_daemon_reload_failed")
            )
    if activation_attempted and external_ops_allowed:
        try:
            rollback_errors.extend(
                _resource_monitor_restore_service_state(previous_service_state)
            )
        except AgentError as exc:
            rollback_errors.append(_resource_monitor_error(str(exc)))
        except Exception:
            rollback_errors.append(
                _resource_monitor_error("resource_monitor_rollback_state_failed")
            )
    rollback_error: dict[str, Any] | None = None
    if rollback_errors:
        if len(rollback_errors) == 1:
            rollback_error = rollback_errors[0]
        else:
            rollback_error = {"code": "rollback_failed", "errors": rollback_errors}
    return {
        "ok": False,
        "status": "rollback_failed" if rollback_error else "rolled_back",
        "primary_error": primary_error,
        "rollback_error": rollback_error,
        "raw_output": "not_returned",
    }


def install_resource_monitor(
    *,
    root: Path | None = None,
    systemd_user_dir: Path | None = None,
    force: bool = False,
) -> dict[str, Any]:
    root = root or repo_root()
    target_dir = systemd_user_dir or (Path.home() / ".config" / "systemd" / "user")
    with install_lock() as lock_handle:
        sources = _resource_monitor_read_sources(root)
        directory_fd = -1
        snapshots: dict[str, os.stat_result | None] = {}
        journals: list[dict[str, Any]] = []
        activation_attempted = False
        previous_service_state: dict[str, Any] = {}
        rollback_reload_allowed = True
        external_ops_allowed = True
        mutation_started = False
        preexisting_rollback_errors: list[dict[str, Any]] = []
        lock_path = (LOCK_DIR / "install.lock").absolute()
        try:
            directory_fd = _resource_monitor_open_directory(target_dir)
            opened_target = os.fstat(directory_fd)
            target_identity = (opened_target.st_dev, opened_target.st_ino)
            snapshots = _resource_monitor_snapshot_targets(directory_fd)
            if not force:
                for name, source in sources.items():
                    if snapshots[name] is None:
                        continue
                    target_bytes, target_stat = _resource_monitor_read_regular_at_fd(
                        directory_fd,
                        name,
                        missing_ok=False,
                    )
                    if (
                        target_bytes != source["bytes"]
                        or stat_module.S_IMODE(target_stat.st_mode) != source["mode"]
                    ):
                        raise AgentError("resource_monitor_target_stale_use_force")
            service_show = _resource_monitor_systemctl_show(
                RESOURCE_MONITOR_SERVICE_NAME
            )
            slice_show = _resource_monitor_systemctl_show(RESOURCE_MONITOR_SLICE_NAME)
            for show in (service_show, slice_show):
                if not show["ok"] and show["returncode"] not in {1}:
                    raise AgentError("resource_monitor_systemctl_unavailable")
            previous_service_state = _resource_monitor_previous_state(service_show)
            for name, source in sources.items():
                staged_name, staged_stat = _resource_monitor_temp_bytes(
                    directory_fd,
                    name,
                    source["bytes"],
                    source["mode"],
                )
                journals.append(
                    _resource_monitor_new_journal(
                        name, snapshots[name], staged_name, staged_stat
                    )
                )
            _resource_monitor_fsync_directory(directory_fd)
            for journal in journals:
                _resource_monitor_journal_mark(journal, "staged_durable")
            for journal in journals:
                mutation_started = True
                _resource_monitor_mutate_unit(directory_fd, journal)

            try:
                _resource_monitor_canonical_surface_check(
                    target_dir=target_dir,
                    target_identity=target_identity,
                    directory_fd=directory_fd,
                    lock_fd=lock_handle.fileno(),
                    lock_path=lock_path,
                    journals=journals,
                )
            except AgentError as exc:
                external_ops_allowed = False
                rollback_reload_allowed = False
                preexisting_rollback_errors.append(
                    _resource_monitor_error("manual_recovery_required")
                )
                raise _ResourceMonitorPrimaryFailure(
                    _resource_monitor_error(str(exc))
                ) from exc

            reload_result = _resource_monitor_systemctl(["daemon-reload"])
            if reload_result.returncode != 0:
                raise _ResourceMonitorPrimaryFailure(
                    _resource_monitor_error(
                        "daemon_reload_failed", reload_result.returncode
                    )
                )
            try:
                _resource_monitor_canonical_surface_check(
                    target_dir=target_dir,
                    target_identity=target_identity,
                    directory_fd=directory_fd,
                    lock_fd=lock_handle.fileno(),
                    lock_path=lock_path,
                    journals=journals,
                )
            except AgentError as exc:
                external_ops_allowed = False
                rollback_reload_allowed = False
                preexisting_rollback_errors.append(
                    _resource_monitor_error("manual_recovery_required")
                )
                raise _ResourceMonitorPrimaryFailure(
                    _resource_monitor_error(str(exc))
                ) from exc
            activation_attempted = True
            enable_result = _resource_monitor_systemctl(
                ["enable", "--now", RESOURCE_MONITOR_SERVICE_NAME]
            )
            if enable_result.returncode != 0:
                raise _ResourceMonitorPrimaryFailure(
                    _resource_monitor_error(
                        "enable_now_failed", enable_result.returncode
                    )
                )
            backup_cleanup_errors = _resource_monitor_commit_backups(
                directory_fd, journals
            )
            if backup_cleanup_errors:
                return {
                    "ok": False,
                    "status": "manual_recovery_required",
                    "primary_error": _resource_monitor_error(
                        "resource_monitor_backup_cleanup_failed"
                    ),
                    "rollback_error": {
                        "code": "manual_recovery_required",
                        "errors": backup_cleanup_errors,
                    },
                    "raw_output": "not_returned",
                }
            return {
                "ok": True,
                "service": RESOURCE_MONITOR_SERVICE_NAME,
                "units_materialized": True,
                "enabled": True,
                "active": True,
                "raw_output": "not_returned",
            }
        except _ResourceMonitorPrimaryFailure as primary:
            return _resource_monitor_rollback_result(
                primary.error,
                directory_fd=directory_fd,
                journals=journals,
                activation_attempted=activation_attempted,
                previous_service_state=previous_service_state,
                preexisting_rollback_errors=preexisting_rollback_errors,
                rollback_reload_allowed=rollback_reload_allowed,
                external_ops_allowed=external_ops_allowed,
            )
        except Exception as exc:
            if directory_fd < 0:
                raise
            if not journals:
                raise
            rollback_reload_allowed = rollback_reload_allowed and mutation_started
            return _resource_monitor_rollback_result(
                _resource_monitor_error(
                    str(exc)
                    if isinstance(exc, AgentError)
                    else "resource_monitor_install_failed"
                ),
                directory_fd=directory_fd,
                journals=journals,
                activation_attempted=activation_attempted,
                previous_service_state=previous_service_state,
                preexisting_rollback_errors=preexisting_rollback_errors,
                rollback_reload_allowed=rollback_reload_allowed,
                external_ops_allowed=external_ops_allowed,
            )
        finally:
            if directory_fd >= 0:
                os.close(directory_fd)


class _ResourceMonitorPrimaryFailure(Exception):
    def __init__(self, error: dict[str, Any]):
        self.error = error


def install_resource_scope_gate(
    *,
    root: Path | None = None,
    target: Path | None = None,
) -> dict[str, Any]:
    if os.geteuid() != 0:
        raise AgentError("resource_scope_gate_install_requires_root")
    root = root or repo_root()
    target = target or Path(RESOURCE_SCOPE_GATE_PATH)
    if (
        not isinstance(root, Path)
        or not isinstance(target, Path)
        or not target.is_absolute()
        or target.name != RESOURCE_SCOPE_GATE_NAME
    ):
        raise AgentError("resource_scope_gate_target_untrusted")
    source = root / "bin" / RESOURCE_SCOPE_GATE_NAME
    raw, _source_stat = _resource_monitor_read_source(source)
    try:
        parent_stat = target.parent.lstat()
    except OSError as exc:
        raise AgentError("resource_scope_gate_target_untrusted") from exc
    if not stat_module.S_ISDIR(
        parent_stat.st_mode
    ) or not directory_chain_is_real_no_symlink(target.parent):
        raise AgentError("resource_scope_gate_target_untrusted")
    directory_fd = -1
    staged_name: str | None = None
    try:
        try:
            directory_fd = _resource_monitor_open_directory(target.parent)
        except AgentError as exc:
            raise AgentError("resource_scope_gate_target_untrusted") from exc
        try:
            installed, installed_stat = _resource_monitor_read_regular_at_fd(
                directory_fd,
                target.name,
                missing_ok=True,
            )
        except AgentError as exc:
            raise AgentError("resource_scope_gate_target_untrusted") from exc
        if (
            installed == raw
            and installed_stat is not None
            and stat_module.S_IMODE(installed_stat.st_mode) == 0o755
        ):
            return {
                "ok": True,
                "status": "already_installed",
                "raw_output": "not_returned",
            }
        staged_name, _staged_stat = _resource_monitor_temp_bytes(
            directory_fd, target.name, raw, 0o755
        )
        os.replace(
            staged_name, target.name, src_dir_fd=directory_fd, dst_dir_fd=directory_fd
        )
        staged_name = None
        os.fsync(directory_fd)
        try:
            verified, verified_stat = _resource_monitor_read_regular_at_fd(
                directory_fd,
                target.name,
                missing_ok=False,
            )
        except AgentError as exc:
            raise AgentError("resource_scope_gate_target_untrusted") from exc
        if (
            verified != raw
            or verified_stat is None
            or stat_module.S_IMODE(verified_stat.st_mode) != 0o755
        ):
            raise AgentError("resource_scope_gate_target_untrusted")
        return {"ok": True, "status": "installed", "raw_output": "not_returned"}
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError("resource_scope_gate_install_failed") from exc
    finally:
        if staged_name is not None and directory_fd >= 0:
            with contextlib.suppress(OSError):
                os.unlink(staged_name, dir_fd=directory_fd)
        if directory_fd >= 0:
            os.close(directory_fd)


def native_hook_coverage_status(
    *, root: Path | None = None, now: float | None = None
) -> dict[str, Any]:
    root = root or repo_root()
    manifest_state = repo_file_status(root / "hooks" / "hooks.json")
    manifest_installed = bool(manifest_state.get("regular_file")) and not bool(
        manifest_state.get("symlink")
    )
    coverage_state = "missing"
    current_time = time.time() if now is None else float(now)
    try:
        raw = read_private_regular_text(
            NATIVE_AGENT_REGISTRY_FILE,
            MAX_NATIVE_AGENT_REGISTRY_BYTES,
            "native hook coverage unavailable",
        )
        payload = json.loads(raw)
        normalized = (
            _native_agent_normalize_registry(payload)
            if isinstance(payload, dict)
            else None
        )
        sessions = payload.get("sessions") if isinstance(payload, dict) else None
        canonical = (
            isinstance(normalized, dict)
            and isinstance(payload, dict)
            and json.dumps(
                payload, sort_keys=True, separators=(",", ":"), allow_nan=False
            )
            == json.dumps(
                normalized, sort_keys=True, separators=(",", ":"), allow_nan=False
            )
        )
        fresh = (
            canonical
            and payload.get("schema_version") == 2
            and isinstance(payload.get("agents"), list)
            and isinstance(sessions, list)
            and isinstance(payload.get("reservations"), list)
            and any(
                isinstance(session, dict)
                and _validate_native_agent_identifier(
                    session.get("session_id"), NATIVE_AGENT_ID_RE
                )
                and session.get("activity_state") == "active"
                and isinstance(session.get("updated_at"), (int, float))
                and 0
                <= current_time - float(session["updated_at"])
                <= NATIVE_AGENT_RETENTION_SECONDS
                for session in sessions
            )
        )
        coverage_state = "fresh_v2" if fresh else "stale"
    except (AgentError, TypeError, ValueError, json.JSONDecodeError):
        coverage_state = "missing"
    result: dict[str, Any] = {
        "manifest_installed": manifest_installed,
        "manifest_state": "installed" if manifest_installed else "missing_or_invalid",
        "fresh_native_coverage": coverage_state == "fresh_v2",
        "coverage_state": coverage_state,
        "ok": manifest_installed and coverage_state == "fresh_v2",
        "raw_output": "not_returned",
    }
    if not result["fresh_native_coverage"]:
        result["action"] = RESOURCE_MONITOR_HOOK_ACTION
    return result


def _resource_monitor_unit_status(
    source: Path,
    target: Path,
) -> dict[str, Any]:
    source_state = repo_file_status(source)
    target_state = repo_file_status(target)
    result: dict[str, Any] = {
        "state": "missing",
        "materialized": False,
        "source_regular": bool(source_state.get("regular_file"))
        and not bool(source_state.get("symlink")),
        "target_regular": bool(target_state.get("regular_file"))
        and not bool(target_state.get("symlink")),
    }
    if target_state.get("exists") and not result["target_regular"]:
        result["state"] = "invalid"
        return result
    if not target_state.get("exists"):
        return result
    if not result["source_regular"]:
        result["state"] = "source_invalid"
        return result
    try:
        source_bytes, source_stat = _resource_monitor_read_source(source)
        target_bytes, target_stat = _resource_monitor_read_source(target)
    except AgentError:
        result["state"] = "unreadable"
        return result
    result["state"] = (
        "materialized"
        if source_bytes == target_bytes
        and stat_module.S_IMODE(source_stat.st_mode)
        == stat_module.S_IMODE(target_stat.st_mode)
        else "stale"
    )
    result["materialized"] = result["state"] == "materialized"
    return result


def _resource_monitor_fragment_state(fragment: str, target: Path) -> str:
    if not fragment:
        return "missing"
    try:
        return "real" if Path(fragment).absolute() == target.absolute() else "synthetic"
    except (OSError, RuntimeError):
        return "synthetic"


def resource_monitor_status(
    *,
    root: Path | None = None,
    systemd_user_dir: Path | None = None,
) -> dict[str, Any]:
    root = root or repo_root()
    target_dir = systemd_user_dir or (Path.home() / ".config" / "systemd" / "user")
    checks: dict[str, Any] = {}
    for name in RESOURCE_MONITOR_UNIT_NAMES:
        source = _resource_monitor_unit_path(root, name)
        target = target_dir / name
        checks[
            "monitor_unit" if name == RESOURCE_MONITOR_SERVICE_NAME else "slice_unit"
        ] = _resource_monitor_unit_status(
            source,
            target,
        )
    service = _resource_monitor_systemctl_show(RESOURCE_MONITOR_SERVICE_NAME)
    slice_status = _resource_monitor_systemctl_show(RESOURCE_MONITOR_SLICE_NAME)
    service_props = service["properties"]
    slice_props = slice_status["properties"]
    monitor_fragment = _resource_monitor_fragment_state(
        service_props.get("FragmentPath", ""),
        target_dir / RESOURCE_MONITOR_SERVICE_NAME,
    )
    slice_fragment = _resource_monitor_fragment_state(
        slice_props.get("FragmentPath", ""),
        target_dir / RESOURCE_MONITOR_SLICE_NAME,
    )
    monitor_child = bool(
        service_props.get("ControlGroup")
        and slice_props.get("ControlGroup")
        and service_props["ControlGroup"].startswith(slice_props["ControlGroup"] + "/")
    )
    tasks_current = slice_props.get("TasksCurrent", "")
    slice_empty = tasks_current in {"", "0"} and not monitor_child
    checks["monitor_unit"].update(
        {
            "loaded": service_props.get("LoadState") == "loaded",
            "active": service_props.get("ActiveState") == "active",
            "fragment_state": monitor_fragment,
            "materialized": checks["monitor_unit"]["materialized"]
            and monitor_fragment == "real",
        }
    )
    if monitor_fragment != "real":
        checks["monitor_unit"]["blocker"] = (
            "synthetic_fragment"
            if monitor_fragment == "synthetic"
            else "fragment_not_materialized"
        )
    slice_materialized = (
        checks["slice_unit"]["materialized"] and slice_fragment == "real"
    )
    checks["slice_runtime"] = {
        "state": "inactive_empty_normal"
        if slice_props.get("ActiveState") == "inactive"
        and slice_empty
        and slice_materialized
        else "inactive_unmaterialized"
        if slice_props.get("ActiveState") == "inactive" and slice_empty
        else "active_anchor"
        if slice_props.get("ActiveState") == "active"
        else "unavailable",
        "real_fragment": slice_fragment == "real",
        "monitor_child": monitor_child,
        "empty": slice_empty,
    }
    if slice_fragment != "real":
        checks["slice_runtime"]["blocker"] = (
            "synthetic_fragment"
            if slice_fragment == "synthetic"
            else "fragment_not_materialized"
        )
    snapshot: dict[str, Any] = {"valid": False, "fresh": False}
    try:
        operator_status = _read_resource_operator_status()
        snapshot = {
            "valid": isinstance(operator_status, ResourceEvidenceOperatorViewV2),
            "fresh": isinstance(operator_status, ResourceEvidenceOperatorViewV2),
            "generation": operator_status.generation
            if isinstance(operator_status, ResourceEvidenceOperatorViewV2)
            else None,
        }
    except Exception:
        pass
    checks["snapshot"] = snapshot
    hook = native_hook_coverage_status(root=root)
    result: dict[str, Any] = {
        "ok": bool(
            checks["monitor_unit"]["materialized"]
            and checks["monitor_unit"]["loaded"]
            and checks["monitor_unit"]["active"]
            and checks["slice_unit"]["materialized"]
            and checks["slice_runtime"]["real_fragment"]
            and checks["slice_runtime"]["monitor_child"]
            and checks["snapshot"]["fresh"]
        ),
        "checks": checks,
        "hook": hook,
        "raw_output": "not_returned",
    }
    if hook.get("action"):
        result["action"] = hook["action"]
    return result


def watchdog_unit_file_status(
    root: Path | None = None, systemd_user_dir: Path | None = None
) -> dict[str, Any]:
    root = root or repo_root()
    installed_dir = systemd_user_dir or (Path.home() / ".config" / "systemd" / "user")
    repo_service = root / "systemd" / "user" / WATCHDOG_SERVICE_NAME
    repo_timer = root / "systemd" / "user" / WATCHDOG_TIMER_NAME
    installed_service = installed_dir / WATCHDOG_SERVICE_NAME
    installed_timer = installed_dir / WATCHDOG_TIMER_NAME

    repo_service_status = repo_file_status(repo_service)
    repo_timer_status = repo_file_status(repo_timer)
    installed_service_status = repo_file_status(installed_service)
    installed_timer_status = repo_file_status(installed_timer)
    repo_service_text, repo_service_readable = safe_unit_text(
        repo_service, repo_service_status
    )
    repo_timer_text, repo_timer_readable = safe_unit_text(repo_timer, repo_timer_status)
    installed_service_text, installed_service_readable = safe_unit_text(
        installed_service, installed_service_status
    )
    installed_timer_text, installed_timer_readable = safe_unit_text(
        installed_timer, installed_timer_status
    )
    hardening_directives = {
        directive: directive in installed_service_text
        for directive in WATCHDOG_REQUIRED_HARDENING_DIRECTIVES
    }
    exec_flags = {
        flag: flag in installed_service_text for flag in WATCHDOG_REQUIRED_EXEC_FLAGS
    }
    hardening_ok = installed_service_readable and all(hardening_directives.values())
    exec_flags_ok = installed_service_readable and all(exec_flags.values())
    service_matches_repo = (
        installed_service_readable
        and repo_service_readable
        and installed_service_text == repo_service_text
    )
    timer_matches_repo = (
        installed_timer_readable
        and repo_timer_readable
        and installed_timer_text == repo_timer_text
    )
    ok = hardening_ok and exec_flags_ok and service_matches_repo and timer_matches_repo
    return {
        "ok": ok,
        "service": {
            "repo": repo_service_status,
            "installed": installed_service_status,
            "repo_readable": repo_service_readable,
            "installed_readable": installed_service_readable,
            "matches_repo": service_matches_repo,
            "hardening_ok": hardening_ok,
            "hardening_directives": hardening_directives,
            "exec_flags_ok": exec_flags_ok,
            "exec_flags": exec_flags,
        },
        "timer": {
            "repo": repo_timer_status,
            "installed": installed_timer_status,
            "repo_readable": repo_timer_readable,
            "installed_readable": installed_timer_readable,
            "matches_repo": timer_matches_repo,
        },
        "raw_output": "not_returned",
    }


def watchdog_security_status() -> dict[str, Any]:
    if not shutil.which("systemd-analyze"):
        return {
            "ok": False,
            "available": False,
            "status": "systemd_analyze_unavailable",
            "raw_output": "not_returned",
        }
    cp = run_command(
        ["systemd-analyze", "--user", "security", WATCHDOG_SERVICE_NAME, "--no-pager"]
    )
    text = strip_ansi(
        (cp.stdout + "\n" + cp.stderr)[-MAX_SYSTEMD_SECURITY_OUTPUT_BYTES:]
    )
    match = re.search(
        r"Overall exposure level[^:]*:\s*([0-9]+(?:\.[0-9]+)?)\s+([A-Z]+)", text
    )
    exposure_score: float | None = None
    exposure_level = ""
    if match:
        exposure_score = float(match.group(1))
        exposure_level = match.group(2)
    parsed = exposure_score is not None
    acceptable = parsed and exposure_score <= 4.0 and exposure_level in {"OK", "SAFE"}
    return {
        "ok": cp.returncode == 0 and acceptable,
        "available": True,
        "status": "ok"
        if cp.returncode == 0 and parsed
        else ("unparsed" if cp.returncode == 0 else "failed"),
        "returncode": cp.returncode,
        "exposure_score": exposure_score,
        "exposure_level": exposure_level,
        "threshold_score": 4.0,
        "raw_output": "not_returned",
    }


def master_watchdog_status(
    root: Path | None = None, systemd_user_dir: Path | None = None
) -> dict[str, Any]:
    timer_properties = (
        "LoadState",
        "ActiveState",
        "SubState",
        "Result",
        "Unit",
        "NextElapseUSecRealtime",
        "LastTriggerUSec",
    )
    service_properties = (
        "LoadState",
        "ActiveState",
        "SubState",
        "Result",
        "ExecMainCode",
        "ExecMainStatus",
        "ExecMainStartTimestamp",
    )
    timer = systemctl_user_show(WATCHDOG_TIMER_NAME, timer_properties)
    service = systemctl_user_show(WATCHDOG_SERVICE_NAME, service_properties)
    unit_files = watchdog_unit_file_status(root=root, systemd_user_dir=systemd_user_dir)
    security = watchdog_security_status()
    timer_props = timer.get("properties", {})
    service_props = service.get("properties", {})
    timer_ok = (
        bool(timer.get("ok"))
        and timer_props.get("LoadState") == "loaded"
        and timer_props.get("ActiveState") == "active"
        and timer_props.get("SubState") in {"waiting", "running", "elapsed"}
    )
    service_ok = (
        bool(service.get("ok"))
        and service_props.get("LoadState") == "loaded"
        and bool(service_props.get("ExecMainStartTimestamp"))
        and service_props.get("Result") == "success"
        and service_props.get("ExecMainStatus") == "0"
    )
    checks = {
        "timer_active": timer_ok,
        "service_last_run_success": service_ok,
        "unit_files_hardened_and_current": bool(unit_files.get("ok")),
        "security_score_ok": bool(security.get("ok")),
    }
    return {
        "ok": all(checks.values()),
        "checks": checks,
        "timer": timer,
        "service": service,
        "unit_files": unit_files,
        "security": security,
        "raw_output": "not_returned",
    }


