def fleet_wrapper_text(
    agent: AgentDescriptor,
    executable: Path,
    *,
    bash_executable: Path = FLEET_BASH_EXECUTABLE,
    taskset_executable: Path = FLEET_TASKSET_EXECUTABLE,
    true_executable: Path = FLEET_TRUE_EXECUTABLE,
) -> str:
    if agent.runner is RunnerKind.CODEX_CLI:
        home_lines = (
            f"export CODEX_HOME={shlex.quote(str(agent.home))}",
            "unset GEMINI_CLI_HOME",
        )
    else:
        quoted_home = shlex.quote(str(agent.home))
        home_lines = (
            f"export HOME={quoted_home}",
            f"export GEMINI_CLI_HOME={quoted_home}",
            "unset CODEX_HOME",
        )
    retained = {
        Provider.OPENAI_API: {"OPENAI_API_KEY"},
        Provider.GEMINI_API: {"GEMINI_API_KEY"},
        Provider.HUGGINGFACE_INFERENCE: {"HF_TOKEN"},
    }.get(agent.provider, set())
    secret_variables = {
        "OPENAI_API_KEY",
        "GEMINI_API_KEY",
        "HF_TOKEN",
        "CODEX_ACCESS_TOKEN",
        "GOOGLE_API_KEY",
        "GOOGLE_APPLICATION_CREDENTIALS",
        "GOOGLE_CLOUD_PROJECT",
        "GOOGLE_CLOUD_LOCATION",
        "GOOGLE_GENAI_USE_VERTEXAI",
    }
    unset_variables = " ".join(sorted(secret_variables - retained))
    executable_word = shlex.quote(str(executable))
    taskset_word = shlex.quote(str(taskset_executable))
    true_word = shlex.quote(str(true_executable))
    return "\n".join(
        [
            f"#!{bash_executable}",
            "set -euo pipefail",
            "",
            *home_lines,
            f"unset {unset_variables}",
            f"if {taskset_word} --cpu-list 4-10 {true_word} >/dev/null 2>&1; then",
            f'  exec {taskset_word} --cpu-list 4-10 {executable_word} "$@"',
            "fi",
            f'exec {executable_word} "$@"',
            "",
        ]
    )


def fleet_minimal_config(agent: AgentDescriptor) -> tuple[str, str]:
    if agent.runner is RunnerKind.GEMINI_CLI:
        document = {
            "advanced": {
                "autoConfigureMemory": False,
                "ignoreLocalEnv": True,
            },
            "general": {
                "defaultApprovalMode": "default",
                "enableAutoUpdate": False,
                "enableAutoUpdateNotification": False,
                "maxAttempts": 1,
                "retryFetchErrors": False,
            },
            "privacy": {"usageStatisticsEnabled": False},
            "security": {
                "auth": {"enforcedType": "gemini-api-key"},
                "disableYoloMode": True,
            },
        }
        return ".gemini/settings.json", json.dumps(
            document, indent=2, sort_keys=True
        ) + "\n"

    lines = [
        f"model = {json.dumps(agent.model)}",
        'approval_policy = "never"',
        'sandbox_mode = "danger-full-access"',
    ]
    if agent.provider is Provider.OLLAMA_LOCAL:
        lines.extend(
            [
                'model_provider = "ollama-launch"',
                f"model_catalog_json = {json.dumps(str(agent.home / 'model.json'))}",
                "",
                "[model_providers.ollama-launch]",
                'name = "Ollama"',
                'base_url = "http://127.0.0.1:11434/v1/"',
                'wire_api = "responses"',
            ]
        )
    elif agent.provider is Provider.HUGGINGFACE_INFERENCE:
        lines.append('model_provider = "huggingface"')
    if agent.series_prefix == "q" and agent.skill_profile == "teamleiterin":
        lines.extend(
            [
                "",
                f"[mcp_servers.{MCP_SERVER_NAME}]",
                f"command = {json.dumps(str(_runtime_mcp_entrypoint()))}",
                f"startup_timeout_sec = {RECOMMENDED_MCP_STARTUP_TIMEOUT_SECONDS}",
                f"default_tools_approval_mode = {json.dumps(MCP_DEFAULT_TOOLS_APPROVAL_MODE)}",
            ]
        )
    lines.extend(
        [
            "",
            "[tui]",
            "animations = false",
            "",
            f"[projects.{json.dumps(str(agent.home))}]",
            'trust_level = "trusted"',
        ]
    )
    if agent.provider is Provider.HUGGINGFACE_INFERENCE:
        lines.extend(
            [
                "",
                "[model_providers.huggingface]",
                'name = "Hugging Face"',
                'base_url = "https://router.huggingface.co/v1"',
                'env_key = "HF_TOKEN"',
                'wire_api = "responses"',
            ]
        )
    return "config.toml", "\n".join((*lines, ""))


def _fleet_candidate_series(
    *,
    prefix: str,
    count: int,
    runner: str,
    provider: str,
    model: str,
    account_id: str | None,
    enabled: bool,
    skill_profile: str = "generic",
    task_profile: str = "standard",
) -> FleetSeries:
    try:
        runner_kind = RunnerKind(runner)
        provider_kind = Provider(provider)
    except (TypeError, ValueError):
        raise AgentError("invalid_series") from None
    return FleetSeries(
        prefix,
        f"Series {prefix.upper()}" if isinstance(prefix, str) else "Series",
        count,
        runner_kind,
        provider_kind,
        model,
        account_id,
        enabled,
        bounded_text(skill_profile, field="skill_profile", max_chars=64, required=True)
        or "generic",
        bounded_text(task_profile, field="task_profile", max_chars=64, required=True)
        or "standard",
    )


def _fleet_plan_materialized_ids(prefix: str, count: int) -> set[str]:
    try:
        root_stat = AGENT_POOL_ROOT.lstat()
    except FileNotFoundError:
        return set()
    except OSError as exc:
        raise AgentError("fleet_home_state_unknown") from exc
    _fleet_private_directory_stat(root_stat, "fleet_home_state_unknown")
    root_fd = open_directory_no_follow_matching(
        AGENT_POOL_ROOT,
        root_stat,
        error_text="fleet_home_state_unknown",
        changed_text="fleet_home_state_unknown",
    )
    present: set[str] = set()
    try:
        for ordinal in range(1, count + 1):
            agent_id = f"{prefix}{ordinal}"
            try:
                current = os.stat(agent_id, dir_fd=root_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise AgentError("fleet_home_state_unknown") from exc
            _fleet_private_directory_stat(current, "fleet_home_state_unknown")
            present.add(agent_id)
    finally:
        os.close(root_fd)
    return present


def _fleet_materialization_sets(
    existing: FleetSeries | None,
    candidate: FleetSeries,
    present_ids: set[str],
) -> dict[str, tuple[str, ...]]:
    old_count = existing.count if existing is not None else 0
    target_ids = {
        f"{candidate.prefix}{ordinal}" for ordinal in range(1, candidate.count + 1)
    }
    managed_changed = existing is not None and (
        existing.runner is not candidate.runner
        or existing.provider is not candidate.provider
        or existing.model != candidate.model
        or existing.skill_profile != candidate.skill_profile
        or existing.task_profile != candidate.task_profile
    )
    tail_ids = {
        f"{candidate.prefix}{ordinal}"
        for ordinal in range(old_count + 1, candidate.count + 1)
    }
    if existing is None and candidate.enabled:
        create_ids = target_ids
    elif candidate.enabled:
        create_ids = target_ids - present_ids
    elif existing is not None and present_ids:
        create_ids = tail_ids - present_ids
    else:
        create_ids = set()
    update_ids = present_ids & target_ids if managed_changed else set()
    keep_ids = (present_ids & target_ids) - update_ids - create_ids
    remove_ids = present_ids - target_ids

    def ordered(values: set[str]) -> tuple[str, ...]:
        return tuple(
            sorted(values, key=lambda item: int(item[len(candidate.prefix) :]))
        )

    return {
        "create_ids": ordered(create_ids),
        "keep_ids": ordered(keep_ids),
        "update_ids": ordered(update_ids),
        "remove_ids": ordered(remove_ids),
    }


def _fleet_series_plan_with_service(
    service: FleetService,
    *,
    prefix: str,
    count: int,
    runner: str,
    provider: str,
    model: str,
    account_id: str | None,
    enabled: bool,
    expected_generation: int,
    confirmed_remove_ids: list[str] | None,
    skill_profile: str = "generic",
    task_profile: str = "standard",
) -> tuple[
    dict[str, Any],
    FleetSnapshot,
    FleetSnapshot,
    FleetSeries | None,
    FleetSeries,
    dict[str, tuple[str, ...]],
]:
    candidate = _fleet_candidate_series(
        prefix=prefix,
        count=count,
        runner=runner,
        provider=provider,
        model=model,
        account_id=account_id,
        enabled=enabled,
        skill_profile=skill_profile,
        task_profile=task_profile,
    )
    try:
        current = service.load()
        planned = plan_series_apply(
            current,
            candidate,
            expected_generation=expected_generation,
            confirmed_remove_ids=confirmed_remove_ids or (),
        )
    except (FleetConflictError, FleetValidationError, ValueError) as exc:
        code = str(exc)
        if not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", code):
            code = "fleet_series_invalid"
        raise AgentError(code) from None
    normalized = next(
        item for item in planned.series if item.prefix == candidate.prefix
    )
    if normalized.enabled:
        decision = service.series_gate(normalized, snapshot=current)
        # Registry metadata/materialization may be refreshed while a project
        # probe is stale.  Invocation admission performs the one fresh probe;
        # hard provider/auth/limit failures still block activation.
        if not decision.allowed and decision.reason not in {
            "probe_stale",
            "limit_unknown",
        }:
            raise AgentError(decision.reason)
    existing = next(
        (item for item in current.series if item.prefix == normalized.prefix), None
    )
    old_count = existing.count if existing is not None else 0
    known_count = max(old_count, normalized.count)
    present_ids = _fleet_plan_materialized_ids(normalized.prefix, known_count)
    materialization = _fleet_materialization_sets(existing, normalized, present_ids)
    result = {
        "mutation_performed": False,
        "generation": current.generation,
        "next_generation": planned.generation,
        "create_count": len(materialization["create_ids"]),
        "keep_count": len(materialization["keep_ids"]),
        "update_count": len(materialization["update_ids"]),
        "remove_count": len(materialization["remove_ids"]),
        "confirmation_required": normalized.count < old_count,
        "pool_root": "not_returned",
        "raw_output": "not_returned",
    }
    return result, current, planned, existing, normalized, materialization


def fleet_series_plan(
    *,
    prefix: str,
    count: int,
    runner: str,
    provider: str,
    model: str,
    account_id: str | None,
    enabled: bool = True,
    expected_generation: int,
    confirmed_remove_ids: list[str] | None = None,
    skill_profile: str = "generic",
    task_profile: str = "standard",
) -> dict[str, Any]:
    result, _current, _planned, _existing, _candidate, _materialization = (
        _fleet_series_plan_with_service(
            _readonly_fleet_service(),
            prefix=prefix,
            count=count,
            runner=runner,
            provider=provider,
            model=model,
            account_id=account_id,
            enabled=enabled,
            expected_generation=expected_generation,
            confirmed_remove_ids=confirmed_remove_ids,
            skill_profile=skill_profile,
            task_profile=task_profile,
        )
    )
    return result


@contextlib.contextmanager
def _fleet_pinned_path(
    path: Path,
    *,
    invalid_text: str,
    close_state: dict[str, bool] | None = None,
) -> Any:
    path = path.expanduser()
    if not path.is_absolute():
        raise AgentError(invalid_text)
    path = path.absolute()
    try:
        expected = path.lstat()
    except OSError as exc:
        raise AgentError(invalid_text) from exc
    if (
        not stat_module.S_ISREG(expected.st_mode)
        or getattr(expected, "st_nlink", 1) != 1
        or expected.st_mode & 0o111 == 0
    ):
        raise AgentError(invalid_text)
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(path, flags)
        opened = os.fstat(fd)
        if (
            not source_identity_with_snapshot_matches(opened, expected)
            or not stat_module.S_ISREG(opened.st_mode)
            or getattr(opened, "st_nlink", 1) != 1
            or opened.st_mode & 0o111 == 0
        ):
            raise AgentError(invalid_text)
        yield path, opened
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(invalid_text) from exc
    finally:
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                if close_state is not None:
                    close_state["cleanup_pending"] = True


@contextlib.contextmanager
def _fleet_pinned_executable(
    runner: RunnerKind,
    *,
    codex_executable: Path | None,
    gemini_executable: Path | None,
    close_state: dict[str, bool] | None = None,
) -> Any:
    supplied = codex_executable if runner is RunnerKind.CODEX_CLI else gemini_executable
    supplied_by_caller = supplied is not None
    if supplied is None:
        found = shutil.which("codex" if runner is RunnerKind.CODEX_CLI else "gemini")
        if found is None:
            raise AgentError("fleet_executable_unavailable")
        path = Path(found)
    elif isinstance(supplied, Path):
        path = supplied
    else:
        raise AgentError("fleet_executable_invalid")
    if path.is_symlink():
        # Both npm-installed CLIs may be exposed through a launcher symlink.
        # Pin the resolved bundle, while keeping the no-symlink validation for
        # the final executable path.
        if runner is RunnerKind.CODEX_CLI and supplied_by_caller:
            raise AgentError("fleet_executable_invalid")
        path = (
            trusted_gemini_executable(path)
            if runner is RunnerKind.GEMINI_CLI
            else trusted_runner_executable(path)
        )
    with _fleet_pinned_path(
        path,
        invalid_text="fleet_executable_invalid",
        close_state=close_state,
    ) as pinned:
        yield pinned


def _fleet_revalidate_executable(path: Path, expected: os.stat_result) -> None:
    try:
        current = path.lstat()
    except OSError as exc:
        raise AgentError("fleet_executable_changed") from exc
    if not source_identity_with_snapshot_matches(current, expected):
        raise AgentError("fleet_executable_changed")


def _build_fleet_home_target(
    descriptor: AgentDescriptor,
    executable: Path,
    *,
    target_skill_profile: str | None = None,
    executable_stat: os.stat_result | None = None,
    bash_executable: Path = FLEET_BASH_EXECUTABLE,
    bash_stat: os.stat_result | None = None,
    taskset_executable: Path = FLEET_TASKSET_EXECUTABLE,
    taskset_stat: os.stat_result | None = None,
    true_executable: Path = FLEET_TRUE_EXECUTABLE,
    true_stat: os.stat_result | None = None,
    include_portable_skills: bool = True,
) -> FleetHomeTarget:
    executable_checks = tuple(
        (path, expected)
        for path, expected in (
            (executable, executable_stat),
            (bash_executable, bash_stat),
            (taskset_executable, taskset_stat),
            (true_executable, true_stat),
        )
        if expected is not None
    )
    for path, expected in executable_checks:
        _fleet_revalidate_executable(path, expected)
    effective_descriptor = (
        dataclass_replace(descriptor, skill_profile=target_skill_profile)
        if target_skill_profile is not None
        else descriptor
    )
    projection = fleet_markdown_projection(effective_descriptor)
    effective_skill_profile = projection.metadata.class_profile
    runtime_skill_profile = (
        effective_skill_profile
        if target_skill_profile is not None
        and descriptor.runner is RunnerKind.CODEX_CLI
        and effective_skill_profile != "generic"
        and effective_skill_profile != descriptor.skill_profile.strip().lower()
        else None
    )
    wrapper_name = "codex" if descriptor.runner is RunnerKind.CODEX_CLI else "gemini"
    config_name, config_text = fleet_minimal_config(effective_descriptor)
    if (
        descriptor.provider is Provider.OLLAMA_LOCAL
        and descriptor.runner is RunnerKind.CODEX_CLI
    ):
        config_text = (
            config_text.rstrip("\n")
            + f"\nmodel_catalog_json = {json.dumps(str(descriptor.home / 'model.json'))}\n"
        )
    files: dict[str, tuple[bytes, int]] = {
        wrapper_name: (
            fleet_wrapper_text(
                effective_descriptor,
                executable,
                bash_executable=bash_executable,
                taskset_executable=taskset_executable,
                true_executable=true_executable,
            ).encode("utf-8"),
            0o700,
        ),
        config_name: (config_text.encode("utf-8"), 0o600),
        **{name: (content, 0o600) for name, content in projection.artifacts.items()},
    }
    if descriptor.runner is RunnerKind.GEMINI_CLI:
        policy = "\n".join(
            (
                "[[rule]]",
                'toolName = "run_shell_command"',
                'decision = "deny"',
                "priority = 999",
                "",
            )
        )
        files[".gemini/policies/codex-master.toml"] = (policy.encode("utf-8"), 0o600)
    if include_portable_skills and effective_skill_profile != "generic":
        files.update(
            {
                name: (data, 0o600)
                for name, data in portable_gemini_skill_artifacts(
                    effective_skill_profile
                ).items()
            }
        )
    if (
        descriptor.provider is Provider.OLLAMA_LOCAL
        and descriptor.runner is RunnerKind.CODEX_CLI
    ):
        files["model.json"] = (
            fleet_model_catalog(effective_descriptor).encode("utf-8"),
            0o600,
        )
    marker: dict[str, Any] = {
        "schema_version": 2,
        "kind": "codex_master_fleet_agent",
        "agent_id": descriptor.agent_id,
        "prefix": descriptor.series_prefix,
        "runner": descriptor.runner.value,
        "provider": descriptor.provider.value,
        "model": descriptor.model,
        "common_policy": _fleet_marker_common_policy(projection),
        "managed_files": sorted(files),
        "files": {
            name: hashlib.sha256(content).hexdigest()
            for name, (content, _mode) in sorted(files.items())
        },
    }
    if runtime_skill_profile is not None:
        marker[_FLEET_RUNTIME_SKILL_PROFILE_FIELD] = runtime_skill_profile
    marker_bytes = (json.dumps(marker, indent=2, sort_keys=True) + "\n").encode("utf-8")
    for path, expected in executable_checks:
        _fleet_revalidate_executable(path, expected)
    return FleetHomeTarget(
        descriptor=descriptor,
        effective_skill_profile=effective_skill_profile,
        runtime_skill_profile=runtime_skill_profile,
        files=tuple(
            (name, content, mode) for name, (content, mode) in sorted(files.items())
        ),
        marker_bytes=marker_bytes,
        policy_schema_version=projection.metadata.schema_version,
        policy_generation=projection.metadata.generation,
        common_digest=projection.metadata.common_digest,
        provider_projection_digest=projection.metadata.provider_artifact_digest,
        executable_checks=executable_checks,
    )


@contextlib.contextmanager
def _fleet_artifact_builder(
    runner: RunnerKind,
    *,
    codex_executable: Path | None,
    gemini_executable: Path | None,
    include_portable_skills: bool = True,
) -> Any:
    close_state = {"cleanup_pending": False}
    with contextlib.ExitStack() as stack:
        executable, executable_stat = stack.enter_context(
            _fleet_pinned_executable(
                runner,
                codex_executable=codex_executable,
                gemini_executable=gemini_executable,
                close_state=close_state,
            )
        )
        bash_executable, bash_stat = stack.enter_context(
            _fleet_pinned_path(
                FLEET_BASH_EXECUTABLE,
                invalid_text="fleet_system_executable_invalid",
                close_state=close_state,
            )
        )
        taskset_executable, taskset_stat = stack.enter_context(
            _fleet_pinned_path(
                FLEET_TASKSET_EXECUTABLE,
                invalid_text="fleet_system_executable_invalid",
                close_state=close_state,
            )
        )
        true_executable, true_stat = stack.enter_context(
            _fleet_pinned_path(
                FLEET_TRUE_EXECUTABLE,
                invalid_text="fleet_system_executable_invalid",
                close_state=close_state,
            )
        )

        def build(agent: AgentDescriptor) -> dict[str, Any]:
            return _fleet_home_artifacts(
                agent,
                executable,
                executable_stat=executable_stat,
                bash_executable=bash_executable,
                bash_stat=bash_stat,
                taskset_executable=taskset_executable,
                taskset_stat=taskset_stat,
                true_executable=true_executable,
                true_stat=true_stat,
                include_portable_skills=include_portable_skills,
            )

        def validate() -> None:
            for path, expected in (
                (executable, executable_stat),
                (bash_executable, bash_stat),
                (taskset_executable, taskset_stat),
                (true_executable, true_stat),
            ):
                _fleet_revalidate_executable(path, expected)

        build.validate = validate  # type: ignore[attr-defined]
        build.close_state = close_state  # type: ignore[attr-defined]
        yield build


def _fleet_home_artifacts(
    agent: AgentDescriptor,
    executable: Path,
    *,
    executable_stat: os.stat_result | None = None,
    bash_executable: Path = FLEET_BASH_EXECUTABLE,
    bash_stat: os.stat_result | None = None,
    taskset_executable: Path = FLEET_TASKSET_EXECUTABLE,
    taskset_stat: os.stat_result | None = None,
    true_executable: Path = FLEET_TRUE_EXECUTABLE,
    true_stat: os.stat_result | None = None,
    include_portable_skills: bool = False,
    runtime_skill_profile: str | None = None,
) -> dict[str, Any]:
    target = _build_fleet_home_target(
        agent,
        executable,
        target_skill_profile=runtime_skill_profile,
        executable_stat=executable_stat,
        bash_executable=bash_executable,
        bash_stat=bash_stat,
        taskset_executable=taskset_executable,
        taskset_stat=taskset_stat,
        true_executable=true_executable,
        true_stat=true_stat,
        include_portable_skills=include_portable_skills,
    )
    files = {name: (content, mode) for name, content, mode in target.files}
    files[FLEET_AGENT_MARKER_FILE] = (target.marker_bytes, 0o600)
    return {
        "files": files,
        "marker": json.loads(target.marker_bytes.decode("utf-8")),
        "executable_checks": target.executable_checks,
    }


def _fleet_home_policy_observation_at(
    home_fd: int,
    descriptor: AgentDescriptor,
    target: FleetHomeTarget,
) -> FleetHomePolicyObservation:
    error = "fleet_home_content_invalid"
    if target.descriptor != descriptor:
        raise AgentError(error)

    def observation(
        state: Literal["absent", "current", "stale"],
        *,
        common_policy: Mapping[str, Any] | None = None,
        provider_digest: str | None = None,
    ) -> FleetHomePolicyObservation:
        return FleetHomePolicyObservation(
            state=state,
            expected_schema_version=target.policy_schema_version,
            expected_generation=target.policy_generation,
            expected_common_digest=target.common_digest,
            expected_provider_projection_digest=target.provider_projection_digest,
            observed_schema_version=(
                common_policy["schema_version"] if common_policy is not None else None
            ),
            observed_generation=(
                common_policy["generation"] if common_policy is not None else None
            ),
            observed_common_digest=(
                common_policy["digest"] if common_policy is not None else None
            ),
            observed_provider_artifact_digest=provider_digest,
        )

    marker_bytes, _marker_stat = _fleet_read_private_file_at(
        home_fd,
        FLEET_AGENT_MARKER_FILE,
        0o600,
        error,
    )
    try:
        payload = json.loads(marker_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise AgentError(error) from exc
    marker = _fleet_validate_agent_marker_shape(
        payload,
        marker_error=error,
        policy_error=error,
    )
    common_policy = _fleet_marker_common_policy_value(marker, error)
    if (
        marker.get("agent_id") != descriptor.agent_id
        or marker.get("prefix") != descriptor.series_prefix
        or marker.get("runner") != descriptor.runner.value
        or marker.get("provider") != descriptor.provider.value
        or marker.get("model") != descriptor.model
    ):
        raise AgentError(error)
    observed_descriptor = _fleet_projection_descriptor_from_marker(
        marker,
        descriptor.home,
        error,
    )
    marker_names = set(marker["files"])
    target_files = {name: (content, mode) for name, content, mode in target.files}
    target_names = set(target_files)
    observed_class_name = (
        f".gemini/AGENTS.class-{observed_descriptor.skill_profile}.md"
        if descriptor.runner is RunnerKind.GEMINI_CLI
        else f"AGENTS.class-{observed_descriptor.skill_profile}.md"
    )
    target_class_name = (
        f".gemini/AGENTS.class-{target.effective_skill_profile}.md"
        if descriptor.runner is RunnerKind.GEMINI_CLI
        else f"AGENTS.class-{target.effective_skill_profile}.md"
    )

    removable_gemini_aliases = (
        marker_names & {"settings.json", "AGENTS.md"}
        if descriptor.runner is RunnerKind.GEMINI_CLI
        else set()
    )
    marker_core = {
        name
        for name in marker_names
        if name != observed_class_name
        and name not in removable_gemini_aliases
        and not _portable_skill_projection_name(name)
    }
    target_core = {
        name
        for name in target_names
        if name != target_class_name and not _portable_skill_projection_name(name)
    }
    if (
        observed_class_name not in marker_names
        or target_class_name not in target_names
        or marker_core != target_core
        or any(not _fleet_managed_name(name) for name in marker_names)
    ):
        raise AgentError(error)

    codex_runtime_directories: Collection[str] = ()
    shared_runtime_sources: contextlib.AbstractContextManager[dict[str, str]] = (
        contextlib.nullcontext({})
    )
    if descriptor.runner is RunnerKind.CODEX_CLI:
        codex_runtime_directories = _FLEET_CODEX_RUNTIME_DIRECTORIES
        if descriptor.agent_id != f"{descriptor.series_prefix}1":
            shared_runtime_sources = _fleet_pinned_shared_runtime_symlinks(
                descriptor.home.parent,
                descriptor,
                error,
            )
    with shared_runtime_sources as codex_runtime_symlinks:
        actual_files, actual_directories, actual_symlinks = _fleet_tree_entries(
            home_fd,
            error,
            allow_gemini_runtime=descriptor.runner is RunnerKind.GEMINI_CLI,
            opaque_runtime_directories=codex_runtime_directories,
            allowed_runtime_symlinks=codex_runtime_symlinks,
        )
        expected_managed_files = marker_names | {FLEET_AGENT_MARKER_FILE}
        expected_directories = _fleet_artifact_directories(
            {name: None for name in expected_managed_files}
        )
        optional_runtime_files = actual_files & {"auth.json"}
        if descriptor.runner is RunnerKind.CODEX_CLI:
            runtime_regular_files = {
                name
                for name in actual_files
                if name in _FLEET_CODEX_RUNTIME_FILES
                or _FLEET_CODEX_RUNTIME_DATABASE_RE.fullmatch(name) is not None
            }
            runtime_directories = actual_directories & set(codex_runtime_directories)
            for name in runtime_regular_files:
                _fleet_codex_runtime_regular_file_stat(home_fd, name, error)
        else:
            optional_runtime_files |= actual_files & {".gemini/projects.json"}
            runtime_regular_files = {
                name
                for name in actual_files
                if name.startswith(".gemini/history/")
                or name.startswith(".gemini/tmp/")
            }
            runtime_directories = {
                name
                for name in actual_directories
                if name == ".gemini/history"
                or name.startswith(".gemini/history/")
                or name == ".gemini/tmp"
                or name.startswith(".gemini/tmp/")
            }
            for name in runtime_regular_files:
                _fleet_codex_runtime_regular_file_stat(home_fd, name, error)
        if (
            actual_files
            != expected_managed_files | optional_runtime_files | runtime_regular_files
            or actual_directories != expected_directories | runtime_directories
            or set(actual_symlinks) - set(codex_runtime_symlinks)
        ):
            raise AgentError(error)
        for name in optional_runtime_files:
            _fleet_read_private_file_at(home_fd, name, 0o600, error)
        _fleet_revalidate_symlink_snapshots(home_fd, actual_symlinks, error)

    provider_name = (
        ".gemini/GEMINI.md"
        if descriptor.runner is RunnerKind.GEMINI_CLI
        else "AGENTS.md"
    )
    provider_digest: str | None = None
    for name in sorted(marker_names):
        expected_digest = marker["files"].get(name)
        if (
            not isinstance(expected_digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", expected_digest) is None
        ):
            raise AgentError(error)
        target_file = target_files.get(name)
        mode = (
            target_file[1]
            if target_file is not None
            else 0o700
            if name in {"codex", "gemini"}
            else 0o600
        )
        content, _file_stat = _fleet_read_private_file_at(
            home_fd,
            name,
            mode,
            error,
        )
        actual_digest = hashlib.sha256(content).hexdigest()
        if not hmac.compare_digest(actual_digest, expected_digest):
            raise AgentError(error)
        if name == provider_name:
            provider_digest = actual_digest
    if provider_digest is None:
        raise AgentError(error)
    if observed_class_name == target_class_name and not hmac.compare_digest(
        marker["files"][observed_class_name],
        hashlib.sha256(target_files[target_class_name][0]).hexdigest(),
    ):
        raise AgentError(error)
    expected_common_policy = {
        "schema_version": target.policy_schema_version,
        "generation": target.policy_generation,
        "digest": target.common_digest,
    }
    state: Literal["current", "stale"] = (
        "current"
        if common_policy == expected_common_policy
        and hmac.compare_digest(
            provider_digest,
            target.provider_projection_digest,
        )
        and observed_class_name == target_class_name
        and not removable_gemini_aliases
        else "stale"
    )
    return observation(
        state,
        common_policy=common_policy,
        provider_digest=provider_digest,
    )


def _fleet_home_policy_observation(
    descriptor: AgentDescriptor,
    target: FleetHomeTarget,
) -> FleetHomePolicyObservation:
    error = "fleet_home_content_invalid"
    if target.descriptor != descriptor:
        raise AgentError(error)
    try:
        home_stat = descriptor.home.lstat()
    except FileNotFoundError:
        return FleetHomePolicyObservation(
            state="absent",
            expected_schema_version=target.policy_schema_version,
            expected_generation=target.policy_generation,
            expected_common_digest=target.common_digest,
            expected_provider_projection_digest=target.provider_projection_digest,
            observed_schema_version=None,
            observed_generation=None,
            observed_common_digest=None,
            observed_provider_artifact_digest=None,
        )
    except OSError as exc:
        raise AgentError(error) from exc
    _fleet_private_directory_stat(home_stat, error)
    home_fd = open_directory_no_follow_matching(
        descriptor.home,
        home_stat,
        error_text=error,
        changed_text=error,
    )
    try:
        result = _fleet_home_policy_observation_at(home_fd, descriptor, target)
        opened_final = os.fstat(home_fd)
        try:
            path_final = descriptor.home.lstat()
        except OSError as exc:
            raise AgentError(error) from exc
        _fleet_private_directory_stat(opened_final, error)
        _fleet_private_directory_stat(path_final, error)
        if not source_identity_with_snapshot_matches(
            opened_final, home_stat
        ) or not source_identity_with_snapshot_matches(path_final, home_stat):
            raise AgentError(error)
        return result
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    finally:
        os.close(home_fd)


def _fleet_revalidate_artifact_executables(artifacts: dict[str, Any]) -> None:
    for path, expected in artifacts.get("executable_checks", ()):
        _fleet_revalidate_executable(path, expected)


def _fleet_artifact_files(artifacts: dict[str, Any]) -> dict[str, tuple[bytes, int]]:
    return {**artifacts["files"], **artifacts.get("extra_files", {})}


def _fleet_private_directory_stat(current: os.stat_result, error: str) -> None:
    if (
        not stat_module.S_ISDIR(current.st_mode)
        or stat_module.S_ISLNK(current.st_mode)
        or current.st_uid != os.geteuid()
        or stat_module.S_IMODE(current.st_mode) != 0o700
    ):
        raise AgentError(error)


def _fleet_artifact_directories(files: Mapping[str, Any]) -> set[str]:
    directories: set[str] = set()
    for name in files:
        path = Path(name)
        if (
            path.is_absolute()
            or not path.parts
            or any(part in {"", ".", ".."} for part in path.parts)
        ):
            raise AgentError("fleet_artifact_path_invalid")
        current = path.parent
        while current != Path("."):
            directories.add(current.as_posix())
            current = current.parent
    return directories


def _fleet_open_artifact_parent(
    home_fd: int,
    name: str,
    *,
    create: bool,
    error: str,
) -> tuple[int, str]:
    path = Path(name)
    if (
        path.is_absolute()
        or not path.parts
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise AgentError(error)
    try:
        current_fd = os.dup(home_fd)
        for part in path.parts[:-1]:
            if create:
                try:
                    os.mkdir(part, 0o700, dir_fd=current_fd)
                except FileExistsError:
                    pass
            flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            next_fd = os.open(part, flags, dir_fd=current_fd)
            try:
                _fleet_private_directory_stat(os.fstat(next_fd), error)
            except Exception:
                os.close(next_fd)
                raise
            os.close(current_fd)
            current_fd = next_fd
        return current_fd, path.parts[-1]
    except Exception as exc:
        if "current_fd" in locals():
            try:
                os.close(current_fd)
            except OSError:
                pass
        if isinstance(exc, AgentError):
            raise
        raise AgentError(error) from exc


# ponytail: Only inert Codex runtime roots stay opaque. Active skills/.system,
# plugins, and memories fail closed; never migrate or delete them before a
# separate, version-bound trust policy exists.
_FLEET_CODEX_RUNTIME_DIRECTORIES = frozenset(
    {
        ".tmp",
        "cache",
        "log",
        "logs",
        "sessions",
        "shell_snapshots",
        "thread-writer-locks",
        "tmp",
    }
)
_FLEET_CODEX_RUNTIME_FILES = frozenset(
    {
        ".personality_migration",
        ".sandbox_migration",
        "history.jsonl",
        "installation_id",
        "models_cache.json",
        "version.json",
    }
)
_FLEET_CODEX_RUNTIME_DATABASE_RE = re.compile(
    r"(?:goals|logs|memories|queue|state|thread_history)_[1-9][0-9]*\.sqlite(?:-shm|-wal)?\Z"
)
_FLEET_CODEX_SHARED_RUNTIME_FILES = frozenset(
    {".personality_migration", "models_cache.json", "version.json"}
)
_FLEET_CODEX_RUNTIME_FILE_MODES = frozenset({0o600, 0o644})
_FLEET_PROC_FD_PATH_RE = re.compile(r"/proc/self/fd/([0-9]+)\Z")


def _fleet_codex_runtime_regular_file_stat(
    directory_fd: int,
    name: str,
    error: str,
    *,
    missing_ok: bool = False,
) -> os.stat_result | None:
    parent_fd, basename = _fleet_open_artifact_parent(
        directory_fd,
        name,
        create=False,
        error=error,
    )
    try:
        try:
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            if missing_ok:
                return None
            raise AgentError(error) from None
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
            or current.st_uid != os.geteuid()
            or stat_module.S_IMODE(current.st_mode)
            not in _FLEET_CODEX_RUNTIME_FILE_MODES
        ):
            raise AgentError(error)
        return current
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    finally:
        os.close(parent_fd)


def _fleet_open_shared_runtime_root(root: Path, error: str) -> int:
    proc_fd = _FLEET_PROC_FD_PATH_RE.fullmatch(str(root))
    if proc_fd is not None:
        root_fd = -1
        try:
            root_fd = os.dup(int(proc_fd.group(1)))
            _fleet_private_directory_stat(os.fstat(root_fd), error)
            return root_fd
        except AgentError:
            if root_fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(root_fd)
            raise
        except (OSError, ValueError) as exc:
            raise AgentError(error) from exc
    try:
        root_stat = root.lstat()
        _fleet_private_directory_stat(root_stat, error)
        return open_directory_chain_no_follow_matching(
            root,
            root_stat,
            error_text=error,
            changed_text=error,
        )
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc


@contextlib.contextmanager
def _fleet_pinned_shared_runtime_symlinks(
    root: Path,
    agent: AgentDescriptor,
    error: str,
) -> Iterator[dict[str, str]]:
    root_fd = -1
    template_fd = -1
    source_fds: dict[str, int] = {}
    source_stats: dict[str, os.stat_result] = {}
    try:
        root_fd = _fleet_open_shared_runtime_root(root, error)
        template_agent = f"{agent.series_prefix}1"
        try:
            template_stat = os.stat(
                template_agent, dir_fd=root_fd, follow_symlinks=False
            )
        except FileNotFoundError:
            yield {}
            return
        _fleet_private_directory_stat(template_stat, error)
        template_fd = open_directory_no_follow_matching(
            template_agent,
            template_stat,
            error_text=error,
            changed_text=error,
            dir_fd=root_fd,
        )
        for name in _FLEET_CODEX_SHARED_RUNTIME_FILES:
            source_stat = _fleet_codex_runtime_regular_file_stat(
                template_fd,
                name,
                error,
                missing_ok=True,
            )
            if source_stat is None:
                continue
            flags = os.O_RDONLY
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            source_fd = os.open(name, flags, dir_fd=template_fd)
            opened = os.fstat(source_fd)
            if not source_identity_with_snapshot_matches(opened, source_stat):
                os.close(source_fd)
                raise AgentError(error)
            source_fds[name] = source_fd
            source_stats[name] = source_stat
        yield {name: f"../{template_agent}/{name}" for name in source_stats}
        current_template = os.stat(
            template_agent, dir_fd=root_fd, follow_symlinks=False
        )
        if (
            not source_identity_with_snapshot_matches(current_template, template_stat)
            or not stat_module.S_ISDIR(current_template.st_mode)
            or stat_module.S_ISLNK(current_template.st_mode)
            or current_template.st_uid != os.geteuid()
            or stat_module.S_IMODE(current_template.st_mode) != 0o700
        ):
            raise AgentError(error)
        for name, source_stat in source_stats.items():
            current = _fleet_codex_runtime_regular_file_stat(template_fd, name, error)
            opened = os.fstat(source_fds[name])
            if (
                current is None
                or not source_identity_with_snapshot_matches(current, source_stat)
                or not source_identity_with_snapshot_matches(opened, source_stat)
            ):
                raise AgentError(error)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    finally:
        for source_fd in source_fds.values():
            with contextlib.suppress(OSError):
                os.close(source_fd)
        if template_fd >= 0:
            os.close(template_fd)
        if root_fd >= 0:
            os.close(root_fd)


def _fleet_tree_entries(
    directory_fd: int,
    error: str,
    *,
    allow_gemini_runtime: bool = False,
    opaque_runtime_directories: Collection[str] = (),
    allowed_runtime_symlinks: Mapping[str, str] | None = None,
) -> tuple[set[str], set[str], dict[str, tuple[os.stat_result, str]]]:
    files: set[str] = set()
    directories: set[str] = set()
    symlinks: dict[str, tuple[os.stat_result, str]] = {}
    entry_count = 0

    def visit(current_fd: int, prefix: str, depth: int) -> None:
        nonlocal entry_count
        current_fd_stat = os.fstat(current_fd)
        prefix_is_gemini_runtime = allow_gemini_runtime and (
            prefix == ".gemini/history"
            or prefix.startswith(".gemini/history/")
            or prefix == ".gemini/tmp"
            or prefix.startswith(".gemini/tmp/")
        )
        if depth > 8:
            raise AgentError(error)
        if prefix_is_gemini_runtime:
            if (
                current_fd_stat.st_uid != os.geteuid()
                or stat_module.S_IMODE(current_fd_stat.st_mode) not in {0o700, 0o755}
                or getattr(current_fd_stat, "st_nlink", 1) < 1
            ):
                raise AgentError(error)
        else:
            _fleet_private_directory_stat(current_fd_stat, error)
        try:
            # A directory FD that was opened before entries were created can
            # retain an end-of-directory stream position on some filesystems.
            # Rewind it before enumerating so freshly materialized homes are
            # not mistaken for empty or partial directories.
            os.lseek(current_fd, 0, os.SEEK_SET)
        except OSError as exc:
            raise AgentError(error) from exc
        for name in os.listdir(current_fd):
            entry_count += 1
            if (
                entry_count > 4096
                or not isinstance(name, str)
                or name in {"", ".", ".."}
                or "/" in name
            ):
                raise AgentError(error)
            relative = f"{prefix}/{name}" if prefix else name
            current = os.stat(name, dir_fd=current_fd, follow_symlinks=False)
            if stat_module.S_ISDIR(current.st_mode) and not stat_module.S_ISLNK(
                current.st_mode
            ):
                relative_is_opaque_runtime = relative in opaque_runtime_directories
                relative_is_gemini_runtime = allow_gemini_runtime and (
                    relative == ".gemini/history"
                    or relative.startswith(".gemini/history/")
                    or relative == ".gemini/tmp"
                    or relative.startswith(".gemini/tmp/")
                )
                if relative_is_gemini_runtime or relative_is_opaque_runtime:
                    if (
                        current.st_uid != os.geteuid()
                        or stat_module.S_IMODE(current.st_mode) not in {0o700, 0o755}
                        or getattr(current, "st_nlink", 1) < 1
                    ):
                        raise AgentError(error)
                else:
                    _fleet_private_directory_stat(current, error)
                directories.add(relative)
                flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
                if hasattr(os, "O_NOFOLLOW"):
                    flags |= os.O_NOFOLLOW
                child_fd = os.open(name, flags, dir_fd=current_fd)
                try:
                    child_stat = os.fstat(child_fd)
                    if relative_is_gemini_runtime or relative_is_opaque_runtime:
                        if (
                            child_stat.st_uid != os.geteuid()
                            or stat_module.S_IMODE(child_stat.st_mode)
                            not in {0o700, 0o755}
                            or getattr(child_stat, "st_nlink", 1) < 1
                        ):
                            raise AgentError(error)
                    else:
                        _fleet_private_directory_stat(child_stat, error)
                    if not source_identity_matches(child_stat, current):
                        raise AgentError(error)
                    if not relative_is_opaque_runtime:
                        visit(child_fd, relative, depth + 1)
                finally:
                    os.close(child_fd)
            elif stat_module.S_ISLNK(current.st_mode):
                expected_target = (
                    allowed_runtime_symlinks.get(relative)
                    if allowed_runtime_symlinks is not None
                    else None
                )
                target = os.readlink(name, dir_fd=current_fd)
                if expected_target is None or target != expected_target:
                    raise AgentError(error)
                symlinks[relative] = (current, target)
            elif (
                stat_module.S_ISREG(current.st_mode)
                and getattr(current, "st_nlink", 1) == 1
                and current.st_uid == os.geteuid()
            ):
                files.add(relative)
            else:
                raise AgentError(error)

    try:
        visit(directory_fd, "", 0)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    return files, directories, symlinks


def _fleet_revalidate_symlink_snapshots(
    directory_fd: int,
    symlinks: Mapping[str, tuple[os.stat_result, str]],
    error: str,
) -> None:
    for name, (expected_stat, expected_target) in symlinks.items():
        parent_fd, basename = _fleet_open_artifact_parent(
            directory_fd,
            name,
            create=False,
            error=error,
        )
        try:
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            if (
                not stat_module.S_ISLNK(current.st_mode)
                or not source_identity_with_snapshot_matches(current, expected_stat)
                or os.readlink(basename, dir_fd=parent_fd) != expected_target
            ):
                raise AgentError(error)
        except AgentError:
            raise
        except OSError as exc:
            raise AgentError(error) from exc
        finally:
            os.close(parent_fd)


def _fleet_read_private_file_at(
    home_fd: int,
    name: str,
    mode: int,
    error: str,
) -> tuple[bytes, os.stat_result]:
    parent_fd, basename = _fleet_open_artifact_parent(
        home_fd, name, create=False, error=error
    )
    fd = -1
    try:
        current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
            or current.st_uid != os.geteuid()
            or stat_module.S_IMODE(current.st_mode) != mode
        ):
            raise AgentError(error)
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(basename, flags, dir_fd=parent_fd)
        opened = os.fstat(fd)
        if (
            not source_identity_with_snapshot_matches(opened, current)
            or not stat_module.S_ISREG(opened.st_mode)
            or getattr(opened, "st_nlink", 1) != 1
            or opened.st_uid != os.geteuid()
            or stat_module.S_IMODE(opened.st_mode) != mode
        ):
            raise AgentError(error)
        with os.fdopen(fd, "rb") as handle:
            fd = -1
            data = handle.read(MAX_POOL_SPEC_BYTES + 1)
        if len(data) > MAX_POOL_SPEC_BYTES:
            raise AgentError(error)
        return data, opened
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    finally:
        if fd >= 0:
            os.close(fd)
        os.close(parent_fd)


def _fleet_read_exact_file_at(
    home_fd: int,
    name: str,
    expected: bytes,
    mode: int,
    error: str,
) -> os.stat_result:
    data, opened = _fleet_read_private_file_at(home_fd, name, mode, error)
    if data != expected:
        raise AgentError(error)
    return opened


def _fleet_read_exact_file(
    path: Path, expected: bytes, mode: int, error: str
) -> os.stat_result:
    try:
        current = path.lstat()
    except OSError as exc:
        raise AgentError(error) from exc
    if (
        not stat_module.S_ISREG(current.st_mode)
        or getattr(current, "st_nlink", 1) != 1
        or current.st_uid != os.geteuid()
        or stat_module.S_IMODE(current.st_mode) != mode
    ):
        raise AgentError(error)
    data = pool_read_private_bytes(
        path,
        MAX_POOL_SPEC_BYTES,
        error,
        expected_target_stat=current,
        expected_mode=mode,
    )
    if data != expected:
        raise AgentError(error)
    return current


def _fleet_verify_home(
    root: Path,
    agent_id: str,
    artifacts: dict[str, Any],
    *,
    exact_contents: bool,
) -> os.stat_result:
    home = root / agent_id
    try:
        home_stat = home.lstat()
    except OSError as exc:
        raise AgentError("fleet_home_verification_failed") from exc
    _fleet_private_directory_stat(home_stat, "fleet_home_verification_failed")
    home_fd = open_directory_no_follow_matching(
        home,
        home_stat,
        error_text="fleet_home_verification_failed",
        changed_text="fleet_home_verification_failed",
    )
    try:
        artifact_files = _fleet_artifact_files(artifacts)
        actual_files, actual_directories, actual_symlinks = _fleet_tree_entries(
            home_fd,
            "fleet_home_verification_failed",
        )
        actual_entries = actual_files | set(actual_symlinks)
        expected_directories = _fleet_artifact_directories(artifact_files)
        if exact_contents:
            if (
                actual_entries != set(artifact_files)
                or actual_directories != expected_directories
            ):
                raise AgentError("fleet_home_verification_failed")
        elif (
            not set(artifact_files) <= actual_entries
            or not expected_directories <= actual_directories
        ):
            raise AgentError("fleet_home_verification_failed")
        for name, (content, mode) in artifact_files.items():
            _fleet_read_exact_file_at(
                home_fd,
                name,
                content,
                mode,
                "fleet_home_verification_failed",
            )
        return home_stat
    finally:
        os.close(home_fd)


def _fleet_root_marker_state(root: Path) -> bool:
    marker = root / FLEET_POOL_MARKER_FILE
    expected = b'{\n  "kind": "codex_master_fleet_pool",\n  "schema_version": 1\n}\n'
    try:
        marker.lstat()
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise AgentError("fleet_pool_marker_invalid") from exc
    _fleet_read_exact_file(marker, expected, 0o600, "fleet_pool_marker_invalid")
    return True


def _fleet_write_root_marker(root_fd: int) -> None:
    expected = b'{\n  "kind": "codex_master_fleet_pool",\n  "schema_version": 1\n}\n'
    if not write_private_bytes_if_absent_at_dir_fd(
        root_fd,
        FLEET_POOL_MARKER_FILE,
        expected,
        mode=0o600,
        error_text="fleet_pool_marker_invalid",
    ):
        raise AgentError("fleet_pool_marker_invalid")


class _FleetPartialHomeError(Exception):
    def __init__(self, staging_name: str, home_stat: os.stat_result | None) -> None:
        self.staging_name = staging_name
        self.home_stat = home_stat
        super().__init__("fleet_partial_home")


def _fleet_create_home(
    root_fd: int,
    agent_id: str,
    artifacts: dict[str, Any],
    *,
    hidden_name: str | None = None,
    entry_index: int | None = None,
    transaction: _FleetRecoveryTransaction | None = None,
) -> os.stat_result:
    """Materialize one new home under the caller's pool mutation lock."""

    with hive_capacity_probe_guard("fleet_series_apply"):
        return _fleet_create_home_unlocked(
            root_fd,
            agent_id,
            artifacts,
            hidden_name=hidden_name,
            entry_index=entry_index,
            transaction=transaction,
        )


def _fleet_create_home_unlocked(
    root_fd: int,
    agent_id: str,
    artifacts: dict[str, Any],
    *,
    hidden_name: str | None = None,
    entry_index: int | None = None,
    transaction: _FleetRecoveryTransaction | None = None,
) -> os.stat_result:
    _fleet_revalidate_artifact_executables(artifacts)
    if hidden_name is None:
        if transaction is not None:
            if entry_index is None:
                raise AgentError("fleet_recovery_state_invalid")
            raise AgentError("fleet_recovery_state_invalid")
        hidden_name = f"{FLEET_TOMBSTONE_PREFIX}create-{uuid.uuid4().hex}"
    if transaction is not None and entry_index is not None:
        transaction.record_entry_phase(entry_index, EntryPhase.INTENT)
    elif transaction is None and entry_index is None:
        _fleet_record_recovery_intent(
            agent_id,
            MutationKind.CREATED,
            hidden_name,
        )
    try:
        os.mkdir(hidden_name, 0o700, dir_fd=root_fd)
    except FileExistsError:
        raise AgentError("fleet_tombstone_collision") from None
    except OSError as exc:
        raise AgentError("fleet_home_create_failed") from exc
    try:
        created_stat = os.stat(hidden_name, dir_fd=root_fd, follow_symlinks=False)
    except OSError as exc:
        raise _FleetPartialHomeError(hidden_name, None) from exc
    home_fd = -1
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        home_fd = os.open(hidden_name, flags, dir_fd=root_fd)
        os.fchmod(home_fd, 0o700)
        home_stat = os.fstat(home_fd)
        _fleet_private_directory_stat(home_stat, "fleet_home_verification_failed")
        artifact_files = _fleet_artifact_files(artifacts)
        for name, (content, mode) in artifact_files.items():
            parent_fd, basename = _fleet_open_artifact_parent(
                home_fd,
                name,
                create=True,
                error="fleet_home_verification_failed",
            )
            try:
                write_private_new_bytes(
                    Path(basename), content, mode=mode, dir_fd=parent_fd
                )
            finally:
                os.close(parent_fd)
        actual_files, actual_directories, actual_symlinks = _fleet_tree_entries(
            home_fd,
            "fleet_home_verification_failed",
        )
        if (actual_files | set(actual_symlinks)) != set(
            artifact_files
        ) or actual_directories != _fleet_artifact_directories(artifact_files):
            raise AgentError("fleet_home_verification_failed")
        for name, (content, mode) in artifact_files.items():
            _fleet_read_exact_file_at(
                home_fd,
                name,
                content,
                mode,
                "fleet_home_verification_failed",
            )
        _fleet_revalidate_artifact_executables(artifacts)
        home_stat = os.fstat(home_fd)
    except Exception as exc:
        partial_stat = os.fstat(home_fd) if home_fd >= 0 else created_stat
        if home_fd >= 0:
            with contextlib.suppress(OSError):
                os.close(home_fd)
        raise _FleetPartialHomeError(hidden_name, partial_stat) from exc

    published = False

    def mark_published() -> None:
        nonlocal published
        published = True

    try:
        _fleet_rename_noreplace_at(
            root_fd,
            hidden_name,
            agent_id,
            home_stat,
            "fleet_home_publish_failed",
            collision_text="fleet_create_target_exists",
            committed=mark_published,
        )
    except AgentError as exc:
        if not published:
            with contextlib.suppress(OSError):
                os.close(home_fd)
            raise
        quarantine = f"{FLEET_TOMBSTONE_PREFIX}create-{uuid.uuid4().hex}"
        quarantined = False

        def mark_quarantined() -> None:
            nonlocal quarantined
            quarantined = True

        try:
            _fleet_rename_noreplace_at(
                root_fd,
                agent_id,
                quarantine,
                os.fstat(home_fd),
                "fleet_create_rollback_diverged",
                collision_text="fleet_create_rollback_diverged",
                committed=mark_quarantined,
            )
        except AgentError:
            if not quarantined:
                with contextlib.suppress(OSError):
                    os.close(home_fd)
                raise AgentError("fleet_create_rollback_diverged") from None
        with contextlib.suppress(OSError):
            os.close(home_fd)
        raise _FleetPartialHomeError(quarantine, home_stat) from exc
    with contextlib.suppress(OSError):
        os.close(home_fd)
    return home_stat


def _fleet_created_home_unchanged(
    root: Path,
    agent_id: str,
    expected_home: os.stat_result,
    artifacts: dict[str, Any],
) -> bool:
    home = root / agent_id
    try:
        current_home = home.lstat()
        if (
            not source_identity_matches(current_home, expected_home)
            or current_home.st_uid != os.geteuid()
        ):
            return False
        _fleet_private_directory_stat(current_home, "fleet_create_rollback_diverged")
        home_fd = open_directory_no_follow_matching(
            home,
            current_home,
            error_text="fleet_create_rollback_diverged",
            changed_text="fleet_create_rollback_diverged",
        )
        try:
            artifact_files = _fleet_artifact_files(artifacts)
            actual_files, actual_directories, actual_symlinks = _fleet_tree_entries(
                home_fd,
                "fleet_create_rollback_diverged",
            )
            if not (actual_files | set(actual_symlinks)) <= set(
                artifact_files
            ) or not actual_directories <= _fleet_artifact_directories(artifact_files):
                return False
            for name in actual_files | set(actual_symlinks):
                content, mode = artifact_files[name]
                _fleet_read_exact_file_at(
                    home_fd,
                    name,
                    content,
                    mode,
                    "fleet_create_rollback_diverged",
                )
            return True
        finally:
            os.close(home_fd)
    except (AgentError, OSError):
        return False


def _fleet_rollback_created(
    created: list[
        tuple[str, os.stat_result, dict[str, Any], str]
        | tuple[str, os.stat_result, dict[str, Any]]
    ],
) -> bool:
    if not created:
        return True
    clean = True
    try:
        with (
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=False,
                error_text="fleet_create_rollback_diverged",
                require_private=True,
            ) as root,
        ):
            root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                for created_item in reversed(created):
                    agent_id, expected_home, artifacts = created_item[:3]
                    if not _fleet_created_home_unchanged(
                        root,
                        agent_id,
                        expected_home,
                        artifacts,
                    ):
                        clean = False
                        continue
                    quarantine = (
                        created_item[3]
                        if len(created_item) > 3 and created_item[3]
                        else f"{FLEET_TOMBSTONE_PREFIX}rollback-{uuid.uuid4().hex}"
                    )
                    try:
                        _fleet_rename_noreplace_at(
                            root_fd,
                            agent_id,
                            quarantine,
                            expected_home,
                            "fleet_create_rollback_diverged",
                            collision_text="fleet_create_rollback_diverged",
                        )
                    except AgentError:
                        clean = False
            finally:
                os.close(root_fd)
    except AgentError:
        return False
    return clean


def _fleet_publish_stored(service: FleetService, stored: FleetSnapshot) -> None:
    try:
        reloaded = service.load()
    except Exception:
        raise AgentError("fleet_inventory_publish_failed") from None
    if reloaded.generation != stored.generation:
        raise AgentError("fleet_inventory_publish_failed")
    transaction = _FLEET_ACTIVE_RECOVERY_TRANSACTION.get()
    if isinstance(transaction, _FleetRecoveryTransaction):
        if transaction.journal.phase not in (
            RecoveryPhase.VERIFIED,
            RecoveryPhase.PUBLISHED,
            RecoveryPhase.COMPLETE,
        ):
            raise AgentError("fleet_inventory_publish_failed")
        if not _fleet_verify_authoritative_materialization(
            reloaded, transaction.journal
        ):
            raise AgentError("fleet_inventory_publish_failed")
    try:
        publish_agent_inventory(build_inventory(reloaded, AGENT_POOL_ROOT))
    except Exception:
        raise AgentError("fleet_inventory_publish_failed") from None


def _fleet_publish_recovery_commit(
    service: FleetService,
    stored: FleetSnapshot,
    transaction: _FleetRecoveryTransaction | None,
) -> None:
    if transaction is None:
        _fleet_publish_stored(service, stored)
        return
    try:
        authoritative = service.load()
    except Exception:
        raise AgentError("fleet_inventory_publish_failed") from None
    if authoritative.generation != stored.generation:
        raise AgentError("fleet_inventory_publish_failed")
    if (
        transaction.journal.operation is RecoveryOperation.REGISTRY_ONLY
        and authoritative != stored
    ):
        transaction.advance(
            RecoveryPhase.DEGRADED,
            authoritative_generation=authoritative.generation,
            blocking_error_codes=("fleet_recovery_incomplete",),
        )
        raise AgentError("fleet_registry_commit_diverged")
    if transaction.journal.phase is RecoveryPhase.MATERIALIZING:
        transaction.advance(RecoveryPhase.CAS_PENDING)
    if transaction.journal.phase is RecoveryPhase.CAS_PENDING:
        transaction.advance(
            RecoveryPhase.RECONCILING,
            authoritative_generation=authoritative.generation,
        )
    if transaction.journal.phase is RecoveryPhase.RECONCILING:
        if not _fleet_verify_authoritative_materialization(
            authoritative,
            transaction.journal,
        ):
            raise AgentError("fleet_inventory_publish_failed")
        transaction.advance(
            RecoveryPhase.VERIFIED,
            authoritative_generation=authoritative.generation,
        )
    if transaction.journal.phase is not RecoveryPhase.VERIFIED:
        raise AgentError("fleet_inventory_publish_failed")
    with _fleet_active_recovery_transaction(transaction):
        _fleet_publish_stored(service, authoritative)
    transaction.advance(
        RecoveryPhase.PUBLISHED,
        authoritative_generation=authoritative.generation,
    )


def _fleet_reconcile_commit_exception(
    service: FleetService,
    current: FleetSnapshot,
    planned: FleetSnapshot,
) -> tuple[str, FleetSnapshot]:
    try:
        reloaded = service.load()
    except Exception:
        raise AgentError("fleet_registry_commit_diverged") from None
    if reloaded == planned:
        return "planned", reloaded
    if reloaded == current:
        return "current", reloaded
    return "third", reloaded


def _fleet_commit_registry_only(
    service: FleetService,
    current: FleetSnapshot,
    planned: FleetSnapshot,
    *,
    expected_generation: int,
) -> FleetSnapshot:
    transaction = _FleetRecoveryTransaction.begin(
        RecoveryOperation.REGISTRY_ONLY,
        current,
        planned,
        (),
    )
    transaction.advance(RecoveryPhase.MATERIALIZING)
    transaction.advance(RecoveryPhase.CAS_PENDING)
    try:
        stored = service.commit_snapshot(
            planned,
            expected_generation=expected_generation,
        )
    except Exception as exc:
        state, authoritative = _fleet_reconcile_commit_exception(
            service,
            current,
            planned,
        )
        transaction.advance(
            RecoveryPhase.RECONCILING,
            authoritative_generation=authoritative.generation,
        )
        reconciled = _fleet_reconcile_divergent_materialization(
            current,
            planned,
            authoritative,
            transaction=transaction,
        )
        if state == "third" or not reconciled:
            transaction.advance(
                RecoveryPhase.DEGRADED,
                authoritative_generation=authoritative.generation,
                blocking_error_codes=("fleet_recovery_incomplete",),
            )
            if state == "third":
                raise AgentError("fleet_registry_commit_diverged") from None
            if state == "planned":
                raise AgentError("fleet_registry_commit_failed_after_cas") from None
            if isinstance(exc, FleetConflictError):
                raise AgentError("generation_conflict") from None
            raise AgentError("fleet_registry_commit_failed") from None
        _fleet_publish_recovery_commit(service, authoritative, transaction)
        transaction.advance(
            RecoveryPhase.COMPLETE,
            authoritative_generation=authoritative.generation,
        )
        _fleet_remove_complete_recovery_journal(transaction.journal)
        if state == "planned":
            raise AgentError("fleet_registry_commit_failed_after_cas") from None
        if isinstance(exc, FleetConflictError):
            raise AgentError("generation_conflict") from None
        raise AgentError("fleet_registry_commit_failed") from None
    _fleet_publish_recovery_commit(service, stored, transaction)
    transaction.advance(
        RecoveryPhase.COMPLETE,
        authoritative_generation=stored.generation,
    )
    _fleet_remove_complete_recovery_journal(transaction.journal)
    return stored


def _fleet_recovery_action_error_code(action: RecoveryActionKind) -> str | None:
    return {
        RecoveryActionKind.QUARANTINE_CREATED: "fleet_create_rollback_diverged",
        RecoveryActionKind.VERIFY_CREATED: "fleet_recovery_incomplete",
        RecoveryActionKind.RESTORE_BACKUP: "fleet_update_rollback_diverged",
        RecoveryActionKind.RESTORE_TOMBSTONE: "fleet_tombstone_rollback_diverged",
        RecoveryActionKind.RELEASE_RESERVATION: "fleet_registry_delete_reservation_diverged",
    }.get(action)


@contextlib.contextmanager
def _fleet_active_recovery_transaction(
    transaction: _FleetRecoveryTransaction | None,
) -> Any:
    if transaction is None:
        yield
        return
    token = _FLEET_ACTIVE_RECOVERY_TRANSACTION.set(transaction)
    try:
        yield
    finally:
        _FLEET_ACTIVE_RECOVERY_TRANSACTION.reset(token)


def _fleet_record_recovery_intent(
    agent_id: str,
    kind: MutationKind,
    hidden_name: str,
    manifest: tuple[tuple[str, int, str], ...] = (),
) -> int | None:
    transaction = _FLEET_ACTIVE_RECOVERY_TRANSACTION.get()
    if transaction is None:
        return None
    for index, entry in enumerate(transaction.journal.entries):
        if entry.agent_id == agent_id and entry.hidden_name == hidden_name:
            transaction.record_entry_phase(index, EntryPhase.INTENT)
            return index
    new_entry = RecoveryEntry(
        kind=kind,
        agent_id=agent_id,
        hidden_name=hidden_name,
        old_descriptor_fingerprint=None,
        new_descriptor_fingerprint=None,
        old_materialization_fingerprint=None,
        new_materialization_fingerprint=None,
        source_identity=None,
        target_identity=None,
        manifest=tuple(
            ArtifactDigest(
                relative_path=relative_path,
                mode=mode,
                sha256=hashes,
            )
            for relative_path, mode, hashes in manifest
        ),
        phase=EntryPhase.INTENT,
        result_code=None,
    )
    return transaction.append_entry(new_entry)


def _fleet_execute_recovery_action(
    action: RecoveryAction,
    entry: RecoveryEntry,
    authoritative_agent: AgentDescriptor | None,
) -> bool:
    if action.kind == RecoveryActionKind.RETAIN_QUARANTINE:
        return True

    if action.kind == RecoveryActionKind.VERIFY_CREATED:
        if authoritative_agent is None or entry.target_identity is None:
            return False
        try:
            current = _fleet_managed_home_state(
                AGENT_POOL_ROOT,
                authoritative_agent,
                strict_contents=True,
            )
        except AgentError:
            return False
        return source_identity_matches(current, entry.target_identity)

    if action.kind == RecoveryActionKind.QUARANTINE_CREATED:
        if authoritative_agent is None:
            return False
        try:
            with (
                pool_root_lock(AGENT_POOL_ROOT),
                pool_root_operation(
                    AGENT_POOL_ROOT,
                    ensure=False,
                    error_text="fleet_create_rollback_diverged",
                    require_private=True,
                ) as root,
            ):
                root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    try:
                        home_stat = os.stat(
                            authoritative_agent.agent_id,
                            dir_fd=root_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        return True
                    except OSError:
                        return False
                    _fleet_rename_noreplace_at(
                        root_fd,
                        authoritative_agent.agent_id,
                        entry.hidden_name,
                        home_stat,
                        "fleet_create_rollback_diverged",
                        collision_text="fleet_create_rollback_diverged",
                    )
                finally:
                    os.close(root_fd)
            return True
        except (AgentError, OSError):
            return False

    if action.kind == RecoveryActionKind.RESTORE_BACKUP:
        if authoritative_agent is None:
            return False
        try:
            with (
                pool_root_lock(AGENT_POOL_ROOT),
                pool_root_operation(
                    AGENT_POOL_ROOT,
                    ensure=False,
                    error_text="fleet_update_rollback_diverged",
                    require_private=True,
                ) as root,
            ):
                root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    backup_stat = os.stat(
                        entry.hidden_name,
                        dir_fd=root_fd,
                        follow_symlinks=False,
                    )
                    target_stat = None
                    try:
                        target_stat = os.stat(
                            authoritative_agent.agent_id,
                            dir_fd=root_fd,
                            follow_symlinks=False,
                        )
                        if not stat_module.S_ISDIR(target_stat.st_mode):
                            return False
                    except FileNotFoundError:
                        target_stat = None
                    if target_stat is not None:
                        quarantine = (
                            f"{FLEET_TOMBSTONE_PREFIX}restore-{uuid.uuid4().hex}"
                        )
                        _fleet_rename_noreplace_at(
                            root_fd,
                            authoritative_agent.agent_id,
                            quarantine,
                            target_stat,
                            "fleet_update_rollback_diverged",
                            collision_text="fleet_update_rollback_diverged",
                        )
                    _fleet_rename_noreplace_at(
                        root_fd,
                        entry.hidden_name,
                        authoritative_agent.agent_id,
                        backup_stat,
                        "fleet_update_rollback_diverged",
                        collision_text="fleet_update_rollback_diverged",
                    )
                finally:
                    os.close(root_fd)
            return True
        except (AgentError, OSError):
            return False

    if action.kind == RecoveryActionKind.RESTORE_TOMBSTONE:
        if authoritative_agent is None:
            return False
        try:
            with (
                pool_root_lock(AGENT_POOL_ROOT),
                pool_root_operation(
                    AGENT_POOL_ROOT,
                    ensure=False,
                    error_text="fleet_tombstone_rollback_diverged",
                    require_private=True,
                ) as root,
            ):
                root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    tombstone_stat = os.stat(
                        entry.hidden_name,
                        dir_fd=root_fd,
                        follow_symlinks=False,
                    )
                    _fleet_rename_noreplace_at(
                        root_fd,
                        entry.hidden_name,
                        authoritative_agent.agent_id,
                        tombstone_stat,
                        "fleet_tombstone_rollback_diverged",
                        collision_text="fleet_tombstone_rollback_diverged",
                    )
                finally:
                    os.close(root_fd)
            return True
        except (AgentError, OSError):
            return False

    if action.kind == RecoveryActionKind.RELEASE_RESERVATION:
        try:
            with (
                pool_root_lock(AGENT_POOL_ROOT),
                pool_root_operation(
                    AGENT_POOL_ROOT,
                    ensure=False,
                    error_text="fleet_registry_delete_reservation_diverged",
                    require_private=True,
                ) as root,
            ):
                root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    try:
                        home_stat = os.stat(
                            entry.agent_id,
                            dir_fd=root_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        return True
                    except OSError:
                        return False
                    if not stat_module.S_ISDIR(home_stat.st_mode):
                        return False
                    with contextlib.closing(
                        os.open(
                            entry.agent_id,
                            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                            dir_fd=root_fd,
                        )
                    ) as home_dir_fd:
                        if os.listdir(home_dir_fd):
                            return False
                    os.rmdir(entry.agent_id, dir_fd=root_fd)
                finally:
                    os.close(root_fd)
            return True
        except (AgentError, OSError):
            return False

    return False


def _fleet_verify_authoritative_materialization(
    authoritative: FleetSnapshot,
    journal: FleetRecoveryJournal,
) -> bool:
    authoritative_agents = build_inventory(authoritative, AGENT_POOL_ROOT).agents
    authoritative_fingerprints = {
        entry.agent_id: (
            descriptor_fingerprint(authoritative_agents[entry.agent_id])
            if entry.agent_id in authoritative_agents
            else None
        )
        for entry in journal.entries
    }
    plan = plan_reconciliation(journal, authoritative_fingerprints)
    if plan.has_third:
        return False
    for action in plan.actions:
        entry = journal.entries[action.entry_index]
        if action.kind is RecoveryActionKind.RETAIN_QUARANTINE:
            continue
        if action.kind is RecoveryActionKind.RELEASE_RESERVATION:
            reservation = AGENT_POOL_ROOT / entry.agent_id
            try:
                reservation_stat = reservation.lstat()
            except FileNotFoundError:
                continue
            except OSError:
                return False
            if entry.target_identity is None or not source_identity_matches(
                reservation_stat, entry.target_identity
            ):
                return False
            try:
                reservation_fd = open_directory_no_follow_matching(
                    reservation,
                    reservation_stat,
                    error_text="fleet_registry_delete_reservation_diverged",
                    changed_text="fleet_registry_delete_reservation_diverged",
                )
                try:
                    if os.listdir(reservation_fd):
                        return False
                finally:
                    os.close(reservation_fd)
            except (AgentError, OSError):
                return False
            continue
        if action.descriptor_state is DescriptorState.NEW:
            if entry.target_identity is None:
                return False
            if not _fleet_verify_directory_fingerprint(
                AGENT_POOL_ROOT / entry.agent_id,
                entry.target_identity,
            ):
                return False
            continue
        if action.descriptor_state in {DescriptorState.ABSENT, DescriptorState.OLD}:
            if _fleet_private_directory_exists(AGENT_POOL_ROOT / entry.agent_id):
                if entry.source_identity is None:
                    return False
                if not _fleet_verify_directory_fingerprint(
                    AGENT_POOL_ROOT / entry.agent_id,
                    entry.source_identity,
                ):
                    return False
            continue
    return True


def _fleet_private_directory_exists(path: Path) -> bool:
    try:
        stat_result = path.lstat()
    except OSError:
        return False
    return stat_module.S_ISDIR(stat_result.st_mode) and not stat_module.S_ISLNK(
        stat_result.st_mode
    )


def _fleet_verify_directory_fingerprint(path: Path, expected: FileIdentity) -> bool:
    try:
        stat_result = path.lstat()
    except OSError:
        return False
    return (
        stat_result.st_ino == expected.ino
        and stat_result.st_dev == expected.dev
        and stat_result.st_mode == expected.mode
        and stat_result.st_nlink == expected.nlink
    )


def _fleet_execute_recovery_plan(
    transaction: _FleetRecoveryTransaction,
    recovery_plan: RecoveryPlan,
    authoritative: FleetSnapshot,
) -> tuple[tuple[str, ...], bool]:
    errors: list[str] = []
    blocking = False
    try:
        authoritative = current_fleet_service().load()
    except Exception:
        errors.append("fleet_recovery_incomplete")
        return tuple(dict.fromkeys(errors)), True
    authoritative_agents = build_inventory(authoritative, AGENT_POOL_ROOT).agents
    for action in recovery_plan.actions:
        entry = transaction.journal.entries[action.entry_index]
        authoritative_agent = authoritative_agents.get(action.agent_id)
        try:
            ok = _fleet_execute_recovery_action(
                action,
                entry,
                authoritative_agent,
            )
        except (AgentError, OSError):
            ok = False
        if not ok:
            code = _fleet_recovery_action_error_code(action.kind)
            if code is not None:
                errors.append(code)
        transaction.record_action_result(action.entry_index, ok)
    if recovery_plan.has_third:
        errors.append("fleet_recovery_incomplete")
        blocking = True
    else:
        try:
            authoritative = current_fleet_service().load()
        except Exception:
            errors.append("fleet_recovery_incomplete")
            return tuple(dict.fromkeys(errors)), True
        if not _fleet_verify_authoritative_materialization(
            authoritative,
            transaction.journal,
        ):
            errors.append("fleet_recovery_incomplete")
            blocking = True
    blocking_codes = {
        "fleet_create_rollback_diverged",
        "fleet_update_rollback_diverged",
        "fleet_tombstone_rollback_diverged",
        "fleet_registry_delete_reservation_diverged",
    }
    blocking = blocking or any(code in blocking_codes for code in errors)
    return tuple(dict.fromkeys(errors)), blocking


def _fleet_prepare_managed_update_recovery_entries(
    current: FleetSnapshot,
    planned: FleetSnapshot,
    update_ids: tuple[str, ...],
    create_ids: tuple[str, ...],
    remove_ids: tuple[str, ...],
) -> tuple[RecoveryEntry, ...]:
    old_inventory = build_inventory(current, AGENT_POOL_ROOT)
    planned_inventory = build_inventory(planned, AGENT_POOL_ROOT)
    entries: list[RecoveryEntry] = []
    for agent_id in update_ids:
        old_agent = old_inventory.agents[agent_id]
        new_agent = planned_inventory.agents[agent_id]
        entries.append(
            RecoveryEntry(
                kind=MutationKind.CREATED,
                agent_id=agent_id,
                hidden_name=f"{FLEET_TOMBSTONE_PREFIX}create-{uuid.uuid4().hex}",
                old_descriptor_fingerprint=descriptor_fingerprint(old_agent),
                new_descriptor_fingerprint=descriptor_fingerprint(new_agent),
                old_materialization_fingerprint=None,
                new_materialization_fingerprint=None,
                source_identity=None,
                target_identity=None,
                manifest=(),
                phase=EntryPhase.INTENT,
                result_code=None,
            )
        )
        entries.append(
            RecoveryEntry(
                kind=MutationKind.BACKUP,
                agent_id=agent_id,
                hidden_name=f"{FLEET_TOMBSTONE_PREFIX}backup-{uuid.uuid4().hex}",
                old_descriptor_fingerprint=descriptor_fingerprint(old_agent),
                new_descriptor_fingerprint=descriptor_fingerprint(new_agent),
                old_materialization_fingerprint=None,
                new_materialization_fingerprint=None,
                source_identity=None,
                target_identity=None,
                manifest=(),
                phase=EntryPhase.INTENT,
                result_code=None,
            )
        )
    for agent_id in create_ids:
        new_agent = planned_inventory.agents[agent_id]
        entries.append(
            RecoveryEntry(
                kind=MutationKind.CREATED,
                agent_id=agent_id,
                hidden_name=f"{FLEET_TOMBSTONE_PREFIX}create-{uuid.uuid4().hex}",
                old_descriptor_fingerprint=None,
                new_descriptor_fingerprint=descriptor_fingerprint(new_agent),
                old_materialization_fingerprint=None,
                new_materialization_fingerprint=None,
                source_identity=None,
                target_identity=None,
                manifest=(),
                phase=EntryPhase.INTENT,
                result_code=None,
            )
        )
    for agent_id in remove_ids:
        old_agent = old_inventory.agents[agent_id]
        entries.append(
            RecoveryEntry(
                kind=MutationKind.TOMBSTONE,
                agent_id=agent_id,
                hidden_name=f"{FLEET_TOMBSTONE_PREFIX}{uuid.uuid4().hex}",
                old_descriptor_fingerprint=descriptor_fingerprint(old_agent),
                new_descriptor_fingerprint=None,
                old_materialization_fingerprint=None,
                new_materialization_fingerprint=None,
                source_identity=None,
                target_identity=None,
                manifest=(),
                phase=EntryPhase.INTENT,
                result_code=None,
            )
        )
    return tuple(entries)


def _fleet_descriptor_reconciliation_states(
    current: FleetSnapshot,
    planned: FleetSnapshot,
    authoritative: FleetSnapshot,
    agent_ids: set[str],
) -> dict[str, str]:
    old_agents = build_inventory(current, AGENT_POOL_ROOT).agents
    new_agents = build_inventory(planned, AGENT_POOL_ROOT).agents
    authoritative_agents = build_inventory(authoritative, AGENT_POOL_ROOT).agents
    states: dict[str, str] = {}
    for agent_id in agent_ids:
        authoritative_agent = authoritative_agents.get(agent_id)
        if authoritative_agent is None:
            states[agent_id] = "absent"
        elif authoritative_agent == old_agents.get(agent_id):
            states[agent_id] = "old"
        elif authoritative_agent == new_agents.get(agent_id):
            states[agent_id] = "new"
        else:
            states[agent_id] = "unknown"
    return states


def _fleet_tmux_state(session: str) -> str:
    try:
        result = run_tmux(["has-session", "-t", session], check=False)
    except Exception:
        return "unknown"
    if result.returncode == 0:
        return "running"
    if result.returncode == 1:
        return "stopped"
    return "unknown"


def _fleet_managed_home_details(
    root: Path,
    agent: AgentDescriptor,
    *,
    entry_name: str | None = None,
    strict_contents: bool,
) -> tuple[os.stat_result, str | None]:
    home = root / (entry_name or agent.agent_id)
    try:
        home_stat = home.lstat()
    except OSError as exc:
        raise AgentError("fleet_home_content_invalid") from exc
    _fleet_private_directory_stat(home_stat, "fleet_home_content_invalid")
    home_fd = open_directory_no_follow_matching(
        home,
        home_stat,
        error_text="fleet_home_content_invalid",
        changed_text="fleet_home_content_invalid",
    )
    try:
        marker_bytes, _marker_stat = _fleet_read_private_file_at(
            home_fd,
            FLEET_AGENT_MARKER_FILE,
            0o600,
            "fleet_home_content_invalid",
        )
        try:
            marker = json.loads(marker_bytes.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise AgentError("fleet_home_content_invalid") from None
        marker = _fleet_validate_agent_marker_shape(
            marker,
            marker_error="fleet_home_content_invalid",
            policy_error="common_policy_generation_stale",
        )
        effective_agent, runtime_skill_profile = _fleet_effective_runtime_descriptor(
            marker,
            agent,
            "fleet_home_content_invalid",
        )
        policy_projection = _fleet_current_policy_projection(
            marker,
            effective_agent,
            "common_policy_generation_stale",
        )
        wrapper_name = "codex" if agent.runner is RunnerKind.CODEX_CLI else "gemini"
        markdown_files = set(policy_projection.artifacts)
        base_expected_files = (
            {wrapper_name, "config.toml"}
            | markdown_files
            | ({"model.json"} if agent.provider is Provider.OLLAMA_LOCAL else set())
            if agent.runner is RunnerKind.CODEX_CLI
            else {
                wrapper_name,
                ".gemini/settings.json",
                ".gemini/policies/codex-master.toml",
            }
            | markdown_files
        )
        if (
            marker.get("agent_id") != agent.agent_id
            or marker.get("prefix") != agent.series_prefix
            or marker.get("runner") != agent.runner.value
            or marker.get("provider") != agent.provider.value
            or marker.get("model") != agent.model
        ):
            raise AgentError("fleet_home_content_invalid")
        marker_files = set(marker["managed_files"])
        marker_digest_files = set(marker["files"])
        compatibility_files = (
            {"settings.json"} | markdown_files
            if agent.runner is RunnerKind.GEMINI_CLI
            else markdown_files
        )
        portable_files = {
            name for name in marker_files if _portable_skill_projection_name(name)
        }
        if (
            not base_expected_files <= marker_files
            or marker_files != marker_digest_files
            or len(portable_files) > MAX_PORTABLE_SKILLS
            or any(not _fleet_managed_name(name) for name in marker_files)
            or any(
                not _portable_skill_projection_name(name)
                for name in marker_files - base_expected_files - compatibility_files
            )
        ):
            raise AgentError("fleet_home_content_invalid")
        expected_files = marker_files
        provider_artifact_digest: str | None = None
        for name in expected_files:
            digest = marker["files"].get(name)
            if (
                not isinstance(digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            ):
                raise AgentError("fleet_home_content_invalid")
            mode = 0o700 if name == wrapper_name else 0o600
            content, _file_stat = _fleet_read_private_file_at(
                home_fd,
                name,
                mode,
                "fleet_home_content_invalid",
            )
            actual_digest = hashlib.sha256(content).hexdigest()
            if not hmac.compare_digest(actual_digest, digest):
                raise AgentError("fleet_home_content_invalid")
            if name == policy_projection.metadata.provider_artifact_name:
                provider_artifact_digest = actual_digest
        if provider_artifact_digest is None or not hmac.compare_digest(
            provider_artifact_digest,
            policy_projection.metadata.provider_artifact_digest,
        ):
            raise AgentError("common_policy_generation_stale")
        codex_runtime_directories: Collection[str] = ()
        shared_runtime_sources: contextlib.AbstractContextManager[dict[str, str]] = (
            contextlib.nullcontext({})
        )
        if agent.runner is RunnerKind.CODEX_CLI:
            codex_runtime_directories = _FLEET_CODEX_RUNTIME_DIRECTORIES
            template_agent = f"{agent.series_prefix}1"
            if agent.agent_id != template_agent:
                shared_runtime_sources = _fleet_pinned_shared_runtime_symlinks(
                    root,
                    agent,
                    "fleet_home_content_invalid",
                )
        with shared_runtime_sources as codex_runtime_symlinks:
            actual_files, actual_directories, actual_symlinks = _fleet_tree_entries(
                home_fd,
                "fleet_home_content_invalid",
                allow_gemini_runtime=True,
                opaque_runtime_directories=codex_runtime_directories,
                allowed_runtime_symlinks=codex_runtime_symlinks,
            )
            allowed_files = {
                FLEET_AGENT_MARKER_FILE,
                *expected_files,
                "auth.json",
                ".gemini/projects.json",
                "settings.json",
            }
            expected_directories = _fleet_artifact_directories(
                {name: None for name in expected_files}
            )
            if strict_contents:
                if agent.runner is RunnerKind.CODEX_CLI:
                    runtime_regular_files = {
                        path
                        for path in actual_files
                        if path in _FLEET_CODEX_RUNTIME_FILES
                        or _FLEET_CODEX_RUNTIME_DATABASE_RE.fullmatch(path) is not None
                    }
                    for path in runtime_regular_files:
                        _fleet_codex_runtime_regular_file_stat(
                            home_fd,
                            path,
                            "fleet_home_content_invalid",
                        )
                    runtime_files = runtime_regular_files | set(actual_symlinks)
                    runtime_directories = actual_directories & set(
                        codex_runtime_directories
                    )
                else:
                    runtime_files = {
                        path
                        for path in actual_files
                        if path.startswith(".gemini/history/")
                        or path.startswith(".gemini/tmp/")
                    }
                    runtime_directories = {
                        path
                        for path in actual_directories
                        if path == ".gemini/history"
                        or path.startswith(".gemini/history/")
                        or path == ".gemini/tmp"
                        or path.startswith(".gemini/tmp/")
                    }
                if (
                    not (actual_files | set(actual_symlinks))
                    <= allowed_files | runtime_files
                    or actual_directories != expected_directories | runtime_directories
                ):
                    raise AgentError("fleet_home_content_invalid")
        _fleet_revalidate_symlink_snapshots(
            home_fd,
            actual_symlinks,
            "fleet_home_content_invalid",
        )
        if "auth.json" in actual_files:
            _fleet_read_private_file_at(
                home_fd,
                "auth.json",
                0o600,
                "fleet_home_content_invalid",
            )
        return home_stat, runtime_skill_profile
    except OSError as exc:
        raise AgentError("fleet_home_content_invalid") from exc
    finally:
        os.close(home_fd)


def _fleet_managed_home_state(
    root: Path,
    agent: AgentDescriptor,
    *,
    entry_name: str | None = None,
    strict_contents: bool,
) -> os.stat_result:
    return _fleet_managed_home_details(
        root,
        agent,
        entry_name=entry_name,
        strict_contents=strict_contents,
    )[0]


def _fleet_validate_materialized_series_homes(
    snapshot: FleetSnapshot,
    series: FleetSeries,
) -> None:
    inventory = build_inventory(snapshot, AGENT_POOL_ROOT)
    with pool_root_lock(AGENT_POOL_ROOT):
        present_ids = _fleet_plan_materialized_ids(series.prefix, series.count)
        if not present_ids:
            return
        with pool_root_operation(
            AGENT_POOL_ROOT,
            ensure=False,
            error_text="fleet_home_state_unknown",
            require_private=True,
        ) as root:
            for agent_id in sorted(present_ids):
                _fleet_managed_home_state(
                    root,
                    inventory.agents[agent_id],
                    strict_contents=True,
                )


@contextlib.contextmanager
def _fleet_idle_agent_locks(
    inventory: InventorySnapshot,
    agent_ids_to_check: list[str],
) -> Any:
    pinned: dict[str, os.stat_result] = {}
    with pool_agent_lifecycle_locks(agent_ids_to_check, snapshot=inventory):
        for agent_id in sorted(agent_ids_to_check):
            agent = inventory.agents[agent_id]
            try:
                home_stat = agent.home.lstat()
            except OSError as exc:
                raise AgentError("fleet_home_content_invalid") from exc
            _fleet_private_directory_stat(home_stat, "fleet_home_content_invalid")
            pinned[agent_id] = home_stat
            lease = agent_lease_status(
                agent_id,
                initialize_state=False,
                snapshot=inventory,
            )
            if lease.get("state") not in {"unclaimed", "expired"}:
                raise AgentError("fleet_agent_lease_active")
            tmux_state = _fleet_tmux_state(agent.session)
            if tmux_state == "running":
                raise AgentError("fleet_agent_running")
            if tmux_state != "stopped":
                raise AgentError("fleet_agent_tmux_unknown")
            processes = pool_home_processes(agent.home)
            if processes is None:
                raise AgentError("fleet_agent_process_unknown")
            if processes:
                raise AgentError("fleet_agent_process_active")
        yield pinned


def _fleet_rename_noreplace_at(
    root_fd: int,
    source: str,
    target: str,
    expected_source: os.stat_result,
    error_text: str,
    *,
    collision_text: str | None = None,
    committed: Callable[[], None] | None = None,
) -> None:
    try:
        current = os.stat(source, dir_fd=root_fd, follow_symlinks=False)
    except OSError as exc:
        raise AgentError(error_text) from exc
    if not source_identity_matches(current, expected_source):
        raise AgentError(error_text)
    libc = ctypes.CDLL(None, use_errno=True)
    renameat2 = getattr(libc, "renameat2", None)
    if renameat2 is None:
        raise AgentError("fleet_noreplace_unavailable")
    renameat2.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    result = renameat2(
        root_fd,
        os.fsencode(source),
        root_fd,
        os.fsencode(target),
        1,
    )
    if result != 0:
        current_errno = ctypes.get_errno()
        if current_errno == errno.EEXIST and collision_text is not None:
            raise AgentError(collision_text)
        raise AgentError(error_text)
    if committed is not None:
        committed()
    try:
        renamed = os.stat(target, dir_fd=root_fd, follow_symlinks=False)
    except OSError as exc:
        raise AgentError(error_text) from exc
    if not source_identity_matches(renamed, expected_source):
        raise AgentError(error_text)


def _fleet_restore_tombstones(staged: list[dict[str, Any]]) -> bool:
    if not staged:
        return True
    try:
        agent_ids_to_restore = [item["agent"].agent_id for item in staged]
        with (
            pool_agent_lifecycle_locks(
                agent_ids_to_restore,
                snapshot=staged[0]["inventory"],
            ),
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=False,
                error_text="fleet_tombstone_rollback_diverged",
                require_private=True,
            ) as root,
        ):
            root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                for item in reversed(staged):
                    agent = item["agent"]
                    tombstone = item["tombstone"]
                    current = _fleet_managed_home_state(
                        root,
                        agent,
                        entry_name=tombstone,
                        strict_contents=True,
                    )
                    if not source_identity_matches(current, item["home_stat"]):
                        return False
                    _fleet_rename_noreplace_at(
                        root_fd,
                        tombstone,
                        agent.agent_id,
                        current,
                        "fleet_tombstone_rollback_diverged",
                        collision_text="fleet_tombstone_rollback_diverged",
                    )
            finally:
                os.close(root_fd)
    except (AgentError, OSError):
        return False
    return True


def _fleet_stage_tombstones(
    inventory: InventorySnapshot,
    agent_ids_to_remove: list[str],
    *,
    transaction: _FleetRecoveryTransaction | None = None,
    planned_tombstones: dict[str, tuple[str, int]] | None = None,
) -> list[dict[str, Any]]:
    staged: list[dict[str, Any]] = []
    try:
        with _fleet_idle_agent_locks(inventory, agent_ids_to_remove) as pinned:
            with (
                pool_root_lock(AGENT_POOL_ROOT),
                pool_root_operation(
                    AGENT_POOL_ROOT,
                    ensure=False,
                    error_text="fleet_pool_root_invalid",
                    require_private=True,
                ) as root,
            ):
                if not _fleet_root_marker_state(root):
                    raise AgentError("fleet_pool_marker_required")
                root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                try:
                    ordered = sorted(
                        agent_ids_to_remove,
                        key=lambda item: inventory.agents[item].ordinal,
                        reverse=True,
                    )
                    for agent_id in ordered:
                        agent = inventory.agents[agent_id]
                        current = _fleet_managed_home_state(
                            root,
                            agent,
                            strict_contents=True,
                        )
                        if not source_identity_matches(current, pinned[agent_id]):
                            raise AgentError("fleet_home_changed")
                        if planned_tombstones is None:
                            if transaction is not None:
                                raise AgentError("fleet_recovery_state_invalid")
                            tombstone = f"{FLEET_TOMBSTONE_PREFIX}{uuid.uuid4().hex}"
                            tombstone_index = None
                        else:
                            tombstone, tombstone_index = planned_tombstones[agent_id]
                        if transaction is not None and tombstone_index is not None:
                            transaction.record_entry_phase(
                                tombstone_index, EntryPhase.INTENT
                            )
                        staged_item = {
                            "agent": agent,
                            "inventory": inventory,
                            "tombstone": tombstone,
                            "home_stat": current,
                        }
                        try:
                            _fleet_rename_noreplace_at(
                                root_fd,
                                agent_id,
                                tombstone,
                                current,
                                "fleet_tombstone_stage_failed",
                                collision_text="fleet_tombstone_collision",
                                committed=lambda item=staged_item: staged.append(item),
                            )
                        except AgentError:
                            raise
                        tombstone_stat = os.stat(
                            tombstone,
                            dir_fd=root_fd,
                            follow_symlinks=False,
                        )
                        if not source_identity_matches(tombstone_stat, current):
                            raise AgentError("fleet_home_changed")
                finally:
                    os.close(root_fd)
    except Exception:
        if staged and not _fleet_restore_tombstones(staged):
            raise AgentError("fleet_tombstone_rollback_diverged") from None
        raise
    return staged


def _fleet_cleanup_tombstones(staged: list[dict[str, Any]]) -> bool:
    return bool(staged)


def _fleet_reserve_absent_homes(
    agent_ids: list[str],
    *,
    transaction: _FleetRecoveryTransaction | None = None,
    planned_reservations: dict[str, tuple[str, int]] | None = None,
) -> list[dict[str, Any]]:
    reservations: list[dict[str, Any]] = []
    try:
        with (
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=True,
                error_text="fleet_pool_root_invalid",
                require_private=True,
            ) as root,
        ):
            root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                if not _fleet_root_marker_state(root):
                    _fleet_write_root_marker(root_fd)
                for agent_id in agent_ids:
                    try:
                        os.stat(agent_id, dir_fd=root_fd, follow_symlinks=False)
                    except FileNotFoundError:
                        pass
                    except OSError as exc:
                        raise AgentError("fleet_home_state_unknown") from exc
                    else:
                        raise AgentError("fleet_registry_delete_raced")
                    if planned_reservations is None:
                        if transaction is not None:
                            raise AgentError("fleet_recovery_state_invalid")
                        staging = (
                            f"{FLEET_TOMBSTONE_PREFIX}reservation-{uuid.uuid4().hex}"
                        )
                        staging_index = None
                    else:
                        staging, staging_index = planned_reservations[agent_id]
                    if transaction is not None and staging_index is not None:
                        transaction.record_entry_phase(staging_index, EntryPhase.INTENT)
                    try:
                        os.mkdir(staging, 0o700, dir_fd=root_fd)
                        reservation: dict[str, Any] = {
                            "agent_id": agent_id,
                            "entry_name": staging,
                            "home_stat": None,
                        }
                        reservations.append(reservation)
                        home_stat = os.stat(
                            staging, dir_fd=root_fd, follow_symlinks=False
                        )
                        reservation["home_stat"] = home_stat
                    except OSError as exc:
                        raise AgentError(
                            "fleet_registry_delete_reservation_failed"
                        ) from exc

                    def mark_reserved(item: dict[str, Any] = reservation) -> None:
                        item["entry_name"] = item["agent_id"]

                    _fleet_rename_noreplace_at(
                        root_fd,
                        staging,
                        agent_id,
                        home_stat,
                        "fleet_registry_delete_reservation_failed",
                        collision_text="fleet_registry_delete_raced",
                        committed=mark_reserved,
                    )
                    if transaction is not None and staging_index is not None:
                        transaction.record_entry_phase(
                            staging_index,
                            EntryPhase.PUBLIC,
                            target_identity=_snapshot_file_identity(home_stat),
                        )
            finally:
                os.close(root_fd)
    except Exception:
        if reservations and not _fleet_release_reservations(reservations):
            raise AgentError("fleet_registry_delete_reservation_diverged") from None
        raise
    return reservations


def _fleet_release_reservations(reservations: list[dict[str, Any]]) -> bool:
    if not reservations:
        return True
    clean = True
    try:
        with (
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=False,
                error_text="fleet_registry_delete_raced",
                require_private=True,
            ) as root,
        ):
            root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                for item in reservations:
                    entry_name = item.get("entry_name", item["agent_id"])
                    expected_home = item.get("home_stat")
                    if expected_home is None:
                        clean = False
                        continue
                    try:
                        current = os.stat(
                            entry_name,
                            dir_fd=root_fd,
                            follow_symlinks=False,
                        )
                    except OSError:
                        clean = False
                        continue
                    if not source_identity_matches(current, expected_home):
                        clean = False
                        continue
                    if entry_name != item["agent_id"]:
                        clean = False
                        continue
                    try:
                        reservation_fd = open_directory_no_follow_matching(
                            root / item["agent_id"],
                            current,
                            error_text="fleet_registry_delete_raced",
                            changed_text="fleet_registry_delete_raced",
                        )
                    except AgentError:
                        clean = False
                        continue
                    try:
                        if os.listdir(reservation_fd):
                            clean = False
                    finally:
                        os.close(reservation_fd)
                    quarantine = (
                        f"{FLEET_TOMBSTONE_PREFIX}reservation-{uuid.uuid4().hex}"
                    )
                    try:
                        _fleet_rename_noreplace_at(
                            root_fd,
                            item["agent_id"],
                            quarantine,
                            current,
                            "fleet_registry_delete_raced",
                            collision_text="fleet_registry_delete_raced",
                        )
                    except AgentError:
                        clean = False
            finally:
                os.close(root_fd)
    except (AgentError, OSError):
        return False
    return clean


def _fleet_commit_staged_removal(
    service: FleetService,
    current: FleetSnapshot,
    planned: FleetSnapshot,
    *,
    expected_generation: int,
    inventory: InventorySnapshot,
    agent_ids_to_remove: list[str],
    planned_tombstones: dict[str, tuple[str, int]] | None = None,
    transaction: _FleetRecoveryTransaction | None = None,
) -> tuple[FleetSnapshot, bool]:
    staged = _fleet_stage_tombstones(
        inventory,
        agent_ids_to_remove,
        transaction=transaction,
        planned_tombstones=planned_tombstones,
    )
    if transaction is not None:
        transaction.advance(RecoveryPhase.CAS_PENDING)
    try:
        stored = service.commit_snapshot(
            planned, expected_generation=expected_generation
        )
    except Exception as exc:
        state, reloaded = _fleet_reconcile_commit_exception(service, current, planned)
        if state == "planned":
            _fleet_publish_recovery_commit(service, reloaded, transaction)
            cleanup_complete = True
            try:
                cleanup_complete = not _fleet_cleanup_tombstones(staged)
            except Exception:
                cleanup_complete = False
            if transaction is not None and cleanup_complete:
                transaction.advance(RecoveryPhase.COMPLETE)
                _fleet_remove_complete_recovery_journal(transaction.journal)
            staged = []
            raise AgentError("fleet_registry_commit_failed_after_cas") from None
        if state == "third":
            if transaction is not None:
                transaction.advance(
                    RecoveryPhase.RECONCILING,
                    authoritative_generation=reloaded.generation,
                )
            reconciled = _fleet_reconcile_divergent_materialization(
                current,
                planned,
                reloaded,
                staged=staged,
                transaction=transaction,
            )
            if not reconciled:
                raise AgentError("fleet_registry_commit_diverged") from None
            _fleet_publish_recovery_commit(service, reloaded, transaction)
            if transaction is not None:
                transaction.advance(RecoveryPhase.COMPLETE)
                _fleet_remove_complete_recovery_journal(transaction.journal)
            staged = []
            raise AgentError("fleet_registry_commit_diverged") from None
        if not _fleet_restore_tombstones(staged):
            staged = []
            raise AgentError("fleet_tombstone_rollback_diverged") from None
        if isinstance(exc, FleetConflictError):
            if transaction is not None:
                _fleet_complete_rolled_back_transaction(
                    transaction,
                    current.generation,
                )
            staged = []
            raise AgentError("generation_conflict") from None
        staged = []
        raise AgentError("fleet_registry_commit_failed") from None
    _fleet_publish_recovery_commit(service, stored, transaction)
    cleanup_complete = True
    try:
        cleanup_pending = _fleet_cleanup_tombstones(staged)
        cleanup_complete = not cleanup_pending
    except Exception:
        cleanup_pending = True
        cleanup_complete = False
    if transaction is not None and cleanup_complete:
        transaction.advance(RecoveryPhase.COMPLETE)
    return stored, cleanup_pending


def _fleet_home_file_snapshot(
    home_fd: int, name: str
) -> tuple[bytes, int, os.stat_result]:
    pinned = Path(f"/proc/self/fd/{home_fd}") / name
    try:
        current = os.stat(name, dir_fd=home_fd, follow_symlinks=False)
    except OSError as exc:
        raise AgentError("fleet_home_content_invalid") from exc
    if not stat_module.S_ISREG(current.st_mode) or getattr(current, "st_nlink", 1) != 1:
        raise AgentError("fleet_home_content_invalid")
    return (
        pool_read_private_bytes(
            pinned,
            MAX_POOL_SPEC_BYTES,
            "fleet_home_content_invalid",
            expected_target_stat=current,
        ),
        stat_module.S_IMODE(current.st_mode),
        current,
    )


def _fleet_snapshot_metadata(current: os.stat_result) -> tuple[int, ...]:
    return (
        current.st_dev,
        current.st_ino,
        current.st_mode,
        current.st_uid,
        current.st_gid,
        current.st_nlink,
        current.st_size,
        current.st_mtime_ns,
    )


_FleetIdentitySnapshot = tuple[tuple[int, ...], str | None]


@dataclass(frozen=True, slots=True)
class _FleetIdentityJournalEntry:
    name: str
    before: _FleetIdentitySnapshot | None
    replacement_kind: Literal["file", "directory"] | None
    replacement_mode: int | None
    replacement_bytes: bytes | None


@dataclass(slots=True)
class _FleetIdentityJournalState:
    entry: _FleetIdentityJournalEntry
    old_slot: str | None
    replacement_slot: str | None
    replacement_snapshot: _FleetIdentitySnapshot | None
    old_moved: bool = False
    replacement_moved: bool = False


@dataclass(slots=True)
class _FleetIdentityJournal:
    name: str
    fd: int
    snapshot: tuple[int, ...]
    parent_before: tuple[int, ...]
    parent_current: tuple[int, ...]
    directory_before: dict[str, tuple[int, ...]]
    directory_current: dict[str, tuple[int, ...]]
    states: list[_FleetIdentityJournalState]


def _fleet_identity_journal_snapshot_at(
    directory_fd: int,
    name: str,
    error: str,
) -> _FleetIdentitySnapshot:
    if not name or name in {".", ".."} or "/" in name:
        raise AgentError(error)
    try:
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        metadata = _fleet_snapshot_metadata(current)
        mode = stat_module.S_IMODE(current.st_mode)
        if stat_module.S_ISREG(current.st_mode):
            if (
                current.st_uid != os.geteuid()
                or current.st_nlink != 1
                or mode not in {0o600, 0o700}
            ):
                raise AgentError(error)
            flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
            fd = os.open(name, flags, dir_fd=directory_fd)
            try:
                if _fleet_snapshot_metadata(os.fstat(fd)) != metadata:
                    raise AgentError(error)
                digest = hashlib.sha256()
                while chunk := os.read(fd, 1024 * 1024):
                    digest.update(chunk)
                if _fleet_snapshot_metadata(os.fstat(fd)) != metadata:
                    raise AgentError(error)
            finally:
                os.close(fd)
            return metadata, digest.hexdigest()
        if stat_module.S_ISDIR(current.st_mode) and not stat_module.S_ISLNK(
            current.st_mode
        ):
            if current.st_uid != os.geteuid() or mode != 0o700:
                raise AgentError(error)
            fd = open_directory_no_follow_matching(
                name,
                current,
                error_text=error,
                changed_text=error,
                dir_fd=directory_fd,
            )
            try:
                if _fleet_snapshot_metadata(os.fstat(fd)) != metadata:
                    raise AgentError(error)
            finally:
                os.close(fd)
            return metadata, None
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    raise AgentError(error)


def _fleet_identity_journal_rename_noreplace_at(
    source_fd: int,
    source: str,
    target_fd: int,
    target: str,
    expected_source: _FleetIdentitySnapshot,
    *,
    error: str = "fleet_identity_journal_changed",
    transition: tuple[
        _FleetIdentityJournal,
        _FleetIdentityJournalState,
        str,
        int,
        Literal["old_moved", "replacement_moved"],
        bool,
        _FleetIdentitySnapshot | None,
    ]
    | None = None,
) -> None:
    def transition_callback() -> None:
        if transition is None:
            return
        journal, state, parent_name, parent_fd, field, value, replacement_snapshot = (
            transition
        )
        setattr(state, field, value)
        if replacement_snapshot is not None:
            state.replacement_snapshot = replacement_snapshot
        journal.directory_current[parent_name] = _fleet_snapshot_metadata(
            os.fstat(parent_fd)
        )
        journal.snapshot = _fleet_snapshot_metadata(os.fstat(journal.fd))

    if (
        not source
        or not target
        or source in {".", ".."}
        or target in {".", ".."}
        or "/" in source
        or "/" in target
    ):
        raise AgentError(error)
    if (
        _fleet_identity_journal_snapshot_at(
            source_fd,
            source,
            error,
        )
        != expected_source
    ):
        raise AgentError(error)
    libc = ctypes.CDLL(None, use_errno=True)
    renameat2 = getattr(libc, "renameat2", None)
    if renameat2 is None:
        raise AgentError("fleet_noreplace_unavailable")
    renameat2.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    if (
        renameat2(
            source_fd,
            os.fsencode(source),
            target_fd,
            os.fsencode(target),
            1,
        )
        != 0
    ):
        current_errno = ctypes.get_errno()
        if current_errno == errno.EEXIST:
            raise AgentError("fleet_identity_journal_collision")
        raise AgentError(error)
    transition_callback()
    try:
        os.fsync(source_fd)
        if target_fd != source_fd:
            os.fsync(target_fd)
        try:
            os.stat(source, dir_fd=source_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise AgentError(error)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc
    if (
        _fleet_identity_journal_snapshot_at(
            target_fd,
            target,
            error,
        )
        != expected_source
    ):
        raise AgentError(error)


def _fleet_identity_journal_prepare(
    parent_fd: int,
    home_fd: int,
    parent_snapshot: tuple[int, ...],
    home_snapshot: tuple[int, ...],
    entries: tuple[_FleetIdentityJournalEntry, ...],
    plan: FleetIdentityJournalPlan,
    *,
    faultpoint: Callable[[str], None] | None = None,
) -> _FleetIdentityJournal:
    error = "fleet_identity_journal_changed"
    try:
        validate_fleet_identity_journal_plan(
            plan,
            tuple(
                (
                    entry.name,
                    entry.before is not None,
                    entry.replacement_kind is not None,
                )
                for entry in entries
            ),
        )
    except FleetHomeRecoveryValidationError as exc:
        raise AgentError(error) from exc
    if (
        _fleet_snapshot_metadata(os.fstat(parent_fd)) != parent_snapshot
        or _fleet_snapshot_metadata(os.fstat(home_fd)) != home_snapshot
    ):
        raise AgentError(error)
    _fleet_private_directory_stat(os.fstat(parent_fd), error)
    _fleet_private_directory_stat(os.fstat(home_fd), error)
    names: set[str] = set()
    future_directories: set[str] = set()
    directory_before = {"": home_snapshot}
    for entry in entries:
        path = Path(entry.name)
        if (
            path.is_absolute()
            or not path.parts
            or any(part in {"", ".", ".."} for part in path.parts)
            or entry.name in names
            or entry.replacement_kind not in {None, "file", "directory"}
            or (
                entry.replacement_kind == "file"
                and (
                    type(entry.replacement_bytes) is not bytes
                    or type(entry.replacement_mode) is not int
                    or entry.replacement_mode not in {0o600, 0o700}
                )
            )
            or (
                entry.replacement_kind == "directory"
                and (
                    entry.replacement_bytes is not None
                    or type(entry.replacement_mode) is not int
                    or entry.replacement_mode != 0o700
                )
            )
            or (
                entry.replacement_kind is None
                and (
                    entry.replacement_bytes is not None
                    or entry.replacement_mode is not None
                )
            )
        ):
            raise AgentError(error)
        if entry.before is not None:
            metadata, digest = entry.before
            if (
                not isinstance(metadata, tuple)
                or len(metadata) != 8
                or any(type(value) is not int for value in metadata)
                or (
                    stat_module.S_ISREG(metadata[2])
                    and (
                        stat_module.S_IMODE(metadata[2]) not in {0o600, 0o700}
                        or not isinstance(digest, str)
                        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                    )
                )
                or (
                    stat_module.S_ISDIR(metadata[2])
                    and (
                        stat_module.S_IMODE(metadata[2]) != 0o700 or digest is not None
                    )
                )
                or not (
                    stat_module.S_ISREG(metadata[2]) or stat_module.S_ISDIR(metadata[2])
                )
            ):
                raise AgentError(error)
        names.add(entry.name)
        parent_name = path.parent.as_posix()
        parent_name = "" if parent_name == "." else parent_name
        parent_is_future = any(
            parent_name == name or parent_name.startswith(f"{name}/")
            for name in future_directories
        )
        if parent_is_future:
            if entry.before is not None:
                raise AgentError(error)
        else:
            entry_parent_fd, basename = _fleet_open_artifact_parent(
                home_fd,
                entry.name,
                create=False,
                error=error,
            )
            try:
                parent_current = os.fstat(entry_parent_fd)
                _fleet_private_directory_stat(parent_current, error)
                directory_before.setdefault(
                    parent_name,
                    _fleet_snapshot_metadata(parent_current),
                )
                if entry.before is None:
                    try:
                        os.stat(
                            basename,
                            dir_fd=entry_parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        pass
                    else:
                        raise AgentError(error)
                elif (
                    _fleet_identity_journal_snapshot_at(
                        entry_parent_fd, basename, error
                    )
                    != entry.before
                ):
                    raise AgentError(error)
            finally:
                os.close(entry_parent_fd)
        if entry.before is None and entry.replacement_kind == "directory":
            future_directories.add(entry.name)
    if (
        _fleet_snapshot_metadata(os.fstat(parent_fd)) != parent_snapshot
        or _fleet_snapshot_metadata(os.fstat(home_fd)) != home_snapshot
    ):
        raise AgentError(error)

    staging_name = plan.staging_name
    journal_name = plan.journal_name
    journal_path_name = staging_name
    journal_fd = -1
    journal_snapshot: tuple[int, ...] | None = None
    parent_current: tuple[int, ...] | None = None
    states: list[_FleetIdentityJournalState] = []
    cleanup_error = "fleet_identity_journal_cleanup_diverged"

    def finalize_cleanup(cleanup_fd: int, cleanup_snapshot: tuple[int, ...]) -> None:
        if parent_current is None:
            raise AgentError(cleanup_error)
        cleanup_journal = _FleetIdentityJournal(
            journal_path_name,
            cleanup_fd,
            cleanup_snapshot,
            parent_snapshot,
            parent_current,
            directory_before,
            dict(directory_before),
            states,
        )
        cleanup_slots = tuple(
            (state.replacement_slot, state.replacement_snapshot)
            for state in states
            if state.replacement_slot is not None
            and state.replacement_snapshot is not None
        )
        try:
            _fleet_identity_journal_finalize(
                parent_fd,
                cleanup_journal,
                cleanup_slots,
                cleanup_error,
            )
        except Exception as cleanup_exc:
            if cleanup_journal.fd >= 0:
                os.close(cleanup_journal.fd)
                cleanup_journal.fd = -1
            if (
                isinstance(cleanup_exc, AgentError)
                and str(cleanup_exc) == cleanup_error
            ):
                raise
            raise AgentError(cleanup_error) from cleanup_exc

    try:
        os.mkdir(staging_name, 0o700, dir_fd=parent_fd)
        if faultpoint is not None:
            faultpoint("after_staging_mkdir")
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        journal_fd = os.open(staging_name, flags, dir_fd=parent_fd)
        if faultpoint is not None:
            faultpoint("after_staging_pin")
        journal_stat = os.fstat(journal_fd)
        journal_snapshot = _fleet_snapshot_metadata(journal_stat)
        if faultpoint is not None:
            faultpoint("after_staging_fstat")
        _fleet_private_directory_stat(journal_stat, error)
        if faultpoint is not None:
            faultpoint("after_staging_validation")
        journal_path_stat = os.stat(
            staging_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if _fleet_snapshot_metadata(journal_path_stat) != journal_snapshot:
            raise AgentError(error)
        if faultpoint is not None:
            faultpoint("after_staging_path_stat")
        if os.listdir(journal_fd):
            raise AgentError(error)
        if faultpoint is not None:
            faultpoint("after_staging_empty_check")
        parent_current = _fleet_snapshot_metadata(os.fstat(parent_fd))
        if faultpoint is not None:
            faultpoint("after_parent_fstat")
        for entry, planned_slot in zip(entries, plan.slots, strict=True):
            old_slot = planned_slot.old
            replacement_slot = planned_slot.replacement
            replacement_snapshot = None
            if replacement_slot is not None:
                if entry.replacement_kind == "file":
                    write_private_new_bytes(
                        Path(replacement_slot),
                        entry.replacement_bytes,
                        mode=entry.replacement_mode,
                        dir_fd=journal_fd,
                    )
                else:
                    os.mkdir(
                        replacement_slot, entry.replacement_mode, dir_fd=journal_fd
                    )
                replacement_snapshot = _fleet_identity_journal_snapshot_at(
                    journal_fd,
                    replacement_slot,
                    error,
                )
                expected_digest = (
                    hashlib.sha256(entry.replacement_bytes).hexdigest()
                    if entry.replacement_kind == "file"
                    else None
                )
                if replacement_snapshot[1] != expected_digest:
                    raise AgentError(error)
            states.append(
                _FleetIdentityJournalState(
                    entry,
                    old_slot,
                    replacement_slot,
                    replacement_snapshot,
                )
            )
            journal_snapshot = _fleet_snapshot_metadata(os.fstat(journal_fd))
        os.fsync(journal_fd)
        if faultpoint is not None:
            faultpoint("after_staging_fsync")
        journal_stat = os.fstat(journal_fd)
        journal_snapshot = _fleet_snapshot_metadata(journal_stat)
        if faultpoint is not None:
            faultpoint("after_staging_final_fstat")
        if _fleet_identity_journal_snapshot_at(parent_fd, staging_name, error) != (
            journal_snapshot,
            None,
        ):
            raise AgentError(error)
        if faultpoint is not None:
            faultpoint("after_staging_final_path_validation")

        expected_slots: dict[str, _FleetIdentitySnapshot] = {}
        for state in states:
            if state.replacement_slot is None or state.replacement_snapshot is None:
                if (
                    state.replacement_slot is not None
                    or state.replacement_snapshot is not None
                ):
                    raise AgentError(error)
                continue
            if state.replacement_slot in expected_slots:
                raise AgentError(error)
            expected_slots[state.replacement_slot] = state.replacement_snapshot
        with contextlib.suppress(OSError):
            os.lseek(journal_fd, 0, os.SEEK_SET)
        if set(os.listdir(journal_fd)) != set(expected_slots):
            raise AgentError(error)
        for slot, expected_snapshot in expected_slots.items():
            if (
                _fleet_identity_journal_snapshot_at(journal_fd, slot, error)
                != expected_snapshot
            ):
                raise AgentError(error)

        validated_parents = {""}
        for state in states:
            entry = state.entry
            path = Path(entry.name)
            parent_name = path.parent.as_posix()
            parent_name = "" if parent_name == "." else parent_name
            parent_is_future = any(
                parent_name == name or parent_name.startswith(f"{name}/")
                for name in future_directories
            )
            if parent_is_future:
                continue
            expected_parent = directory_before.get(parent_name)
            if expected_parent is None:
                raise AgentError(error)
            entry_parent_fd, basename = _fleet_open_artifact_parent(
                home_fd,
                entry.name,
                create=False,
                error=error,
            )
            try:
                parent_stat = os.fstat(entry_parent_fd)
                _fleet_private_directory_stat(parent_stat, error)
                if _fleet_snapshot_metadata(parent_stat) != expected_parent:
                    raise AgentError(error)
                if entry.before is None:
                    try:
                        os.stat(
                            basename,
                            dir_fd=entry_parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        pass
                    else:
                        raise AgentError(error)
                elif (
                    _fleet_identity_journal_snapshot_at(
                        entry_parent_fd, basename, error
                    )
                    != entry.before
                ):
                    raise AgentError(error)
                if (
                    _fleet_snapshot_metadata(os.fstat(entry_parent_fd))
                    != expected_parent
                ):
                    raise AgentError(error)
                validated_parents.add(parent_name)
            finally:
                os.close(entry_parent_fd)
        if validated_parents != set(directory_before):
            raise AgentError(error)
        if (
            parent_current is None
            or _fleet_snapshot_metadata(os.fstat(parent_fd)) != parent_current
            or _fleet_snapshot_metadata(os.fstat(home_fd)) != home_snapshot
            or _fleet_snapshot_metadata(os.fstat(journal_fd)) != journal_snapshot
            or _fleet_identity_journal_snapshot_at(parent_fd, staging_name, error)
            != (journal_snapshot, None)
        ):
            raise AgentError(error)

        def mark_published() -> None:
            nonlocal journal_path_name, parent_current
            journal_path_name = journal_name
            parent_current = _fleet_snapshot_metadata(os.fstat(parent_fd))
            if faultpoint is not None:
                faultpoint("after_journal_publish")

        _fleet_rename_noreplace_at(
            parent_fd,
            staging_name,
            journal_name,
            journal_stat,
            error,
            collision_text="fleet_identity_journal_collision",
            committed=mark_published,
        )
        parent_current = _fleet_snapshot_metadata(os.fstat(parent_fd))
        if _fleet_snapshot_metadata(
            os.fstat(journal_fd)
        ) != journal_snapshot or _fleet_identity_journal_snapshot_at(
            parent_fd, journal_name, error
        ) != (journal_snapshot, None):
            raise AgentError(error)
        os.fsync(parent_fd)
        return _FleetIdentityJournal(
            journal_name,
            journal_fd,
            _fleet_snapshot_metadata(os.fstat(journal_fd)),
            parent_snapshot,
            parent_current,
            directory_before,
            dict(directory_before),
            states,
        )
    except Exception:
        if journal_fd >= 0:
            try:
                cleanup_stat = os.fstat(journal_fd)
                _fleet_private_directory_stat(cleanup_stat, cleanup_error)
                journal_snapshot = _fleet_snapshot_metadata(cleanup_stat)
                if parent_current is None:
                    parent_current = _fleet_snapshot_metadata(os.fstat(parent_fd))
            except Exception as cleanup_exc:
                os.close(journal_fd)
                journal_fd = -1
                raise AgentError(cleanup_error) from cleanup_exc
            owned_journal_fd = journal_fd
            journal_fd = -1
            finalize_cleanup(owned_journal_fd, journal_snapshot)
        raise


def _fleet_identity_journal_switch(
    home_fd: int,
    journal: _FleetIdentityJournal,
    *,
    faultpoint: Callable[[str], None] | None = None,
) -> None:
    error = "fleet_identity_journal_changed"
    if (
        journal.fd < 0
        or _fleet_snapshot_metadata(os.fstat(home_fd)) != journal.directory_current[""]
    ):
        raise AgentError(error)
    replacement_slots = {
        state.replacement_slot
        for state in journal.states
        if state.replacement_slot is not None
    }
    with contextlib.suppress(OSError):
        os.lseek(journal.fd, 0, os.SEEK_SET)
    if set(os.listdir(journal.fd)) != replacement_slots:
        raise AgentError(error)
    for state in journal.states:
        if state.entry.replacement_kind not in {None, "file", "directory"}:
            raise AgentError(error)
        if state.replacement_slot is not None and (
            state.replacement_snapshot is None
            or _fleet_identity_journal_snapshot_at(
                journal.fd,
                state.replacement_slot,
                error,
            )
            != state.replacement_snapshot
        ):
            raise AgentError(error)
    if faultpoint is not None:
        faultpoint("before_switch")
    for state in journal.states:
        entry = state.entry
        path = Path(entry.name)
        parent_name = path.parent.as_posix()
        parent_name = "" if parent_name == "." else parent_name
        entry_parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            entry.name,
            create=False,
            error=error,
        )
        try:
            if (
                _fleet_snapshot_metadata(os.fstat(entry_parent_fd))
                != journal.directory_current[parent_name]
                or _fleet_snapshot_metadata(os.fstat(journal.fd)) != journal.snapshot
            ):
                raise AgentError(error)
            if state.old_slot is not None and entry.before is not None:
                _fleet_identity_journal_rename_noreplace_at(
                    entry_parent_fd,
                    basename,
                    journal.fd,
                    state.old_slot,
                    entry.before,
                    transition=(
                        journal,
                        state,
                        parent_name,
                        entry_parent_fd,
                        "old_moved",
                        True,
                        None,
                    ),
                )
            if (
                state.replacement_slot is not None
                and state.replacement_snapshot is not None
            ):
                _fleet_identity_journal_rename_noreplace_at(
                    journal.fd,
                    state.replacement_slot,
                    entry_parent_fd,
                    basename,
                    state.replacement_snapshot,
                    transition=(
                        journal,
                        state,
                        parent_name,
                        entry_parent_fd,
                        "replacement_moved",
                        True,
                        None,
                    ),
                )
                if entry.replacement_kind == "directory":
                    journal.directory_current[entry.name] = state.replacement_snapshot[
                        0
                    ]
            if (
                _fleet_snapshot_metadata(os.fstat(home_fd))
                != journal.directory_current[""]
            ):
                raise AgentError(error)
        finally:
            os.close(entry_parent_fd)
        if faultpoint is not None:
            faultpoint("during_switch")
    if faultpoint is not None:
        faultpoint("after_switch")


def _fleet_identity_journal_finalize(
    parent_fd: int,
    journal: _FleetIdentityJournal,
    slots: tuple[tuple[str, _FleetIdentitySnapshot], ...],
    error: str,
) -> None:
    try:
        if (
            journal.fd < 0
            or _fleet_snapshot_metadata(os.fstat(parent_fd)) != journal.parent_current
            or _fleet_snapshot_metadata(os.fstat(journal.fd)) != journal.snapshot
        ):
            raise AgentError(error)
        journal_path_stat = os.stat(
            journal.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if _fleet_snapshot_metadata(journal_path_stat) != journal.snapshot:
            raise AgentError(error)
        verified_fd = open_directory_no_follow_matching(
            journal.name,
            journal_path_stat,
            error_text=error,
            changed_text=error,
            dir_fd=parent_fd,
        )
        try:
            if _fleet_snapshot_metadata(os.fstat(verified_fd)) != journal.snapshot:
                raise AgentError(error)
        finally:
            os.close(verified_fd)
        slot_names = [name for name, _snapshot in slots]
        if len(slot_names) != len(set(slot_names)):
            raise AgentError(error)
        with contextlib.suppress(OSError):
            os.lseek(journal.fd, 0, os.SEEK_SET)
        if set(os.listdir(journal.fd)) != set(slot_names):
            raise AgentError(error)
        for name, expected in slots:
            if _fleet_identity_journal_snapshot_at(journal.fd, name, error) != expected:
                raise AgentError(error)
        for name, expected in reversed(slots):
            if (
                _fleet_snapshot_metadata(os.fstat(journal.fd)) != journal.snapshot
                or _fleet_identity_journal_snapshot_at(journal.fd, name, error)
                != expected
            ):
                raise AgentError(error)
            mode = expected[0][2]
            if stat_module.S_ISDIR(mode):
                os.rmdir(name, dir_fd=journal.fd)
            elif stat_module.S_ISREG(mode):
                os.unlink(name, dir_fd=journal.fd)
            else:
                raise AgentError(error)
            journal.snapshot = _fleet_snapshot_metadata(os.fstat(journal.fd))
        with contextlib.suppress(OSError):
            os.lseek(journal.fd, 0, os.SEEK_SET)
        if os.listdir(journal.fd):
            raise AgentError(error)
        journal_path_stat = os.stat(
            journal.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            _fleet_snapshot_metadata(journal_path_stat) != journal.snapshot
            or _fleet_snapshot_metadata(os.fstat(parent_fd)) != journal.parent_current
        ):
            raise AgentError(error)
        os.rmdir(journal.name, dir_fd=parent_fd)
        os.close(journal.fd)
        journal.fd = -1
        parent_after_remove = _fleet_snapshot_metadata(os.fstat(parent_fd))
        if (
            parent_after_remove[:7] != journal.parent_before[:7]
            or _fleet_snapshot_metadata(os.fstat(parent_fd)) != parent_after_remove
        ):
            raise AgentError(error)
        current_parent = os.fstat(parent_fd)
        os.utime(parent_fd, ns=(current_parent.st_atime_ns, journal.parent_before[7]))
        if _fleet_snapshot_metadata(os.fstat(parent_fd)) != journal.parent_before:
            raise AgentError(error)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error) from exc


def _fleet_identity_journal_rollback(
    parent_fd: int,
    home_fd: int,
    journal: _FleetIdentityJournal,
) -> None:
    error = "fleet_identity_journal_rollback_diverged"
    if (
        journal.fd < 0
        or _fleet_snapshot_metadata(os.fstat(parent_fd)) != journal.parent_current
        or _fleet_snapshot_metadata(os.fstat(home_fd)) != journal.directory_current[""]
        or _fleet_snapshot_metadata(os.fstat(journal.fd)) != journal.snapshot
    ):
        raise AgentError(error)
    if any(
        state.entry.replacement_kind not in {None, "file", "directory"}
        for state in journal.states
    ):
        raise AgentError(error)
    for state in reversed(journal.states):
        if not state.old_moved and not state.replacement_moved:
            continue
        entry = state.entry
        path = Path(entry.name)
        parent_name = path.parent.as_posix()
        parent_name = "" if parent_name == "." else parent_name
        entry_parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            entry.name,
            create=False,
            error=error,
        )
        try:
            if (
                _fleet_snapshot_metadata(os.fstat(entry_parent_fd))
                != journal.directory_current[parent_name]
                or _fleet_snapshot_metadata(os.fstat(journal.fd)) != journal.snapshot
            ):
                raise AgentError(error)
            if state.replacement_moved:
                expected_replacement = (
                    (journal.directory_current[entry.name], None)
                    if entry.replacement_kind == "directory"
                    else state.replacement_snapshot
                )
                if state.replacement_slot is None or expected_replacement is None:
                    raise AgentError(error)
                _fleet_identity_journal_rename_noreplace_at(
                    entry_parent_fd,
                    basename,
                    journal.fd,
                    state.replacement_slot,
                    expected_replacement,
                    error=error,
                    transition=(
                        journal,
                        state,
                        parent_name,
                        entry_parent_fd,
                        "replacement_moved",
                        False,
                        expected_replacement,
                    ),
                )
                if entry.replacement_kind == "directory":
                    journal.directory_current.pop(entry.name, None)
            if state.old_moved:
                if state.old_slot is None or entry.before is None:
                    raise AgentError(error)
                _fleet_identity_journal_rename_noreplace_at(
                    journal.fd,
                    state.old_slot,
                    entry_parent_fd,
                    basename,
                    entry.before,
                    error=error,
                    transition=(
                        journal,
                        state,
                        parent_name,
                        entry_parent_fd,
                        "old_moved",
                        False,
                        None,
                    ),
                )
        finally:
            os.close(entry_parent_fd)

    absent_directories: set[str] = set()
    for state in journal.states:
        entry = state.entry
        path = Path(entry.name)
        parent_name = path.parent.as_posix()
        parent_name = "" if parent_name == "." else parent_name
        parent_was_absent = any(
            parent_name == name or parent_name.startswith(f"{name}/")
            for name in absent_directories
        )
        if entry.before is None and parent_was_absent:
            if entry.replacement_kind == "directory":
                absent_directories.add(entry.name)
            continue
        entry_parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            entry.name,
            create=False,
            error=error,
        )
        try:
            if entry.before is None:
                try:
                    os.stat(basename, dir_fd=entry_parent_fd, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    raise AgentError(error)
                if entry.replacement_kind == "directory":
                    absent_directories.add(entry.name)
            elif (
                _fleet_identity_journal_snapshot_at(entry_parent_fd, basename, error)
                != entry.before
            ):
                raise AgentError(error)
        finally:
            os.close(entry_parent_fd)

    for _, name, expected in sorted(
        (
            (len(Path(name).parts), name, expected)
            for name, expected in journal.directory_before.items()
        ),
        reverse=True,
    ):
        if name:
            directory_parent_fd, basename = _fleet_open_artifact_parent(
                home_fd,
                name,
                create=False,
                error=error,
            )
            flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            try:
                directory_fd = os.open(basename, flags, dir_fd=directory_parent_fd)
            finally:
                os.close(directory_parent_fd)
        else:
            directory_fd = os.dup(home_fd)
        try:
            current = os.fstat(directory_fd)
            if _fleet_snapshot_metadata(current) != journal.directory_current[name]:
                raise AgentError(error)
            os.utime(directory_fd, ns=(current.st_atime_ns, expected[7]))
            if _fleet_snapshot_metadata(os.fstat(directory_fd)) != expected:
                raise AgentError(error)
            journal.directory_current[name] = expected
        finally:
            os.close(directory_fd)

    replacement_slots = tuple(
        (state.replacement_slot, state.replacement_snapshot)
        for state in journal.states
        if state.replacement_slot is not None and state.replacement_snapshot is not None
    )
    _fleet_identity_journal_finalize(parent_fd, journal, replacement_slots, error)


def _fleet_identity_journal_commit(
    parent_fd: int,
    journal: _FleetIdentityJournal,
) -> None:
    error = "fleet_identity_journal_cleanup_diverged"
    original_slots = tuple(
        (state.old_slot, state.entry.before)
        for state in journal.states
        if state.old_slot is not None and state.entry.before is not None
    )
    _fleet_identity_journal_finalize(parent_fd, journal, original_slots, error)


def _fleet_home_tree_snapshot(
    home_fd: int,
) -> dict[str, tuple[tuple[int, ...], str | None]]:
    error = "fleet_home_content_invalid"
    files, directories, symlinks = _fleet_tree_entries(home_fd, error)
    snapshot: dict[str, tuple[tuple[int, ...], str | None]] = {
        "": (_fleet_snapshot_metadata(os.fstat(home_fd)), None)
    }
    for name in sorted(directories):
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error=error,
        )
        try:
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
            _fleet_private_directory_stat(current, error)
            snapshot[name] = (_fleet_snapshot_metadata(current), None)
        finally:
            os.close(parent_fd)
    for name in sorted(files | set(symlinks)):
        parent_fd, basename = _fleet_open_artifact_parent(
            home_fd,
            name,
            create=False,
            error=error,
        )
        try:
            current = os.stat(basename, dir_fd=parent_fd, follow_symlinks=False)
        finally:
            os.close(parent_fd)
        content, opened = _fleet_read_private_file_at(
            home_fd,
            name,
            stat_module.S_IMODE(current.st_mode),
            error,
        )
        snapshot[name] = (
            _fleet_snapshot_metadata(opened),
            hashlib.sha256(content).hexdigest(),
        )
    return snapshot


def _fleet_restore_managed_updates(backups: list[dict[str, Any]]) -> bool:
    if not backups:
        return True
    try:
        ids = [item["old_agent"].agent_id for item in backups]
        with (
            pool_agent_lifecycle_locks(
                ids,
                snapshot=backups[0]["inventory"],
            ),
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=False,
                error_text="fleet_update_rollback_diverged",
                require_private=True,
            ) as root,
        ):
            root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                for item in reversed(backups):
                    current = _fleet_managed_home_state(
                        root,
                        item["old_agent"],
                        entry_name=item["backup"],
                        strict_contents=True,
                    )
                    if not source_identity_matches(current, item["home_stat"]):
                        return False
                    backup_fd = open_directory_no_follow_matching(
                        root / item["backup"],
                        current,
                        error_text="fleet_update_rollback_diverged",
                        changed_text="fleet_update_rollback_diverged",
                    )
                    try:
                        if _fleet_home_tree_snapshot(backup_fd) != item["snapshot"]:
                            return False
                    finally:
                        os.close(backup_fd)
                    _fleet_rename_noreplace_at(
                        root_fd,
                        item["backup"],
                        item["old_agent"].agent_id,
                        current,
                        "fleet_update_rollback_diverged",
                        collision_text="fleet_update_rollback_diverged",
                    )
            finally:
                os.close(root_fd)
    except (AgentError, OSError):
        return False
    return True


def _fleet_created_homes_match(
    created: list[
        tuple[str, os.stat_result, dict[str, Any], str]
        | tuple[str, os.stat_result, dict[str, Any]]
    ],
) -> bool:
    if not created:
        return True
    try:
        with (
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT,
                ensure=False,
                error_text="fleet_create_rollback_diverged",
                require_private=True,
            ) as root,
        ):
            for created_item in created:
                agent_id, expected_home, artifacts = created_item[:3]
                current = _fleet_verify_home(
                    root,
                    agent_id,
                    artifacts,
                    exact_contents=True,
                )
                if not source_identity_matches(current, expected_home):
                    return False
    except (AgentError, OSError):
        return False
    return True


def _fleet_reconcile_divergent_materialization(
    current: FleetSnapshot,
    planned: FleetSnapshot,
    authoritative: FleetSnapshot,
    *,
    created: list[tuple[str, os.stat_result, dict[str, Any], str]] | None = None,
    backups: list[dict[str, Any]] | None = None,
    staged: list[dict[str, Any]] | None = None,
    transaction: _FleetRecoveryTransaction | None = None,
) -> bool:
    if transaction is None:
        return False

    try:
        persisted = _fleet_load_recovery_journal(transaction.paths)
    except AgentError:
        return False
    if persisted is None:
        return False
    entries = tuple(persisted.entries)
    if not entries and persisted.operation is not RecoveryOperation.REGISTRY_ONLY:
        return False
    transaction.journal = persisted

    authoritative_inventory = build_inventory(authoritative, AGENT_POOL_ROOT)
    authoritative_fingerprints = {
        agent_id: (
            descriptor_fingerprint(authoritative_inventory.agents[agent_id])
            if agent_id in authoritative_inventory.agents
            else None
        )
        for entry in entries
        for agent_id in [entry.agent_id]
    }
    plan = plan_reconciliation(persisted, authoritative_fingerprints)
    errors, blocking = _fleet_execute_recovery_plan(
        transaction,
        plan,
        authoritative,
    )
    if errors:
        return False
    if blocking:
        return False
    return True


def _fleet_apply_managed_update(
    service: FleetService,
    current: FleetSnapshot,
    planned: FleetSnapshot,
    existing: FleetSeries,
    candidate: FleetSeries,
    materialization: dict[str, tuple[str, ...]],
    *,
    expected_generation: int,
    codex_executable: Path | None,
    gemini_executable: Path | None,
    transaction: _FleetRecoveryTransaction | None = None,
) -> tuple[FleetSnapshot, bool, int, int, int]:
    if existing.enabled and not candidate.enabled:
        raise AgentError("series_must_be_disabled")

    def find_entry(
        agent_id: str,
        kind: MutationKind,
    ) -> tuple[int | None, RecoveryEntry | None]:
        if transaction is None:
            return None, None
        for index, entry in enumerate(transaction.journal.entries):
            if entry.agent_id == agent_id and entry.kind == kind:
                return index, entry
        return None, None

    old_inventory = build_inventory(current, AGENT_POOL_ROOT)
    new_inventory = build_inventory(planned, AGENT_POOL_ROOT)
    update_ids = list(materialization["update_ids"])
    create_ids = list(materialization["create_ids"])
    remove_ids = list(materialization["remove_ids"])
    backups: list[dict[str, Any]] = []
    created: list[tuple[str, os.stat_result, dict[str, Any], str]] = []
    staged: list[dict[str, Any]] = []

    def rollback() -> bool:
        clean = True
        if created and not _fleet_rollback_created(created):
            clean = False
        if backups and not _fleet_restore_managed_updates(backups):
            clean = False
        if staged and not _fleet_restore_tombstones(staged):
            clean = False
        return clean

    def _advance_verified(target_generation: int | None = None) -> None:
        if transaction is None:
            return
        if transaction.journal.phase is RecoveryPhase.CAS_PENDING:
            transaction.advance(
                RecoveryPhase.RECONCILING,
                authoritative_generation=target_generation,
            )
        transaction.advance(
            RecoveryPhase.VERIFIED,
            authoritative_generation=target_generation,
        )

    if transaction is not None:
        transaction.advance(RecoveryPhase.MATERIALIZING)

    with _fleet_artifact_builder(
        candidate.runner,
        codex_executable=codex_executable,
        gemini_executable=gemini_executable,
    ) as build_artifacts:
        try:
            new_artifacts = {
                agent_id: build_artifacts(new_inventory.agents[agent_id])
                for agent_id in (*update_ids, *create_ids)
            }
            with _fleet_idle_agent_locks(
                old_inventory, [*update_ids, *remove_ids]
            ) as pinned:
                with (
                    pool_root_lock(AGENT_POOL_ROOT),
                    pool_root_operation(
                        AGENT_POOL_ROOT,
                        ensure=not (update_ids or remove_ids),
                        error_text="fleet_pool_root_invalid",
                        require_private=True,
                    ) as root,
                ):
                    marker_present = _fleet_root_marker_state(root)
                    if not marker_present and (update_ids or remove_ids):
                        raise AgentError("fleet_pool_marker_required")
                    root_fd = os.open(root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
                    try:
                        if not marker_present:
                            _fleet_write_root_marker(root_fd)
                        for agent_id in update_ids:
                            old_agent = old_inventory.agents[agent_id]
                            new_agent = new_inventory.agents[agent_id]
                            current_home = _fleet_managed_home_state(
                                root,
                                old_agent,
                                strict_contents=True,
                            )
                            if not source_identity_matches(
                                current_home, pinned[agent_id]
                            ):
                                raise AgentError("fleet_home_changed")
                            home_fd = open_directory_no_follow_matching(
                                root / agent_id,
                                current_home,
                                error_text="fleet_home_changed",
                                changed_text="fleet_home_changed",
                            )
                            try:
                                if "auth.json" in os.listdir(home_fd):
                                    auth_bytes, auth_mode, _auth_stat = (
                                        _fleet_home_file_snapshot(
                                            home_fd,
                                            "auth.json",
                                        )
                                    )
                                    new_artifacts[agent_id]["extra_files"] = {
                                        "auth.json": (auth_bytes, auth_mode)
                                    }
                                backup_snapshot = _fleet_home_tree_snapshot(home_fd)
                            finally:
                                os.close(home_fd)
                            backup_index, backup_entry = find_entry(
                                agent_id, MutationKind.BACKUP
                            )
                            if transaction is not None and backup_index is not None:
                                transaction.record_entry_phase(
                                    backup_index, EntryPhase.INTENT
                                )
                            backup = (
                                backup_entry.hidden_name
                                if backup_entry is not None
                                else f"{FLEET_TOMBSTONE_PREFIX}backup-{uuid.uuid4().hex}"
                            )
                            backup_item = {
                                "old_agent": old_agent,
                                "inventory": old_inventory,
                                "backup": backup,
                                "home_stat": current_home,
                                "snapshot": backup_snapshot,
                            }
                            _fleet_rename_noreplace_at(
                                root_fd,
                                agent_id,
                                backup,
                                current_home,
                                "fleet_managed_update_failed",
                                collision_text="fleet_tombstone_collision",
                                committed=lambda item=backup_item: backups.append(item),
                            )
                            if transaction is not None and backup_index is not None:
                                transaction.record_entry_phase(
                                    backup_index,
                                    EntryPhase.INTENT,
                                    source_identity=_snapshot_file_identity(
                                        current_home
                                    ),
                                )
                            create_index, create_entry = find_entry(
                                agent_id, MutationKind.CREATED
                            )
                            create_hidden_name = (
                                create_entry.hidden_name
                                if create_entry is not None
                                else None
                            )
                            if create_hidden_name is None:
                                raise AgentError("fleet_recovery_state_invalid")
                            if transaction is not None and create_index is not None:
                                transaction.record_entry_phase(
                                    create_index,
                                    EntryPhase.INTENT,
                                )
                            try:
                                home_stat = _fleet_create_home(
                                    root_fd,
                                    agent_id,
                                    new_artifacts[agent_id],
                                    hidden_name=create_hidden_name,
                                    entry_index=create_index,
                                    transaction=transaction,
                                )
                            except _FleetPartialHomeError:
                                raise AgentError(
                                    "fleet_materialization_failed"
                                ) from None
                            if transaction is not None and create_index is not None:
                                transaction.record_entry_phase(
                                    create_index,
                                    transaction.journal.entries[create_index].phase,
                                    target_identity=_snapshot_file_identity(home_stat),
                                )
                            created.append(
                                (
                                    agent_id,
                                    home_stat,
                                    new_artifacts[agent_id],
                                    create_hidden_name,
                                )
                            )
                            _fleet_verify_home(
                                root,
                                agent_id,
                                new_artifacts[agent_id],
                                exact_contents=True,
                            )
                            _fleet_managed_home_state(
                                root, new_agent, strict_contents=True
                            )

                        for agent_id in create_ids:
                            create_index, create_entry = find_entry(
                                agent_id, MutationKind.CREATED
                            )
                            create_hidden_name = (
                                create_entry.hidden_name
                                if create_entry is not None
                                else None
                            )
                            if path_present_no_follow(root / agent_id):
                                raise AgentError("fleet_create_target_exists")
                            if transaction is not None and create_index is not None:
                                transaction.record_entry_phase(
                                    create_index, EntryPhase.INTENT
                                )
                            try:
                                home_stat = _fleet_create_home(
                                    root_fd,
                                    agent_id,
                                    new_artifacts[agent_id],
                                    hidden_name=create_hidden_name,
                                    entry_index=create_index,
                                    transaction=transaction,
                                )
                            except _FleetPartialHomeError:
                                raise AgentError(
                                    "fleet_materialization_failed"
                                ) from None
                            if transaction is not None and create_index is not None:
                                transaction.record_entry_phase(
                                    create_index,
                                    transaction.journal.entries[create_index].phase,
                                    target_identity=_snapshot_file_identity(home_stat),
                                )
                            created.append(
                                (
                                    agent_id,
                                    home_stat,
                                    new_artifacts[agent_id],
                                    create_hidden_name or "",
                                )
                            )
                            _fleet_verify_home(
                                root,
                                agent_id,
                                new_artifacts[agent_id],
                                exact_contents=True,
                            )

                        for agent_id in sorted(
                            remove_ids,
                            key=lambda item: old_inventory.agents[item].ordinal,
                            reverse=True,
                        ):
                            old_agent = old_inventory.agents[agent_id]
                            current_home = _fleet_managed_home_state(
                                root,
                                old_agent,
                                strict_contents=True,
                            )
                            if not source_identity_matches(
                                current_home, pinned[agent_id]
                            ):
                                raise AgentError("fleet_home_changed")
                            tombstone_index, tombstone_entry = find_entry(
                                agent_id, MutationKind.TOMBSTONE
                            )
                            if transaction is not None and tombstone_index is not None:
                                transaction.record_entry_phase(
                                    tombstone_index, EntryPhase.INTENT
                                )
                            tombstone = (
                                tombstone_entry.hidden_name
                                if tombstone_entry is not None
                                else f"{FLEET_TOMBSTONE_PREFIX}{uuid.uuid4().hex}"
                            )
                            staged_item = {
                                "agent": old_agent,
                                "inventory": old_inventory,
                                "tombstone": tombstone,
                                "home_stat": current_home,
                            }
                            _fleet_rename_noreplace_at(
                                root_fd,
                                agent_id,
                                tombstone,
                                current_home,
                                "fleet_tombstone_stage_failed",
                                collision_text="fleet_tombstone_collision",
                                committed=lambda item=staged_item: staged.append(item),
                            )
                            if transaction is not None and tombstone_index is not None:
                                transaction.record_entry_phase(
                                    tombstone_index,
                                    EntryPhase.INTENT,
                                    source_identity=_snapshot_file_identity(
                                        current_home
                                    ),
                                )
                    finally:
                        os.close(root_fd)
            build_artifacts.validate()  # type: ignore[attr-defined]
        except Exception as exc:
            if not rollback():
                raise AgentError("fleet_update_rollback_diverged") from None
            if isinstance(exc, AgentError):
                raise
            raise AgentError("fleet_managed_update_failed") from None
        if transaction is not None:
            transaction.advance(RecoveryPhase.CAS_PENDING)
        try:
            stored = service.commit_snapshot(
                planned, expected_generation=expected_generation
            )
        except Exception as exc:
            state, reloaded = _fleet_reconcile_commit_exception(
                service, current, planned
            )
            if state == "planned":
                if transaction is not None:
                    _advance_verified(reloaded.generation)
                try:
                    build_artifacts.validate()  # type: ignore[attr-defined]
                except AgentError:
                    _fleet_publish_stored(service, reloaded)
                    raise AgentError("fleet_executable_changed_after_cas") from None
                _fleet_publish_stored(service, reloaded)
                try:
                    build_artifacts.validate()  # type: ignore[attr-defined]
                except AgentError:
                    raise AgentError("fleet_executable_changed_after_cas") from None
                created = []
                backups = []
                staged = []
                raise AgentError("fleet_registry_commit_failed_after_cas") from None
            if state == "third":
                if transaction is not None:
                    transaction.advance(
                        RecoveryPhase.RECONCILING,
                        authoritative_generation=reloaded.generation,
                    )
                reconciled = _fleet_reconcile_divergent_materialization(
                    current,
                    planned,
                    reloaded,
                    created=created,
                    backups=backups,
                    staged=staged,
                    transaction=transaction,
                )
                if not reconciled:
                    raise AgentError("fleet_registry_commit_diverged") from None
                if transaction is not None:
                    _advance_verified(reloaded.generation)
                _fleet_publish_stored(service, reloaded)
                created = []
                backups = []
                staged = []
                raise AgentError("fleet_registry_commit_diverged") from None
            if not rollback():
                created = []
                backups = []
                staged = []
                raise AgentError("fleet_update_rollback_diverged") from None
            if isinstance(exc, FleetConflictError):
                if transaction is not None:
                    _fleet_complete_rolled_back_transaction(
                        transaction,
                        current.generation,
                    )
                created = []
                backups = []
                staged = []
                raise AgentError("generation_conflict") from None
            created = []
            backups = []
            staged = []
            raise AgentError("fleet_registry_commit_failed") from None
        try:
            build_artifacts.validate()  # type: ignore[attr-defined]
        except AgentError:
            if transaction is not None:
                _advance_verified(stored.generation)
            _fleet_publish_stored(service, stored)
            raise AgentError("fleet_executable_changed_after_cas") from None
        if transaction is not None:
            transaction.advance(
                RecoveryPhase.RECONCILING,
                authoritative_generation=stored.generation,
            )
            transaction.advance(
                RecoveryPhase.VERIFIED, authoritative_generation=stored.generation
            )
        _fleet_publish_stored(service, stored)
        if transaction is not None:
            transaction.advance(
                RecoveryPhase.PUBLISHED, authoritative_generation=stored.generation
            )
            transaction.advance(
                RecoveryPhase.COMPLETE, authoritative_generation=stored.generation
            )
            _fleet_remove_complete_recovery_journal(transaction.journal)
        try:
            build_artifacts.validate()  # type: ignore[attr-defined]
        except AgentError:
            raise AgentError("fleet_executable_changed_after_cas") from None
    cleanup_pending = bool(backups or staged)
    try:
        cleanup_pending = _fleet_cleanup_tombstones(staged) or cleanup_pending
    except Exception:
        cleanup_pending = True
    cleanup_pending = build_artifacts.close_state["cleanup_pending"] or cleanup_pending  # type: ignore[attr-defined]
    return stored, cleanup_pending, len(create_ids), len(update_ids), len(remove_ids)


_Q_INPLACE_MANAGED_FILES = {
    "codex",
    "config.toml",
    "AGENTS.md",
    "AGENTS.class-teamleiterin.md",
    FLEET_AGENT_MARKER_FILE,
}


def _fleet_q_inplace_failure(
    core_code: str,
    *,
    server_code: str | None = None,
) -> FleetInplaceUpdateError:
    code = server_code or {
        "registry_conflict": "generation_conflict",
        "registry_cas_uncertain": "fleet_registry_commit_uncertain",
        "rollback_diverged": "fleet_update_rollback_diverged",
        "roll_forward_diverged": "fleet_update_recovery_diverged",
        "generation_ambiguous": "fleet_registry_commit_diverged",
        "recovery_diverged": "fleet_update_recovery_diverged",
        "managed_drift": "fleet_home_changed",
        "home_drift": "fleet_home_changed",
        "unsafe_home": "fleet_home_content_invalid",
        "unsafe_managed_leaf": "fleet_home_content_invalid",
        "transaction_contains_foreign_entry": "fleet_recovery_incomplete",
        "transaction_exists": "fleet_recovery_incomplete",
        "invalid_journal": "fleet_recovery_incomplete",
    }.get(core_code, "fleet_managed_update_failed")
    retained = core_code in {
        "registry_cas_uncertain",
        "rollback_diverged",
        "roll_forward_diverged",
        "generation_ambiguous",
        "recovery_diverged",
        "transaction_contains_foreign_entry",
        "transaction_exists",
        "invalid_journal",
    }
    return FleetInplaceUpdateError(
        code,
        {
            "code": code,
            "explanation": (
                "Der transaktionale Q-Serien-Updatezustand ist nicht eindeutig bestaetigt."
                if retained
                else "Der transaktionale Q-Serien-Updatepfad hat die Aenderung sicher abgebrochen."
            ),
            "rule": (
                "Q-Homes bleiben bestehen; nur codex, config.toml, die Hive-Markdown-Dateien und der Fleet-Marker "
                "duerfen unter genau einem Registry-CAS geaendert werden."
            ),
            "action": (
                "Recovery-Zustand und autoritative Generation pruefen; nicht manuell migrieren."
                if retained
                else "Autoritative Generation neu laden, Ursache beheben und erneut planen."
            ),
        },
    )


def _fleet_q_inplace_transaction_root(paths: FleetPaths) -> Path:
    return paths.root / "q-inplace"


def _fleet_q_inplace_pending_transaction(transaction_root: Path) -> str | None:
    try:
        root_stat = transaction_root.lstat()
    except FileNotFoundError:
        return None
    except OSError:
        raise _fleet_q_inplace_failure("invalid_journal") from None
    try:
        _fleet_private_directory_stat(root_stat, "fleet_recovery_incomplete")
        root_fd = os.open(
            transaction_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            if not source_identity_matches(os.fstat(root_fd), root_stat):
                raise _fleet_q_inplace_failure("invalid_journal")
            names = os.listdir(root_fd)
            for name in names:
                if re.fullmatch(r"[0-9a-f]{32}", name) is None:
                    raise _fleet_q_inplace_failure("transaction_contains_foreign_entry")
                child = os.stat(name, dir_fd=root_fd, follow_symlinks=False)
                _fleet_private_directory_stat(child, "fleet_recovery_incomplete")
        finally:
            os.close(root_fd)
    except FleetInplaceUpdateError:
        raise
    except (AgentError, OSError):
        raise _fleet_q_inplace_failure("invalid_journal") from None
    if len(names) > 1:
        raise _fleet_q_inplace_failure("transaction_exists")
    return names[0] if names else None


def _fleet_recover_pending_q_inplace(service: FleetService, paths: FleetPaths) -> None:
    transaction_root = _fleet_q_inplace_transaction_root(paths)
    transaction_id = _fleet_q_inplace_pending_transaction(transaction_root)
    if transaction_id is None:
        return
    try:
        authoritative = service.load()
        inventory = build_inventory(authoritative, AGENT_POOL_ROOT)
        homes = {
            agent_id: descriptor.home
            for agent_id, descriptor in inventory.agents.items()
            if descriptor.series_prefix == "q"
        }
        recover_q_series_update(
            homes,
            transaction_root=transaction_root,
            transaction_id=transaction_id,
            authoritative_generation=authoritative.generation,
        )
    except InplaceError as exc:
        server_code = (
            "fleet_update_recovery_diverged"
            if exc.code in {"rollback_diverged", "roll_forward_diverged"}
            else None
        )
        raise _fleet_q_inplace_failure(exc.code, server_code=server_code) from None
    except FleetInplaceUpdateError:
        raise
    except Exception:
        raise _fleet_q_inplace_failure("registry_cas_uncertain") from None
    _fleet_publish_stored(service, authoritative)


def _fleet_q_inplace_eligible(
    existing: FleetSeries,
    candidate: FleetSeries,
    materialization: Mapping[str, tuple[str, ...]],
) -> bool:
    expected_ids = tuple(f"q{ordinal}" for ordinal in range(1, candidate.count + 1))
    return (
        existing.prefix == candidate.prefix == "q"
        and existing.count == candidate.count == 3
        and existing.runner is candidate.runner is RunnerKind.CODEX_CLI
        and existing.provider is candidate.provider is Provider.OPENAI_CHATGPT
        and existing.skill_profile == candidate.skill_profile == "teamleiterin"
        and existing.task_profile == candidate.task_profile == "standard"
        and not materialization["create_ids"]
        and not materialization["remove_ids"]
        and materialization["update_ids"] == expected_ids
    )


def _fleet_apply_q_inplace_update(
    service: FleetService,
    current: FleetSnapshot,
    planned: FleetSnapshot,
    candidate: FleetSeries,
    materialization: Mapping[str, tuple[str, ...]],
    *,
    codex_executable: Path | None,
) -> FleetSnapshot:
    paths = FleetPaths.from_state_root(STATE_ROOT)
    transaction_root = _fleet_q_inplace_transaction_root(paths)
    ensure_private_dir(transaction_root)
    planned_inventory = build_inventory(planned, AGENT_POOL_ROOT)
    with (
        pool_root_lock(AGENT_POOL_ROOT),
        pool_root_operation(
            AGENT_POOL_ROOT,
            ensure=False,
            error_text="fleet_pool_root_invalid",
            require_private=True,
        ) as root,
    ):
        if not _fleet_root_marker_state(root):
            raise AgentError("fleet_pool_marker_required")
    stored: FleetSnapshot | None = None
    updates: list[QHomeUpdate] = []
    with _fleet_artifact_builder(
        candidate.runner,
        codex_executable=codex_executable,
        gemini_executable=None,
        include_portable_skills=False,
    ) as build_artifacts:
        for agent_id in materialization["update_ids"]:
            descriptor = planned_inventory.agents[agent_id]
            artifacts = build_artifacts(descriptor)
            files = _fleet_artifact_files(artifacts)
            if set(files) != _Q_INPLACE_MANAGED_FILES:
                raise _fleet_q_inplace_failure(
                    "invalid_request",
                    server_code="fleet_q_inplace_scope_invalid",
                )
            updates.append(
                QHomeUpdate(
                    home_id=agent_id,
                    home=descriptor.home,
                    wrapper=files["codex"][0],
                    config=files["config.toml"][0],
                    instructions=files["AGENTS.md"][0],
                    class_instructions=files["AGENTS.class-teamleiterin.md"][0],
                    marker=files[FLEET_AGENT_MARKER_FILE][0],
                )
            )
        build_artifacts.validate()  # type: ignore[attr-defined]

        def registry_cas(old_generation: int, new_generation: int) -> bool:
            nonlocal stored
            if (
                old_generation != current.generation
                or new_generation != planned.generation
            ):
                raise RuntimeError("generation mismatch")
            build_artifacts.validate()  # type: ignore[attr-defined]
            try:
                stored = service.commit_snapshot(
                    planned,
                    expected_generation=old_generation,
                )
            except FleetConflictError:
                return False
            if stored.generation != new_generation:
                raise RuntimeError("generation mismatch")
            build_artifacts.validate()  # type: ignore[attr-defined]
            return True

        try:
            apply_q_series_update(
                tuple(updates),
                transaction_root=transaction_root,
                transaction_id=uuid.uuid4().hex,
                old_generation=current.generation,
                new_generation=planned.generation,
                registry_cas=registry_cas,
            )
        except InplaceError as exc:
            if exc.code != "registry_cas_uncertain":
                raise _fleet_q_inplace_failure(exc.code) from None
            try:
                authoritative = service.load()
                transaction_id = _fleet_q_inplace_pending_transaction(transaction_root)
                if transaction_id is None:
                    raise _fleet_q_inplace_failure("invalid_journal")
                recover_q_series_update(
                    {item.home_id: item.home for item in updates},
                    transaction_root=transaction_root,
                    transaction_id=transaction_id,
                    authoritative_generation=authoritative.generation,
                )
            except FleetInplaceUpdateError:
                raise
            except InplaceError as recovery_error:
                server_code = (
                    "fleet_update_recovery_diverged"
                    if recovery_error.code
                    in {"rollback_diverged", "roll_forward_diverged"}
                    else None
                )
                raise _fleet_q_inplace_failure(
                    recovery_error.code,
                    server_code=server_code,
                ) from None
            except Exception:
                raise _fleet_q_inplace_failure("registry_cas_uncertain") from None
            if authoritative.generation == planned.generation:
                _fleet_publish_stored(service, authoritative)
                raise _fleet_q_inplace_failure(
                    "registry_cas_uncertain",
                    server_code="fleet_registry_commit_failed_after_cas",
                ) from None
            raise _fleet_q_inplace_failure(
                "registry_cas_uncertain",
                server_code="fleet_registry_commit_failed",
            ) from None
        build_artifacts.validate()  # type: ignore[attr-defined]
    if stored is None:
        raise _fleet_q_inplace_failure("registry_cas_uncertain")
    _fleet_publish_stored(service, stored)
    return stored


def fleet_series_apply(
    *,
    prefix: str,
    count: int,
    runner: str,
    provider: str,
    model: str,
    account_id: str | None,
    enabled: bool = True,
    expected_generation: int,
    confirmed_remove_ids: list[str] | None = None,
    skill_profile: str = "generic",
    task_profile: str = "standard",
    codex_executable: Path | None = None,
    gemini_executable: Path | None = None,
) -> dict[str, Any]:
    fleet_paths = FleetPaths.from_state_root(STATE_ROOT)
    if prefix == "q":
        service = current_fleet_service()
        with fleet_mutation_lock(fleet_paths):
            _fleet_recover_pending_q_inplace(service, fleet_paths)
    else:
        require_fleet_recovery_ready("fleet_series_apply")
        service = current_fleet_service()
    if prefix == "q":
        require_fleet_recovery_ready("fleet_series_apply")
    plan, current, planned, existing, candidate, materialization = (
        _fleet_series_plan_with_service(
            service,
            prefix=prefix,
            count=count,
            runner=runner,
            provider=provider,
            model=model,
            account_id=account_id,
            enabled=enabled,
            expected_generation=expected_generation,
            confirmed_remove_ids=confirmed_remove_ids,
            skill_profile=skill_profile,
            task_profile=task_profile,
        )
    )
    if materialization["create_ids"]:
        require_resource_capacity_preflight(operation="fleet_series_apply")
    planned_inventory = build_inventory(planned, AGENT_POOL_ROOT)
    old_count = existing.count if existing is not None else 0
    managed_changed = existing is not None and (
        existing.runner is not candidate.runner
        or existing.provider is not candidate.provider
        or existing.model != candidate.model
        or existing.skill_profile != candidate.skill_profile
        or existing.task_profile != candidate.task_profile
    )
    prepared_recovery_entries: tuple[RecoveryEntry, ...] = ()
    with fleet_mutation_lock(fleet_paths):
        if candidate.prefix == "q":
            _fleet_recover_pending_q_inplace(service, fleet_paths)
        if managed_changed and any(
            plan[name] for name in ("create_count", "update_count", "remove_count")
        ):
            if candidate.prefix == "q":
                if not _fleet_q_inplace_eligible(existing, candidate, materialization):
                    raise _fleet_q_inplace_failure(
                        "invalid_request",
                        server_code="fleet_q_inplace_scope_invalid",
                    )
                stored = _fleet_apply_q_inplace_update(
                    service,
                    current,
                    planned,
                    candidate,
                    materialization,
                    codex_executable=codex_executable,
                )
                return {
                    "mutation_performed": True,
                    "generation": stored.generation,
                    "created_count": 0,
                    "kept_count": 0,
                    "updated_count": len(materialization["update_ids"]),
                    "removed_count": 0,
                    "cleanup_pending": False,
                    "pool_root": "not_returned",
                    "raw_output": "not_returned",
                }
            prepared_recovery_entries = _fleet_prepare_managed_update_recovery_entries(
                current,
                planned,
                materialization["update_ids"],
                materialization["create_ids"],
                materialization["remove_ids"],
            )
            with _fleet_active_recovery_transaction(
                _FleetRecoveryTransaction.begin(
                    RecoveryOperation.SERIES_APPLY,
                    current,
                    planned,
                    prepared_recovery_entries,
                )
            ):
                stored, cleanup_pending, created_count, updated_count, removed_count = (
                    _fleet_apply_managed_update(
                        service,
                        current,
                        planned,
                        existing,
                        candidate,
                        materialization,
                        expected_generation=expected_generation,
                        codex_executable=codex_executable,
                        gemini_executable=gemini_executable,
                        transaction=_FLEET_ACTIVE_RECOVERY_TRANSACTION.get(),
                    )
                )
            return {
                "mutation_performed": True,
                "generation": stored.generation,
                "created_count": created_count,
                "kept_count": 0,
                "updated_count": updated_count,
                "removed_count": removed_count,
                "cleanup_pending": cleanup_pending,
                "pool_root": "not_returned",
                "raw_output": "not_returned",
            }
    with fleet_mutation_lock(fleet_paths):
        enabling = existing is not None and not existing.enabled and candidate.enabled
        registry_only = not any(
            materialization[name] for name in ("create_ids", "update_ids", "remove_ids")
        ) and (
            (existing is None and not candidate.enabled)
            or managed_changed
            or (existing is not None and old_count == candidate.count and not enabling)
        )
        if registry_only:
            _fleet_validate_materialized_series_homes(planned, candidate)
            stored = _fleet_commit_registry_only(
                service,
                current,
                planned,
                expected_generation=expected_generation,
            )
            return {
                "mutation_performed": True,
                "generation": stored.generation,
                "created_count": 0,
                "kept_count": len(materialization["keep_ids"]),
                "updated_count": len(materialization["update_ids"]),
                "removed_count": len(materialization["remove_ids"]),
                "cleanup_pending": False,
                "pool_root": "not_returned",
                "raw_output": "not_returned",
            }

        create_ids = list(materialization["create_ids"])
        keep_ids = list(materialization["keep_ids"])
        update_ids = list(materialization["update_ids"])
        remove_ids = list(materialization["remove_ids"])
        verify_keep_ids = keep_ids if enabling else []
        artifacts: dict[str, dict[str, Any]] = {}
        created: list[tuple[str, os.stat_result, dict[str, Any]]] = []
        staged: list[dict[str, Any]] = []
        active_tx = None
        preplanned_create_indexes: dict[str, int] = {}
        preplanned_create_names: dict[str, str] = {}
        planned_tombstone_indexes: dict[str, int] = {}
        planned_tombstone_names: dict[str, str] = {}
        if create_ids or update_ids or remove_ids:
            prepared_entries: list[RecoveryEntry] = []
            current_inventory = build_inventory(current, AGENT_POOL_ROOT)
            for agent_id in create_ids:
                hidden_name = f"{FLEET_TOMBSTONE_PREFIX}create-{uuid.uuid4().hex}"
                new_agent = planned_inventory.agents[agent_id]
                preplanned_create_indexes[agent_id] = len(prepared_entries)
                preplanned_create_names[agent_id] = hidden_name
                prepared_entries.append(
                    RecoveryEntry(
                        kind=MutationKind.CREATED,
                        agent_id=agent_id,
                        hidden_name=hidden_name,
                        old_descriptor_fingerprint=None,
                        new_descriptor_fingerprint=descriptor_fingerprint(new_agent),
                        old_materialization_fingerprint=None,
                        new_materialization_fingerprint=None,
                        source_identity=None,
                        target_identity=None,
                        manifest=(),
                        phase=EntryPhase.INTENT,
                        result_code=None,
                    )
                )
            for agent_id in remove_ids:
                old_agent = current_inventory.agents[agent_id]
                hidden_name = f"{FLEET_TOMBSTONE_PREFIX}tombstone-{uuid.uuid4().hex}"
                planned_tombstone_indexes[agent_id] = len(prepared_entries)
                planned_tombstone_names[agent_id] = hidden_name
                prepared_entries.append(
                    RecoveryEntry(
                        kind=MutationKind.TOMBSTONE,
                        agent_id=agent_id,
                        hidden_name=hidden_name,
                        old_descriptor_fingerprint=descriptor_fingerprint(old_agent),
                        new_descriptor_fingerprint=None,
                        old_materialization_fingerprint=None,
                        new_materialization_fingerprint=None,
                        source_identity=None,
                        target_identity=None,
                        manifest=(),
                        phase=EntryPhase.INTENT,
                        result_code=None,
                    )
                )
            active_tx = _FleetRecoveryTransaction.begin(
                RecoveryOperation.SERIES_APPLY,
                current,
                planned,
                tuple(prepared_entries),
            )
            _fleet_recovery_crash_point("after_journal_before_pool")
        artifact_context = (
            _fleet_artifact_builder(
                candidate.runner,
                codex_executable=codex_executable,
                gemini_executable=gemini_executable,
            )
            if create_ids or verify_keep_ids
            else contextlib.nullcontext(None)
        )
        with _fleet_active_recovery_transaction(active_tx):
            with artifact_context as build_artifacts:
                try:

                    def _advance_verified(target_generation: int | None = None) -> None:
                        if active_tx is None:
                            return
                        if active_tx.journal.phase is RecoveryPhase.CAS_PENDING:
                            active_tx.advance(
                                RecoveryPhase.RECONCILING,
                                authoritative_generation=target_generation,
                            )
                        active_tx.advance(
                            RecoveryPhase.VERIFIED,
                            authoritative_generation=target_generation,
                        )

                    if active_tx is not None:
                        active_tx.advance(RecoveryPhase.MATERIALIZING)
                    _fleet_recovery_crash_point("after_intent_before_filesystem")
                    if build_artifacts is not None:
                        for agent_id in (*verify_keep_ids, *create_ids):
                            artifacts[agent_id] = build_artifacts(
                                planned_inventory.agents[agent_id]
                            )
                    if verify_keep_ids or create_ids:
                        with (
                            pool_root_lock(AGENT_POOL_ROOT),
                            pool_root_operation(
                                AGENT_POOL_ROOT,
                                ensure=True,
                                error_text="fleet_pool_root_invalid",
                                require_private=True,
                            ) as root,
                        ):
                            marker_present = _fleet_root_marker_state(root)
                            if not marker_present and remove_ids:
                                raise AgentError("fleet_pool_marker_required")
                            for agent_id in verify_keep_ids:
                                _fleet_verify_home(
                                    root,
                                    agent_id,
                                    artifacts[agent_id],
                                    exact_contents=False,
                                )
                            for agent_id in keep_ids:
                                _fleet_managed_home_state(
                                    root,
                                    planned_inventory.agents[agent_id],
                                    strict_contents=True,
                                )
                            for agent_id in create_ids:
                                if path_present_no_follow(root / agent_id):
                                    raise AgentError("fleet_create_target_exists")
                            root_fd = os.open(
                                root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
                            )
                            try:
                                if not marker_present:
                                    _fleet_write_root_marker(root_fd)
                                for agent_id in create_ids:
                                    try:
                                        home_stat = _fleet_create_home(
                                            root_fd,
                                            agent_id,
                                            artifacts[agent_id],
                                            hidden_name=preplanned_create_names[
                                                agent_id
                                            ],
                                            entry_index=preplanned_create_indexes[
                                                agent_id
                                            ],
                                            transaction=active_tx,
                                        )
                                    except _FleetPartialHomeError:
                                        raise AgentError(
                                            "fleet_materialization_failed"
                                        ) from None
                                    entry_index = preplanned_create_indexes[agent_id]
                                    if (
                                        active_tx is not None
                                        and entry_index is not None
                                    ):
                                        active_tx.record_entry_phase(
                                            entry_index,
                                            active_tx.journal.entries[
                                                entry_index
                                            ].phase,
                                            target_identity=_snapshot_file_identity(
                                                home_stat
                                            ),
                                        )
                                    created.append(
                                        (
                                            agent_id,
                                            home_stat,
                                            artifacts[agent_id],
                                            preplanned_create_names[agent_id],
                                        )
                                    )
                                for created_item in created:
                                    agent_id, _home_stat, item_artifacts = created_item[
                                        :3
                                    ]
                                    _fleet_verify_home(
                                        root,
                                        agent_id,
                                        item_artifacts,
                                        exact_contents=True,
                                    )
                            finally:
                                os.close(root_fd)
                    if remove_ids:
                        staged = _fleet_stage_tombstones(
                            build_inventory(current, AGENT_POOL_ROOT),
                            remove_ids,
                            transaction=active_tx,
                            planned_tombstones={
                                agent_id: (
                                    planned_tombstone_names[agent_id],
                                    planned_tombstone_indexes[agent_id],
                                )
                                for agent_id in planned_tombstone_names
                            },
                        )
                    _fleet_recovery_crash_point("after_filesystem_before_applied")
                    if build_artifacts is not None:
                        build_artifacts.validate()  # type: ignore[attr-defined]
                    _fleet_recovery_crash_point("after_materialization_before_cas")
                    try:
                        if (
                            active_tx is not None
                            and active_tx.journal.phase is RecoveryPhase.MATERIALIZING
                        ):
                            active_tx.advance(RecoveryPhase.CAS_PENDING)
                        stored = service.commit_snapshot(
                            planned, expected_generation=expected_generation
                        )
                        _fleet_recovery_crash_point("after_cas_before_reload")
                    except Exception as exc:
                        reconciled_materialization = False
                        state, reloaded = _fleet_reconcile_commit_exception(
                            service, current, planned
                        )
                        if state == "planned":
                            if active_tx is not None:
                                _advance_verified(reloaded.generation)
                            if build_artifacts is not None:
                                try:
                                    build_artifacts.validate()  # type: ignore[attr-defined]
                                except AgentError:
                                    _fleet_publish_stored(service, reloaded)
                                    raise AgentError(
                                        "fleet_executable_changed_after_cas"
                                    ) from None
                            _fleet_publish_stored(service, reloaded)
                            if build_artifacts is not None:
                                try:
                                    build_artifacts.validate()  # type: ignore[attr-defined]
                                except AgentError:
                                    created = []
                                    staged = []
                                    raise AgentError(
                                        "fleet_executable_changed_after_cas"
                                    ) from None
                            created = []
                            staged = []
                            raise AgentError(
                                "fleet_registry_commit_failed_after_cas"
                            ) from None
                        if state == "third":
                            if active_tx is not None:
                                active_tx.advance(
                                    RecoveryPhase.RECONCILING,
                                    authoritative_generation=reloaded.generation,
                                )
                            if reloaded.series == current.series and (
                                created or staged
                            ):
                                reconciled_materialization = True
                                reconciled = _fleet_reconcile_divergent_materialization(
                                    current,
                                    planned,
                                    reloaded,
                                    created=created,
                                    staged=staged,
                                    transaction=active_tx,
                                )
                                if not reconciled:
                                    created = []
                                    staged = []
                                    raise AgentError(
                                        "fleet_registry_commit_diverged"
                                    ) from None
                                created = []
                                staged = []
                                if active_tx is not None:
                                    _advance_verified(reloaded.generation)
                            else:
                                if not created:
                                    created = []
                                    staged = []
                            raise AgentError("fleet_registry_commit_diverged") from None
                        clean = _fleet_rollback_created(created)
                        if (
                            staged
                            and not reconciled_materialization
                            and not _fleet_restore_tombstones(staged)
                        ):
                            clean = False
                            staged = []
                        if not clean:
                            created = []
                            staged = []
                            raise AgentError("fleet_create_rollback_diverged") from None
                        if isinstance(exc, FleetConflictError):
                            if active_tx is not None:
                                _fleet_complete_rolled_back_transaction(
                                    active_tx,
                                    current.generation,
                                )
                            created = []
                            staged = []
                            raise AgentError("generation_conflict") from None
                        created = []
                        staged = []
                        raise AgentError("fleet_registry_commit_failed") from None
                    if build_artifacts is not None:
                        try:
                            build_artifacts.validate()  # type: ignore[attr-defined]
                        except AgentError:
                            if active_tx is not None:
                                _advance_verified(stored.generation)
                            created = []
                            staged = []
                            _fleet_publish_stored(service, stored)
                            raise AgentError(
                                "fleet_executable_changed_after_cas"
                            ) from None
                    try:
                        if active_tx is not None:
                            _advance_verified(stored.generation)
                        _fleet_recovery_crash_point("after_verify_before_publish")
                        _fleet_publish_stored(service, stored)
                        _fleet_recovery_crash_point("after_publish_before_complete")
                    except AgentError:
                        created = []
                        staged = []
                        raise
                    if build_artifacts is not None:
                        try:
                            build_artifacts.validate()  # type: ignore[attr-defined]
                        except AgentError:
                            if active_tx is not None:
                                _fleet_remove_complete_recovery_journal(
                                    active_tx.journal
                                )
                            created = []
                            staged = []
                            raise AgentError(
                                "fleet_executable_changed_after_cas"
                            ) from None
                    if active_tx is not None:
                        active_tx.advance(
                            RecoveryPhase.PUBLISHED,
                            authoritative_generation=stored.generation,
                        )
                        active_tx.advance(
                            RecoveryPhase.COMPLETE,
                            authoritative_generation=stored.generation,
                        )
                        _fleet_recovery_crash_point("after_complete_before_remove")
                        _fleet_remove_complete_recovery_journal(active_tx.journal)
                except Exception as exc:
                    clean = _fleet_rollback_created(created)
                    if staged and not _fleet_restore_tombstones(staged):
                        clean = False
                    if not clean:
                        raise AgentError("fleet_create_rollback_diverged") from None
                    if isinstance(exc, AgentError):
                        raise
                    raise AgentError("fleet_materialization_failed") from None
        cleanup_pending = bool(staged)
        try:
            cleanup_pending = _fleet_cleanup_tombstones(staged) or cleanup_pending
        except Exception:
            cleanup_pending = True
        if build_artifacts is not None:
            cleanup_pending = (
                build_artifacts.close_state["cleanup_pending"] or cleanup_pending
            )  # type: ignore[attr-defined]
        return {
            "mutation_performed": True,
            "generation": stored.generation,
            "created_count": len(create_ids),
            "kept_count": len(keep_ids),
            "updated_count": plan["update_count"],
            "removed_count": len(remove_ids),
            "cleanup_pending": cleanup_pending,
            "pool_root": "not_returned",
            "raw_output": "not_returned",
        }


def fleet_series_disable(*, prefix: str, expected_generation: int) -> dict[str, Any]:
    service = current_fleet_service()
    with fleet_mutation_lock(FleetPaths.from_state_root(STATE_ROOT)):
        try:
            current = service.load()
            planned = plan_series_disable(
                current,
                prefix,
                expected_generation=expected_generation,
            )
            build_inventory(planned, AGENT_POOL_ROOT)
            planned_series = next(
                item for item in planned.series if item.prefix == prefix
            )
            _fleet_validate_materialized_series_homes(planned, planned_series)
        except FleetValidationError as exc:
            raise AgentError(str(exc)) from None
        except AgentError:
            raise
        except Exception:
            raise AgentError("fleet_registry_commit_failed") from None
        stored = _fleet_commit_registry_only(
            service,
            current,
            planned,
            expected_generation=expected_generation,
        )
        return {
            "mutation_performed": True,
            "generation": stored.generation,
            "disabled": True,
            "pool_root": "not_returned",
            "raw_output": "not_returned",
        }


def fleet_series_delete(
    *,
    prefix: str,
    expected_generation: int,
    confirmed_remove_ids: list[str],
    yes: bool = False,
) -> dict[str, Any]:
    service = current_fleet_service()
    with fleet_mutation_lock(FleetPaths.from_state_root(STATE_ROOT)):
        try:
            current = service.load()
            planned = plan_series_delete(
                current,
                prefix,
                expected_generation=expected_generation,
            )
        except FleetValidationError as exc:
            raise AgentError(str(exc)) from None
        existing = next(item for item in current.series if item.prefix == prefix)
        if not yes:
            raise AgentError("fleet_series_delete_confirmation_required")
        expected_ids = [
            f"{prefix}{ordinal}" for ordinal in range(1, existing.count + 1)
        ]
        if (
            not isinstance(confirmed_remove_ids, list)
            or len(confirmed_remove_ids) != len(expected_ids)
            or frozenset(confirmed_remove_ids) != frozenset(expected_ids)
        ):
            raise AgentError("remove_confirmation_required")
        build_inventory(planned, AGENT_POOL_ROOT)
        present_ids = _fleet_plan_materialized_ids(prefix, existing.count)
        if not present_ids:
            old_inventory = build_inventory(current, AGENT_POOL_ROOT)
            planned_tombstones: dict[str, tuple[str, int]] = {}
            prepared_entries: list[RecoveryEntry] = []
            for agent_id in expected_ids:
                entry_index = len(prepared_entries)
                hidden_name = f"{FLEET_TOMBSTONE_PREFIX}reservation-{uuid.uuid4().hex}"
                planned_tombstones[agent_id] = (hidden_name, entry_index)
                prepared_entries.append(
                    RecoveryEntry(
                        kind=MutationKind.RESERVATION,
                        agent_id=agent_id,
                        hidden_name=hidden_name,
                        old_descriptor_fingerprint=descriptor_fingerprint(
                            old_inventory.agents[agent_id]
                        ),
                        new_descriptor_fingerprint=None,
                        old_materialization_fingerprint=None,
                        new_materialization_fingerprint=None,
                        source_identity=None,
                        target_identity=None,
                        manifest=(),
                        phase=EntryPhase.INTENT,
                        result_code=None,
                    )
                )
            active_tx = _FleetRecoveryTransaction.begin(
                RecoveryOperation.SERIES_APPLY,
                current,
                planned,
                tuple(prepared_entries),
            )
            active_tx.advance(RecoveryPhase.MATERIALIZING)
            reservations = _fleet_reserve_absent_homes(
                expected_ids,
                transaction=active_tx,
                planned_reservations=planned_tombstones,
            )
            active_tx.advance(RecoveryPhase.CAS_PENDING)
            stored: FleetSnapshot | None = None
            try:
                try:
                    stored = service.commit_snapshot(
                        planned, expected_generation=expected_generation
                    )
                except Exception as exc:
                    state, reloaded = _fleet_reconcile_commit_exception(
                        service, current, planned
                    )
                    if state == "planned":
                        stored = reloaded
                        _fleet_publish_recovery_commit(service, reloaded, active_tx)
                        raise AgentError(
                            "fleet_registry_commit_failed_after_cas"
                        ) from None
                    if state == "third":
                        active_tx.advance(
                            RecoveryPhase.RECONCILING,
                            authoritative_generation=reloaded.generation,
                        )
                        descriptor_states = _fleet_descriptor_reconciliation_states(
                            current,
                            planned,
                            reloaded,
                            set(expected_ids),
                        )
                        if any(
                            descriptor_state == "unknown"
                            for descriptor_state in descriptor_states.values()
                        ):
                            raise AgentError("fleet_registry_commit_diverged") from None
                        _fleet_publish_recovery_commit(service, reloaded, active_tx)
                        raise AgentError("fleet_registry_commit_diverged") from None
                    if isinstance(exc, FleetConflictError):
                        raise AgentError("generation_conflict") from None
                    raise AgentError("fleet_registry_commit_failed") from None
                _fleet_publish_recovery_commit(service, stored, active_tx)
            finally:
                if active_tx.journal.phase is RecoveryPhase.PUBLISHED:
                    if not _fleet_release_reservations(reservations):
                        raise AgentError("fleet_registry_delete_raced") from None
                    active_tx.advance(RecoveryPhase.COMPLETE)
                    _fleet_remove_complete_recovery_journal(active_tx.journal)
            return {
                "mutation_performed": True,
                "generation": stored.generation,
                "removed_count": 0,
                "cleanup_pending": True,
                "pool_root": "not_returned",
                "raw_output": "not_returned",
            }
        old_inventory = build_inventory(current, AGENT_POOL_ROOT)
        planned_tombstones = {
            agent_id: (
                f"{FLEET_TOMBSTONE_PREFIX}tombstone-{uuid.uuid4().hex}",
                index,
            )
            for index, agent_id in enumerate(expected_ids)
        }
        prepared_entries = tuple(
            RecoveryEntry(
                kind=MutationKind.TOMBSTONE,
                agent_id=agent_id,
                hidden_name=hidden_name,
                old_descriptor_fingerprint=descriptor_fingerprint(
                    old_inventory.agents[agent_id]
                ),
                new_descriptor_fingerprint=None,
                old_materialization_fingerprint=None,
                new_materialization_fingerprint=None,
                source_identity=None,
                target_identity=None,
                manifest=(),
                phase=EntryPhase.INTENT,
                result_code=None,
            )
            for agent_id, (hidden_name, _) in planned_tombstones.items()
        )
        active_tx = _FleetRecoveryTransaction.begin(
            RecoveryOperation.SERIES_APPLY,
            current,
            planned,
            prepared_entries,
        )
        active_tx.advance(RecoveryPhase.MATERIALIZING)
        stored, cleanup_pending = _fleet_commit_staged_removal(
            service,
            current,
            planned,
            expected_generation=expected_generation,
            inventory=old_inventory,
            agent_ids_to_remove=expected_ids,
            planned_tombstones=planned_tombstones,
            transaction=active_tx,
        )
        _fleet_remove_complete_recovery_journal(active_tx.journal)
        return {
            "mutation_performed": True,
            "generation": stored.generation,
            "removed_count": len(expected_ids),
            "cleanup_pending": cleanup_pending,
            "pool_root": "not_returned",
            "raw_output": "not_returned",
        }


def pool_expand_text(value: str) -> str:
    def replace_default(match: re.Match[str]) -> str:
        env_name = match.group(1)
        default = match.group(2)
        return os.environ.get(env_name, default)

    text = re.sub(r"\$\{([A-Za-z_][A-Za-z0-9_]*):-([^}]*)\}", replace_default, value)
    return os.path.expandvars(text)


def pool_validate_codex_bin(value: str) -> str:
    if not value:
        raise AgentError("codex_bin must resolve to a non-empty string")
    if any(ord(char) < 32 or ord(char) == 127 for char in value):
        raise AgentError("codex_bin contains unsupported characters")
    if "/" in value:
        path = Path(value).expanduser()
        if not path.is_absolute():
            path = Path.cwd() / path
        value = str(path.absolute())
    if len(value) > MAX_PATH_TEXT:
        raise AgentError(f"codex_bin exceeds {MAX_PATH_TEXT} characters")
    return value


def pool_codex_bin_state(value: str) -> str:
    if "/" in value:
        path = Path(value).expanduser()
        if not path.is_absolute():
            path = Path.cwd() / path
        try:
            mode = path.stat().st_mode
        except OSError as exc:
            raise AgentError(
                "codex_bin path must resolve to an executable file"
            ) from exc
        if not stat_module.S_ISREG(mode) or not os.access(path, os.X_OK):
            raise AgentError("codex_bin path must resolve to an executable file")
        return "executable_path"
    if shutil.which(value) is None:
        raise AgentError("codex_bin command must resolve to an executable on PATH")
    return "executable_command"


def pool_normalized_path(value: str) -> Path:
    path = Path(pool_expand_text(value)).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    return path


def pool_public_path_state(path: Path) -> str:
    try:
        mode = path.lstat().st_mode
    except FileNotFoundError:
        return "missing"
    except OSError:
        return "unreadable"
    if stat_module.S_ISLNK(mode):
        return "symlink"
    if stat_module.S_ISDIR(mode):
        return "directory"
    if stat_module.S_ISREG(mode):
        return "file"
    return "other"


def pool_shared_asset_source(path: Path, root: Path) -> bool:
    return pool_shared_asset_identity(path, root) is not None


def pool_shared_asset_identity(
    path: Path, root: Path
) -> tuple[Path, os.stat_result] | None:
    try:
        resolved = path.resolve(strict=True)
        resolved.relative_to(root.resolve(strict=False))
        source_stat = resolved.lstat()
    except (OSError, RuntimeError, ValueError):
        return None
    if (
        stat_module.S_ISREG(source_stat.st_mode)
        and getattr(source_stat, "st_nlink", 1) == 1
    ) or stat_module.S_ISDIR(source_stat.st_mode):
        return resolved, source_stat
    return None


def pool_regular_marker_present(path: Path) -> bool:
    try:
        current = path.lstat()
    except OSError:
        return False
    return stat_module.S_ISREG(current.st_mode) and getattr(current, "st_nlink", 1) == 1


def open_pool_entry_parent(path: Path, expected_stat: os.stat_result) -> int:
    parent = path.parent
    parent_parts = parent.parts
    if (
        len(parent_parts) == 5
        and parent_parts[:4] == ("/", "proc", "self", "fd")
        and parent_parts[4].isdigit()
    ):
        parent_fd = -1
        try:
            parent_fd = os.dup(int(parent_parts[4]))
            opened_parent = os.fstat(parent_fd)
        except OSError as exc:
            if parent_fd >= 0:
                os.close(parent_fd)
            raise AgentError("pool entry changed during removal") from exc
        if not stat_module.S_ISDIR(opened_parent.st_mode):
            os.close(parent_fd)
            raise AgentError("pool entry changed during removal")
        return parent_fd
    return open_directory_no_follow_matching(
        parent,
        expected_stat,
        error_text="pool entry changed during removal",
        changed_text="pool entry changed during removal",
    )


def remove_agent_pool_entry(path: Path) -> str:
    try:
        current = path.lstat()
    except FileNotFoundError:
        return "missing"
    except OSError:
        return "skipped"
    mode = current.st_mode
    if stat_module.S_ISLNK(mode) or stat_module.S_ISREG(mode):
        parent_fd = -1
        try:
            try:
                parent_stat = path.parent.lstat()
                parent_fd = open_pool_entry_parent(path, parent_stat)
                latest = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return "missing"
            except (AgentError, OSError):
                return "skipped"
            if not source_identity_matches(latest, current):
                return "skipped"
            try:
                os.unlink(path.name, dir_fd=parent_fd)
            except FileNotFoundError:
                return "missing"
            except OSError:
                return "skipped"
            return "removed"
        finally:
            if parent_fd >= 0:
                os.close(parent_fd)
    if stat_module.S_ISDIR(mode):
        if not getattr(shutil.rmtree, "avoids_symlink_attacks", False):
            raise AgentError("safe pool removal is unavailable")
        try:
            latest = path.lstat()
        except FileNotFoundError:
            return "missing"
        except OSError:
            return "skipped"
        if not source_identity_matches(latest, current):
            return "skipped"
        try:
            remove_real_plugin_cache_dir(path)
        except AgentError as exc:
            if str(exc) in {
                "plugin cache entry changed during removal",
                "plugin cache entry is not a real directory",
            }:
                return "skipped"
            raise AgentError("safe pool removal is unavailable") from exc
        return "removed"
    return "skipped"


def pool_safe_relative_path(value: Any, *, field: str) -> Path:
    if not isinstance(value, str) or not value:
        raise AgentError(f"{field} must be a non-empty relative path")
    if len(value) > 200 or not POOL_SAFE_RELATIVE_RE.fullmatch(value):
        raise AgentError(f"{field} contains unsupported characters")
    path = Path(value)
    if (
        path.is_absolute()
        or not path.parts
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise AgentError(f"{field} must stay inside the Agentin home")
    if path.parts[0] in {"auth.json", "codex", "config.toml"}:
        raise AgentError(f"{field} must not target protected Agentin files")
    return path


def pool_load_raw_spec(spec_path: str | None = None) -> tuple[dict[str, Any], str]:
    if spec_path is None:
        default_path = repo_root() / POOL_SPEC_FILE
        if not path_present_no_follow(default_path):
            return default_agent_pool_spec(), "built_in_default"
        spec_path = str(default_path)

    path = Path(spec_path).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    try:
        if not path_present_no_follow(path):
            raise AgentError("pool spec not found")
        text = read_private_regular_text(
            path,
            MAX_POOL_SPEC_BYTES,
            "pool spec must be a readable regular file within the size limit",
        )
        payload = json.loads(text)
    except AgentError:
        raise
    except json.JSONDecodeError as exc:
        raise AgentError("pool spec is not valid JSON") from exc
    except OSError as exc:
        raise AgentError("pool spec is unreadable") from exc
    if not isinstance(payload, dict):
        raise AgentError("pool spec must be a JSON object")
    return payload, "file"


def pool_normalize_spec(
    spec_path: str | None = None,
    *,
    target_dir: str | None = None,
    codex_bin: str | None = None,
) -> dict[str, Any]:
    raw, source = pool_load_raw_spec(spec_path)
    schema_version = raw.get("schema_version", POOL_SCHEMA_VERSION)
    if schema_version != POOL_SCHEMA_VERSION:
        raise AgentError("unsupported pool schema_version")

    raw_pool_root = (
        target_dir
        if target_dir is not None
        else raw.get("pool_root", "${HOME}/.codex-agents")
    )
    if not isinstance(raw_pool_root, str) or not raw_pool_root:
        raise AgentError("pool_root must be a non-empty string")
    pool_root = pool_normalized_path(raw_pool_root)

    raw_codex_bin = (
        codex_bin
        if codex_bin is not None
        else raw.get("codex_bin", POOL_DEFAULT_CODEX_BIN)
    )
    if not isinstance(raw_codex_bin, str) or not raw_codex_bin:
        raise AgentError("codex_bin must be a non-empty string")
    codex_bin_value = pool_validate_codex_bin(pool_expand_text(raw_codex_bin))
    codex_bin_state = pool_codex_bin_state(codex_bin_value)

    raw_series = raw.get("series")
    if not isinstance(raw_series, list) or not raw_series:
        raise AgentError("series must be a non-empty array")
    if len(raw_series) > MAX_POOL_SERIES:
        raise AgentError(f"series must not contain more than {MAX_POOL_SERIES} entries")

    ids: list[str] = []
    series_ids: dict[str, list[str]] = {}
    templates: dict[str, str] = {}
    authenticated: set[str] = set()
    series_accounts: dict[str, str | None] = {}
    agent_accounts: dict[str, str | None] = {}
    prefixes: set[str] = set()
    for index, item in enumerate(raw_series):
        if not isinstance(item, dict):
            raise AgentError(f"series[{index}] must be an object")
        prefix = item.get("prefix")
        if not isinstance(prefix, str) or not POOL_PREFIX_RE.fullmatch(prefix):
            raise AgentError(f"series[{index}].prefix is invalid")
        if prefix in prefixes:
            raise AgentError("series prefix is duplicated")
        prefixes.add(prefix)
        count = normalize_int_field(
            item.get("count"),
            field=f"series[{index}].count",
            minimum=1,
            maximum=MAX_POOL_AGENTS,
        )
        current_ids = [f"{prefix}{number}" for number in range(1, count + 1)]
        template = item.get("template", current_ids[0])
        if not isinstance(template, str) or template not in current_ids:
            raise AgentError(f"series[{index}].template must be one of its Agentin ids")
        auth_items = item.get("authenticated", [])
        if not isinstance(auth_items, list) or any(
            not isinstance(agent, str) for agent in auth_items
        ):
            raise AgentError(
                f"series[{index}].authenticated must be an array of Agentin ids"
            )
        unknown_auth = sorted(set(auth_items) - set(current_ids))
        if unknown_auth:
            raise AgentError(
                f"series[{index}].authenticated contains unknown Agentin ids"
            )
        for agent in current_ids:
            templates[agent] = template
        account = item.get("codex_usage_account")
        if account is not None:
            if not isinstance(account, str) or not CODEX_USAGE_ACCOUNT_RE.fullmatch(
                account
            ):
                raise AgentError(f"series[{index}].codex_usage_account is invalid")
        series_accounts[f"{prefix}-series"] = account
        for agent in current_ids:
            agent_accounts[agent] = account
        authenticated.update(auth_items)
        series_ids[f"{prefix}-series"] = current_ids
        ids.extend(current_ids)

    if len(ids) > MAX_POOL_AGENTS:
        raise AgentError(
            f"pool must not contain more than {MAX_POOL_AGENTS} Agentinnen"
        )
    if len(set(ids)) != len(ids):
        raise AgentError("pool contains duplicate Agentin ids")

    raw_aliases = raw.get("aliases", {})
    if not isinstance(raw_aliases, dict):
        raise AgentError("aliases must be an object")
    aliases: dict[str, str | list[str]] = {}
    valid_targets = set(ids) | set(series_ids)
    reserved_aliases = valid_targets | {"all"}
    for alias, target in raw_aliases.items():
        if not isinstance(alias, str) or not alias or len(alias) > 64:
            raise AgentError("alias names must be short strings")
        normalized_alias = alias.strip().lower()
        if not normalized_alias:
            raise AgentError("alias names must be short strings")
        if normalized_alias in reserved_aliases or normalized_alias in aliases:
            raise AgentError("alias conflicts with a pool selector")
        if isinstance(target, str):
            normalized_target = target.strip().lower()
            if normalized_target not in valid_targets:
                raise AgentError("alias points to an unknown target")
            aliases[normalized_alias] = normalized_target
        elif (
            isinstance(target, list)
            and target
            and all(isinstance(agent, str) for agent in target)
        ):
            normalized_targets = [agent.strip().lower() for agent in target]
            if any(agent not in valid_targets for agent in normalized_targets):
                raise AgentError("alias points to an unknown target")
            aliases[normalized_alias] = normalized_targets
        else:
            raise AgentError(
                "alias must point to an Agentin id, series selector, or non-empty list"
            )

    shared_assets = raw.get("shared_assets", [])
    if (
        not isinstance(shared_assets, list)
        or len(shared_assets) > MAX_POOL_SHARED_ASSETS
    ):
        raise AgentError(
            f"shared_assets must be an array with at most {MAX_POOL_SHARED_ASSETS} entries"
        )
    shared_asset_paths = [
        pool_safe_relative_path(item, field="shared_assets[]") for item in shared_assets
    ]

    runtime_dirs = raw.get("runtime_dirs", [])
    if not isinstance(runtime_dirs, list) or len(runtime_dirs) > MAX_POOL_RUNTIME_DIRS:
        raise AgentError(
            f"runtime_dirs must be an array with at most {MAX_POOL_RUNTIME_DIRS} entries"
        )
    runtime_dir_paths = [
        pool_safe_relative_path(item, field="runtime_dirs[]") for item in runtime_dirs
    ]

    raw_auth = raw.get("auth", {})
    if not isinstance(raw_auth, dict):
        raise AgentError("auth must be an object")
    auth_policy = raw_auth.get("policy", "preserve_existing_only")
    if auth_policy not in POOL_AUTH_POLICIES:
        raise AgentError(f"auth.policy must be one of: {', '.join(POOL_AUTH_POLICIES)}")

    return {
        "raw": raw,
        "source": source,
        "schema_version": schema_version,
        "pool_root": pool_root,
        "codex_bin": codex_bin_value,
        "codex_bin_state": codex_bin_state,
        "ids": ids,
        "series_ids": series_ids,
        "templates": templates,
        "authenticated": sorted(authenticated),
        "series_accounts": series_accounts,
        "agent_accounts": agent_accounts,
        "codex_usage_profiles_root": CODEX_USAGE_PROFILES_ROOT,
        "aliases": aliases,
        "shared_assets": shared_asset_paths,
        "runtime_dirs": runtime_dir_paths,
        "auth_policy": auth_policy,
    }


def pool_selector_ids(normalized: dict[str, Any], selector: str) -> list[str]:
    if not isinstance(selector, str):
        raise AgentError("unknown pool selector")
    selector = selector.strip().lower()
    if selector == "all":
        return list(normalized["ids"])
    series_ids = normalized["series_ids"]
    if selector in series_ids:
        return list(series_ids[selector])
    aliases = normalized["aliases"]
    if selector in aliases:
        target = aliases[selector]
        if isinstance(target, str):
            return pool_selector_ids(normalized, target)
        selected: list[str] = []
        for item in target:
            selected.extend(pool_selector_ids(normalized, item))
        return list(dict.fromkeys(selected))
    if selector in normalized["ids"]:
        return [selector]
    raise AgentError("unknown pool selector")


def pool_guard_root(pool_root: Path) -> None:
    resolved = pool_root.resolve(strict=False)
    forbidden = {
        Path("/").resolve(),
        Path.home().resolve(strict=False),
        repo_root().resolve(strict=False),
    }
    if resolved in forbidden or len(resolved.parts) < 3:
        raise AgentError("refusing unsafe pool root")


def pool_require_real_root(root: Path) -> None:
    if not is_real_directory_no_symlink(root):
        raise AgentError("pool root must be a real directory")


def pool_shell_double_content(value: str) -> str:
    return (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("$", "\\$")
        .replace("`", "\\`")
    )


def pool_wrapper_text(agent: str, home: Path, codex_bin: str) -> str:
    home_text = pool_shell_double_content(str(home))
    codex_bin_word = shlex.quote(codex_bin)
    return "\n".join(
        [
            "#!/usr/bin/env bash",
            "set -euo pipefail",
            "",
            f'export CODEX_HOME="{home_text}"',
            'if [[ -z "${CODEX_AGENT_BIN:-}" ]]; then',
            f"  CODEX_AGENT_BIN={codex_bin_word}",
            "fi",
            "export CODEX_AGENT_BIN",
            "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
            "if taskset --cpu-list 4-10 /usr/bin/true >/dev/null 2>&1; then",
            '  exec taskset --cpu-list 4-10 /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
            "fi",
            'exec /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
            "",
        ]
    )


def pool_minimal_config(home: Path) -> str:
    project_key = json.dumps(str(home))
    return "\n".join(
        [
            f'model = "{DEFAULT_AGENT_MODEL}"',
            f'model_reasoning_effort = "{DEFAULT_AGENT_MODEL_EFFORT}"',
            'approval_policy = "never"',
            'sandbox_mode = "danger-full-access"',
            "",
            "[tui]",
            "animations = false",
            "",
            f"[projects.{project_key}]",
            'trust_level = "trusted"',
            "",
        ]
    )


def pool_write_private_file(path: Path, text: str, mode: int) -> None:
    replace_private_text(path, text, mode=mode)


def pool_write_private_bytes(path: Path, data: bytes, mode: int) -> None:
    replace_private_bytes(path, data, mode=mode)


def write_private_bytes_if_absent_at_dir_fd(
    directory_fd: int,
    name: str,
    data: bytes,
    mode: int = 0o600,
    *,
    error_text: str,
) -> bool:
    tmp_name = f".{name}.{now_id()}.{uuid.uuid4().hex}.tmp"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    tmp_created = False
    linked = False
    try:
        try:
            fd = os.open(tmp_name, flags, mode, dir_fd=directory_fd)
        except OSError as exc:
            raise AgentError(error_text) from exc
        tmp_created = True
        current = os.fstat(fd)
        if (
            not stat_module.S_ISREG(current.st_mode)
            or getattr(current, "st_nlink", 1) != 1
        ):
            raise AgentError(error_text)
        try:
            os.fchmod(fd, mode)
        except PermissionError:
            pass
        with os.fdopen(fd, "wb") as fh:
            fd = -1
            fh.write(data)
        try:
            os.link(
                tmp_name,
                name,
                src_dir_fd=directory_fd,
                dst_dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileExistsError:
            return False
        except OSError as exc:
            raise AgentError(error_text) from exc
        linked = True
        return True
    finally:
        if fd >= 0:
            os.close(fd)
        if tmp_created:
            try:
                os.unlink(tmp_name, dir_fd=directory_fd)
            except FileNotFoundError:
                pass
            except OSError as exc:
                if linked:
                    raise AgentError(error_text) from exc


def pool_write_private_bytes_if_absent(
    path: Path, data: bytes, mode: int = 0o600
) -> bool:
    try:
        parent_stat = path.parent.lstat()
    except OSError as exc:
        raise AgentError("pool auth target changed during copy") from exc
    parent_fd = open_directory_no_follow_matching(
        path.parent,
        parent_stat,
        error_text="pool auth target changed during copy",
        changed_text="pool auth target changed during copy",
    )
    try:
        return write_private_bytes_if_absent_at_dir_fd(
            parent_fd,
            path.name,
            data,
            mode=mode,
            error_text="pool auth target changed during copy",
        )
    finally:
        os.close(parent_fd)


def pool_read_private_bytes(
    path: Path,
    max_bytes: int,
    error_text: str,
    *,
    expected_parent_stat: os.stat_result | None = None,
    expected_target_stat: os.stat_result | None = None,
    expected_mode: int | None = None,
    expected_uid: int | None = None,
) -> bytes:
    parent_fd = -1
    try:
        parent_stat = (
            expected_parent_stat
            if expected_parent_stat is not None
            else path.parent.lstat()
        )
        parent_fd = open_directory_no_follow_matching(
            path.parent,
            parent_stat,
            error_text=error_text,
            changed_text=error_text,
        )
        current = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
    except (AgentError, OSError) as exc:
        if parent_fd >= 0:
            os.close(parent_fd)
        raise AgentError(error_text) from exc
    if (
        stat_module.S_ISLNK(current.st_mode)
        or not stat_module.S_ISREG(current.st_mode)
        or getattr(current, "st_nlink", 1) != 1
        or current.st_size > max_bytes
    ):
        os.close(parent_fd)
        parent_fd = -1
        raise AgentError(error_text)
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(path.name, flags, dir_fd=parent_fd)
        opened = os.fstat(fd)
        if (
            not source_identity_matches(opened, current)
            or (
                expected_target_stat is not None
                and not source_identity_with_snapshot_matches(
                    opened, expected_target_stat
                )
            )
            or stat_module.S_ISLNK(opened.st_mode)
            or not stat_module.S_ISREG(opened.st_mode)
            or getattr(opened, "st_nlink", 1) != 1
            or opened.st_size > max_bytes
            or (
                expected_mode is not None
                and stat_module.S_IMODE(opened.st_mode) != expected_mode
            )
            or (expected_uid is not None and opened.st_uid != expected_uid)
        ):
            raise AgentError(error_text)
        with os.fdopen(fd, "rb") as fh:
            fd = -1
            data = fh.read(max_bytes + 1)
    except AgentError:
        raise
    except OSError as exc:
        raise AgentError(error_text) from exc
    finally:
        if fd >= 0:
            os.close(fd)
        if parent_fd >= 0:
            os.close(parent_fd)
    if len(data) > max_bytes:
        raise AgentError(error_text)
    return data


def fleet_read_optional_private_bytes(
    path: Path, max_bytes: int, error_text: str
) -> bytes | None:
    stats = _fleet_optional_stats(path, error_text)
    if stats is None:
        return None
    parent_stat, target_stat = stats
    return pool_read_private_bytes(
        path,
        max_bytes,
        error_text,
        expected_parent_stat=parent_stat,
        expected_target_stat=target_stat,
    )


def pool_private_text_matches(path: Path, expected: str, max_bytes: int) -> bool:
    try:
        return (
            read_private_regular_text(
                path, max_bytes, "pool private file could not be read"
            )
            == expected
        )
    except AgentError:
        return False


def _pool_root_digest_text(path: Path) -> str:
    try:
        return str(path.resolve(strict=False))
    except (OSError, RuntimeError):
        return str(path.absolute())


def pool_marker_payload(normalized: dict[str, Any]) -> dict[str, Any]:
    digest = hashlib.sha256(
        json.dumps(normalized["raw"], sort_keys=True).encode("utf-8")
    ).hexdigest()
    pool_root_digest = hashlib.sha256(
        _pool_root_digest_text(normalized["pool_root"]).encode("utf-8")
    ).hexdigest()
    return {
        "schema_version": normalized["schema_version"],
        "installed_at": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "agent_count": len(normalized["ids"]),
        "series_count": len(normalized["series_ids"]),
        "spec_sha256": digest,
        "pool_root_sha256": pool_root_digest,
        "codex_bin_state": normalized["codex_bin_state"],
        "pool_root": PATH_NOT_RETURNED,
    }


def pool_marker_matches(
    path: Path, expected_stat: os.stat_result, normalized: dict[str, Any]
) -> bool:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = -1
    try:
        fd = os.open(path, flags)
        opened = os.fstat(fd)
        if (
            not source_identity_matches(opened, expected_stat)
            or not stat_module.S_ISREG(opened.st_mode)
            or getattr(opened, "st_nlink", 1) != 1
        ):
            return False
        with os.fdopen(fd, "rb") as fh:
            fd = -1
            raw = fh.read(MAX_POOL_SPEC_BYTES + 1)
    except OSError:
        return False
    finally:
        if fd >= 0:
            os.close(fd)
    if len(raw) > MAX_POOL_SPEC_BYTES:
        return False
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return False
    expected = pool_marker_payload(normalized)
    return (
        isinstance(payload, dict)
        and payload.get("schema_version") == expected["schema_version"]
        and payload.get("agent_count") == expected["agent_count"]
        and payload.get("series_count") == expected["series_count"]
        and payload.get("spec_sha256") == expected["spec_sha256"]
        and payload.get("pool_root_sha256") == expected["pool_root_sha256"]
        and payload.get("codex_bin_state") == expected["codex_bin_state"]
    )


def agent_pool_validate(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    return {
        "ok": True,
        "schema_version": normalized["schema_version"],
        "spec_source": normalized["source"],
        "pool_root": PATH_NOT_RETURNED,
        "pool_root_state": pool_public_path_state(normalized["pool_root"]),
        "codex_bin_state": normalized["codex_bin_state"],
        "expected_agent_count": len(normalized["ids"]),
        "series_count": len(normalized["series_ids"]),
        "series": "not_returned",
        "series_state": "set" if normalized["series_ids"] else "not_set",
        "alias_count": len(normalized["aliases"]),
        "aliases": "not_returned",
        "aliases_state": "set" if normalized["aliases"] else "not_set",
        "authenticated_agent_count": len(normalized["authenticated"]),
        "authenticated_agents": "not_returned",
        "authenticated_agents_state": "set"
        if normalized["authenticated"]
        else "not_set",
        "shared_asset_count": len(normalized["shared_assets"]),
        "runtime_dir_count": len(normalized["runtime_dirs"]),
        "auth_policy": normalized["auth_policy"],
        "raw_output": "not_returned",
    }


def agent_pool_status(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    root = normalized["pool_root"]
    try:
        expected_parent_stat = root.parent.lstat()
    except OSError:
        expected_parent_stat = None
    try:
        expected_root_stat = root.lstat()
    except OSError:
        expected_root_stat = None
    root_state = pool_public_path_state(root)
    if root_state != "directory":
        return {
            "ok": False,
            "pool_root": PATH_NOT_RETURNED,
            "pool_root_state": root_state,
            "marker_state": "missing" if root_state == "missing" else "not_checked",
            "marker_present": False,
            "marker_valid": False,
            "expected_agent_count": len(normalized["ids"]),
            "existing_agent_count": 0,
            "missing_agent_count": len(normalized["ids"]),
            "wrapper_executable_count": 0,
            "config_count": 0,
            "auth_count": 0,
            "shared_asset_symlink_count": 0,
            "shared_asset_expected_link_count": 0,
            "shared_asset_valid_link_count": 0,
            "shared_asset_missing_link_count": 0,
            "shared_asset_invalid_link_count": 0,
            "shared_asset_template_source_count": 0,
            "shared_asset_template_source_missing_count": 0,
            "series_count": len(normalized["series_ids"]),
            "series": "not_returned",
            "series_state": "set" if normalized["series_ids"] else "not_set",
            "raw_output": "not_returned",
        }
    with pool_root_operation(
        root,
        ensure=False,
        error_text="pool root changed during status",
        expected_parent_stat=expected_parent_stat,
        expected_root_stat=expected_root_stat,
    ) as operation_root:
        return _agent_pool_status_at_root(normalized, operation_root, root_state)


def _agent_pool_status_at_root(
    normalized: dict[str, Any], root: Path, root_state: str
) -> dict[str, Any]:
    ids = normalized["ids"]
    existing = 0
    wrappers = 0
    configs = 0
    auth = 0
    shared_symlinks = 0
    for agent in ids:
        home = root / agent
        if not is_real_directory_no_symlink(home):
            continue
        existing += 1
        if is_regular_executable_no_symlink(home / "codex"):
            wrappers += 1
        if is_regular_file_no_symlink(home / "config.toml"):
            configs += 1
        if is_regular_file_no_symlink(home / "auth.json"):
            auth += 1
        for asset in normalized["shared_assets"]:
            if (home / asset).is_symlink():
                shared_symlinks += 1

    missing = len(ids) - existing
    marker = root / POOL_MARKER_FILE
    marker_present = pool_regular_marker_present(marker)
    marker_valid = False
    if marker_present:
        try:
            marker_stat = marker.lstat()
        except OSError:
            marker_stat = None
        marker_valid = marker_stat is not None and pool_marker_matches(
            marker, marker_stat, normalized
        )
    shared_expected = 0
    shared_valid = 0
    shared_invalid = 0
    shared_missing = 0
    template_sources = 0
    template_sources_missing = 0
    templates_with_consumers = {
        normalized["templates"][agent]
        for agent in ids
        if normalized["templates"][agent] != agent
    }
    for agent in ids:
        template = normalized["templates"][agent]
        home = root / agent
        home_is_real = is_real_directory_no_symlink(home)
        for asset in normalized["shared_assets"]:
            target = home / asset
            if template == agent:
                if not home_is_real:
                    if agent in templates_with_consumers:
                        template_sources_missing += 1
                    continue
                if pool_shared_asset_source(target, root):
                    template_sources += 1
                elif agent in templates_with_consumers:
                    template_sources_missing += 1
                continue
            shared_expected += 1
            if not home_is_real:
                shared_missing += 1
                continue
            try:
                mode = target.lstat().st_mode
            except FileNotFoundError:
                shared_missing += 1
                continue
            except OSError:
                shared_invalid += 1
                continue
            if not stat_module.S_ISLNK(mode):
                shared_invalid += 1
                continue
            try:
                link_target = os.readlink(target)
            except OSError:
                shared_invalid += 1
                continue
            expected_source = root / template / asset
            if os.path.isabs(link_target) or not pool_shared_asset_source(
                expected_source, root
            ):
                shared_invalid += 1
                continue
            actual_path = os.path.normpath(os.path.abspath(target.parent / link_target))
            expected_path = os.path.normpath(os.path.abspath(expected_source))
            actual_resolved = (target.parent / link_target).resolve(strict=False)
            expected_resolved = expected_source.resolve(strict=False)
            if actual_path == expected_path or actual_resolved == expected_resolved:
                shared_valid += 1
            else:
                shared_invalid += 1
    return {
        "ok": (
            missing == 0
            and wrappers == len(ids)
            and configs == len(ids)
            and marker_valid
            and shared_missing == 0
            and shared_invalid == 0
            and template_sources_missing == 0
        ),
        "pool_root": PATH_NOT_RETURNED,
        "pool_root_state": root_state,
        "marker_state": pool_public_path_state(marker),
        "marker_present": marker_present,
        "marker_valid": marker_valid,
        "expected_agent_count": len(ids),
        "existing_agent_count": existing,
        "missing_agent_count": missing,
        "wrapper_executable_count": wrappers,
        "config_count": configs,
        "auth_count": auth,
        "shared_asset_symlink_count": shared_symlinks,
        "shared_asset_expected_link_count": shared_expected,
        "shared_asset_valid_link_count": shared_valid,
        "shared_asset_missing_link_count": shared_missing,
        "shared_asset_invalid_link_count": shared_invalid,
        "shared_asset_template_source_count": template_sources,
        "shared_asset_template_source_missing_count": template_sources_missing,
        "series_count": len(normalized["series_ids"]),
        "series": "not_returned",
        "series_state": "set" if normalized["series_ids"] else "not_set",
        "raw_output": "not_returned",
    }


@contextlib.contextmanager
def pool_root_operation(
    root: Path,
    *,
    ensure: bool,
    error_text: str,
    expected_parent_stat: os.stat_result | None = None,
    expected_root_stat: os.stat_result | None = None,
    require_private: bool = False,
) -> Any:
    if expected_parent_stat is None:
        try:
            parent_stat = root.parent.lstat()
        except FileNotFoundError:
            parent_stat = None
        except OSError as exc:
            raise AgentError(error_text) from exc
    else:
        parent_stat = expected_parent_stat
    if expected_root_stat is None:
        try:
            root_stat = root.lstat()
        except FileNotFoundError:
            root_stat = None
        except OSError as exc:
            raise AgentError(error_text) from exc
    else:
        root_stat = expected_root_stat

    if require_private and root_stat is not None:
        _fleet_private_directory_stat(root_stat, error_text)
    if ensure:
        ensure_private_dir(root)
    elif parent_stat is None or root_stat is None:
        raise AgentError(error_text)
    if parent_stat is None:
        try:
            parent_stat = root.parent.lstat()
        except OSError as exc:
            raise AgentError(error_text) from exc
    if root_stat is None:
        try:
            root_stat = root.lstat()
        except OSError as exc:
            raise AgentError(error_text) from exc
    if require_private:
        _fleet_private_directory_stat(root_stat, error_text)

    parent_fd = -1
    root_fd = -1
    try:
        parent_fd = open_directory_no_follow_matching(
            root.parent,
            parent_stat,
            error_text=error_text,
            changed_text=error_text,
        )
        root_fd = open_directory_no_follow_matching(
            root.name,
            root_stat,
            error_text=error_text,
            changed_text=error_text,
            dir_fd=parent_fd,
        )
        if require_private:
            _fleet_private_directory_stat(os.fstat(root_fd), error_text)
        operation_root = Path(f"/proc/self/fd/{root_fd}")
        yield operation_root
    finally:
        if root_fd >= 0:
            os.close(root_fd)
        if parent_fd >= 0:
            os.close(parent_fd)


def pool_codex_usage_auth_source(normalized: dict[str, Any], account: str) -> Path:
    """Resolve one canonical codex-usage auth file without following untrusted links."""
    if not isinstance(account, str) or not CODEX_USAGE_ACCOUNT_RE.fullmatch(account):
        raise AgentError("codex-usage account id is invalid")
    profiles_root = normalized["codex_usage_profiles_root"]
    if not isinstance(profiles_root, Path) or not is_real_directory_no_symlink(
        profiles_root
    ):
        raise AgentError("codex-usage profiles root is missing or invalid")
    profile = profiles_root / account
    codex_home = profile / "codex-home"
    if not is_real_directory_no_symlink(profile) or not is_real_directory_no_symlink(
        codex_home
    ):
        raise AgentError("codex-usage profile codex-home is missing or invalid")
    source = codex_home / "auth.json"
    if not is_regular_file_no_symlink(source):
        raise AgentError("codex-usage profile auth is missing or invalid")
    return source


def _agent_pool_install_unlocked(
    normalized: dict[str, Any],
    *,
    copy_auth_from: str | None = None,
    copy_auth_to: str | None = None,
    yes: bool = False,
    overwrite_auth: bool = False,
) -> dict[str, Any]:
    if copy_auth_from or copy_auth_to:
        if not copy_auth_from or not copy_auth_to:
            raise AgentError(
                "copy_auth_from and copy_auth_to must be provided together"
            )
        _agent_pool_copy_auth_unlocked(
            normalized,
            from_agent=copy_auth_from,
            to=copy_auth_to,
            yes=False,
            overwrite=overwrite_auth,
        )
    pool_root = normalized["pool_root"]
    pool_guard_root(pool_root)
    with pool_root_operation(
        pool_root, ensure=True, error_text="pool root changed during install"
    ) as root:
        created = 0
        updated_wrappers = 0
        created_configs = 0
        created_runtime_dirs = 0
        linked_assets = 0
        missing_asset_sources = 0
        skipped_existing_assets = 0
        auth_copied = 0
        auth_skipped_existing = 0
        auth_skipped_unconfigured = 0

        for agent in normalized["ids"]:
            home = root / agent
            logical_home = pool_root / agent
            before = home.exists()
            ensure_private_dir(home)
            if not before:
                created += 1

            wrapper = pool_wrapper_text(agent, logical_home, normalized["codex_bin"])
            wrapper_path = home / "codex"
            if not pool_private_text_matches(
                wrapper_path, wrapper, MAX_CODEX_CONFIG_BYTES
            ):
                pool_write_private_file(wrapper_path, wrapper, 0o700)
                updated_wrappers += 1

            config_path = home / "config.toml"
            if not is_regular_file_no_symlink(config_path):
                pool_write_private_file(
                    config_path, pool_minimal_config(logical_home), 0o600
                )
                created_configs += 1

            account = normalized["agent_accounts"].get(agent)
            if account is None:
                auth_skipped_unconfigured += 1
            else:
                target_auth = home / "auth.json"
                if path_present_no_follow(target_auth):
                    auth_skipped_existing += 1
                else:
                    source = pool_codex_usage_auth_source(normalized, account)
                    if pool_write_private_bytes_if_absent(
                        target_auth,
                        pool_read_private_bytes(
                            source,
                            MAX_CODEX_CONFIG_BYTES,
                            "codex-usage profile auth is missing or invalid",
                        ),
                    ):
                        auth_copied += 1
                    else:
                        auth_skipped_existing += 1

            for runtime_dir in normalized["runtime_dirs"]:
                runtime_path = home / runtime_dir
                runtime_existed = is_real_directory_no_symlink(runtime_path)
                ensure_private_dir(runtime_path)
                if not runtime_existed:
                    created_runtime_dirs += 1

            template = normalized["templates"][agent]
            if template == agent:
                continue
            template_home = root / template
            for asset in normalized["shared_assets"]:
                source = template_home / asset
                target = home / asset
                if path_present_no_follow(target):
                    skipped_existing_assets += 1
                    continue
                if not pool_shared_asset_source(source, root):
                    missing_asset_sources += 1
                    continue
                source_identity = pool_shared_asset_identity(source, root)
                if source_identity is None:
                    raise AgentError("pool shared asset source changed during install")
                try:
                    parent_stat = target.parent.lstat()
                except FileNotFoundError:
                    parent_stat = None
                except OSError as exc:
                    raise AgentError(
                        "pool shared asset target changed during install"
                    ) from exc
                ensure_private_dir(target.parent)
                if parent_stat is None:
                    try:
                        parent_stat = target.parent.lstat()
                    except OSError as exc:
                        raise AgentError(
                            "pool shared asset target changed during install"
                        ) from exc
                parent_fd = open_directory_no_follow_matching(
                    target.parent,
                    parent_stat,
                    error_text="pool shared asset target changed during install",
                    changed_text="pool shared asset target changed during install",
                )
                relative_source = os.path.relpath(source, target.parent)
                created_target_stat: os.stat_result | None = None
                try:
                    try:
                        os.lstat(target.name, dir_fd=parent_fd)
                    except FileNotFoundError:
                        pass
                    else:
                        skipped_existing_assets += 1
                        continue
                    os.symlink(relative_source, target.name, dir_fd=parent_fd)
                    created_target_stat = os.lstat(target.name, dir_fd=parent_fd)
                    current_source = pool_shared_asset_identity(source, root)
                    if current_source is None or not source_identity_matches(
                        current_source[1], source_identity[1]
                    ):
                        try:
                            latest_target_stat = os.lstat(target.name, dir_fd=parent_fd)
                        except OSError:
                            latest_target_stat = None
                        if (
                            latest_target_stat is not None
                            and source_identity_matches(
                                latest_target_stat, created_target_stat
                            )
                            and stat_module.S_ISLNK(latest_target_stat.st_mode)
                        ):
                            with contextlib.suppress(OSError):
                                os.unlink(target.name, dir_fd=parent_fd)
                        raise AgentError(
                            "pool shared asset source changed during install"
                        )
                except OSError as exc:
                    raise AgentError(
                        "pool shared asset target changed during install"
                    ) from exc
                finally:
                    os.close(parent_fd)
                linked_assets += 1

        auth_result: dict[str, Any] | None = None
        if copy_auth_from or copy_auth_to:
            auth_result = _agent_pool_copy_auth_unlocked(
                normalized,
                from_agent=copy_auth_from,
                to=copy_auth_to,
                yes=yes,
                overwrite=overwrite_auth,
            )

        marker = root / POOL_MARKER_FILE
        marker_is_current = False
        try:
            marker_stat = marker.lstat()
        except FileNotFoundError:
            marker_stat = None
        except OSError:
            marker_stat = None
        if (
            marker_stat is not None
            and stat_module.S_ISREG(marker_stat.st_mode)
            and getattr(marker_stat, "st_nlink", 1) == 1
            and stat_module.S_IMODE(marker_stat.st_mode) == 0o600
        ):
            marker_is_current = pool_marker_matches(marker, marker_stat, normalized)
        if not marker_is_current:
            pool_write_private_file(
                marker,
                json.dumps(pool_marker_payload(normalized), indent=2, sort_keys=True)
                + "\n",
                0o600,
            )

        return {
            "ok": True,
            "pool_root": PATH_NOT_RETURNED,
            "installed_agent_count": len(normalized["ids"]),
            "created_agent_homes": created,
            "updated_wrappers": updated_wrappers,
            "created_configs": created_configs,
            "created_runtime_dirs": created_runtime_dirs,
            "linked_shared_assets": linked_assets,
            "skipped_existing_shared_assets": skipped_existing_assets,
            "missing_shared_asset_sources": missing_asset_sources,
            "auth_copied_count": auth_copied,
            "auth_skipped_existing_count": auth_skipped_existing,
            "auth_skipped_unconfigured_count": auth_skipped_unconfigured,
            "auth": auth_result,
            "raw_output": "not_returned",
        }


def agent_pool_install(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
    *,
    copy_auth_from: str | None = None,
    copy_auth_to: str | None = None,
    yes: bool = False,
    overwrite_auth: bool = False,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    with pool_root_lock(normalized["pool_root"]):
        return _agent_pool_install_unlocked(
            normalized,
            copy_auth_from=copy_auth_from,
            copy_auth_to=copy_auth_to,
            yes=yes,
            overwrite_auth=overwrite_auth,
        )


def _agent_pool_copy_auth_unlocked(
    normalized: dict[str, Any],
    *,
    from_agent: str,
    to: str,
    yes: bool = False,
    overwrite: bool = False,
) -> dict[str, Any]:
    if not isinstance(from_agent, str):
        raise AgentError("from_agent must be a concrete pool Agentin id")
    from_agent = from_agent.strip().lower()
    root = normalized["pool_root"]
    pool_guard_root(root)
    try:
        expected_parent_stat = root.parent.lstat()
        expected_root_stat = root.lstat()
    except OSError as exc:
        raise AgentError("pool root must be a real directory") from exc
    pool_require_real_root(root)
    with pool_root_operation(
        root,
        ensure=False,
        error_text="pool root changed during auth copy",
        expected_parent_stat=expected_parent_stat,
        expected_root_stat=expected_root_stat,
    ) as root:
        if from_agent not in normalized["ids"]:
            raise AgentError("from_agent is not part of the pool")
        target_ids = [
            agent for agent in pool_selector_ids(normalized, to) if agent != from_agent
        ]
        if not target_ids:
            raise AgentError(
                "copy_auth target selector resolves to no target Agentinnen"
            )

        source_home = root / from_agent
        if not is_real_directory_no_symlink(source_home):
            raise AgentError("source Agentin home is missing or invalid")
        source = source_home / "auth.json"
        auth_bytes = pool_read_private_bytes(
            source, MAX_CODEX_CONFIG_BYTES, "source auth is missing or invalid"
        )
        copyable = 0
        copied = 0
        skipped_existing = 0
        skipped_missing_home = 0

        for agent in target_ids:
            home = root / agent
            if not is_real_directory_no_symlink(home):
                skipped_missing_home += 1
                continue
            target = home / "auth.json"
            if path_present_no_follow(target) and not overwrite:
                skipped_existing += 1
                continue
            if not yes:
                copyable += 1
                continue
            if overwrite:
                copyable += 1
                pool_write_private_bytes(target, auth_bytes, 0o600)
                copied += 1
            elif pool_write_private_bytes_if_absent(target, auth_bytes):
                copyable += 1
                copied += 1
            else:
                skipped_existing += 1

        return {
            "ok": True,
            "dry_run": not yes,
            "source_agent": "not_returned",
            "source_agent_state": "set",
            "target_selector": "not_returned",
            "target_selector_state": "set",
            "target_count": len(target_ids),
            "copyable_count": copyable,
            "copied_count": copied,
            "skipped_existing_count": skipped_existing,
            "skipped_missing_home_count": skipped_missing_home,
            "overwrite": overwrite,
            "auth_content": "not_returned",
            "pool_root": PATH_NOT_RETURNED,
            "raw_output": "not_returned",
        }


def agent_pool_copy_auth(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
    *,
    from_agent: str,
    to: str,
    yes: bool = False,
    overwrite: bool = False,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    with pool_root_lock(normalized["pool_root"]):
        return _agent_pool_copy_auth_unlocked(
            normalized,
            from_agent=from_agent,
            to=to,
            yes=yes,
            overwrite=overwrite,
        )


def _agent_pool_refresh_auth_unlocked(
    normalized: dict[str, Any],
    *,
    agent: str,
    yes: bool,
) -> dict[str, Any]:
    root = normalized["pool_root"]
    pool_guard_root(root)
    try:
        expected_parent_stat = root.parent.lstat()
        expected_root_stat = root.lstat()
    except OSError as exc:
        raise AgentError("auth refresh pool root is missing or invalid") from exc
    with pool_root_operation(
        root,
        ensure=False,
        error_text="auth refresh pool root changed unexpectedly",
        expected_parent_stat=expected_parent_stat,
        expected_root_stat=expected_root_stat,
        require_private=True,
    ) as root:
        home = root / agent
        try:
            expected_home_stat = home.lstat()
            expected_home_parent_stat = home.parent.lstat()
        except OSError as exc:
            raise AgentError("auth refresh target home is missing or invalid") from exc
        _fleet_private_directory_stat(
            expected_home_stat, "auth refresh target home is missing or invalid"
        )
        with pool_root_operation(
            home,
            ensure=False,
            error_text="auth refresh target home changed unexpectedly",
            expected_parent_stat=expected_home_parent_stat,
            expected_root_stat=expected_home_stat,
            require_private=True,
        ) as home:
            if tmux_alive(agent_config(agent)["session"]):
                raise AgentError("auth refresh target is running or in use")
            processes = pool_home_processes(home)
            if processes is None or processes:
                raise AgentError("auth refresh target is running or in use")

            target = home / "auth.json"
            try:
                expected_target_stat = target.lstat()
            except FileNotFoundError:
                expected_target_stat = None
            except OSError as exc:
                raise AgentError(
                    "auth refresh target auth is missing or invalid"
                ) from exc
            if expected_target_stat is not None and (
                not stat_module.S_ISREG(expected_target_stat.st_mode)
                or getattr(expected_target_stat, "st_nlink", 1) != 1
                or expected_target_stat.st_uid != os.geteuid()
                or stat_module.S_IMODE(expected_target_stat.st_mode) != 0o600
            ):
                raise AgentError("auth refresh target auth is missing or invalid")

            account = normalized["agent_accounts"].get(agent)
            if not isinstance(account, str) or not CODEX_USAGE_ACCOUNT_RE.fullmatch(
                account
            ):
                raise AgentError(
                    "auth refresh target has no canonical codex-usage account"
                )
            source = pool_codex_usage_auth_source(normalized, account)
            try:
                expected_source_stat = source.lstat()
            except OSError as exc:
                raise AgentError(
                    "codex-usage profile auth is missing or invalid"
                ) from exc
            auth_bytes = pool_read_private_bytes(
                source,
                MAX_CODEX_CONFIG_BYTES,
                "codex-usage profile auth is missing or invalid",
                expected_target_stat=expected_source_stat,
                expected_mode=0o600,
                expected_uid=os.geteuid(),
            )
            if yes:
                replace_private_bytes(
                    target,
                    auth_bytes,
                    mode=0o600,
                    expected_existing_stat=expected_target_stat,
                )
            return {
                "ok": True,
                "dry_run": not yes,
                "target_agent": "not_returned",
                "target_agent_state": "set",
                "source_profile": "not_returned",
                "source_profile_state": "set",
                "target_auth_state": "present"
                if expected_target_stat is not None
                else "missing",
                "refreshed": yes,
                "auth_content": "not_returned",
                "pool_root": PATH_NOT_RETURNED,
                "raw_output": "not_returned",
            }


def agent_pool_refresh_auth(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
    *,
    agent: str,
    yes: bool = False,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    if not isinstance(agent, str):
        raise AgentError("auth refresh target must be a concrete pool Agentin id")
    agent = agent.strip().lower()
    if agent not in normalized["ids"]:
        raise AgentError("auth refresh target is not part of the pool")
    try:
        if canonical_agent_id(agent) != agent:
            raise AgentError("auth refresh target is not a managed Agentin")
    except AgentError:
        raise AgentError("auth refresh target is not a managed Agentin") from None
    with agent_lifecycle_lock(agent), pool_root_lock(normalized["pool_root"]):
        return _agent_pool_refresh_auth_unlocked(normalized, agent=agent, yes=yes)


@contextlib.contextmanager
def pool_agent_lifecycle_locks(
    agents: list[str],
    *,
    snapshot: InventorySnapshot | None = None,
) -> Any:
    known_agents = set((snapshot or current_agent_inventory()).agent_ids)
    with contextlib.ExitStack() as stack:
        for agent in sorted(agents):
            if agent in known_agents:
                lock = (
                    agent_lifecycle_lock(agent)
                    if snapshot is None
                    else agent_lifecycle_lock(agent, snapshot=snapshot)
                )
                stack.enter_context(lock)
        yield


def _agent_pool_destroy_pool_unlocked(
    normalized: dict[str, Any],
    *,
    yes: bool = False,
    force: bool = False,
    remove_root: bool = False,
) -> dict[str, Any]:
    root = normalized["pool_root"]
    pool_guard_root(root)
    if not yes:
        raise AgentError("destroy_pool requires yes=true")
    try:
        root_stat_before = root.lstat()
    except FileNotFoundError:
        root_stat_before = None
    except OSError as exc:
        raise AgentError("pool root must be a real directory") from exc
    root_state = pool_public_path_state(root)
    if root_state != "directory" and not (root_state == "missing" and force):
        raise AgentError("pool root must be a real directory")
    if root_state == "missing":
        return {
            "ok": True,
            "pool_root": PATH_NOT_RETURNED,
            "removed_agent_entries": 0,
            "missing_agent_entries": len(normalized["ids"]),
            "skipped_agent_entries": 0,
            "root_removed": False,
            "raw_output": "not_returned",
        }

    removed = 0
    missing = 0
    skipped = 0
    root_removed = False
    parent_fd = -1
    root_fd = -1
    try:
        operation_root = root
        if root_state == "directory":
            if root_stat_before is None or not stat_module.S_ISDIR(
                root_stat_before.st_mode
            ):
                raise AgentError("pool root must be a real directory")
            try:
                parent_stat = root.parent.lstat()
            except OSError as exc:
                raise AgentError("pool root must be a real directory") from exc
            parent_fd = open_directory_no_follow_matching(
                root.parent,
                parent_stat,
                error_text="pool root must be a real directory",
                changed_text="pool root must be a real directory",
            )
            root_fd = open_directory_no_follow_matching(
                root.name,
                root_stat_before,
                error_text="pool root must be a real directory",
                changed_text="pool root must be a real directory",
                dir_fd=parent_fd,
            )
            operation_root = Path(f"/proc/self/fd/{root_fd}")
        elif root_stat_before is not None:
            raise AgentError("pool root must be a real directory")

        marker = operation_root / POOL_MARKER_FILE
        try:
            marker_stat = marker.lstat()
        except FileNotFoundError:
            marker_stat = None
        except OSError as exc:
            raise AgentError("pool marker could not be read") from exc
        marker_present = (
            marker_stat is not None
            and stat_module.S_ISREG(marker_stat.st_mode)
            and getattr(marker_stat, "st_nlink", 1) == 1
        )
        marker_valid = marker_present and pool_marker_matches(
            marker, marker_stat, normalized
        )
        if not marker_valid and not force:
            raise AgentError(
                "destroy_pool requires an installed pool marker or force=true"
            )
        marker_bytes: bytes | None = None
        if marker_present:
            try:
                marker_bytes = pool_read_private_bytes(
                    marker,
                    MAX_POOL_SPEC_BYTES,
                    "pool marker could not be read",
                )
            except AgentError:
                if remove_root:
                    marker_bytes = None

        def verify_marker_before_removal() -> None:
            if not marker_present:
                return
            try:
                latest_marker_stat = marker.lstat()
            except (FileNotFoundError, OSError) as exc:
                raise AgentError("pool marker changed during removal") from exc
            if (
                not stat_module.S_ISREG(latest_marker_stat.st_mode)
                or getattr(latest_marker_stat, "st_nlink", 1) != 1
                or not source_identity_matches(latest_marker_stat, marker_stat)
            ):
                raise AgentError("pool marker changed during removal")
            if marker_bytes is not None:
                try:
                    latest_marker_bytes = pool_read_private_bytes(
                        marker,
                        MAX_POOL_SPEC_BYTES,
                        "pool marker changed during removal",
                    )
                except AgentError as exc:
                    raise AgentError("pool marker changed during removal") from exc
                if latest_marker_bytes != marker_bytes:
                    raise AgentError("pool marker changed during removal")

        with pool_agent_lifecycle_locks(normalized["ids"]):
            known_agents = set(all_agent_ids())
            for agent in normalized["ids"]:
                if agent in known_agents:
                    lease = agent_lease_status(agent, initialize_state=False)
                    if lease.get("state") not in {"unclaimed", "expired"}:
                        raise AgentError(
                            "pool Agentin has an active or unreadable lease"
                        )
                target = operation_root / agent
                try:
                    target_stat = target.lstat()
                except FileNotFoundError:
                    continue
                except OSError as exc:
                    raise AgentError(
                        "pool Agentin home could not be inspected"
                    ) from exc
                if stat_module.S_ISDIR(target_stat.st_mode) and not stat_module.S_ISLNK(
                    target_stat.st_mode
                ):
                    processes = pool_home_processes(target)
                    if processes is None:
                        raise AgentError("pool Agentin home process scan unavailable")
                    if processes:
                        raise AgentError("pool Agentin home is in use")

            for agent in normalized["ids"]:
                verify_marker_before_removal()
                target = operation_root / agent
                removal_state = remove_agent_pool_entry(target)
                if removal_state == "missing":
                    missing += 1
                elif removal_state == "removed":
                    removed += 1
                else:
                    skipped += 1

            marker_removed = False
            if (
                marker_present
                and skipped == 0
                and (not remove_root or marker_bytes is not None)
            ):
                try:
                    latest_marker_stat = marker.lstat()
                except FileNotFoundError:
                    latest_marker_stat = None
                except OSError as exc:
                    raise AgentError("pool marker changed during removal") from exc
                if latest_marker_stat is not None:
                    if (
                        not stat_module.S_ISREG(latest_marker_stat.st_mode)
                        or getattr(latest_marker_stat, "st_nlink", 1) != 1
                        or not source_identity_matches(latest_marker_stat, marker_stat)
                    ):
                        raise AgentError("pool marker changed during removal")
                    try:
                        if root_fd >= 0:
                            os.unlink(POOL_MARKER_FILE, dir_fd=root_fd)
                        else:
                            marker.unlink()
                        marker_removed = True
                    except FileNotFoundError:
                        pass
            if remove_root and skipped == 0 and (not marker_present or marker_removed):
                if root_fd >= 0:
                    try:
                        current_root = os.stat(
                            root.name, dir_fd=parent_fd, follow_symlinks=False
                        )
                        if stat_module.S_ISDIR(
                            current_root.st_mode
                        ) and source_identity_matches(current_root, root_stat_before):
                            os.rmdir(root.name, dir_fd=parent_fd)
                            root_removed = True
                    except OSError:
                        root_removed = False
                else:
                    try:
                        root.rmdir()
                        root_removed = True
                    except OSError:
                        root_removed = False
            if (
                remove_root
                and not root_removed
                and marker_removed
                and marker_bytes is not None
            ):
                if root_fd < 0 or not write_private_bytes_if_absent_at_dir_fd(
                    root_fd,
                    POOL_MARKER_FILE,
                    marker_bytes,
                    mode=0o600,
                    error_text="pool marker changed during removal",
                ):
                    raise AgentError("pool marker changed during removal")
    finally:
        if root_fd >= 0:
            os.close(root_fd)
        if parent_fd >= 0:
            os.close(parent_fd)

    return {
        "ok": skipped == 0 and (not remove_root or root_removed),
        "pool_root": PATH_NOT_RETURNED,
        "removed_agent_entries": removed,
        "missing_agent_entries": missing,
        "skipped_agent_entries": skipped,
        "root_removed": root_removed,
        "raw_output": "not_returned",
    }


def agent_pool_destroy_pool(
    spec: str | None = None,
    target_dir: str | None = None,
    codex_bin: str | None = None,
    *,
    yes: bool = False,
    force: bool = False,
    remove_root: bool = False,
) -> dict[str, Any]:
    normalized = pool_normalize_spec(spec, target_dir=target_dir, codex_bin=codex_bin)
    with pool_root_lock(normalized["pool_root"]):
        return _agent_pool_destroy_pool_unlocked(
            normalized,
            yes=yes,
            force=force,
            remove_root=remove_root,
        )


def legacy_agent_inventory(
    agents: Mapping[str, Mapping[str, Any]] | None = None,
) -> InventorySnapshot:
    runtime_fallback = agents is None
    source = AGENTS if runtime_fallback else agents
    descriptors: dict[str, AgentDescriptor] = {}
    by_series_lists: dict[str, list[str]] = {}
    positions: dict[str, int] = {}
    agent_ids: list[str] = []
    series_prefixes: list[str] = []
    for agent, config in source.items():
        match = re.fullmatch(r"([a-z])([1-9][0-9]{0,2})", agent)
        if not isinstance(config, Mapping):
            raise AgentError("legacy_agent_inventory_invalid")
        if match is None:
            if not runtime_fallback or agent not in LEGACY_AGENT_ALIASES:
                raise AgentError("legacy_agent_inventory_invalid")
            prefix = agent
            ordinal = 1
        else:
            prefix, ordinal_text = match.groups()
            ordinal = int(ordinal_text)
        if runtime_fallback:
            home = Path(config.get("home", AGENT_POOL_ROOT / agent))
            label = config.get("label", f"Codex Agentin {agent.upper()}")
            Path(config.get("runner", home / "codex"))
            session = config.get("session", f"codex_agent_{agent}_mcp")
        else:
            try:
                label = config["label"]
                Path(config["runner"])
                home = Path(config["home"])
                session = config["session"]
            except (KeyError, TypeError, ValueError):
                raise AgentError("legacy_agent_inventory_invalid") from None
        if not isinstance(label, str) or not isinstance(session, str):
            raise AgentError("legacy_agent_inventory_invalid")
        if prefix not in by_series_lists:
            by_series_lists[prefix] = []
            series_prefixes.append(prefix)
        positions[agent] = len(agent_ids)
        agent_ids.append(agent)
        by_series_lists[prefix].append(agent)
        descriptors[agent] = AgentDescriptor(
            agent_id=agent,
            series_prefix=prefix,
            ordinal=ordinal,
            label=label,
            runner=RunnerKind.CODEX_CLI,
            provider=Provider.OPENAI_CHATGPT,
            model=DEFAULT_AGENT_MODEL,
            account_id=f"legacy-{prefix}",
            home=home,
            session=session,
            enabled=config.get("enabled", True) is True,
        )
    by_series = {
        f"{prefix}-series": tuple(ids) for prefix, ids in by_series_lists.items()
    }
    return InventorySnapshot(
        agent_ids=tuple(agent_ids),
        agents=MappingProxyType(descriptors),
        by_series=MappingProxyType(by_series),
        positions=MappingProxyType(positions),
        series_prefixes=tuple(series_prefixes),
    )


def normalize_applet_agents(agents: Any, *, allow_empty: bool = False) -> list[str]:
    if not isinstance(agents, list):
        raise AgentError("applet_agents must be a list")
    normalized_agents = agents
    if not normalized_agents and not allow_empty:
        raise AgentError("applet_agents must contain 1 to 6 entries")
    if len(normalized_agents) > MAX_APPLET_AGENTS:
        raise AgentError("applet_agents list has at most 6 entries")
    normalized: list[str] = []
    seen: set[str] = set()
    snapshot = current_agent_inventory()
    for agent in normalized_agents:
        if not isinstance(agent, str):
            raise AgentError("applet_agents entries must be strings")
        value = normalize_agent_selector_text(agent)
        if value in seen:
            raise AgentError("applet_agents must not contain duplicates")
        descriptor = snapshot.agents.get(value)
        if descriptor is None or not descriptor.enabled:
            raise AgentError("applet_agents only accepts concrete enabled agent ids")
        normalized.append(value)
        seen.add(value)
    return normalized


def applet_remaining_timeout(deadline: float) -> float:
    if (
        isinstance(deadline, bool)
        or not isinstance(deadline, (int, float))
        or not math.isfinite(deadline)
    ):
        raise AgentError("applet status deadline is invalid")
    remaining = float(deadline) - time.monotonic()
    if remaining <= 0:
        raise AgentError("applet status deadline exceeded")
    return min(APPLET_TMUX_TIMEOUT_SECONDS, remaining)


def ensure_applet_action_key() -> bytes:
    ensure_private_dir(STATE_ROOT)
    try:
        APPLET_ACTION_KEY_FILE.lstat()
    except FileNotFoundError:
        encoded = base64.urlsafe_b64encode(os.urandom(APPLET_ACTION_KEY_BYTES))
        write_private_new_bytes(APPLET_ACTION_KEY_FILE, encoded, mode=0o600)
    except OSError as exc:
        raise AgentError("applet action key is unavailable") from exc
    return read_applet_action_key()


def read_applet_action_key() -> bytes:
    try:
        key_stat = APPLET_ACTION_KEY_FILE.lstat()
    except OSError as exc:
        raise AgentError("applet action key is unavailable") from exc
    if (
        not stat_module.S_ISREG(key_stat.st_mode)
        or stat_module.S_ISLNK(key_stat.st_mode)
        or getattr(key_stat, "st_nlink", 1) > 1
        or key_stat.st_uid != os.geteuid()
        or stat_module.S_IMODE(key_stat.st_mode) != 0o600
        or key_stat.st_size != APPLET_ACTION_KEY_TEXT_BYTES
    ):
        raise AgentError("applet action key is unavailable")
    encoded = read_private_regular_text(
        APPLET_ACTION_KEY_FILE,
        APPLET_ACTION_KEY_TEXT_BYTES,
        "applet action key is unavailable",
    )
    if not re.fullmatch(r"[A-Za-z0-9_-]{43}=", encoded):
        raise AgentError("applet action key is unavailable")
    try:
        key = base64.b64decode(encoded, altchars=b"-_", validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        raise AgentError("applet action key is unavailable") from exc
    if len(key) != APPLET_ACTION_KEY_BYTES:
        raise AgentError("applet action key is unavailable")
    return key


def _applet_token_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def _applet_token_decode(text: str) -> bytes:
    if not isinstance(text, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", text):
        raise AgentError("applet context token is invalid")
    padding = "=" * (-len(text) % 4)
    try:
        decoded = base64.b64decode(text + padding, altchars=b"-_", validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        raise AgentError("applet context token is invalid") from exc
    if _applet_token_encode(decoded) != text:
        raise AgentError("applet context token is invalid")
    return decoded


def applet_action_fingerprint(state: dict[str, Any]) -> str:
    try:
        encoded = json.dumps(
            state, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        ).encode("ascii")
    except (TypeError, ValueError, RecursionError, UnicodeError) as exc:
        raise AgentError("applet action state is invalid") from exc
    return hashlib.sha256(encoded).hexdigest()


def applet_action_fingerprint_for(action: str, state: dict[str, Any]) -> str:
    if action == "start":
        selected = {
            key: state.get(key)
            for key in (
                "agent",
                "activity_state",
                "backend_state",
                "control_state",
                "auth_state",
                "identity_state",
                "lease_state",
                "limit_state",
                "blocked_until_utc",
                "run_marker",
            )
        }
    elif action == "stop":
        selected = {
            key: state.get(key)
            for key in (
                "agent",
                "activity_state",
                "backend_state",
                "identity_state",
                "lease_state",
                "run_marker",
            )
        }
    else:
        raise AgentError("applet action is invalid")
    return applet_action_fingerprint(selected)


def issue_applet_action_token(
    action: str,
    agent: str,
    state: dict[str, Any],
    key: bytes,
    *,
    now: float | None = None,
) -> str:
    if action not in {"start", "stop"}:
        raise AgentError("applet action is invalid")
    agent = normalize_applet_agents([agent])[0]
    if not isinstance(key, bytes) or len(key) != APPLET_ACTION_KEY_BYTES:
        raise AgentError("applet action key is unavailable")
    issued_at = int(time.time() if now is None else now)
    claims = {
        "a": action,
        "e": issued_at + APPLET_ACTION_TOKEN_TTL_SECONDS,
        "f": applet_action_fingerprint_for(action, state),
        "g": agent,
        "i": issued_at,
        "v": 1,
    }
    payload = json.dumps(claims, sort_keys=True, separators=(",", ":")).encode("ascii")
    encoded_payload = _applet_token_encode(payload)
    signature = hmac.new(key, encoded_payload.encode("ascii"), hashlib.sha256).digest()
    token = f"{encoded_payload}.{_applet_token_encode(signature)}"
    if len(token) > MAX_APPLET_ACTION_TOKEN_CHARS:
        raise AgentError("applet context token is invalid")
    return token


def validate_applet_action_token(
    token: str,
    key: bytes,
    *,
    now: float | None = None,
) -> dict[str, Any]:
    if (
        not isinstance(token, str)
        or not token
        or len(token) > MAX_APPLET_ACTION_TOKEN_CHARS
        or not APPLET_ACTION_TOKEN_RE.fullmatch(token)
    ):
        raise AgentError("applet context token is invalid")
    if not isinstance(key, bytes) or len(key) != APPLET_ACTION_KEY_BYTES:
        raise AgentError("applet action key is unavailable")
    encoded_payload, encoded_signature = token.split(".", 1)
    supplied_signature = _applet_token_decode(encoded_signature)
    expected_signature = hmac.new(
        key, encoded_payload.encode("ascii"), hashlib.sha256
    ).digest()
    if len(supplied_signature) != len(expected_signature) or not hmac.compare_digest(
        supplied_signature,
        expected_signature,
    ):
        raise AgentError("applet context token is invalid")
    try:
        claims = json.loads(_applet_token_decode(encoded_payload))
    except (json.JSONDecodeError, UnicodeDecodeError, RecursionError) as exc:
        raise AgentError("applet context token is invalid") from exc
    if not isinstance(claims, dict) or set(claims) != {"a", "e", "f", "g", "i", "v"}:
        raise AgentError("applet context token is invalid")
    if (
        claims.get("v") != 1
        or claims.get("a") not in {"start", "stop"}
        or not isinstance(claims.get("g"), str)
        or claims["g"] not in current_agent_inventory().agents
        or not isinstance(claims.get("f"), str)
        or not re.fullmatch(r"[0-9a-f]{64}", claims["f"])
        or isinstance(claims.get("i"), bool)
        or not isinstance(claims.get("i"), int)
        or isinstance(claims.get("e"), bool)
        or not isinstance(claims.get("e"), int)
        or claims["e"] - claims["i"] != APPLET_ACTION_TOKEN_TTL_SECONDS
    ):
        raise AgentError("applet context token is invalid")
    timestamp = time.time() if now is None else now
    if claims["i"] > timestamp + 5:
        raise AgentError("applet context token is invalid")
    if claims["e"] < timestamp:
        raise AgentError("applet context token expired")
    return claims


def applet_limit_observation(usage: Any) -> tuple[str, str | None]:
    if not isinstance(usage, dict):
        return "unknown", None
    blocked_until = usage.get("blocked_until_utc")
    if blocked_until is not None and (
        not isinstance(blocked_until, str) or parse_utc_timestamp(blocked_until) is None
    ):
        blocked_until = None
    if usage.get("blocked") is True:
        return "blocked", blocked_until
    if usage.get("blocked") is False and usage.get("state") in {
        "clear",
        "ok",
        "released",
    }:
        return "clear", blocked_until
    return "unknown", blocked_until


def applet_capacity_observation(admission: Any) -> dict[str, Any] | None:
    if not isinstance(admission, dict):
        return None
    allowed = admission.get("allowed")
    reason_codes = admission.get("reason_codes")
    if (
        not isinstance(allowed, bool)
        or not isinstance(reason_codes, list)
        or any(
            not isinstance(reason, str) or reason not in RESOURCE_REASON_CODES
            for reason in reason_codes
        )
    ):
        return None
    return {
        "allowed": allowed,
        "reason_codes": sorted(set(reason_codes)),
    }


def applet_action_state(
    row: dict[str, Any],
    usage: Any,
    admission: Any = None,
    *,
    run_marker: str | None = None,
) -> dict[str, Any]:
    limit_state, blocked_until = applet_limit_observation(usage)
    return {
        "agent": row.get("agent"),
        "activity_state": row.get("activity_state"),
        "backend_state": row.get("backend_state"),
        "control_state": row.get("control_state"),
        "auth_state": row.get("auth_state"),
        "identity_state": row.get("identity_state"),
        "lease_state": row.get("lease_state"),
        "limit_state": limit_state,
        "blocked_until_utc": blocked_until,
        "capacity": applet_capacity_observation(admission),
        "run_marker": run_marker
        if isinstance(run_marker, str) and len(run_marker) <= 128
        else None,
    }


def applet_action_allowed(
    action: str,
    state: dict[str, Any],
    *,
    require_capacity: bool = True,
) -> bool:
    if action == "start":
        capacity = state.get("capacity")
        return (
            state.get("activity_state") == "sleeping"
            and state.get("backend_state") == "ok"
            and state.get("control_state") == "ready"
            and state.get("auth_state") == "ready"
            and state.get("identity_state") == "stopped"
            and state.get("lease_state") in {"unclaimed", "expired"}
            and state.get("limit_state") == "clear"
            and (
                not require_capacity
                or (isinstance(capacity, dict) and capacity.get("allowed") is True)
            )
        )
    if action == "stop":
        return (
            state.get("activity_state") == "running"
            and state.get("backend_state") == "ok"
            and state.get("identity_state") == "verified"
            and state.get("lease_state") in {"unclaimed", "expired"}
        )
    return False


def pane_pid_from_text(text: str) -> int | None:
    if not text.isascii() or not text.isdigit():
        return None
    try:
        value = int(text)
    except ValueError:
        return None
    return value if value > 0 and text == str(value) else None


def managed_applet_inventory(
    snapshot: InventorySnapshot | None = None,
) -> dict[str, Any]:
    if snapshot is None:
        selected, _registry_backed = effective_observation_inventory()
        if selected is None:
            raise AgentError("fleet_registry_unavailable")
    else:
        selected = snapshot
    inventory = run_tmux(
        ["list-sessions", "-F", "#{session_name}"],
        check=False,
        timeout=APPLET_TMUX_TIMEOUT_SECONDS,
    )
    if inventory.returncode != 0:
        raise AgentError("applet status backend unavailable")
    session_to_agent = {
        agent_config(agent, selected)["session"]: agent
        for agent in selected.agent_ids
        if selected.agents[agent].enabled
    }
    ordered_running: list[str] = []
    seen: set[str] = set()
    for line in inventory.stdout.splitlines():
        agent = session_to_agent.get(line.strip())
        if agent is None or agent in seen:
            continue
        seen.add(agent)
        ordered_running.append(agent)
    ordered_running.sort(key=selected.positions.__getitem__)
    visible_running = ordered_running[:MAX_APPLET_AGENTS]
    return {
        "running_agents": ordered_running,
        "visible_running_agents": visible_running,
        "overflow": max(0, len(ordered_running) - len(visible_running)),
    }


def applet_agent_observation(
    agent: str, *, deadline: float, known_running: bool | None = None
) -> dict[str, Any]:
    agent = normalize_applet_agents([agent])[0]
    cfg = agent_config(agent)
    session = cfg["session"]
    if known_running is None:
        session_check = run_tmux(
            ["has-session", "-t", session],
            check=False,
            timeout=applet_remaining_timeout(deadline),
        )
        if session_check.returncode not in {0, 1}:
            raise AgentError("applet status backend unavailable")
        running = session_check.returncode == 0
    else:
        if not isinstance(known_running, bool):
            raise AgentError("known_running must be a boolean")
        running = known_running

    applet_remaining_timeout(deadline)
    process_summary = agent_home_process_summary(agent)
    if running:
        pane_check = run_tmux(
            ["display-message", "-p", "-t", session, "#{pane_pid}"],
            check=False,
            timeout=applet_remaining_timeout(deadline),
        )
        if pane_check.returncode != 0:
            raise AgentError("applet status backend unavailable")
        pane_text = pane_check.stdout.strip()
        pane_process_id = pane_pid_from_text(pane_text)
        activity_state = "running"
    else:
        pane_process_id = None
        activity_state = "sleeping"
    identity_guard = agent_identity_guard(
        running,
        process_summary,
        pane_process_id=pane_process_id,
    )
    identity_verified = identity_guard.get("ok") is True
    identity_state = (
        ("verified" if running else "stopped") if identity_verified else "unverified"
    )
    backend_state = "ok" if identity_verified else "degraded"

    applet_remaining_timeout(deadline)
    auth = agent_auth_status(agent)
    if auth.get("authenticated") is True:
        auth_state = "ready"
    elif auth.get("auth_state") == "unreadable":
        auth_state = "unknown"
    else:
        auth_state = "blocked"

    applet_remaining_timeout(deadline)
    lease = agent_lease_status(agent, initialize_state=False)
    applet_remaining_timeout(deadline)
    raw_lease_state = lease.get("state")
    lease_state = (
        raw_lease_state
        if raw_lease_state in {"unclaimed", "held", "expired", "unreadable"}
        else "unreadable"
    )

    if (
        auth_state == "blocked"
        or identity_state == "unverified"
        or lease_state == "held"
    ):
        control_state = "blocked"
    elif (
        auth_state == "unknown"
        or identity_state == "unknown"
        or lease_state == "unreadable"
    ):
        control_state = "unknown"
    elif auth_state == "ready" and identity_state in {"verified", "stopped"}:
        control_state = "ready"
    else:
        control_state = "unknown"

    return {
        "agent": agent,
        "activity_state": activity_state,
        "backend_state": backend_state,
        "control_state": control_state,
        "auth_state": auth_state,
        "identity_state": identity_state,
        "lease_state": lease_state,
    }


def applet_error_row(agent: str) -> dict[str, Any]:
    return {
        "agent": agent,
        "activity_state": "unknown",
        "backend_state": "error",
        "control_state": "unknown",
        "auth_state": "unknown",
        "identity_state": "unknown",
        "lease_state": "unreadable",
    }


def applet_action_rows(
    rows: list[dict[str, Any]],
    *,
    running_count: int | None = None,
    deadline: float,
) -> list[dict[str, Any]]:
    try:
        key = read_applet_action_key()
    except AgentError:
        key = None
    start_offered = False
    admission: dict[str, Any] | None = None
    admission_checked = False
    decorated: list[dict[str, Any]] = []
    for row in rows:
        if time.monotonic() >= deadline:
            decorated.append(
                {
                    **row,
                    "allowed_action": "none",
                    "context_token": "",
                    "limit_state": "unknown",
                    "blocked_until_utc": None,
                }
            )
            continue
        meta = read_meta(row["agent"])
        run_marker = meta.get("run_id") if not meta.get("meta_error") else None
        try:
            usage = codex_usage_watchdog_status(row["agent"])
        except AgentError:
            usage = None
        action = "none"
        if (
            key is not None
            and not start_offered
            and row.get("activity_state") == "sleeping"
            and row.get("control_state") == "ready"
        ):
            if not admission_checked:
                admission_checked = True
                try:
                    admission = spawn_admission_decision(
                        1,
                        running_agents_override=running_count,
                    )
                except AgentError:
                    admission = None
            candidate_state = applet_action_state(
                row, usage, admission, run_marker=run_marker
            )
            if applet_action_allowed("start", candidate_state):
                action = "start"
                start_offered = True
        state = applet_action_state(
            row,
            usage,
            admission if action == "start" else None,
            run_marker=run_marker,
        )
        if (
            action == "none"
            and key is not None
            and applet_action_allowed("stop", state)
        ):
            action = "stop"
        context_token = ""
        if action != "none" and key is not None:
            try:
                context_token = issue_applet_action_token(
                    action, row["agent"], state, key
                )
            except AgentError:
                action = "none"
        decorated.append(
            {
                **row,
                "allowed_action": action,
                "context_token": context_token,
                "limit_state": state["limit_state"],
                "blocked_until_utc": state["blocked_until_utc"],
            }
        )
    return decorated


def normalize_applet_schema_version(schema_version: Any) -> int:
    if isinstance(schema_version, bool) or not isinstance(schema_version, int):
        raise AgentError("schema_version must be an integer")
    if schema_version not in {1, 2}:
        raise AgentError("schema_version must be 1 or 2")
    return schema_version


def applet_status_v1(agents: Any) -> dict[str, Any]:
    selected = normalize_applet_agents(agents)
    deadline = time.monotonic() + APPLET_STATUS_TIMEOUT_SECONDS
    rows: list[dict[str, Any]] = []
    for agent in selected:
        if time.monotonic() >= deadline:
            rows.append(applet_error_row(agent))
            continue
        try:
            rows.append(applet_agent_observation(agent, deadline=deadline))
        except AgentError:
            rows.append(applet_error_row(agent))

    activity_states = [row["activity_state"] for row in rows]
    if all(state == "running" for state in activity_states):
        activity_state = "running"
    elif all(state == "sleeping" for state in activity_states):
        activity_state = "sleeping"
    elif all(state == "unknown" for state in activity_states):
        activity_state = "unknown"
    else:
        activity_state = "mixed"

    backend_states = [row["backend_state"] for row in rows]
    if all(state == "ok" for state in backend_states):
        backend_state = "ok"
    elif all(state == "error" for state in backend_states):
        backend_state = "unavailable"
    else:
        backend_state = "degraded"

    control_states = [row["control_state"] for row in rows]
    if all(state == "ready" for state in control_states):
        control_state = "ready"
    elif all(state == "blocked" for state in control_states):
        control_state = "blocked"
    elif all(state == "unknown" for state in control_states):
        control_state = "unknown"
    else:
        control_state = "mixed"

    counts = {
        "tracked": len(rows),
        "running": activity_states.count("running"),
        "sleeping": activity_states.count("sleeping"),
        "ready": control_states.count("ready"),
        "blocked": control_states.count("blocked"),
        "issues": sum(
            row["backend_state"] != "ok" or row["control_state"] != "ready"
            for row in rows
        ),
    }
    return {
        "schema_version": 1,
        "mode": "read_only",
        "activity_state": activity_state,
        "backend_state": backend_state,
        "control_state": control_state,
        "counts": counts,
        "agents": rows,
        "raw_output": "not_returned",
    }


def applet_status_v2(agents: Any) -> dict[str, Any]:
    pinned_agents = normalize_applet_agents(agents, allow_empty=True)
    selected: list[str] = []
    running_agents: list[str] = []
    overflow = 0
    try:
        inventory = managed_applet_inventory()
    except AgentError:
        pass
    else:
        running_agents = inventory["running_agents"]
        overflow = inventory["overflow"]
        selected = list(inventory["visible_running_agents"])
        running_set = set(running_agents)
        for agent in pinned_agents:
            if agent in running_set or agent in selected:
                continue
            if len(selected) >= MAX_APPLET_AGENTS:
                break
            selected.append(agent)

    deadline = time.monotonic() + APPLET_STATUS_TIMEOUT_SECONDS
    running_set = set(running_agents)
    rows: list[dict[str, Any]] = []
    for agent in selected:
        if time.monotonic() >= deadline:
            rows.append(applet_error_row(agent))
            continue
        try:
            rows.append(
                applet_agent_observation(
                    agent,
                    deadline=deadline,
                    known_running=agent in running_set,
                )
            )
        except AgentError:
            rows.append(applet_error_row(agent))

    rows = applet_action_rows(
        rows,
        running_count=len(running_agents),
        deadline=deadline,
    )

    try:
        native_agents = native_agent_status(
            expected_parent_sessions=len(running_agents)
        )
    except AgentError:
        native_agents = {
            "bridge_state": "degraded",
            "counts": {"active": 0, "unconfirmed": 0, "overflow": 0},
            "agents": [],
            "truncated": False,
        }

    return {
        "schema_version": 2,
        "mode": "read_only",
        "counts": {
            "tracked": len(rows),
            "running": len(running_agents),
            "sleeping": sum(row["activity_state"] == "sleeping" for row in rows),
            "overflow": overflow,
        },
        "agents": rows,
        "native_agents": native_agents,
        "raw_output": "not_returned",
    }


def applet_action(action: Any, agent: Any, context_token: Any) -> dict[str, Any]:
    if not isinstance(action, str) or action not in {"start", "stop"}:
        raise AgentError("applet action is invalid")
    if not isinstance(agent, str):
        raise AgentError("applet agent is invalid")
    agent = normalize_applet_agents([agent])[0]
    if not isinstance(context_token, str):
        raise AgentError("applet context token is invalid")
    if action == "start":
        require_fleet_recovery_ready("agent_start")
    with agent_lifecycle_lock(agent, timeout_seconds=APPLET_TMUX_TIMEOUT_SECONDS):
        key = read_applet_action_key()
        claims = validate_applet_action_token(context_token, key)
        if claims["a"] != action or claims["g"] != agent:
            raise AgentError("applet context token is invalid")
        deadline = time.monotonic() + APPLET_STATUS_TIMEOUT_SECONDS
        row = applet_agent_observation(agent, deadline=deadline)
        try:
            usage = codex_usage_watchdog_status(agent)
        except AgentError:
            usage = None
        admission = None
        meta = read_meta(agent)
        run_marker = meta.get("run_id") if not meta.get("meta_error") else None
        state = applet_action_state(row, usage, admission, run_marker=run_marker)
        if not hmac.compare_digest(
            claims["f"], applet_action_fingerprint_for(action, state)
        ):
            raise AgentError("applet context token is stale")
        if not applet_action_allowed(action, state, require_capacity=action != "start"):
            raise AgentError("applet action is no longer allowed")

        if action == "start":
            require_resource_capacity_preflight(operation="agent_start")
            with _resource_gate_composer_scope():
                with hive_capacity_probe_guard("agent_start"):
                    result = _start_agent_with_lease_unlocked(
                        agent,
                        cwd=str(Path.home()),
                    )
            final_state = (
                "running"
                if result.get("status") in {"started", "already_running"}
                else "unknown"
            )
        else:
            _claim_agent_unlocked(
                agent,
                ttl_seconds=60,
                enforce_recovery_gate=False,
            )
            try:
                result = _stop_agent_unlocked(agent)
            except Exception:
                with contextlib.suppress(AgentError):
                    current_lease = agent_lease_status(agent)
                    if current_lease.get("held_by_this_server"):
                        _release_agent_unlocked(agent, force=True)
                raise
            final_state = (
                "sleeping"
                if result.get("status") in {"stopped", "not_running"}
                else "unknown"
            )
        return {
            "agent": agent,
            "action": action,
            "status": "completed" if final_state != "unknown" else "unknown",
            "state": final_state,
            "raw_output": "not_returned",
        }


def _snapshot_file_identity(stat_result: os.stat_result | None) -> FileIdentity | None:
    if stat_result is None:
        return None
    return FileIdentity(
        stat_result.st_dev,
        stat_result.st_ino,
        stat_result.st_mode,
        stat_result.st_uid,
        stat_result.st_gid,
        stat_result.st_nlink,
    )


def _fleet_load_recovery_journal_with_identity(
    paths: FleetPaths | None = None,
) -> tuple[FleetRecoveryJournal, FileIdentity] | None:
    paths = paths or FleetPaths.from_state_root(STATE_ROOT)
    raw_text: str | None = None
    identity: FileIdentity | None = None
    try:
        parent_stat = paths.root.lstat()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise AgentError("fleet_recovery_state_invalid") from exc
    parent_fd = -1
    try:
        parent_fd = open_directory_no_follow_matching(
            paths.root,
            parent_stat,
            error_text="fleet_recovery_state_invalid",
            changed_text="fleet_recovery_state_invalid",
        )
        try:
            target_stat = os.stat(
                paths.recovery.name, dir_fd=parent_fd, follow_symlinks=False
            )
        except FileNotFoundError:
            return None
        except OSError as exc:
            raise AgentError("fleet_recovery_state_invalid") from exc
        if (
            not stat_module.S_ISREG(target_stat.st_mode)
            or stat_module.S_ISLNK(target_stat.st_mode)
            or getattr(target_stat, "st_nlink", 1) != 1
            or target_stat.st_uid != os.geteuid()
            or stat_module.S_IMODE(target_stat.st_mode) != 0o600
            or target_stat.st_size > MAX_RECOVERY_DOCUMENT_BYTES
        ):
            raise AgentError("fleet_recovery_state_invalid")
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = -1
        try:
            fd = os.open(paths.recovery.name, flags, dir_fd=parent_fd)
            opened = os.fstat(fd)
            if not source_identity_with_snapshot_matches(opened, target_stat):
                raise AgentError("fleet_recovery_state_invalid")
            identity = _snapshot_file_identity(opened)
            with os.fdopen(fd, "rb") as handle:
                fd = -1
                raw = handle.read(MAX_RECOVERY_DOCUMENT_BYTES + 1)
            if len(raw) > MAX_RECOVERY_DOCUMENT_BYTES:
                raise AgentError("fleet_recovery_state_invalid")
            raw_text = raw.decode("utf-8")
        except OSError as exc:
            raise AgentError("fleet_recovery_state_invalid") from exc
        finally:
            if fd >= 0:
                os.close(fd)
    finally:
        if parent_fd >= 0:
            os.close(parent_fd)
    try:
        payload = json.loads(raw_text)
    except (json.JSONDecodeError, TypeError, UnicodeError) as exc:
        raise AgentError("fleet_recovery_state_invalid") from exc
    try:
        journal = normalize_recovery_document(payload)
    except Exception as exc:
        raise AgentError("fleet_recovery_state_invalid") from exc
    if identity is None:
        raise AgentError("fleet_recovery_state_invalid")
    return journal, identity


@contextlib.contextmanager
def native_agent_registry_lock(
    *, timeout_seconds: float = NATIVE_AGENT_LOCK_TIMEOUT_SECONDS
) -> Any:
    held_locks = _NATIVE_AGENT_REGISTRY_LOCK_STACK.get()
    if "native-agents" in held_locks:
        yield
        return
    try:
        timeout_seconds_f = float(timeout_seconds)
    except (OverflowError, TypeError, ValueError) as exc:
        raise AgentError(
            "native agent registry lock timeout must be a finite number"
        ) from exc
    if not math.isfinite(timeout_seconds_f) or timeout_seconds_f < 0:
        raise AgentError("native agent registry lock timeout must be a finite number")
    deadline = time.monotonic() + timeout_seconds_f if timeout_seconds_f > 0 else None
    ensure_private_dir(STATE_ROOT)
    ensure_private_dir(LOCK_DIR)
    lock_path = NATIVE_AGENT_REGISTRY_LOCK_FILE
    with open_private_regular_update(lock_path) as fh:
        token = None
        lock_acquired = False
        try:
            if deadline is None:
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX)
            else:
                while True:
                    try:
                        fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        remaining = deadline - time.monotonic()
                        if remaining <= 0:
                            raise AgentError(
                                "could not acquire native agent registry lock"
                            )
                        time.sleep(min(0.01, remaining))
            lock_acquired = True
            token = _NATIVE_AGENT_REGISTRY_LOCK_STACK.set(
                (*held_locks, "native-agents")
            )
            yield
        except OSError as exc:
            raise AgentError("could not acquire native agent registry lock") from exc
        finally:
            if token is not None:
                _NATIVE_AGENT_REGISTRY_LOCK_STACK.reset(token)
            if lock_acquired:
                try:
                    fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
                except OSError:
                    pass


@contextlib.contextmanager
def spawn_admission_lock() -> Any:
    held_locks = _SPAWN_ADMISSION_LOCK_STACK.get()
    if "spawn-admission" in held_locks:
        yield
        return
    ensure_private_dir(STATE_ROOT)
    ensure_private_dir(LOCK_DIR)
    lock_path = LOCK_DIR / "spawn-admission.lock"
    with open_private_regular_update(lock_path) as fh:
        try:
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX)
        except OSError as exc:
            raise AgentError("could not acquire spawn admission lock") from exc
        token = _SPAWN_ADMISSION_LOCK_STACK.set((*held_locks, "spawn-admission"))
        try:
            yield
        finally:
            _SPAWN_ADMISSION_LOCK_STACK.reset(token)
            try:
                fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
            except OSError:
                pass


