# Hive diagnostics are additive and read-only.  Their schemas are deliberately
# closed; productive admission/assignment operations remain outside this catalog.
_published_tool_names = {tool["name"] for tool in TOOLS}
TOOLS.extend(
    tool
    for tool in hive_tool_definitions()
    if tool["name"] not in _published_tool_names
)


TOOL_SCHEMAS = {tool["name"]: tool["inputSchema"] for tool in TOOLS}


def validate_tool_call(name: Any, args: Any) -> tuple[str, dict[str, Any]]:
    if not isinstance(name, str) or not name.strip():
        raise AgentError("tools/call requires a known tool name")
    if name not in TOOL_SCHEMAS:
        raise AgentError("unknown tool")
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise AgentError("tools/call arguments must be an object")

    schema = TOOL_SCHEMAS[name]
    properties = schema.get("properties", {})
    if schema.get("additionalProperties") is False:
        extra = sorted(set(args) - set(properties))
        if extra:
            raise AgentError(f"unknown argument(s) for {name}")

    missing = [
        field
        for field in schema.get("required", [])
        if field not in args or args[field] is None
    ]
    if missing:
        raise AgentError(
            f"missing required argument(s) for {name}: {', '.join(missing)}"
        )
    for field, value in args.items():
        validate_schema_value(field, value, properties[field])
    return name, args


def compact_optional_args(args: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in args.items() if value is not None}


def call_validated_tool(
    name: str,
    args: dict[str, Any],
    *,
    principal_class: str | None = None,
) -> dict[str, Any]:
    validated_name, validated_args = validate_tool_call(
        name, compact_optional_args(args)
    )
    if principal_class is not None:
        return call_tool(
            validated_name,
            validated_args,
            principal_class=principal_class,
        )
    return call_tool(validated_name, validated_args)


def call_teamleader_tool(name: str, args: dict[str, Any]) -> dict[str, Any]:
    status = require_teamleader_tool_access()
    principal_class = require_principal_tool_access(name, status)
    return call_validated_tool(
        name,
        args,
        principal_class=principal_class,
    )


def teamleader_tool_catalog() -> list[dict[str, Any]]:
    status = require_teamleader_tool_access()
    allowed_names = allowed_tool_names_for_principal_class(
        verified_principal_class(status)
    )
    allowed_tools = [tool for tool in TOOLS if tool["name"] in allowed_names]
    try:
        encoded = json.dumps(
            allowed_tools, ensure_ascii=True, separators=(",", ":")
        ).encode("ascii")
    except (TypeError, ValueError, RecursionError, UnicodeError) as exc:
        raise AgentError("teamleader tool catalog is invalid") from exc
    if len(encoded) > MAX_TOOL_CATALOG_BYTES:
        raise AgentError("teamleader tool catalog is invalid")
    snapshot = json.loads(encoded)
    if not isinstance(snapshot, list):
        raise AgentError("teamleader tool catalog is invalid")
    return snapshot


def validate_schema_value(field: str, value: Any, schema: dict[str, Any]) -> None:
    value_type = schema.get("type")
    if value_type == "string":
        if not isinstance(value, str):
            raise AgentError(f"{field} must be a string")
        allowed = schema.get("enum")
        if allowed and value not in allowed:
            raise AgentError(f"{field} must be one of: {', '.join(allowed)}")
        max_length = schema.get("maxLength")
        if isinstance(max_length, int) and len(value) > max_length:
            raise AgentError(f"{field} must not exceed {max_length} characters")
        return
    if value_type == "integer":
        if isinstance(value, bool) or not isinstance(value, int):
            raise AgentError(f"{field} must be an integer")
        allowed = schema.get("enum")
        if allowed and value not in allowed:
            raise AgentError(
                f"{field} must be one of: {', '.join(str(item) for item in allowed)}"
            )
        minimum = schema.get("minimum")
        maximum = schema.get("maximum")
        if isinstance(minimum, int) and value < minimum:
            raise AgentError(f"{field} must be >= {minimum}")
        if isinstance(maximum, int) and value > maximum:
            raise AgentError(f"{field} must be <= {maximum}")
        return
    if value_type == "boolean":
        if not isinstance(value, bool):
            raise AgentError(f"{field} must be a boolean")
        return
    if value_type == "array":
        if not isinstance(value, list):
            raise AgentError(f"{field} must be an array")
        min_items = schema.get("minItems")
        if isinstance(min_items, int) and len(value) < min_items:
            raise AgentError(f"{field} must contain at least {min_items} item(s)")
        max_items = schema.get("maxItems")
        if isinstance(max_items, int) and len(value) > max_items:
            raise AgentError(f"{field} must contain at most {max_items} items")
        item_schema = schema.get("items", {})
        if isinstance(item_schema, dict):
            for index, item in enumerate(value):
                validate_schema_value(f"{field}[{index}]", item, item_schema)
        return
    raise AgentError(f"{field} uses an unsupported schema type")


def rpc_result(message_id: Any, result: Any) -> dict[str, Any]:
    return {"jsonrpc": "2.0", "id": message_id, "result": result}


def rpc_error(message_id: Any, code: int, message: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": message_id,
        "error": {"code": code, "message": safe_error_text(message)},
    }


def handle_rpc(
    msg: dict[str, Any],
    *,
    enforce_master_role: bool = False,
    autonomous_runtime_surface: bool = False,
) -> dict[str, Any] | None:
    if not isinstance(msg, dict):
        raise AgentError("RPC message must be an object")
    if autonomous_runtime_surface:
        enforce_master_role = True
    message_id = msg.get("id")
    valid_id = message_id is None or (
        isinstance(message_id, str)
        or (
            isinstance(message_id, (int, float))
            and not isinstance(message_id, bool)
            and (not isinstance(message_id, float) or math.isfinite(message_id))
        )
    )
    if "id" in msg and not valid_id:
        return rpc_error(None, -32600, "Invalid Request")
    if msg.get("jsonrpc") != "2.0":
        return rpc_error(message_id if "id" in msg else None, -32600, "Invalid Request")
    method = msg.get("method")
    if not isinstance(method, str):
        return rpc_error(message_id if "id" in msg else None, -32600, "Invalid Request")

    def reply(payload: dict[str, Any]) -> dict[str, Any] | None:
        return payload if "id" in msg else None

    if method == "initialize":
        params = msg.get("params", {})
        if params is None:
            params = {}
        if not isinstance(params, dict):
            return reply(
                rpc_error(message_id, -32602, "initialize params must be an object")
            )
        requested = params.get("protocolVersion")
        try:
            protocol_version = negotiate_protocol_version(requested)
        except AgentError:
            return reply(
                rpc_error(
                    message_id,
                    -32602,
                    "Unsupported protocol version",
                )
            )
        return reply(
            rpc_result(
                message_id,
                {
                    "protocolVersion": protocol_version,
                    "capabilities": {"tools": {}, "resources": {}, "prompts": {}},
                    "serverInfo": {"name": MCP_SERVER_NAME, "version": __version__},
                },
            )
        )
    if method == "tools/list":
        tools = TOOLS
        if autonomous_runtime_surface:
            tools = [tool for tool in TOOLS if tool["name"] == "runtime_status"]
        elif enforce_master_role:
            tools = (
                teamleader_tool_catalog()
                if master_tool_access_status()["authorized"]
                else [tool for tool in TOOLS if tool["name"] == "runtime_status"]
            )
        return reply(rpc_result(message_id, {"tools": tools}))
    if method == "resources/list":
        return reply(rpc_result(message_id, {"resources": []}))
    if method == "prompts/list":
        return reply(rpc_result(message_id, {"prompts": []}))
    if method == "tools/call":
        try:
            principal_class = None
            params = msg.get("params", {})
            if params is None:
                params = {}
            if not isinstance(params, dict):
                raise AgentError("tools/call params must be an object")
            if enforce_master_role:
                requested_name = params.get("name")
                if not isinstance(requested_name, str):
                    raise AgentError("tools/call requires a known tool name")
                if requested_name != "runtime_status":
                    if autonomous_runtime_surface:
                        raise AgentError("teamleader authorization required")
                    status = require_teamleader_tool_access()
                    principal_class = require_principal_tool_access(requested_name, status)
            name, args = validate_tool_call(
                params.get("name"), params.get("arguments", {})
            )
            payload = (
                runtime_status()
                if name == "runtime_status"
                else (
                    call_tool(name, args, principal_class=principal_class)
                    if principal_class is not None
                    else call_tool(name, args)
                )
            )
            text = json.dumps(payload, indent=2, sort_keys=True)
            return reply(
                rpc_result(
                    message_id,
                    {"content": [{"type": "text", "text": text}], "isError": False},
                )
            )
        except Exception as exc:
            text = json.dumps(public_error_payload(exc), indent=2, sort_keys=True)
            return reply(
                rpc_result(
                    message_id,
                    {"content": [{"type": "text", "text": text}], "isError": True},
                )
            )
    if method in ("notifications/initialized", "notifications/cancelled"):
        return None
    if "id" not in msg:
        return None
    return rpc_error(message_id, -32601, "method not found")


def parse_content_length(line: bytes, max_bytes: int = MAX_RPC_MESSAGE_BYTES) -> int:
    try:
        length = int(line.decode("ascii").split(":", 1)[1].strip())
    except (IndexError, UnicodeDecodeError, ValueError) as exc:
        raise AgentError("invalid Content-Length header") from exc
    if length <= 0:
        raise AgentError("Content-Length must be positive")
    if length > max_bytes:
        raise AgentError(f"Content-Length exceeds {max_bytes} bytes")
    return length


def mcp_header_name(line: str | bytes) -> str:
    if isinstance(line, bytes):
        try:
            line = line.decode("ascii")
        except UnicodeDecodeError:
            return ""
    name, separator, _ = line.partition(":")
    name = name.strip()
    if not separator or not re.fullmatch(r"[A-Za-z0-9-]+", name):
        return ""
    return name.lower()


def read_message() -> dict[str, Any] | None:
    while True:
        first = sys.stdin.buffer.readline(MAX_RPC_MESSAGE_BYTES + 1)
        if len(first) > MAX_RPC_MESSAGE_BYTES:
            raise AgentError(f"RPC message line exceeds {MAX_RPC_MESSAGE_BYTES} bytes")
        if not first:
            return None
        if first.strip():
            break
    if mcp_header_name(first):
        header_lines = [first]
        header_bytes = len(first)
        while True:
            line = sys.stdin.buffer.readline(MAX_RPC_MESSAGE_BYTES + 1)
            if len(line) > MAX_RPC_MESSAGE_BYTES:
                raise AgentError(
                    f"RPC header line exceeds {MAX_RPC_MESSAGE_BYTES} bytes"
                )
            header_bytes += len(line)
            if header_bytes > MAX_RPC_MESSAGE_BYTES:
                raise AgentError(
                    f"RPC header block exceeds {MAX_RPC_MESSAGE_BYTES} bytes"
                )
            if line in (b"\r\n", b"\n", b""):
                break
            header_lines.append(line)
        content_length_line = next(
            (
                line
                for line in header_lines
                if mcp_header_name(line) == "content-length"
            ),
            None,
        )
        if content_length_line is None:
            raise AgentError("missing Content-Length header")
        length = parse_content_length(content_length_line)
        body = sys.stdin.buffer.read(length)
        if len(body) != length:
            raise AgentError("incomplete RPC message body")
        message = json.loads(body.decode("utf-8"))
        if message is None:
            raise AgentError("RPC message must be an object")
        return message
    stripped = first.strip()
    if stripped:
        message = json.loads(stripped.decode("utf-8"))
        if message is None:
            raise AgentError("RPC message must be an object")
        return message
    return None


def write_message(message: dict[str, Any]) -> None:
    sys.stdout.buffer.write(
        json.dumps(message, separators=(",", ":")).encode("utf-8") + b"\n"
    )
    sys.stdout.buffer.flush()


def fleet_materialize_native_registry() -> dict[str, Any]:
    """Move native A/B/C authority from the legacy pool into Fleet Registry.

    Existing homes are adopted in place: only Fleet-managed wrapper/config
    files and the marker are added or refreshed; unrelated files, including
    auth.json, remain untouched.  b92 is intentionally not migrated here.
    """

    require_fleet_recovery_ready("fleet_series_apply")
    targets = (("a", 5), ("b", 3), ("c", 3))
    service = current_fleet_service()
    with fleet_mutation_lock(FleetPaths.from_state_root(STATE_ROOT)):
        current = service.load()
        changed = 0
        for prefix, count in targets:
            account_id = f"native-{prefix}"
            source = AGENTS.get(f"{prefix}1")
            auth_path = (
                Path(source.get("home", AGENT_POOL_ROOT / f"{prefix}1")) / "auth.json"
                if source
                else None
            )
            auth_configured = bool(auth_path and path_present_no_follow(auth_path))
            account = FleetAccount(
                account_id,
                f"Native Series {prefix.upper()}",
                Provider.OPENAI_CHATGPT,
                AuthKind.CHATGPT_SESSION,
                SecretState.CONFIGURED if auth_configured else SecretState.MISSING,
                LimitState.READY if auth_configured else LimitState.UNKNOWN,
                True,
                None,
                None,
                None,
                None,
            )
            current_account = next(
                (item for item in current.accounts if item.account_id == account_id),
                None,
            )
            if current_account != account:
                planned = plan_account_upsert(
                    current, account, expected_generation=current.generation
                )
                current = service.commit_snapshot(
                    planned, expected_generation=current.generation
                )
                changed += 1
            existing = next(
                (item for item in current.series if item.prefix == prefix), None
            )
            candidate = FleetSeries(
                prefix,
                f"Native Series {prefix.upper()}",
                count,
                RunnerKind.CODEX_CLI,
                Provider.OPENAI_CHATGPT,
                DEFAULT_AGENT_MODEL,
                account_id,
                True,
                "teamleiterin",
                "standard",
            )
            if existing != candidate:
                confirmed = (
                    [
                        f"{prefix}{number}"
                        for number in range(count + 1, existing.count + 1)
                    ]
                    if existing and count < existing.count
                    else []
                )
                planned = plan_series_apply(
                    current,
                    candidate,
                    expected_generation=current.generation,
                    confirmed_remove_ids=confirmed,
                )
                current = service.commit_snapshot(
                    planned, expected_generation=current.generation
                )
                changed += 1

        inventory = build_inventory(current, AGENT_POOL_ROOT)
        with (
            pool_root_lock(AGENT_POOL_ROOT),
            pool_root_operation(
                AGENT_POOL_ROOT, ensure=True, error_text="fleet_pool_root_invalid"
            ) as root,
        ):
            marker = root / FLEET_POOL_MARKER_FILE
            if not path_present_no_follow(marker):
                replace_private_text(
                    marker,
                    '{\n  "kind": "codex_master_fleet_pool",\n  "schema_version": 1\n}\n',
                )
            for prefix, _count in targets:
                for agent_id in inventory.by_series.get(f"{prefix}-series", ()):
                    descriptor = inventory.agents[agent_id]
                    found = shutil.which("codex")
                    if found is None:
                        raise AgentError("fleet_executable_unavailable")
                    executable = trusted_runner_executable(Path(found))
                    # c1 historically shared a1/skills through a symlink.
                    # Registry-managed homes must be self-contained and the
                    # security checks intentionally reject symlink parents;
                    # replace only this known shared asset with a real dir.
                    skill_root = descriptor.home / "skills"
                    if skill_root.is_symlink():
                        skill_root.unlink()
                    _fleet_write_home(
                        descriptor.home,
                        _fleet_artifacts(descriptor, executable),
                        allow_unmanaged=True,
                    )
        preserved = (
            legacy_agent_inventory({"b92": AGENTS["b92"]}) if "b92" in AGENTS else None
        )
        publish_agent_inventory(
            merge_agent_inventories(inventory, preserved)
            if preserved is not None
            else inventory
        )
    return {
        "materialized_series": [prefix for prefix, _count in targets],
        "agent_count": sum(count for _prefix, count in targets),
        "changed_records": changed,
        "legacy_runtime_source": "removed_for_a_b_c",
        "b92": "preserved_legacy_compatibility",
        "raw_output": "not_returned",
    }


def ollama_local_benchmark(
    *, model: str = "llama3.2:3b", concurrency: int = 1
) -> dict[str, Any]:
    """Run a bounded local Ollama benchmark without retaining generated text."""

    if not isinstance(model, str) or not model or len(model) > 200:
        raise AgentError("ollama_model_invalid")
    if (
        isinstance(concurrency, bool)
        or not isinstance(concurrency, int)
        or not 1 <= concurrency <= 2
    ):
        raise AgentError("ollama_benchmark_concurrency_invalid")
    resource_before = system_resource_snapshot()
    payload = json.dumps(
        {
            "model": model,
            "prompt": "Reply with exactly one short word: ok.",
            "stream": False,
            "options": {"num_predict": 8, "temperature": 0},
        }
    )
    started = time.perf_counter()
    try:
        completed = _run_bounded_stdout_command(
            [
                "curl",
                "-fsS",
                "--max-time",
                "45",
                "-H",
                "Content-Type: application/json",
                "-d",
                payload,
                "http://127.0.0.1:11434/api/generate",
            ],
            timeout=50,
            max_bytes=MAX_OLLAMA_RESPONSE_BYTES,
            error_code="ollama_benchmark_unavailable",
        )
    except AgentError as exc:
        raise AgentError("ollama_benchmark_unavailable") from exc
    elapsed = time.perf_counter() - started
    try:
        response = json.loads(completed.stdout) if completed.returncode == 0 else {}
    except (json.JSONDecodeError, TypeError):
        response = {}
    return {
        "provider": "ollama_local",
        "model": model,
        "concurrency_requested": concurrency,
        "concurrency_policy": "one active agent by default; two only when resource gate allows",
        "returncode": completed.returncode,
        "available": completed.returncode == 0 and isinstance(response, dict),
        "elapsed_seconds": round(elapsed, 3),
        "prompt_eval_count": response.get("prompt_eval_count")
        if isinstance(response, dict)
        else None,
        "eval_count": response.get("eval_count")
        if isinstance(response, dict)
        else None,
        "prompt_eval_duration_ns": response.get("prompt_eval_duration")
        if isinstance(response, dict)
        else None,
        "eval_duration_ns": response.get("eval_duration")
        if isinstance(response, dict)
        else None,
        "resource_before": resource_before,
        "response_text": "not_returned",
        "stderr": "not_returned",
        "raw_output": "not_returned",
    }


def _run_bounded_stdout_command(
    argv: list[str],
    *,
    timeout: float,
    max_bytes: int,
    error_code: str,
) -> subprocess.CompletedProcess[str]:
    if (
        not isinstance(argv, list)
        or not argv
        or any(not isinstance(value, str) or not value for value in argv)
        or isinstance(timeout, bool)
        or not isinstance(timeout, (int, float))
        or not 0 < timeout <= 300
        or isinstance(max_bytes, bool)
        or not isinstance(max_bytes, int)
        or not 1 <= max_bytes <= 4 * 1024 * 1024
        or not isinstance(error_code, str)
        or not error_code
    ):
        raise AgentError("bounded_command_invalid")
    try:
        process = subprocess.Popen(
            argv,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=False,
        )
    except (OSError, ValueError) as exc:
        raise AgentError(error_code) from exc
    stream = process.stdout
    if stream is None:
        _terminate_bounded_process(process)
        raise AgentError(error_code)
    selector = selectors.DefaultSelector()
    output = bytearray()
    deadline = time.monotonic() + float(timeout)
    try:
        selector.register(stream, selectors.EVENT_READ)
        while selector.get_map():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                _terminate_bounded_process(process)
                raise AgentError(error_code)
            ready = selector.select(remaining)
            if not ready:
                _terminate_bounded_process(process)
                raise AgentError(error_code)
            for key, _ in ready:
                chunk = os.read(
                    key.fileobj.fileno(), min(8192, max_bytes + 1 - len(output))
                )
                if not chunk:
                    selector.unregister(key.fileobj)
                    continue
                output.extend(chunk)
                if len(output) > max_bytes:
                    _terminate_bounded_process(process)
                    raise AgentError(error_code)
        return subprocess.CompletedProcess(
            argv,
            process.wait(),
            bytes(output).decode("utf-8", "replace"),
            "",
        )
    finally:
        selector.close()
        stream.close()


def _terminate_bounded_process(process: subprocess.Popen[bytes]) -> None:
    try:
        process.kill()
    except OSError:
        pass
    try:
        process.wait(timeout=1)
    except subprocess.TimeoutExpired:
        pass


def _publish_startup_fleet_inventory() -> None:
    """Publish dynamic series only when the registry contains materialized series.

    Account-only bootstrap metadata must not replace the established native
    a/b/c inventory with an empty snapshot.
    """

    global _FLEET_STARTUP_ERROR
    snapshot, registry_backed = effective_observation_inventory()
    if snapshot is None:
        _FLEET_STARTUP_ERROR = "fleet_registry_unavailable"
    elif registry_backed:
        publish_agent_inventory(snapshot)
    else:
        swap_agent_inventory(None)


def _unauthenticated_mcp_request(message: object) -> bool:
    """Identify requests that must stay on the sterile runtime surface."""

    if not isinstance(message, dict):
        return True
    if message.get("method") in ("initialize", "notifications/initialized"):
        return True
    try:
        return master_tool_access_status().get("authorized") is not True
    except Exception:
        return True


def _sterile_runtime_surface_response(
    message: dict[str, Any], *, autonomous_runtime_surface: bool = False
) -> dict[str, Any] | None:
    """Serve only autonomous runtime RPCs without initializing private state."""

    method = message.get("method")
    if method in (
        "initialize",
        "notifications/initialized",
        "tools/list",
        "tools/call",
    ):
        return handle_rpc(
            message,
            enforce_master_role=True,
            autonomous_runtime_surface=autonomous_runtime_surface,
        )
    message_id = message.get("id")
    if "id" not in message:
        return None
    if not (
        isinstance(message_id, str)
        or (
            isinstance(message_id, (int, float))
            and not isinstance(message_id, bool)
            and (not isinstance(message_id, float) or math.isfinite(message_id))
        )
    ):
        return handle_rpc(
            message,
            enforce_master_role=True,
            autonomous_runtime_surface=autonomous_runtime_surface,
        )
    return rpc_error(message_id, -32000, "teamleader authorization required")


def serve_mcp(*, autonomous_runtime_surface: bool = False) -> int:
    """Serve MCP with a startup inventory scoped to this server lifetime."""

    previous_inventory = swap_agent_inventory(None)
    try:
        return _serve_mcp_impl(autonomous_runtime_surface=autonomous_runtime_surface)
    finally:
        swap_agent_inventory(previous_inventory)


def _serve_mcp_impl(*, autonomous_runtime_surface: bool = False) -> int:
    global _FLEET_STARTUP_ERROR
    initialized_regular_surface = False
    while True:
        try:
            msg = read_message()
            if msg is None:
                return 0
            if autonomous_runtime_surface:
                response = _sterile_runtime_surface_response(
                    msg, autonomous_runtime_surface=True
                )
            elif _unauthenticated_mcp_request(msg):
                response = _sterile_runtime_surface_response(msg)
            else:
                if not initialized_regular_surface:
                    ensure_state()
                    _fleet_initialize_recovery_startup_state()
                    _FLEET_STARTUP_ERROR = None
                    _publish_startup_fleet_inventory()
                    initialized_regular_surface = True
                response = handle_rpc(msg, enforce_master_role=True)
            if response is not None:
                write_message(response)
        except (UnicodeDecodeError, json.JSONDecodeError):
            try:
                write_message(rpc_error(None, -32700, "Parse error"))
            except Exception:
                return 1
        except AgentError as exc:
            try:
                code = -32600 if str(exc) == "RPC message must be an object" else -32000
                message = "Invalid Request" if code == -32600 else safe_error_text(exc)
                write_message(rpc_error(None, code, message))
            except Exception:
                return 1
        except Exception as exc:
            try:
                write_message(rpc_error(None, -32000, safe_error_text(exc)))
            except Exception:
                return 1


def print_json(payload: Any) -> int:
    print(json.dumps(payload, indent=2, sort_keys=True))
    return 0


def _fleet_overview_local_admin(
    *,
    active_only: bool,
    format: str,
    clock: Callable[[], _dt.datetime] | None = None,
    usage_clock: Callable[[], _dt.datetime] | None = None,
) -> str:
    if type(active_only) is not bool or format not in {"compact", "json", "markdown"}:
        raise AgentError("fleet_overview_unavailable")
    selected_clock = (
        clock if clock is not None else (lambda: _dt.datetime.now(_dt.timezone.utc))
    )
    selected_usage_clock = (
        usage_clock
        if usage_clock is not None
        else (lambda: _dt.datetime.now(_dt.timezone.utc))
    )
    paths = FleetPaths.from_state_root(STATE_ROOT)
    try:
        with _fleet_registry_read_lock(paths.lock):
            created_at = selected_clock()
            if (
                not isinstance(created_at, _dt.datetime)
                or created_at.tzinfo is None
                or created_at.utcoffset() != _dt.timedelta(0)
            ):
                raise AgentError("fleet_overview_unavailable")
            service = _readonly_fleet_service()
            snapshot = service.registry_snapshot()
            inventory = build_inventory(snapshot, AGENT_POOL_ROOT)
            overview = build_fleet_overview(
                snapshot,
                inventory,
                active_only=active_only,
                contexts=None,
                created_at=created_at,
            )
        try:
            evidence = read_usage_evidence_v2(clock=selected_usage_clock)
            if evidence.status == "complete":
                derive_limit_decisions(evidence, now=selected_usage_clock())
            usage_snapshot = display_snapshot_from_evidence(
                evidence,
                known_account_ids=frozenset(
                    account.account_id for account in snapshot.accounts
                ),
            )
        except Exception:
            usage_snapshot = UsageSnapshot(
                (), "unavailable", True, ("usage_unavailable",)
            )
        enriched_overview = enrich_fleet_overview_usage(overview, usage_snapshot)
        return render_fleet_overview(enriched_overview, format=format)
    except Exception:
        raise AgentError("fleet_overview_unavailable") from None


def _hive_metrics_local_admin(
    *, clock: Callable[[], _dt.datetime] | None = None
) -> str:
    selected_clock = (
        clock if clock is not None else (lambda: _dt.datetime.now(_dt.timezone.utc))
    )
    paths = FleetPaths.from_state_root(STATE_ROOT)
    try:
        with _fleet_registry_read_lock(paths.lock):
            registry_snapshot = _readonly_fleet_service().registry_snapshot()
            inventory = build_inventory(registry_snapshot, AGENT_POOL_ROOT)
        observation = create_fleet_snapshot(
            agent_homes={
                agent_id: inventory.agents[agent_id].home
                for agent_id in inventory.agent_ids
            },
            agent_sessions={
                agent_id: inventory.agents[agent_id].session
                for agent_id in inventory.agent_ids
            },
            tmux_runner=run_tmux,
        )
        contexts: dict[str, FleetOverviewAgentContext] = {}
        observation_errors = 0
        for agent_id in inventory.agent_ids:
            try:
                status = status_agent(
                    agent_id, initialize_state=False, snapshot=observation
                )
                active = status.get("running") is True
                last_assignment = (
                    status.get("last_assignment")
                    if isinstance(status.get("last_assignment"), dict)
                    else {}
                )
                meta = read_meta(agent_id)
                principal_role = meta.get("agent_class")
                if not isinstance(principal_role, str) or not principal_role:
                    principal_role = last_assignment.get("role")
                if not isinstance(principal_role, str) or not principal_role:
                    principal_role = None
                contexts[agent_id] = FleetOverviewAgentContext(
                    active,
                    "running" if active else "stopped",
                    principal_role,
                    last_assignment.get("assignment_id")
                    if isinstance(last_assignment.get("assignment_id"), str)
                    else None,
                )
            except Exception:
                observation_errors += 1
                contexts[agent_id] = FleetOverviewAgentContext(False, "unknown")
        overview = build_fleet_overview(
            registry_snapshot,
            inventory,
            active_only=True,
            contexts=contexts,
            created_at=observation.created_at,
        )
        native = native_agent_status()
        native_counts = (
            native.get("counts") if isinstance(native.get("counts"), dict) else {}
        )
        native_active = native_counts.get("active")
        native_unconfirmed = native_counts.get("unconfirmed")
        if type(native_active) is not int or native_active < 0:
            native_active = 0
        if type(native_unconfirmed) is not int or native_unconfirmed < 0:
            native_unconfirmed = 0
        values = fleet_metric_values(
            overview, native_active=native_active, observed_at=selected_clock()
        )
        values.update(
            {
                "codex_master_agent_observation_errors": observation_errors,
                "codex_master_native_bridge_ready": int(
                    native.get("bridge_state") == "ready"
                ),
                "codex_master_bees_native_unconfirmed": native_unconfirmed,
                "codex_master_process_scan_available": int(
                    observation.process_scan_available
                ),
                "codex_master_tmux_scan_available": int(
                    observation.tmux_scan_available
                ),
            }
        )
        return render_openmetrics(values)
    except Exception:
        raise AgentError("hive_metrics_unavailable") from None


def _observability_serve_cli(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="codex-master-mcp observability-serve")
    parser.add_argument("--host", choices=("127.0.0.1", "::1"), default="127.0.0.1")
    parser.add_argument("--port", type=int, default=9798)
    parser.add_argument("--cache-seconds", type=float, default=5.0)
    args = parser.parse_args(argv)
    if not 1024 <= args.port <= 65535 or not 0.25 <= args.cache_seconds <= 60:
        print_json({"error": "invalid_observability_configuration"})
        return 2
    server = MetricsHttpServer(
        (args.host, args.port),
        TimedMetricsReader(_hive_metrics_local_admin, ttl_seconds=args.cache_seconds),
    )
    try:
        server.serve_forever(poll_interval=0.5)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


